const historyVariants = [{"number":1,"questions":[{"id":"hi-058","t":"Қобыз өнерін дамытқан XIX ғасыр композиторы кім?","o":["Біржан Қожағұлұлы","Ықылас Дүкенұлы","Ақан сері Қорамсаұлы","Дәулеткерей Шығайұлы"],"a":1,"e":"Ықылас Дүкенұлы қобызшы және күйші ретінде белгілі болды.","l":"A","topic":"XIX ғасырдағы музыка","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":191}},{"id":"hk-120","t":"Қай оқиға Абылай ханның өмір сүрген кезеңіне жатады?","o":["Жоңғар тұтқынынан 1743 жылы босатылуы","1465–1466 жылдары хандықтың құрылуы","1643 жылғы Орбұлақ шайқасы","1594 жылы Құл-Мұхаммедтің елшілігі"],"a":0,"e":"Абылай 1711–1781 жылдары өмір сүрді, сондықтан тек 1743 жылғы оқиға оның өмір кезеңіне сәйкес келеді.","l":"C","topic":"Дәуірлерді ажырату","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hk-031","t":"Тәуекел хан қай ханның ұлы болды?","o":["Шығай ханның","Тәуке ханның","Жәңгір ханның","Абылай ханның"],"a":0,"e":"Тәуекел — Шығай ханның ұлы, XVI ғасырдың соңындағы Қазақ хандығының билеушісі.","l":"A","topic":"Тәуекел хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hm-042","t":"Тың және тыңайған жерлерді игеру қай жылы басталды?","o":["1986 жылы","1928 жылы","1941 жылы","1954 жылы"],"a":3,"e":"Тың игеру науқаны 1954 жылы басталды.","l":"A","topic":"Тың игеру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"ha-079","t":"Әл-Фарабидің өмірбаянындағы Фараб атауын Қазақстандағы қай қаламен байланыстыру қажет?","o":["Отырар","Сарайшық","Испиджаб","Янгикент"],"a":0,"e":"Фараб атауы Отырар қаласы мен оның өңіріне қатысты қолданылған.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"ha-007","t":"Мыс-тас дәуірінің ғылыми атауын көрсетіңіз.","o":["Мезолит","Энеолит","Палеолит","Неолит"],"a":1,"e":"Энеолитте мыс құралдармен қатар тас құралдар да қолданылды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-011","t":"Қазақ хандығы халқының негізгі шаруашылық түрін көрсетіңіз.","o":["Тек қала қолөнері","Тек керуен саудасы","Тек суармалы егіншілік","Көшпелі мал шаруашылығы"],"a":3,"e":"Даланың табиғи жағдайына бейімделген көшпелі және жартылай көшпелі мал шаруашылығы негізгі кәсіп болды.","l":"A","topic":"Қазақ хандығының шаруашылығы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"hm-111","t":"Тың игеру жөніндегі тұжырымдарды бағалаңыз: I — астық егілетін жер көлемі ұлғайды; II — жайылымның жыртылуы мал шаруашылығына қысым түсірді; III — қоныс аудару этнодемографиялық құрамға әсер етті; IV — топырақ эрозиясы толық жойылды.","o":["II, III және IV дұрыс","I, III және IV дұрыс","I, II және III дұрыс","I, II және IV дұрыс"],"a":2,"e":"Тың игеру астық өндірісін және сырттан қоныс аударуды арттырды, жайылымды қысқартты. Шамадан тыс жырту эрозияны жойған жоқ, керісінше күшейтті.","l":"C","topic":"Тың игеру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"hi-089","t":"«Айқап» журналының мазмұнына тән мәселені көрсетіңіз.","o":["Тек атом өнеркәсібі","Тек ортағасырлық теңге соғу","Жер, білім және қоғамдық жаңару","Тек ғарыштық ұшулар"],"a":2,"e":"«Айқап» қазақ қоғамының жер, оқу-ағарту және жаңару мәселелерін көтерді.","l":"B","topic":"XX ғасыр басындағы баспасөз","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":168}},{"id":"ha-024","t":"Есік қорғанынан табылған атақты археологиялық олжа қайсы?","o":["Тайқазан","Ботай қыш мөрі","Орхон тас жазуы","Алтын адам"],"a":3,"e":"Есік қорғанындағы алтынмен әшекейленген сақ жауынгерінің киімі Алтын адам деген атаумен белгілі.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}}],"contexts":[{"id":"hce-01","title":"Ботай қонысының деректері","text":"Ботай мәдениеті Солтүстік Қазақстандағы энеолит дәуіріне жатады. Қонысты зерттеуде Виктор Зайберттің еңбегі маңызды. Тұрғын үйлер, еңбек құралдары және көп жылқы сүйегі табылған. Олар шаруашылықта жылқының маңызды болғанын көрсетеді. Мыс пен тас қатар пайдаланылған кезең энеолит деп аталады. Қоныстың тұрмысын зерттеу үшін тек сүйектерді емес, үй құрылысын және құралдарды да салыстыру қажет. Бір олжа барлық кәсіптің толық сипатын анықтап бермейді. Археологиялық кешен бірнеше дерек түрін біріктіргенде сенімді түсіндіріледі. Табиғи орта мен қоныстың орналасуы да шаруашылық әрекетін бағалауға көмектеседі.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":78},"questions":[{"id":"hce-01-1","t":"«Ботай қонысының деректері» контексі: Ботай орналасқан негізгі өңір қайсы?","o":["Маңғыстау","Жетісу","Арал маңы","Солтүстік Қазақстан"],"a":3,"e":"Мәтіндегі деректер «Солтүстік Қазақстан» деген жауапты негіздейді. Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді.","l":"A","topic":"Ботай қонысының деректері"},{"id":"hce-01-2","t":"«Ботай қонысының деректері» контексі: Ботай мәдениетін зерттеген ғалым кім?","o":["Кемел Ақышев","Виктор Зайберт","Зейнолла Самашев","Әлкей Марғұлан"],"a":1,"e":"Мәтіндегі деректер «Виктор Зайберт» деген жауапты негіздейді. Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді.","l":"A","topic":"Ботай қонысының деректері"},{"id":"hce-01-3","t":"«Ботай қонысының деректері» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Ботай тұрғындары тек жылқы өсірген","Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді","Ботай теңіз саудасына ғана сүйенген","Ботайда тас құрал мүлде қолданылмаған"],"a":1,"e":"Мәтіндегі деректер «Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді» деген жауапты негіздейді. Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді.","l":"B","topic":"Ботай қонысының деректері"},{"id":"hce-01-4","t":"«Ботай қонысының деректері» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Тұрғын үй, құралдар және сүйектерді бірге зерттеу тұрмысты толығырақ ашады","Бір сүйектің түрі барлық кәсіпті толық анықтайды","Кейінгі аңыз археологиялық олжаны толық алмастырады","Қоныс орнын білу құралдарды зерттеуді қажетсіз етеді"],"a":0,"e":"Мәтіндегі деректер «Тұрғын үй, құралдар және сүйектерді бірге зерттеу тұрмысты толығырақ ашады» деген жауапты негіздейді. Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді.","l":"B","topic":"Ботай қонысының деректері"},{"id":"hce-01-5","t":"«Ботай қонысының деректері» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Ботай тұрғындары тек жылқы өсірген","Ботай мәдениеті Солтүстік Қазақстандағы энеолит дәуіріне жатады.","Тұрғын үй, құралдар және сүйектерді бірге зерттеу тұрмысты толығырақ ашады","Жылқы сүйектерінің көптігі оның шаруашылықтағы маңызын көрсетеді"],"a":0,"e":"Мәтіндегі деректер «Ботай тұрғындары тек жылқы өсірген» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Тұрғын үй, құралдар және сүйектерді бірге зерттеу тұрмысты толығырақ ашады.","l":"C","topic":"Ботай қонысының деректері"}]},{"id":"hcl-01","title":"1822 жылғы басқару өзгерісі","text":"XIX ғасырдың алғашқы жартысында Ресей империясы қазақ даласын басқарудың жаңа жүйесін енгізді. Бұрынғы хандық құрылымның орнына империялық әкімшілікке тәуелді басқару сатылары қалыптасты.\n\n1822 жылғы «Сібір қырғыздары туралы жарғы» Орта жүздегі хандық билікті жойды. Округтің басында аға сұлтан тұрды, ал округтер болыстарға және ауылдарға бөлінді. Аға сұлтанды үш жылдық мерзімге сайлау белгіленді. Жарғы жобасын әзірлеуге Сібір әкімшілігін басқарған Михаил Сперанский қатысты.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1},"questions":[{"id":"hcl-01-1","t":"«1822 жылғы басқару өзгерісі» контексі: 1822 жылғы жарғы қай жүздегі хандық билікті жойды?","o":["Кіші жүзде","Ұлы жүзде","Үш жүзде бір мезгілде","Орта жүзде"],"a":3,"e":"1822 жылғы «Сібір қырғыздары туралы жарғы» Орта жүздегі хандық билікті жойды.","l":"A","topic":"1822 жылғы басқару өзгерісі"},{"id":"hcl-01-2","t":"«1822 жылғы басқару өзгерісі» контексі: Округті басқарған лауазым қалай аталды?","o":["Даруға","Аға сұлтан","Генерал-губернатор","Жабғу"],"a":1,"e":"Округтің басында аға сұлтан тұрды, ал округтер болыстарға және ауылдарға бөлінді.","l":"A","topic":"1822 жылғы басқару өзгерісі"},{"id":"hcl-01-3","t":"«1822 жылғы басқару өзгерісі» контексі: Екі деректі сәйкестендіріңіз. 1) 1822 жылғы жарғы қай жүздегі хандық билікті жойды. 2) Аға сұлтан неше жылға сайланды.","o":["1 — Кіші жүзде; 2 — Бес жылға","1 — Орта жүзде; 2 — Бір жылға","1 — Ұлы жүзде; 2 — Үш жылға","1 — Орта жүзде; 2 — Үш жылға"],"a":3,"e":"1822 жылғы «Сібір қырғыздары туралы жарғы» Орта жүздегі хандық билікті жойды. Аға сұлтанды үш жылдық мерзімге сайлау белгіленді.","l":"B","topic":"1822 жылғы басқару өзгерісі"},{"id":"hcl-01-4","t":"«1822 жылғы басқару өзгерісі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Округті басқарған лауазым қалай аталды? 2) Жарғыны әзірлеуге қатысқан мемлекет қайраткері кім?","o":["1 — Аға сұлтан; 2 — Петр Столыпин","1 — Аға сұлтан; 2 — Михаил Сперанский","1 — Даруға; 2 — Сергей Витте","1 — Жабғу; 2 — Михаил Сперанский"],"a":1,"e":"Округтің басында аға сұлтан тұрды, ал округтер болыстарға және ауылдарға бөлінді. Жарғы жобасын әзірлеуге Сібір әкімшілігін басқарған Михаил Сперанский қатысты.","l":"B","topic":"1822 жылғы басқару өзгерісі"},{"id":"hcl-01-5","t":"«1822 жылғы басқару өзгерісі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Болыстар мен ауылдардың құрылуы реформада саяси бағынудан гөрі тек қоныстарды есептеу көзделгенін көрсетеді.","Аға сұлтанды сайлау ханның бұрынғы өкілеттігін өзгеріссіз сақтап қалуға мүмкіндік берді.","Хандық биліктің жойылуы даланы империялық әкімшілікке тікелей бағындыруды күшейтті.","Округтер құру жергілікті басқаруды империялық бақылаудан біртіндеп босатты."],"a":2,"e":"Хандық биліктің жойылуы даланы империялық әкімшілікке тікелей бағындыруды күшейтті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1822 жылғы басқару өзгерісі"}]}]},{"number":2,"questions":[{"id":"hi-102","t":"Реформаларды қабылдану ретімен қойыңыз: 1) 1867–1868 жылғы уақытша ережелер; 2) Кіші жүздегі хандық билікті жою; 3) Сібір қырғыздары туралы жарғы.","o":["1 → 3 → 2","2 → 3 → 1","3 → 1 → 2","3 → 2 → 1"],"a":3,"e":"Сібір жарғысы 1822 жылы, Кіші жүздегі реформа 1824 жылы қабылданды. Уақытша ережелер кейінірек, 1867–1868 жылдары енгізілді.","l":"C","topic":"Әкімшілік реформалар хронологиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":171}},{"id":"hm-049","t":"«Жылымық» кезеңі қай басшының билігімен байланысты?","o":["Никита Хрущев","Владимир Ленин","Филипп Голощекин","Иосиф Сталин"],"a":0,"e":"1950–1960 жылдардағы «жылымық» Н.Хрущев кезеңіндегі өзгерістермен байланысты.","l":"A","topic":"Жылымық","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hk-080","t":"1611 жылғы шайқастан кейін Бұхар билеушісінің келісімге келуіне қандай әскери жағдай әсер етті?","o":["Қазақтардың Сыр қалаларынан толық шегінуі","Ташкенттің Ресей әскерімен қоршалуы","Бұхар мен Жоңғарияның бірігуі","Есім хан әскерінен Ташкент маңында жеңілуі"],"a":3,"e":"Ташкент маңындағы қазақ жеңісі Бұхар билеушісін Қазақ хандығымен келісуге итермеледі.","l":"B","topic":"Есім ханның саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":127}},{"id":"hi-095","t":"1917 жылғы Екінші жалпықазақ съезі өткен қала қайсы?","o":["Ташкент","Орынбор","Петербург","Қоқан"],"a":1,"e":"1917 жылғы желтоқсанда Екінші жалпықазақ съезі Орынборда өтті. Онда Алаш автономиясы мен Алашорда мәселесі шешілді.","l":"A","topic":"Алаш қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":279}},{"id":"hi-034","t":"1867–1868 жылғы ережелерде қазақтардың көшіп-қонатын жерлері кімнің меншігі деп жарияланды?","o":["Ресей мемлекетінің","Жәрмеңке көпестерінің","Әр ауылдың ортақ жеке меншігі","Хандар әулетінің"],"a":0,"e":"Қазақ жерлері Ресей империясының мемлекеттік меншігі деп танылды. Бұл қоныстандыру саясатына құқықтық негіз берді.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":154}},{"id":"hm-095","t":"1992 жылғы мемлекеттік рәміздер мен БҰҰ мүшелігіне ортақ тарихи мән қандай?","o":["КСРО-ны қайта құру","Ұжымдастыруды аяқтау","Тың игеруді кеңейту","Тәуелсіз мемлекеттілікті нығайту"],"a":3,"e":"Рәміздер мемлекеттің даралығын білдірді, БҰҰ мүшелігі халықаралық орнын бекітті.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"hk-046","t":"Орбұлақтағы қазақ әскерін қай хан басқарды?","o":["Абылай хан","Жәңгір хан","Керей хан","Шығай хан"],"a":1,"e":"1643 жылғы Орбұлақ шайқасында қазақ қолына Жәңгір хан басшылық етті.","l":"A","topic":"Орбұлақ шайқасы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"hm-050","t":"1965–1985 жылдардағы кеңестік даму кезеңінің кең тараған атауы қандай?","o":["Тоқырау кезеңі","ЖЭС кезеңі","Әскери коммунизм кезеңі","Қайта құру кезеңі"],"a":0,"e":"1965–1985 жылдардағы жүйелік қайшылықтар күшейген уақыт тоқырау кезеңі деп аталады.","l":"A","topic":"Тоқырау","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"ha-063","t":"Алтын Орда негізінен қай ұлыстың аумағында қалыптасты?","o":["Жошы ұлысы","Төле ұлысы","Үгедей ұлысы","Шағатай ұлысы"],"a":0,"e":"Алтын Орда Жошы ұлысының батыс аумақтарында Батый тұсында қалыптасты.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"ha-125","t":"Оқиғалар мен мәдениетті ертеден кейінге қарай орналастырыңыз: 1) Алтын Орданың қалыптасуы; 2) Ботай мәдениеті; 3) Атлах шайқасы; 4) Моғолстанның құрылуы.","o":["3 → 2 → 1 → 4","2 → 3 → 4 → 1","2 → 3 → 1 → 4","2 → 1 → 3 → 4"],"a":2,"e":"Ботай энеолитке, Атлах 751 жылға, Алтын Орданың қалыптасуы XIII ғасырға, Моғолстанның құрылуы 1348 жылға жатады.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}}],"contexts":[{"id":"hce-02","title":"Сақтар туралы жазба және заттай деректер","text":"Сақтар туралы мәлімет парсы жазбаларында, грек авторларының еңбектерінде және археологиялық ескерткіштерде сақталған. Геродот көшпелі тайпалардың тұрмысын сипаттаған. Парсы деректерінде сақтардың бірнеше атауы кездеседі. Қорғандардан табылған қару мен әшекейлер киім және өнер туралы заттай мәлімет береді. Әр дерек белгілі ортада және белгілі мақсатпен пайда болған. Сондықтан сырттан жазылған сипаттаманы барлық тайпаға бірдей тарату дұрыс емес. Жазба мен археологиялық олжаны салыстыру тарихи көріністі толықтырады. Деректе бір құбылыстың аталмауы оның мүлде болмағанын дәлелдемейді. Автор көзқарасы мен заттың табылған орнын ескеру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":155},"questions":[{"id":"hce-02-1","t":"«Сақтар туралы жазба және заттай деректер» контексі: Сақтарды сипаттаған грек авторы кім?","o":["Әл-Фараби","Геродот","Махмұд Қашқари","Рашид ад-Дин"],"a":1,"e":"Мәтіндегі деректер «Геродот» деген жауапты негіздейді. Жазба мен заттай дерек бірін-бірі толықтыра алады.","l":"A","topic":"Сақтар туралы жазба және заттай деректер"},{"id":"hce-02-2","t":"«Сақтар туралы жазба және заттай деректер» контексі: Сақ киімін заттай зерттеуге не көмектеседі?","o":["Қазіргі жол белгілері","Газет жарнамалары","Телеграф хабарлары","Қорған әшекейлері"],"a":3,"e":"Мәтіндегі деректер «Қорған әшекейлері» деген жауапты негіздейді. Жазба мен заттай дерек бірін-бірі толықтыра алады.","l":"A","topic":"Сақтар туралы жазба және заттай деректер"},{"id":"hce-02-3","t":"«Сақтар туралы жазба және заттай деректер» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Жазба мен заттай дерек бірін-бірі толықтыра алады","Қорған әшекейлері еш тарихи ақпарат бермейді","Бір грек авторы барлық сақ тайпасын толық сипаттаған","Парсы атауы тайпаның төл атауын міндетті түрде дәл береді"],"a":0,"e":"Мәтіндегі деректер «Жазба мен заттай дерек бірін-бірі толықтыра алады» деген жауапты негіздейді. Жазба мен заттай дерек бірін-бірі толықтыра алады.","l":"B","topic":"Сақтар туралы жазба және заттай деректер"},{"id":"hce-02-4","t":"«Сақтар туралы жазба және заттай деректер» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Деректі автор мақсаты мен пайда болған ортасын ескеріп пайдалану керек","Автордың мақсаты тарихи талдауға қатыссыз","Деректе аталмаған нәрсе тарихта болмаған","Ең көне мәтін әрдайым толық және қатесіз болады"],"a":0,"e":"Мәтіндегі деректер «Деректі автор мақсаты мен пайда болған ортасын ескеріп пайдалану керек» деген жауапты негіздейді. Жазба мен заттай дерек бірін-бірі толықтыра алады.","l":"B","topic":"Сақтар туралы жазба және заттай деректер"},{"id":"hce-02-5","t":"«Сақтар туралы жазба және заттай деректер» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Бір грек авторы барлық сақ тайпасын толық сипаттаған","Деректі автор мақсаты мен пайда болған ортасын ескеріп пайдалану керек","Жазба мен заттай дерек бірін-бірі толықтыра алады","Сақтар туралы мәлімет парсы жазбаларында, грек авторларының еңбектерінде және археологиялық ескерткіштерде сақталған."],"a":0,"e":"Мәтіндегі деректер «Бір грек авторы барлық сақ тайпасын толық сипаттаған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Деректі автор мақсаты мен пайда болған ортасын ескеріп пайдалану керек.","l":"C","topic":"Сақтар туралы жазба және заттай деректер"}]},{"id":"hcl-02","title":"Бөкей ордасындағы көтеріліс","text":"Бөкей ордасында жердің шектелуі мен әлеуметтік теңсіздік халық наразылығын күшейтті. Жергілікті билікке қарсы басталған қозғалыс кейін патша өкіметінің жазалау күштерімен қақтығысқа ұласты.\n\nИсатай Тайманұлы мен Махамбет Өтемісұлы бастаған көтеріліс 1836–1838 жылдары өтті. Қозғалыстың негізгі әскери басшысы Исатай Тайманұлы болды. 1837 жылғы Тастөбе шайқасында көтерілісшілер патша әскерінің басым күшімен кездесті. Исатай Тайманұлы 1838 жылғы Ақбұлақ шайқасында қаза тапты.","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":155},"questions":[{"id":"hcl-02-1","t":"«Бөкей ордасындағы көтеріліс» контексі: Бөкей ордасындағы Исатай бастаған көтеріліс қай жылдары өтті?","o":["1856–1857 жылдары","1783–1797 жылдары","1836–1838 жылдары","1916–1917 жылдары"],"a":2,"e":"Исатай Тайманұлы мен Махамбет Өтемісұлы бастаған көтеріліс 1836–1838 жылдары өтті.","l":"A","topic":"Бөкей ордасындағы көтеріліс"},{"id":"hcl-02-2","t":"«Бөкей ордасындағы көтеріліс» контексі: Көтерілістің негізгі басшысы кім болды?","o":["Исатай Тайманұлы","Есет Көтібарұлы","Сырым Датұлы","Амангелді Иманұлы"],"a":0,"e":"Қозғалыстың негізгі әскери басшысы Исатай Тайманұлы болды.","l":"A","topic":"Бөкей ордасындағы көтеріліс"},{"id":"hcl-02-3","t":"«Бөкей ордасындағы көтеріліс» контексі: Екі деректі сәйкестендіріңіз. 1) Бөкей ордасындағы Исатай бастаған көтеріліс қай жылдары өтті. 2) Көтерілісшілер 1837 жылы қай жерде шайқасты.","o":["1 — 1836–1838 жылдары; 2 — Тастөбеде","1 — 1783–1797 жылдары; 2 — Тастөбеде","1 — 1856–1857 жылдары; 2 — Орбұлақта","1 — 1836–1838 жылдары; 2 — Аңырақайда"],"a":0,"e":"Исатай Тайманұлы мен Махамбет Өтемісұлы бастаған көтеріліс 1836–1838 жылдары өтті. 1837 жылғы Тастөбе шайқасында көтерілісшілер патша әскерінің басым күшімен кездесті.","l":"B","topic":"Бөкей ордасындағы көтеріліс"},{"id":"hcl-02-4","t":"«Бөкей ордасындағы көтеріліс» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Көтерілістің негізгі басшысы кім болды? 2) Исатай қаза тапқан 1838 жылғы шайқас қай жерде өтті?","o":["1 — Сырым Датұлы; 2 — Ақбұлақта","1 — Есет Көтібарұлы; 2 — Құндызшада","1 — Исатай Тайманұлы; 2 — Бұлантыда","1 — Исатай Тайманұлы; 2 — Ақбұлақта"],"a":3,"e":"Қозғалыстың негізгі әскери басшысы Исатай Тайманұлы болды. Исатай Тайманұлы 1838 жылғы Ақбұлақ шайқасында қаза тапты.","l":"B","topic":"Бөкей ордасындағы көтеріліс"},{"id":"hcl-02-5","t":"«Бөкей ордасындағы көтеріліс» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Жер мәселесі мен билік озбырлығы әлеуметтік наразылықты қарулы қарсылыққа айналдырды.","Көтерілістің негізгі қайшылығы шаруалар мен билік арасында емес, сыртқы саудагерлер арасында болды.","Тастөбедегі шайқас жер мәселесі шешілгеннен кейін қозғалыстың өздігінен тоқтағанын білдіреді.","Қозғалыстың жетекшілері ауысқанымен, жер тапшылығы оның мақсаттарына әсер еткен жоқ."],"a":0,"e":"Жер мәселесі мен билік озбырлығы әлеуметтік наразылықты қарулы қарсылыққа айналдырды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Бөкей ордасындағы көтеріліс"}]}]},{"number":3,"questions":[{"id":"ha-038","t":"Халықтардың ұлы қоныс аударуына ықпал еткен тайпалық бірлестікті атаңыз.","o":["Ғұндар","Наймандар","Керейіттер","Қоңыраттар"],"a":0,"e":"Ғұндардың батысқа жылжуы Еуразиядағы тайпалардың қозғалысын күшейтті.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"ha-083","t":"Түркістандағы Ясауи кесенесінің XIV ғасырдың соңында ірі құрылыспен жаңғыртылуын қай билеушінің қызметімен байланыстыру керек?","o":["Барақ","Тоғылық Темір","Батый","Әмір Темір"],"a":3,"e":"Ясауи кесенесінің ауқымды құрылысын Әмір Темір бастатқан.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hm-115","t":"ЖЭС пен ұжымдастыруды меншік, айырбас және басқару тұрғысынан дұрыс салыстырыңыз.","o":["ЖЭС ішінара жеке саудаға жол ашты; ұжымдастыру ауылды ұжымдық шаруашылық пен әкімшілік басқаруға көшірді","ЖЭС ұжымдық шаруашылықты күшпен енгізді; ұжымдастыру азық-түлік салығына алғаш көшірді","Екі саясат та тек жеке меншікті кеңейтті және мемлекеттік араласуды тоқтатты","ЖЭС барлық сауданы жойды; ұжымдастыру өнімді еркін сатуға негізделді"],"a":0,"e":"ЖЭС нарық элементтерін уақытша қолданды. 1920 жылдардың соңындағы саясат ұжымдық шаруашылық пен жоспарлы-әкімшілік тетіктерді күшейтті.","l":"C","topic":"Экономикалық саясат","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":257}},{"id":"hk-055","t":"Қарақұм құрылтайында жасақтарды ұйымдастырумен байланысты аталған батыр кім?","o":["Бекболат","Бөгенбай","Исатай","Амангелді"],"a":1,"e":"Бөгенбай батыр XVIII ғасырдағы жоңғарларға қарсы күрестің көрнекті қолбасшыларының бірі болды.","l":"A","topic":"Қазақ-жоңғар соғыстары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-102","t":"Билік ету кезеңдерін салыстырып, дұрыс реттілікті таңдаңыз.","o":["Хақназар → Есім → Қасым → Тәуекел","Есім → Қасым → Тәуекел → Хақназар","Тәуекел → Хақназар → Есім → Қасым","Қасым → Хақназар → Тәуекел → Есім"],"a":3,"e":"Қасым XVI ғасырдың басында, Хақназар 1538–1580 жылдары, Тәуекел 1582–1598 жылдары, Есім 1598 жылдан билік етті.","l":"C","topic":"Қазақ хандарының хронологиясы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hi-051","t":"Ыбырай Алтынсарин білім алған алғашқы оқу орны қай қалада болды?","o":["Орынборда","Верныйда","Ташкентте","Қашғарда"],"a":0,"e":"Ыбырай Орынбор шекара комиссиясы жанындағы мектепте оқыды.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"hk-054","t":"1710 жылғы Қарақұм кеңесінің негізгі талқылаған мәселесі қандай болды?","o":["Қазақ АКСР-ын құру","Тың жерлерді игеру","Теміржол желісін ашу","Жоңғарларға қарсы бірлескен қорғаныс"],"a":3,"e":"Құрылтайда сыртқы қауіпке тойтарыс беру үшін қазақ жасақтарының күшін біріктіру көзделді.","l":"A","topic":"Қарақұм құрылтайы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":187}},{"id":"hi-090","t":"1916 жылғы көтеріліске тікелей түрткі болған патша жарлығы нені көздеді?","o":["Барлық салықты жою","Қазақ жерінде хандық билікті қалпына келтіру","Қазақстанға толық тәуелсіздік беру","Жергілікті ер азаматтарды тыл жұмыстарына алу"],"a":3,"e":"1916 жылғы 25 маусым жарлығы жергілікті халықтың ер азаматтарын майданның тыл жұмыстарына алуды көздеді.","l":"B","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":219}},{"id":"ha-018","t":"Сақ өнеріндегі жануар бейнелеріне негізделген бағытты көрсетіңіз.","o":["Готикалық стиль","Классицизм","Аңдық стиль","Барокко"],"a":2,"e":"Аңдық стильде жануарлар мен олардың қимылдары бейнеленіп, әшекейлер мен тұрмыстық бұйымдар безендірілді.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":69}},{"id":"hm-003","t":"1925 жылы Ақмешіт қаласына қандай атау берілді?","o":["Қызылорда","Ақмола","Верный","Целиноград"],"a":0,"e":"1925 жылы Ақмешіт Қызылорда деп аталды және республика астанасы болды.","l":"A","topic":"Қазақ АКСР","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":259}}],"contexts":[{"id":"hce-03","title":"Томирис және Кир жорығы","text":"Б.з.б. 530 жылы парсы патшасы Кир сақ-массагет тайпаларына жорық жасады. Геродот еңбегінде Томирис елін қорғаған билеуші ретінде сипатталады. Әңгімеде билеушілердің шешімі мен соғыстың нәтижесі байланыстырылған. Оқиға сыртқы басқыншылыққа қарсы күресті көрсетеді. Бұл жорық б.з.б. VI ғасырға жатады. Ежелгі автор оқиғадан кейін өмір сүргендіктен, оның баяндауын басқа деректермен салыстыру қажет. Бір шайқас туралы әңгіме сақ қоғамының бүкіл тұрмысын толық ашпайды. Әскери оқиғаны және автордың оны жеткізу тәсілін бөлек қарастыру дерек мазмұнын түсінуге көмектеседі. Тарихи тұлғаның әрекеті өз дәуірінің жағдайында бағаланады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":137},"questions":[{"id":"hce-03-1","t":"«Томирис және Кир жорығы» контексі: Сақтарға қарсы жорық жасаған парсы билеушісі кім?","o":["Батый","Кир","Естеми","Тоғылық Темір"],"a":1,"e":"Мәтіндегі деректер «Кир» деген жауапты негіздейді. Кир жорығы б.з.б. VI ғасырға жатады.","l":"A","topic":"Томирис және Кир жорығы"},{"id":"hce-03-2","t":"«Томирис және Кир жорығы» контексі: Мәтінде елін қорғаған билеуші кім?","o":["Білге","Сұлу","Үшлік","Томирис"],"a":3,"e":"Мәтіндегі деректер «Томирис» деген жауапты негіздейді. Кир жорығы б.з.б. VI ғасырға жатады.","l":"A","topic":"Томирис және Кир жорығы"},{"id":"hce-03-3","t":"«Томирис және Кир жорығы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Кир жорығы б.з.б. VI ғасырға жатады","Геродот жорықтың тікелей куәгері болған","Жорық б.з. VI ғасырында өтті","Бұл оқиға жоңғар шапқыншылығына жатады"],"a":0,"e":"Мәтіндегі деректер «Кир жорығы б.з.б. VI ғасырға жатады» деген жауапты негіздейді. Кир жорығы б.з.б. VI ғасырға жатады.","l":"B","topic":"Томирис және Кир жорығы"},{"id":"hce-03-4","t":"«Томирис және Кир жорығы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір шайқас сақ қоғамының барлық саласын толық түсіндіреді","Жорық сыртқы басқыншылыққа қарсы қарсылықтың мысалы","Әскери оқиғада билеушілер шешімінің рөлі жоқ","Деректі салыстыру оның маңызын жоққа шығарады"],"a":1,"e":"Мәтіндегі деректер «Жорық сыртқы басқыншылыққа қарсы қарсылықтың мысалы» деген жауапты негіздейді. Кир жорығы б.з.б. VI ғасырға жатады.","l":"B","topic":"Томирис және Кир жорығы"},{"id":"hce-03-5","t":"«Томирис және Кир жорығы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Жорық сыртқы басқыншылыққа қарсы қарсылықтың мысалы","Кир жорығы б.з.б. VI ғасырға жатады","Кир жорығы б.з.б. 530 жылы болды.","Геродот жорықтың тікелей куәгері болған"],"a":3,"e":"Мәтіндегі деректер «Геродот жорықтың тікелей куәгері болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Жорық сыртқы басқыншылыққа қарсы қарсылықтың мысалы.","l":"C","topic":"Томирис және Кир жорығы"}]},{"id":"hcl-03","title":"Кенесары қозғалысының мақсаты","text":"XIX ғасырдағы ұлт-азаттық қозғалыстардың ішінде Кенесары Қасымұлы бастаған күрес ауқымымен ерекшеленді. Қозғалыс отарлық қысымды тоқтатып, қазақ жерінің саяси тұтастығын сақтауды көздеді.\n\nКенесары Қасымұлы бастаған көтеріліс 1837–1847 жылдары жүрді. 1841 жылы Кенесары хан болып сайланып, басқаруды орталықтандыруға ұмтылды. Ағыбай батыр Кенесарының сенімді серіктерінің бірі ретінде күреске қатысты. Көтеріліске үш жүздің өкілдері қатысып, ол бірнеше аймаққа таралды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":17},"questions":[{"id":"hcl-03-1","t":"«Кенесары қозғалысының мақсаты» контексі: Кенесары көтерілісі қай жылдары жүрді?","o":["1836–1838 жылдары","1868–1869 жылдары","1837–1847 жылдары","1783–1797 жылдары"],"a":2,"e":"Кенесары Қасымұлы бастаған көтеріліс 1837–1847 жылдары жүрді.","l":"A","topic":"Кенесары қозғалысының мақсаты"},{"id":"hcl-03-2","t":"«Кенесары қозғалысының мақсаты» контексі: Кенесары хан болып қай жылы сайланды?","o":["1822 жылы","1854 жылы","1831 жылы","1841 жылы"],"a":3,"e":"1841 жылы Кенесары хан болып сайланып, басқаруды орталықтандыруға ұмтылды.","l":"A","topic":"Кенесары қозғалысының мақсаты"},{"id":"hcl-03-3","t":"«Кенесары қозғалысының мақсаты» контексі: Екі деректі сәйкестендіріңіз. 1) Кенесары көтерілісі қай жылдары жүрді. 2) Кенесары қозғалысына қатысқан белгілі батыр кім.","o":["1 — 1837–1847 жылдары; 2 — Бөгенбай","1 — 1837–1847 жылдары; 2 — Ағыбай","1 — 1783–1797 жылдары; 2 — Қабанбай","1 — 1836–1838 жылдары; 2 — Ағыбай"],"a":1,"e":"Кенесары Қасымұлы бастаған көтеріліс 1837–1847 жылдары жүрді. Ағыбай батыр Кенесарының сенімді серіктерінің бірі ретінде күреске қатысты.","l":"B","topic":"Кенесары қозғалысының мақсаты"},{"id":"hcl-03-4","t":"«Кенесары қозғалысының мақсаты» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Кенесары хан болып қай жылы сайланды? 2) Қозғалыстың аумақтық ерекшелігі қандай?","o":["1 — 1841 жылы; 2 — Үш жүздің өкілдерін қамтыды","1 — 1831 жылы; 2 — Тек Еділдің батысында жүрді","1 — 1822 жылы; 2 — Үш жүздің өкілдерін қамтыды","1 — 1841 жылы; 2 — Тек бір қаламен шектелді"],"a":0,"e":"1841 жылы Кенесары хан болып сайланып, басқаруды орталықтандыруға ұмтылды. Көтеріліске үш жүздің өкілдері қатысып, ол бірнеше аймаққа таралды.","l":"B","topic":"Кенесары қозғалысының мақсаты"},{"id":"hcl-03-5","t":"«Кенесары қозғалысының мақсаты» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Қозғалыстың ауқымы мен хан сайлау әрекеті саяси бірлікті қалпына келтіруге ұмтылысты көрсетеді.","Көтеріліске әр аймақтың қатысуы олардың отарлық басқаруды күшейтуді ортақ мақсат еткенін дәлелдейді.","Қозғалыстың саяси мақсаты ортақ басқаруды қалпына келтіруден гөрі әр жүзді толық оқшаулау болды.","Хан сайлау қозғалыстың үш жүзге таралуын тоқтатып, оны бір ғана аймақпен шектеді."],"a":0,"e":"Қозғалыстың ауқымы мен хан сайлау әрекеті саяси бірлікті қалпына келтіруге ұмтылысты көрсетеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Кенесары қозғалысының мақсаты"}]}]},{"number":4,"questions":[{"id":"hm-091","t":"Қазақстанның БҰҰ-ға қабылдануы нені білдірді?","o":["Хандық биліктің қалпына келуін","Барлық сыртқы байланыстың тоқтауын","Тәуелсіз мемлекеттің әлемдік қауымдастыққа кірігуін","Кеңестік ұжымдастырудың басталуын"],"a":2,"e":"БҰҰ мүшелігі Қазақстанның халықаралық құқық субъектісі ретінде танылуын нығайтты.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":209}},{"id":"hk-066","t":"Әбілқайыр билігіне наразылық пен ру-тайпалардың дербес ел болуға ұмтылысы қандай өзгеріске алғышарт болды?","o":["Ноғай Ордасында маңғыт билігінің қалыптасуына","Қазақ хандығының құрылуына","Моғолстанда Есен-бұға билігінің басталуына","Бұхарда II Абдаллах билігінің орнығуына"],"a":1,"e":"Бұл саяси және әлеуметтік себептер XV ғасырда Керей мен Жәнібек бастаған бірлестіктің қалыптасуына ықпал етті.","l":"B","topic":"Қазақ хандығының құрылу себептері","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"ha-120","t":"Суяб, Тараз және Испиджабтан сауда орындары мен қолөнер шеберханалары табылған. Оларды біріктіретін ең дәл тарихи сипаттама қайсы?","o":["Ноғай Ордасының Жайық бойындағы біріккен порттары","Алтын Орданың Еділ бойында кезектескен астаналары","Тек қола дәуіріне жататын малшылар қоныстары","Оңтүстік Қазақстан мен Жетісудағы қала-сауда мәдениетінің орталықтары"],"a":3,"e":"Бұл қалалар Оңтүстік Қазақстан мен Жетісудағы Жібек жолы тармақтарына байланысты дамыған қалалық орталықтар болды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"hm-028","t":"Әлия Молдағұлова соғыста қандай әскери мамандықты меңгерді?","o":["Ұшқыш","Әскери теңізші","Танк жүргізушісі","Мерген"],"a":3,"e":"Ә.Молдағұлова мерген ретінде майданда ерлік көрсетті.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":207}},{"id":"ha-055","t":"Қарахан мемлекетінің негізін қалаушы ретінде белгілі билеуші кім?","o":["Тоқтамыс хан","Сатұқ Боғра хан","Өзбек хан","Батый хан"],"a":1,"e":"Сатұқ Боғра ханның билікке келуі Қарахан мемлекетінің қалыптасуымен байланысты.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":55}},{"id":"hk-027","t":"Хақназар тұсында қазақтарға көптеген ру-тайпалары қосылған көрші бірлестік қайсы?","o":["Қарахан мемлекеті","Қазан губерниясы","Ноғай Ордасы","Ливон ордені"],"a":2,"e":"Ноғай Ордасындағы ыдырау кезінде бірқатар ұлыстар Қазақ хандығына қосылды.","l":"A","topic":"Хақназар хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":139}},{"id":"hm-024","t":"1937–1938 жылдары қуғын-сүргін құрбаны болған әдебиет қайраткерлерін көрсетіңіз.","o":["А.Құнанбайұлы, Ш.Уәлиханов, Ы.Алтынсарин","Қасым хан, Хақназар хан, Тәуекел хан","Т.Бигелдинов, С.Луганский, Л.Беда","С.Сейфуллин, І.Жансүгіров, Б.Майлин"],"a":3,"e":"Сәкен, Ілияс және Бейімбет сталиндік қуғын-сүргін кезінде қаза тапты.","l":"A","topic":"Қуғын-сүргін","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":227}},{"id":"hi-057","t":"Қазақтың шертпе күй дәстүрінің көрнекті өкілі кім?","o":["Біржан Қожағұлұлы","Тәттімбет Қазанғапұлы","Құрманғазы Сағырбайұлы","Жаяу Мұса Байжанұлы"],"a":1,"e":"Тәттімбет — шертпе күй мектебінің әйгілі өкілі. Біржан сал мен Жаяу Мұса әншілік дәстүрімен танылды.","l":"A","topic":"XIX ғасырдағы музыка","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":200}},{"id":"hi-112","t":"Зайырлы мектеп ашу, оқулық жазу және этнографиялық зерттеу жүргізу қандай ортақ тарихи өзгеріске ықпал етті?","o":["Қазақ қоғамының білім және ғылыми таным арқылы жаңаруына","Хандық билікті 1822 жылы нығайтуға","Қазақ тілінде білім беруді толық жоюға","Көшпелі қоғамның сыртқы байланыстарын үзуге"],"a":0,"e":"Мектеп, оқулық және зерттеу білім көкжиегін кеңейтті. Ағартушылар қоғамның жаңаруын біліммен байланыстырды.","l":"C","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":183}},{"id":"hi-062","t":"1916 жылы Жетісудағы көтеріліс басшыларының бірі кім?","o":["Жоламан Тіленшіұлы","Бекболат Әшекеев","Исатай Тайманұлы","Кенесары Қасымұлы"],"a":1,"e":"Бекболат Әшекеев Жетісудағы 1916 жылғы көтеріліс басшыларының бірі болды.","l":"A","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":259}}],"contexts":[{"id":"hce-04","title":"Сақ атауларының мағынасы","text":"Парсы жазбаларында сақтардың бірнеше тобы аталған. Тиграхауда атауы шошақ бөрік киетін сақтармен байланысты. Хаомаварга атауы хаома дайындау ғұрпын білдіреді. Парадарайя теңіздің арғы жағындағы сақтар деп түсіндіріледі. Бұл атауларда сыртқы бақылаушының жіктеу тәсілі көрінеді. Бір атау киімді, екіншісі ғұрыпты, үшіншісі географиялық орналасуды сипаттайды. Оларды тайпалардың өздерін қалай атағанының толық дәлелі деп қабылдауға болмайды. Атауларды археологиялық және географиялық мәліметпен салыстыру қажет. Бір киім белгісі мемлекеттің нақты шекарасын өздігінен анықтамайды. Терминнің мағынасын және тарихи топтың мекенін ажыратып талдау маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":155},"questions":[{"id":"hce-04-1","t":"«Сақ атауларының мағынасы» контексі: Шошақ бөрікті сақтардың атауы қайсы?","o":["Тиграхауда","Дулу","Парадарайя","Хаомаварга"],"a":0,"e":"Мәтіндегі деректер «Тиграхауда» деген жауапты негіздейді. Парадарайя атауы географиялық белгімен байланысты.","l":"A","topic":"Сақ атауларының мағынасы"},{"id":"hce-04-2","t":"«Сақ атауларының мағынасы» контексі: Хаома дайындау ғұрпына қатысты атау қайсы?","o":["Елбөрілі","Нушиби","Хаомаварга","Тиграхауда"],"a":2,"e":"Мәтіндегі деректер «Хаомаварга» деген жауапты негіздейді. Парадарайя атауы географиялық белгімен байланысты.","l":"A","topic":"Сақ атауларының мағынасы"},{"id":"hce-04-3","t":"«Сақ атауларының мағынасы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Барлық парсыша атау сақтардың төл этнонимі болған","Парадарайя атауы географиялық белгімен байланысты","Хаомаварга тек қала тұрғындарының атауы","Тиграхауда атауы салық түрін білдіреді"],"a":1,"e":"Мәтіндегі деректер «Парадарайя атауы географиялық белгімен байланысты» деген жауапты негіздейді. Парадарайя атауы географиялық белгімен байланысты.","l":"B","topic":"Сақ атауларының мағынасы"},{"id":"hce-04-4","t":"«Сақ атауларының мағынасы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Атаулардың әртүрлілігі топтар арасында байланыс болмағанын дәлелдейді","Парсыша атаулардың бәрі тек кәсіпті білдіреді","Бір киім белгісі нақты саяси шекараны толық анықтайды","Сыртқы атауды басқа тарихи дерекпен салыстыру қажет"],"a":3,"e":"Мәтіндегі деректер «Сыртқы атауды басқа тарихи дерекпен салыстыру қажет» деген жауапты негіздейді. Парадарайя атауы географиялық белгімен байланысты.","l":"B","topic":"Сақ атауларының мағынасы"},{"id":"hce-04-5","t":"«Сақ атауларының мағынасы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Сыртқы атауды басқа тарихи дерекпен салыстыру қажет","Парсы жазбаларында сақтардың бірнеше тобы аталған.","Парадарайя атауы географиялық белгімен байланысты","Барлық парсыша атау сақтардың төл этнонимі болған"],"a":3,"e":"Мәтіндегі деректер «Барлық парсыша атау сақтардың төл этнонимі болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сыртқы атауды басқа тарихи дерекпен салыстыру қажет.","l":"C","topic":"Сақ атауларының мағынасы"}]},{"id":"hcl-04","title":"Сыр бойындағы Жанқожа көтерілісі","text":"Сырдария бойындағы халық әртүрлі сыртқы күштердің қысымын сезінді. Жанқожа Нұрмұхамедұлының күресі жергілікті тұрғындардың жері мен еркіндігін қорғауға бағытталды.\n\n1856–1857 жылдардағы Сыр бойы көтерілісін Жанқожа Нұрмұхамедұлы басқарды. Қарсылық Сырдарияның төменгі ағысындағы қазақ ауылдарын қамтыды. Жанқожа батыр Хиуа хандығының Сыр бойына жасаған қысымына қарсы да күресті. Қозғалысқа жері мен шаруашылығын қорғаған қарапайым қазақ шаруалары қатысты. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":43},"questions":[{"id":"hcl-04-1","t":"«Сыр бойындағы Жанқожа көтерілісі» контексі: Сыр бойындағы 1856–1857 жылдардағы көтерілісті кім басқарды?","o":["Сырым Датұлы","Жанқожа Нұрмұхамедұлы","Бекболат Әшекеев","Кенесары Қасымұлы"],"a":1,"e":"1856–1857 жылдардағы Сыр бойы көтерілісін Жанқожа Нұрмұхамедұлы басқарды.","l":"A","topic":"Сыр бойындағы Жанқожа көтерілісі"},{"id":"hcl-04-2","t":"«Сыр бойындағы Жанқожа көтерілісі» контексі: Қозғалыс негізінен қай өңірде болды?","o":["Алтайдың шығысында","Есілдің жоғарғы ағысында","Сырдарияның төменгі ағысында","Іленің бастауында"],"a":2,"e":"Қарсылық Сырдарияның төменгі ағысындағы қазақ ауылдарын қамтыды.","l":"A","topic":"Сыр бойындағы Жанқожа көтерілісі"},{"id":"hcl-04-3","t":"«Сыр бойындағы Жанқожа көтерілісі» контексі: Екі деректі сәйкестендіріңіз. 1) Сыр бойындағы 1856–1857 жылдардағы көтерілісті кім басқарды. 2) Жанқожа бұған дейін қай хандықтың қысымына қарсы күресті.","o":["1 — Жанқожа Нұрмұхамедұлы; 2 — Қазан хандығының","1 — Бекболат Әшекеев; 2 — Сібір хандығының","1 — Жанқожа Нұрмұхамедұлы; 2 — Хиуа хандығының","1 — Кенесары Қасымұлы; 2 — Хиуа хандығының"],"a":2,"e":"1856–1857 жылдардағы Сыр бойы көтерілісін Жанқожа Нұрмұхамедұлы басқарды. Жанқожа батыр Хиуа хандығының Сыр бойына жасаған қысымына қарсы да күресті.","l":"B","topic":"Сыр бойындағы Жанқожа көтерілісі"},{"id":"hcl-04-4","t":"«Сыр бойындағы Жанқожа көтерілісі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Қозғалыс негізінен қай өңірде болды? 2) Көтерілістің әлеуметтік тірегі кімдер болды?","o":["1 — Сырдарияның төменгі ағысында; 2 — Қарапайым қазақ шаруалары","1 — Алтайдың шығысында; 2 — Тек зауыт иелері","1 — Сырдарияның төменгі ағысында; 2 — Тек шетел көпестері","1 — Есілдің жоғарғы ағысында; 2 — Қарапайым қазақ шаруалары"],"a":0,"e":"Қарсылық Сырдарияның төменгі ағысындағы қазақ ауылдарын қамтыды. Қозғалысқа жері мен шаруашылығын қорғаған қарапайым қазақ шаруалары қатысты.","l":"B","topic":"Сыр бойындағы Жанқожа көтерілісі"},{"id":"hcl-04-5","t":"«Сыр бойындағы Жанқожа көтерілісі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Қозғалыс тек сыртқы билеушілер арасындағы бәсекені шешуге бағытталып, шаруалар мүддесін қамтымады.","Хиуаға қарсылық пен патша билігіне қарсы көтеріліс өзара байланыссыз екі әлеуметтік топтың мүддесін білдірді.","Көтерілістің төменгі Сырда өтуі жергілікті шаруашылықты қорғаудан гөрі жаңа хандық аумақтарды жаулауды көрсетеді.","Қарсылықтың бірнеше сыртқы күшке бағытталуы жергілікті халық мүддесін қорғаудың сабақтастығын көрсетеді."],"a":3,"e":"Қарсылықтың бірнеше сыртқы күшке бағытталуы жергілікті халық мүддесін қорғаудың сабақтастығын көрсетеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Сыр бойындағы Жанқожа көтерілісі"}]}]},{"number":5,"questions":[{"id":"hk-007","t":"XV ғасырдың екінші жартысында Керей мен Жәнібек құрған мемлекетті атаңыз.","o":["Қарлұқ қағанаты","Ноғай Ордасы","Қазақ хандығы","Қарақытай мемлекеті"],"a":2,"e":"Керей мен Жәнібек бастаған саяси бірлестіктің құрылуы Қазақ хандығының тарихын бастады.","l":"A","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hm-056","t":"Семей ядролық полигоны қай жылы жабылды?","o":["1949 жылы","1986 жылы","1991 жылы","1954 жылы"],"a":2,"e":"Семей полигонын жабу туралы жарлық 1991 жылғы 29 тамызда шықты.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-073","t":"1832 жылы құрылған Ақмола округі қандай тарихи үдерістің жалғасы болды?","o":["Қазақ АКСР-інің құрылуының","Алаш автономиясының құрылуының","1822 жылғы жарғыға сәйкес округтік басқаруды кеңейтудің","Жоңғар мемлекетін қалпына келтірудің"],"a":2,"e":"Ақмола округінің құрылуы 1822 жылғы жарғы енгізген әкімшілік жүйенің кеңеюімен байланысты. Округ 1832 жылы ұйымдастырылды.","l":"B","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":158}},{"id":"hm-102","t":"Бес оқиғаны ертеден кешке қарай реттеңіз: 1 — Қазақ КСР-інің құрылуы; 2 — Қазақ АКСР-інің құрылуы; 3 — тың игерудің басталуы; 4 — ЖЭС-ке көшу; 5 — Түрксібтің тұрақты пайдалануға берілуі.","o":["2–4–5–1–3","2–4–1–5–3","4–2–5–1–3","2–5–4–3–1"],"a":0,"e":"Оқиғалар тиісінше 1920, 1921, 1931, 1936 және 1954 жылдарға сәйкес келеді.","l":"C","topic":"Хронология","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hk-064","t":"Абылай жоңғар тұтқынында болған мерзімді көрсетіңіз.","o":["1710–1712 жылдар","1783–1785 жылдар","1771–1773 жылдар","1741–1743 жылдар"],"a":3,"e":"Абылай 1741 жылы тұтқынға түсіп, 1743 жылы дипломатиялық әрекеттер нәтижесінде босады.","l":"A","topic":"Абылай хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-028","t":"1867–1868 жылдардағы әкімшілік реформаларды бекіткен Ресей императоры кім?","o":["I Павел","II Николай","II Александр","I Петр"],"a":2,"e":"Уақытша ережелер II Александр билігі тұсында бекітілді.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"ha-076","t":"Билеушіге мемлекетті әділ басқару туралы кеңес беретін ортағасырлық түркі дастанын таңдаңыз.","o":["Диуани лұғат ат-түрік","Диуани хикмет","Кодекс Куманикус","Құтты білік"],"a":3,"e":"Жүсіп Баласағұнидің «Құтты білік» дастанында әділ билік, парасат және адамгершілік мәселелері қарастырылады.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"ha-075","t":"Әбілқайыр ханның билікке келген жылын көрсетіңіз.","o":["1511 жыл","1465 жыл","1428 жыл","1348 жыл"],"a":2,"e":"Әбілқайыр 1428 жылы хан сайланып, Шығыс Дешті Қыпшақта билігін орнатты.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8}},{"id":"hk-115","t":"Жазда шөбі мол жайылымға, қыста ықтасын қонысқа көшкен малшылар туралы дерек қандай байланысты көрсетеді?","o":["Шаруашылықтың табиғи маусымдарға бейімделуін","Шаруашылықтың маусым ауысуына тәуелсіз болғанын","Маусымдық қоныстың тек әскери мақсатпен таңдалғанын","Барлық көшу бағытын тек ханның елшілік жоспары белгілегенін"],"a":0,"e":"Қонысты маусыммен ауыстыру табиғи орта мен мал азығының өзгеруіне бейімделген шаруашылық тәсілі болды.","l":"C","topic":"Шаруашылықты талдау","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":117}},{"id":"ha-048","t":"Араб деректерінде «Сүзеген» атанған түргеш қағаны кім?","o":["Үшлік","Сұлу","Бумын","Естеми"],"a":1,"e":"Сұлу қағанның арабтарға табанды қарсыласуы оның «Сүзеген» атануына себеп болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}}],"contexts":[{"id":"hce-05","title":"Есік қорғаны және әлеуметтік мәртебе","text":"Есік қорғаны Жетісу өңірінде орналасқан. Одан алтын әшекейлі киім киген сақ дәуірінің адамы табылды. Қабірден қару, ыдыстар және жазуы бар күміс тостаған да шыққан. Бас киім мен әшекей бейнелері сақтардың дүниетанымын зерттеуге мүмкіндік береді. Қымбат заттардың молдығы жерленген адамның жоғары мәртебесін көрсетеді. Бірақ алтын киім оның нақты есімін анықтамайды. Бұйымның табылған орны мен басқа заттармен байланысы бірге зерттеледі. Алтын адам кейін Қазақстанның тарихи мұрасын танытатын рәміздердің біріне айналды. Археологиялық мағына мен қазіргі рәміздік қызметті ажырату қажет. Бір ескерткіш бүкіл қоғамдағы барлық адамның тұрмысын бірдей сипаттамайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":139},"questions":[{"id":"hce-05-1","t":"«Есік қорғаны және әлеуметтік мәртебе» контексі: Есік қорғаны қай өңірде орналасқан?","o":["Жетісу","Маңғыстау","Үстірт","Торғай"],"a":0,"e":"Мәтіндегі деректер «Жетісу» деген жауапты негіздейді. Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді.","l":"A","topic":"Есік қорғаны және әлеуметтік мәртебе"},{"id":"hce-05-2","t":"«Есік қорғаны және әлеуметтік мәртебе» контексі: Жазуы бар олжа қайсы?","o":["Күміс тостаған","Баспа кітап","Тас бағана","Қағаз жарлық"],"a":0,"e":"Мәтіндегі деректер «Күміс тостаған» деген жауапты негіздейді. Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді.","l":"A","topic":"Есік қорғаны және әлеуметтік мәртебе"},{"id":"hce-05-3","t":"«Есік қорғаны және әлеуметтік мәртебе» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді","Алтын киім иесінің нақты есімін өздігінен дәлелдейді","Жазуы бар зат міндетті түрде кітап болады","Есік қорғаны ортағасырлық Жаңакентте орналасқан"],"a":0,"e":"Мәтіндегі деректер «Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді» деген жауапты негіздейді. Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді.","l":"B","topic":"Есік қорғаны және әлеуметтік мәртебе"},{"id":"hce-05-4","t":"«Есік қорғаны және әлеуметтік мәртебе» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Қазіргі рәміздік қызмет көне заттың барлық мағынасын алмастырады","Бұйымдарды орналасуы мен өзара байланысын ескеріп зерттеу керек","Әшекей саны нақты билеуші есімін береді","Бір бай қабір бүкіл халықтың бірдей бай болғанын дәлелдейді"],"a":1,"e":"Мәтіндегі деректер «Бұйымдарды орналасуы мен өзара байланысын ескеріп зерттеу керек» деген жауапты негіздейді. Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді.","l":"B","topic":"Есік қорғаны және әлеуметтік мәртебе"},{"id":"hce-05-5","t":"«Есік қорғаны және әлеуметтік мәртебе» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Есік қорғаны Жетісу өңірінде орналасқан.","Алтын әшекейлер жерленген адамның жоғары мәртебесіне меңзейді","Бұйымдарды орналасуы мен өзара байланысын ескеріп зерттеу керек","Алтын киім иесінің нақты есімін өздігінен дәлелдейді"],"a":3,"e":"Мәтіндегі деректер «Алтын киім иесінің нақты есімін өздігінен дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Бұйымдарды орналасуы мен өзара байланысын ескеріп зерттеу керек.","l":"C","topic":"Есік қорғаны және әлеуметтік мәртебе"}]},{"id":"hcl-05","title":"1867–1868 жылдардағы басқару жүйесі","text":"XIX ғасырдың екінші жартысында отарлық басқару бүкіл далаға таралды. Әкімшілік сатылардың өзгеруі жер қатынастарына, алым-салыққа және жергілікті халықтың саяси жағдайына әсер етті.\n\n1867–1868 жылдардағы уақытша ережелерді II Александр бекітті. Реформалар қазақ даласында империялық басқару тәртібін күшейтуді көздеді. Басқару генерал-губернаторлық, облыс, уезд, болыс және ауыл сатыларына бөлінді. Көшпелілер пайдаланған жерлер мемлекеттік меншік ретінде жарияланды. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14},"questions":[{"id":"hcl-05-1","t":"«1867–1868 жылдардағы басқару жүйесі» контексі: 1867–1868 жылдардағы реформаларды бекіткен патша кім?","o":["I Павел","II Николай","I Петр","II Александр"],"a":3,"e":"1867–1868 жылдардағы уақытша ережелерді II Александр бекітті.","l":"A","topic":"1867–1868 жылдардағы басқару жүйесі"},{"id":"hcl-05-2","t":"«1867–1868 жылдардағы басқару жүйесі» контексі: Реформалардың негізгі саяси мақсаты қандай болды?","o":["Тәуелсіз хандықты қалпына келтіру","Барлық салықты жою","Республикалық парламент құру","Империялық басқаруды күшейту"],"a":3,"e":"Реформалар қазақ даласында империялық басқару тәртібін күшейтуді көздеді.","l":"A","topic":"1867–1868 жылдардағы басқару жүйесі"},{"id":"hcl-05-3","t":"«1867–1868 жылдардағы басқару жүйесі» контексі: Екі деректі сәйкестендіріңіз. 1) 1867–1868 жылдардағы реформаларды бекіткен патша кім. 2) Әкімшілік сатылардың ең төменгі буыны қандай болды.","o":["1 — II Александр; 2 — Облыс","1 — II Николай; 2 — Уезд","1 — I Петр; 2 — Ауыл","1 — II Александр; 2 — Ауыл"],"a":3,"e":"1867–1868 жылдардағы уақытша ережелерді II Александр бекітті. Басқару генерал-губернаторлық, облыс, уезд, болыс және ауыл сатыларына бөлінді.","l":"B","topic":"1867–1868 жылдардағы басқару жүйесі"},{"id":"hcl-05-4","t":"«1867–1868 жылдардағы басқару жүйесі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Реформалардың негізгі саяси мақсаты қандай болды? 2) Қазақтардың жері заңда қалай қарастырылды?","o":["1 — Тәуелсіз хандықты қалпына келтіру; 2 — Мемлекеттік меншік ретінде","1 — Империялық басқаруды күшейту; 2 — Әр отбасының шексіз жеке меншігі ретінде","1 — Республикалық парламент құру; 2 — Шетел мемлекетінің меншігі ретінде","1 — Империялық басқаруды күшейту; 2 — Мемлекеттік меншік ретінде"],"a":3,"e":"Реформалар қазақ даласында империялық басқару тәртібін күшейтуді көздеді. Көшпелілер пайдаланған жерлер мемлекеттік меншік ретінде жарияланды.","l":"B","topic":"1867–1868 жылдардағы басқару жүйесі"},{"id":"hcl-05-5","t":"«1867–1868 жылдардағы басқару жүйесі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Әкімшілік сатылар көбейгенімен, жер қатынастары отарлық бақылаудың тетігіне айналған жоқ.","Ауылдық басқарудың сақталуы реформаның империялық билікті күшейтуге бағытталмағанын дәлелдейді.","Жерді мемлекеттік меншік деп жариялау қазақ қауымдарының жерге саяси үстемдігін толық сақтады.","Басқару сатылары мен жер мәртебесінің өзгеруі отарлық бақылаудың әкімшілік және экономикалық тетіктерін біріктірді."],"a":3,"e":"Басқару сатылары мен жер мәртебесінің өзгеруі отарлық бақылаудың әкімшілік және экономикалық тетіктерін біріктірді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1867–1868 жылдардағы басқару жүйесі"}]}]},{"number":6,"questions":[{"id":"hm-040","t":"«ХІХ ғасырдың 20–40 жылдарындағы Қазақстан» монографиясының авторы кім?","o":["Шоқан Уәлиханов","Ермұхан Бекмаханов","Қаныш Сәтбаев","Әлкей Марғұлан"],"a":1,"e":"Е.Бекмаханов бұл еңбекте Кенесары қозғалысын зерттеді.","l":"A","topic":"Ғылым","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":266}},{"id":"hi-004","t":"1822 жылғы жарғы бойынша округтің басында кім тұрды?","o":["Аға сұлтан","Би","Әскери губернатор","Жүзбасы"],"a":0,"e":"Округті аға сұлтан басқарды. Ол округтік приказдың төрағасы болды.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":185}},{"id":"hk-052","t":"Тәуке ханды ежелгі Спартаның Ликургымен салыстырған зерттеуші кім?","o":["Алексей Левшин","Василий Радлов","Григорий Потанин","Николай Пржевальский"],"a":0,"e":"Алексей Левшин Тәуке ханның заң шығарушылық қызметіне жоғары баға берді.","l":"A","topic":"Тарихнама","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-062","t":"1995 жылғы Қазақстан Конституциясы қандай жолмен қабылданды?","o":["Хан кеңесінің шешімімен","Шетел парламентінің қаулысымен","Республикалық референдум арқылы","Жеке кәсіпорын жарғысымен"],"a":2,"e":"1995 жылғы 30 тамызда жаңа Конституция республикалық референдумда қабылданды.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":233}},{"id":"ha-002","t":"Палеолит атауы қандай дәуірді білдіреді?","o":["Мыс-тас дәуірі","Ежелгі тас дәуірі","Орта тас дәуірі","Жаңа тас дәуірі"],"a":1,"e":"Палеолит — адамзат тарихындағы ежелгі тас дәуірінің ғылыми атауы.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":62}},{"id":"ha-109","t":"Еңбектерді авторларымен сәйкестендіріңіз: 1) Құтты білік; 2) Диуани лұғат ат-түрік; 3) Диуани хикмет. А) Ясауи; Ә) Баласағұни; Б) Қашғари.","o":["1–А, 2–Б, 3–Ә","1–Б, 2–Ә, 3–А","1–Ә, 2–А, 3–Б","1–Ә, 2–Б, 3–А"],"a":3,"e":"«Құтты білікті» Баласағұни, түркі тілдерінің сөздігін Қашғари, хикметтерді Ясауи жазды.","l":"C","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-098","t":"Сыр бойындағы қалалардың көшпелі өңірлермен байланысы қандай қатынасқа негізделді?","o":["Егіншілік-қолөнер өнімдері мен мал өнімдерінің айырбасына","Қалалардың жайылымдарды мүлде пайдаланбауына","Көшпелілердің барлық қолөнерден бірден бас тартуына","Екі аймақтың шаруашылық жағынан толық оқшаулануына"],"a":0,"e":"Қалалар мен көшпелі даланың шаруашылығы бірін-бірі толықтырды; бұл Сыр өңірінің маңызын арттырды.","l":"B","topic":"Қазақ хандығының экономикалық байланысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":83}},{"id":"hi-103","t":"Кенесарының хан сайлануы, ортақ салық енгізуі және әскери тәртіп орнатуы қандай мақсатты көрсетеді?","o":["Округтік приказдардың санын көбейту","Қазақ даласын Қоқан уәлаятына айналдыру","Орталықтанған дербес мемлекетті нығайту","Ауылдардың байланысын толық үзу"],"a":2,"e":"Бұл шаралар билік, қаржы және әскери басқаруды бір орталыққа біріктіруге бағытталды. Олар мемлекеттілікті қалпына келтіру мақсатына қызмет етті.","l":"C","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":169}},{"id":"hm-084","t":"«Жылымық» толық демократия орнатты деу неліктен дұрыс емес?","o":["КСРО сол кезде өмір сүруін тоқтатты","Барлық цензура XV ғасырда жойылды","Партияның саяси үстемдігі сақталды","Қазақстан сол кезде тәуелсіз мемлекет болды"],"a":2,"e":"Саяси жұмсару болғанымен, бірпартиялық жүйе мен идеологиялық бақылау жалғасты.","l":"B","topic":"Жылымық","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-033","t":"Сырдария облысы 1867 жылғы реформада қай генерал-губернаторлыққа бағындырылды?","o":["Кавказ","Орынбор","Түркістан","Батыс Сібір"],"a":2,"e":"Сырдария облысы Түркістан генерал-губернаторлығының құрамына кірді.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":148}}],"contexts":[{"id":"hce-06","title":"Аң стилінің көркем тілі","text":"Сақ өнерінде жануарлар бейнесін қолдану кең тарады. Бұғы, барыс, арқар және жыртқыш құс бейнелері әшекейлерде, қаруда және ат әбзелдерінде кездеседі. Бұл бағыт аң стилі деп аталады. Қозғалысты әсерлі беру мен дене бөлшектерін шартты бейнелеу оның белгілеріне жатады. Бейнелер сәндік әрі дүниетанымдық қызмет атқарған. Жануар суретінің болуы зат тек аңшылықта қолданылғанын білдірмейді. Бұйымның қызметі материалы, табылған орны және өзге олжалармен байланысы арқылы анықталады. Көркем үлгілер шаруашылық пен наным-сенімді зерттеуге де көмектеседі. Өнер туындысын тек әшекей ретінде қарастыру оның тарихи мағынасын тарылтады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":139},"questions":[{"id":"hce-06-1","t":"«Аң стилінің көркем тілі» контексі: Жануар бейнелеріне негізделген бағыт қалай аталады?","o":["Классицизм","Аң стилі","Кубизм","Барокко"],"a":1,"e":"Мәтіндегі деректер «Аң стилі» деген жауапты негіздейді. Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады.","l":"A","topic":"Аң стилінің көркем тілі"},{"id":"hce-06-2","t":"«Аң стилінің көркем тілі» контексі: Мәтінде аталған жануар бейнесін табыңыз.","o":["Қолтырауын","Пингвин","Бұғы","Кенгуру"],"a":2,"e":"Мәтіндегі деректер «Бұғы» деген жауапты негіздейді. Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады.","l":"A","topic":"Аң стилінің көркем тілі"},{"id":"hce-06-3","t":"«Аң стилінің көркем тілі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Мұндай бейнелерде қозғалыс еш көрсетілмейді","Аң стилі тек баспа кітаптарға салынған","Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады","Жануар бейнесі заттың тек аңшылық құралы болғанын дәлелдейді"],"a":2,"e":"Мәтіндегі деректер «Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады» деген жауапты негіздейді. Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады.","l":"B","topic":"Аң стилінің көркем тілі"},{"id":"hce-06-4","t":"«Аң стилінің көркем тілі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Өнер мұрасы шаруашылық тарихына еш мәлімет бермейді","Бұйым қызметін бейнемен қатар археологиялық жағдай арқылы анықтайды","Бір жануар суреті бұйымның барлық қызметін толық түсіндіреді","Бейнелердің дүниетанымға қатысы болуы мүмкін емес"],"a":1,"e":"Мәтіндегі деректер «Бұйым қызметін бейнемен қатар археологиялық жағдай арқылы анықтайды» деген жауапты негіздейді. Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады.","l":"B","topic":"Аң стилінің көркем тілі"},{"id":"hce-06-5","t":"«Аң стилінің көркем тілі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Аң стиліндегі бейне сәндік және дүниетанымдық мағына атқара алады","Бұйым қызметін бейнемен қатар археологиялық жағдай арқылы анықтайды","Сақ өнерінде жануарлар бейнесін қолдану кең тарады.","Жануар бейнесі заттың тек аңшылық құралы болғанын дәлелдейді"],"a":3,"e":"Мәтіндегі деректер «Жануар бейнесі заттың тек аңшылық құралы болғанын дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Бұйым қызметін бейнемен қатар археологиялық жағдай арқылы анықтайды.","l":"C","topic":"Аң стилінің көркем тілі"}]},{"id":"hcl-06","title":"1870 жылғы Маңғыстау көтерілісі","text":"Жаңа әкімшілік ережелерді енгізу жергілікті шаруалардың наразылығын туғызды. Маңғыстауда салық қысымы мен билік шаралары қарулы көтеріліске әкелді.\n\nМаңғыстаудағы отарлық ережелерге қарсы көтеріліс 1870 жылы болды. Көтерілісті Досан Тәжіұлы мен Иса Тіленбайұлы басқарды. Қарсылық Каспий маңындағы Маңғыстау өңірінде таралды. Халық жаңа ережелерге және отарлық салық қысымына қарсылық көрсетті. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9},"questions":[{"id":"hcl-06-1","t":"«1870 жылғы Маңғыстау көтерілісі» контексі: Маңғыстаудағы ірі көтеріліс қай жылы өтті?","o":["1870 жылы","1841 жылы","1905 жылы","1822 жылы"],"a":0,"e":"Маңғыстаудағы отарлық ережелерге қарсы көтеріліс 1870 жылы болды.","l":"A","topic":"1870 жылғы Маңғыстау көтерілісі"},{"id":"hcl-06-2","t":"«1870 жылғы Маңғыстау көтерілісі» контексі: Көтеріліс басшыларының бірі кім?","o":["Мұстафа Шоқай","Әлихан Бөкейхан","Досан Тәжіұлы","Тұрар Рысқұлов"],"a":2,"e":"Көтерілісті Досан Тәжіұлы мен Иса Тіленбайұлы басқарды.","l":"A","topic":"1870 жылғы Маңғыстау көтерілісі"},{"id":"hcl-06-3","t":"«1870 жылғы Маңғыстау көтерілісі» контексі: Екі деректі сәйкестендіріңіз. 1) Маңғыстаудағы ірі көтеріліс қай жылы өтті. 2) Көтерілістің негізгі аумағы қай өңір.","o":["1 — 1822 жылы; 2 — Маңғыстау","1 — 1870 жылы; 2 — Жетісу","1 — 1870 жылы; 2 — Маңғыстау","1 — 1841 жылы; 2 — Алтай"],"a":2,"e":"Маңғыстаудағы отарлық ережелерге қарсы көтеріліс 1870 жылы болды. Қарсылық Каспий маңындағы Маңғыстау өңірінде таралды.","l":"B","topic":"1870 жылғы Маңғыстау көтерілісі"},{"id":"hcl-06-4","t":"«1870 жылғы Маңғыстау көтерілісі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Көтеріліс басшыларының бірі кім? 2) Көтеріліс қандай саясатқа қарсылық танытты?","o":["1 — Әлихан Бөкейхан; 2 — Патшалық отарлық ережелерді енгізуге","1 — Досан Тәжіұлы; 2 — Жаңа экономикалық саясатқа","1 — Досан Тәжіұлы; 2 — Патшалық отарлық ережелерді енгізуге","1 — Мұстафа Шоқай; 2 — Тың игеруге"],"a":2,"e":"Көтерілісті Досан Тәжіұлы мен Иса Тіленбайұлы басқарды. Халық жаңа ережелерге және отарлық салық қысымына қарсылық көрсетті.","l":"B","topic":"1870 жылғы Маңғыстау көтерілісі"},{"id":"hcl-06-5","t":"«1870 жылғы Маңғыстау көтерілісі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Жаңа ережелерге наразылық Маңғыстаудағы шаруаларға емес, тек облыстық шенеуніктерге тән болды.","Салық пен басқару өзгерістері жергілікті шаруалардың отарлық билікке қарсы наразылығын күшейтті.","Қозғалыстың аймақтық сипаты оның отарлық басқару мәселесімен байланысын жоққа шығарады.","Салыққа қарсылық қозғалыстың тек жергілікті старшындардың қызмет бөлуіне қатысты болғанын көрсетеді."],"a":1,"e":"Салық пен басқару өзгерістері жергілікті шаруалардың отарлық билікке қарсы наразылығын күшейтті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1870 жылғы Маңғыстау көтерілісі"}]}]},{"number":7,"questions":[{"id":"hi-005","t":"1822 жылғы жарғы бойынша аға сұлтан қанша жылға сайланды?","o":["Үш жылға","Өмір бойына","Бір жылға","Бес жылға"],"a":0,"e":"Аға сұлтан үш жыл мерзімге сайланатын. Оның билігі империялық әкімшіліктің бақылауында болды.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"ha-077","t":"Зерттеуші түркі тайпаларының тілін, мақалдарын және географиялық атауларын салыстырмақ. Оған қай еңбек көбірек сәйкес келеді?","o":["Тарих-и Рашиди","Құтты білік","Шайбани-наме","Диуани лұғат ат-түрік"],"a":3,"e":"Махмұд Қашғари сөздігі түркі тілдерімен бірге тайпалардың орналасуы мен фольклоры туралы мәлімет береді.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hk-061","t":"Абылай ханның өмір сүрген жылдарын көрсетіңіз.","o":["1802–1847 жылдар","1711–1781 жылдар","1538–1580 жылдар","1465–1521 жылдар"],"a":1,"e":"Абылайдың өмірі XVIII ғасырға жатады: ол 1711 жылы туып, 1781 жылы қайтыс болды.","l":"A","topic":"Абылай хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hm-044","t":"Тың игеру негізінен Қазақстанның қай бөлігінде өрістеді?","o":["Тек Маңғыстауда","Солтүстік өңірлерінде","Тек Іле Алатауында","Тек Арал теңізінде"],"a":1,"e":"Астық өсіруге қолайлы кең далалы солтүстік өңірлер тың игерудің негізгі аумағы болды.","l":"A","topic":"Тың игеру","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"ha-060","t":"Моңғол империясының әскери-әкімшілік заңдар жинағы қалай аталды?","o":["Ұлы Жасақ","Жеті жарғы","Ескі жол","Қасқа жол"],"a":0,"e":"Ұлы Жасақ моңғол қоғамындағы тәртіп пен әскери басқару қағидаларын қамтыды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-117","t":"Дулати мәліметін Қазақ хандығының құрылуын зерттеуге қолданудың ең орынды себебі қандай?","o":["Еңбекте алғашқы хандар мен Моғолстанға көшу оқиғалары баяндалады","Автор барлық оқиғаны 1771 жылғы сайлаумен шектейді","Еңбек тек Шыңғыс ханның Еуропа жорықтарын баяндайды","Еңбек тек хандықтың салық көлемін есептейді"],"a":0,"e":"«Тарих-и Рашиди» алғашқы қазақ хандары мен Моғолстан тарихын байланыстыра баяндайтын жазба дерек болып табылады.","l":"C","topic":"Қазақ хандығының деректері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":101}},{"id":"ha-013","t":"Беғазы-Дәндібай мәдениеті Қазақстанның қай өңірімен байланысты?","o":["Орталық Қазақстан","Сырдарияның төменгі ағысы","Солтүстік Жетісу","Батыс Қазақстан"],"a":0,"e":"Беғазы-Дәндібай мәдениетінің негізгі ескерткіштері Орталық Қазақстанда орналасқан.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-082","t":"Патша үкіметінің қоныстандыру саясаты қазақтардың шаруашылығына қандай қысым жасады?","o":["Барлық жерді қазақ қауымдарына қайтарды","Қыстауларға салық салуды мәңгі тоқтатты","Дәстүрлі жайылымдық жерлердің көлемін қысқартты","Көшпелі шаруашылыққа шексіз жер берді"],"a":2,"e":"Қоныс аударушыларға жер бөлу кезінде қазақтардың пайдаланатын аумақтары тарылды. Бұл көшпелі шаруашылыққа әсер етті.","l":"B","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":195}},{"id":"hm-119","t":"Мемлекеттілікке қатысты тұжырымдарды бағалаңыз: I — 1936 жылы Қазақстан одақтас республика болды; II — 1990 жылғы декларация толық тәуелсіздік туралы 1991 жылғы заңнан бұрын қабылданды; III — 1920 жылы Қазақстан БҰҰ-ға қабылданды; IV — 1991 жылы тәуелсіздік заң жүзінде бекітілді.","o":["I, III және IV дұрыс","I, II және IV дұрыс","I, II және III дұрыс","II, III және IV дұрыс"],"a":1,"e":"Одақтас республика мәртебесі 1936 жылы берілді. Декларация — 1990, тәуелсіздік заңы — 1991, БҰҰ мүшелігі — 1992 жыл.","l":"C","topic":"Мемлекеттілік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hk-038","t":"1598 жылы Қазақ хандығының тағына кім отырды?","o":["Есім хан","Хақназар хан","Керей хан","Тәуке хан"],"a":0,"e":"Тәуекел қайтыс болғаннан кейін билік Есім ханға өтті.","l":"A","topic":"Есім хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}}],"contexts":[{"id":"hce-07","title":"Тасмола және мұртты обалар","text":"Тасмола мәдениеті Орталық Қазақстанның ерте темір дәуірімен байланысты. Оның белгілі белгілерінің бірі мұртты обалар деп аталатын кешендер. Мұндай ескерткіштерде оба мен тас тізбектері ұштасады. Құрылым жерлеу дәстүрін және ғұрыптық кеңістікті зерттеуге көмектеседі. Археологтер тас тізбектердің бағытын, қабірдегі заттарды және кешендердің ұқсастығын салыстырады. Ерекше сыртқы пішін ғылыми атаудың қалыптасуына ықпал еткен. Алайда пішіннің өзі барлық қызметті бір ғана түсіндірмемен шектеуге негіз емес. Ескерткіштің мерзімі мен мәдени орнын бірнеше белгі арқылы анықтау қажет. Бір кешенді түсіндіруде тұтас археологиялық орта ескеріледі.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":135},"questions":[{"id":"hce-07-1","t":"«Тасмола және мұртты обалар» контексі: Тасмоланың негізгі аймағы қайсы?","o":["Жетісудың оңтүстігі","Ніл аңғары","Еділдің батысы","Орталық Қазақстан"],"a":3,"e":"Мәтіндегі деректер «Орталық Қазақстан» деген жауапты негіздейді. Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді.","l":"A","topic":"Тасмола және мұртты обалар"},{"id":"hce-07-2","t":"«Тасмола және мұртты обалар» контексі: Тасмоланың белгілі ескерткіш түрі қайсы?","o":["Мұртты оба","Керуен сарай","Медресе","Минарет"],"a":0,"e":"Мәтіндегі деректер «Мұртты оба» деген жауапты негіздейді. Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді.","l":"A","topic":"Тасмола және мұртты обалар"},{"id":"hce-07-3","t":"«Тасмола және мұртты обалар» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді","Тасмола тек ортағасырлық қала мәдениеті","Сыртқы пішін барлық ғұрыптық қызметті толық дәлелдейді","Мұртты оба атауы билеушінің төл есімі"],"a":0,"e":"Мәтіндегі деректер «Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді» деген жауапты негіздейді. Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді.","l":"B","topic":"Тасмола және мұртты обалар"},{"id":"hce-07-4","t":"«Тасмола және мұртты обалар» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Құрылым мен олжаларды салыстыру кешенді дәлірек түсіндіреді","Бір атау ескерткіштің барлық кезеңін анықтайды","Қабірдегі заттар құрылыс мерзіміне қатыссыз","Ғұрыптық нысанды тек қазіргі сыртқы көрініспен түсіндіру жеткілікті"],"a":0,"e":"Мәтіндегі деректер «Құрылым мен олжаларды салыстыру кешенді дәлірек түсіндіреді» деген жауапты негіздейді. Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді.","l":"B","topic":"Тасмола және мұртты обалар"},{"id":"hce-07-5","t":"«Тасмола және мұртты обалар» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Құрылым мен олжаларды салыстыру кешенді дәлірек түсіндіреді","Тасмола мәдениеті Орталық Қазақстанның ерте темір дәуірімен байланысты.","Тас тізбектер жерлеу-ғұрыптық кешеннің құрамына кіреді","Сыртқы пішін барлық ғұрыптық қызметті толық дәлелдейді"],"a":3,"e":"Мәтіндегі деректер «Сыртқы пішін барлық ғұрыптық қызметті толық дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Құрылым мен олжаларды салыстыру кешенді дәлірек түсіндіреді.","l":"C","topic":"Тасмола және мұртты обалар"}]},{"id":"hcl-07","title":"XIX ғасырдағы жәрмеңке саудасы","text":"Дала экономикасына тауар-ақша қатынастарының енуі сауда орындарының маңызын арттырды. Жәрмеңкелер мал шаруашылығын қалалық қолөнермен және сырттан әкелінген тауарлармен байланыстырды.\n\nҚарқаралы маңындағы Қоянды жәрмеңкесі дала саудасының ірі орталықтарының бірі болды. Қазақ шаруалары саудаға мал, жүн, тері сияқты шаруашылық өнімдерін шығарды. Айырбас пен ақшаға сауда жасау тауар-ақша қатынастарының таралуын жеделдетті. Көпестер далаға мата, темір бұйымдар және күнделікті тұрмыс тауарларын жеткізді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":17},"questions":[{"id":"hcl-07-1","t":"«XIX ғасырдағы жәрмеңке саудасы» контексі: Қарқаралы маңындағы белгілі жәрмеңке қайсы?","o":["Мәкәржі","Ирбит","Төменгі Новгород","Қоянды"],"a":3,"e":"Қарқаралы маңындағы Қоянды жәрмеңкесі дала саудасының ірі орталықтарының бірі болды.","l":"A","topic":"XIX ғасырдағы жәрмеңке саудасы"},{"id":"hcl-07-2","t":"«XIX ғасырдағы жәрмеңке саудасы» контексі: Жәрмеңкеге қазақ шаруалары негізінен қандай тауар әкелді?","o":["Компьютерлерді","Теңіз кемелерін","Автомобильдерді","Мал және мал өнімдерін"],"a":3,"e":"Қазақ шаруалары саудаға мал, жүн, тері сияқты шаруашылық өнімдерін шығарды.","l":"A","topic":"XIX ғасырдағы жәрмеңке саудасы"},{"id":"hcl-07-3","t":"«XIX ғасырдағы жәрмеңке саудасы» контексі: Екі деректі сәйкестендіріңіз. 1) Қарқаралы маңындағы белгілі жәрмеңке қайсы. 2) Жәрмеңкелер қандай қатынастардың дамуын жеделдетті.","o":["1 — Мәкәржі; 2 — Құл иеленушілік қатынастардың","1 — Қоянды; 2 — Натуралды шаруашылықтың оқшаулануының","1 — Қоянды; 2 — Тауар-ақша қатынастарының","1 — Ирбит; 2 — Тауар-ақша қатынастарының"],"a":2,"e":"Қарқаралы маңындағы Қоянды жәрмеңкесі дала саудасының ірі орталықтарының бірі болды. Айырбас пен ақшаға сауда жасау тауар-ақша қатынастарының таралуын жеделдетті.","l":"B","topic":"XIX ғасырдағы жәрмеңке саудасы"},{"id":"hcl-07-4","t":"«XIX ғасырдағы жәрмеңке саудасы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Жәрмеңкеге қазақ шаруалары негізінен қандай тауар әкелді? 2) Саудагерлер далаға көбіне не әкелді?","o":["1 — Автомобильдерді; 2 — Тек асыл тұқымды жылқылар","1 — Мал және мал өнімдерін; 2 — Тек киіз үйлер","1 — Теңіз кемелерін; 2 — Мата мен тұрмыстық бұйымдар","1 — Мал және мал өнімдерін; 2 — Мата мен тұрмыстық бұйымдар"],"a":3,"e":"Қазақ шаруалары саудаға мал, жүн, тері сияқты шаруашылық өнімдерін шығарды. Көпестер далаға мата, темір бұйымдар және күнделікті тұрмыс тауарларын жеткізді.","l":"B","topic":"XIX ғасырдағы жәрмеңке саудасы"},{"id":"hcl-07-5","t":"«XIX ғасырдағы жәрмеңке саудасы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Сырттан тауар келуі қазақ шаруаларының нарыққа өнім шығармай, тек тұтынушы ретінде қатысқанын көрсетеді.","Жәрмеңкелер мал шаруашылығын кең нарықпен байланыстырып, экономикалық тәуелділіктер мен мүмкіндіктерді қатар туғызды.","Мал өнімдерінің сатылуы тауар-ақша қатынастарын әлсіретіп, айырбастың барлық түрін бірдей тоқтатты.","Жәрмеңкелердің өсуі мал шаруашылығын сыртқы сұраныстан тәуелсіз етіп, өзіндік тұйық жүйені күшейтті."],"a":1,"e":"Жәрмеңкелер мал шаруашылығын кең нарықпен байланыстырып, экономикалық тәуелділіктер мен мүмкіндіктерді қатар туғызды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"XIX ғасырдағы жәрмеңке саудасы"}]}]},{"number":8,"questions":[{"id":"hm-079","t":"Е.Бекмахановтың қудалануы кеңестік ғылымның қандай мәселесін көрсетті?","o":["Тарихи зерттеудің идеологиялық бақылауға тәуелділігін","Ғылыми институттардың түгел шетелде орналасуын","Мұрағаттардың мүлде болмауын","Ғалымдардың саясаттан толық тәуелсіздігін"],"a":0,"e":"Бекмахановтың Кенесары қозғалысын бағалауы саяси айыптауға ұшырады.","l":"B","topic":"Ғылым","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":229}},{"id":"hi-101","t":"Оқиғаларды ертеден кешке қарай орналастырыңыз: 1) Кенесарының хан сайлануы; 2) Тастөбе шайқасы; 3) Ақбұлақ шайқасы.","o":["1 → 2 → 3","2 → 1 → 3","2 → 3 → 1","3 → 1 → 2"],"a":2,"e":"Тастөбе шайқасы 1837 жылы, Ақбұлақ шайқасы 1838 жылы өтті. Кенесары 1841 жылы хан сайланды.","l":"C","topic":"Ұлт-азаттық қозғалыстар хронологиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":155}},{"id":"hk-029","t":"Хақназар хан өз мүддесіне пайдаланған қарсыластық қай билеушілер арасында болды?","o":["Есен-бұға мен Абылай арасында","II Абдаллах пен Баба сұлтан арасында","Тоғылық Темір мен Сұлу арасында","Батый мен Берке арасында"],"a":1,"e":"Бұхар билеушісі II Абдаллах пен Ташкент билеушісі Баба сұлтан арасындағы тартыс Хақназардың оңтүстік саясатына әсер етті.","l":"A","topic":"Хақназар ханның сыртқы саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":114}},{"id":"hk-085","t":"Қарақұмдағы ортақ жасақ құру шешімі қандай қажеттіліктен туды?","o":["Көршілермен барлық елшілік қатынасты тоқтатудан","Әр жүздің жасақтарын өзара соғысқа дайындау қажеттілігінен","Бытыраңқы күштерді сыртқы жауға қарсы біріктіру қажеттілігінен","Сырдария қалаларын қорғаудан біржола бас тартудан"],"a":2,"e":"Ортақ қауіп қазақ жүздері мен ру-тайпаларының әскери ынтымағын қажет етті.","l":"B","topic":"Қарақұм құрылтайы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":187}},{"id":"ha-027","t":"Тасмола мәдениеті қай дәуірге жатады?","o":["Ерте темір дәуірі","Энеолит","Кейінгі орта ғасыр","Неолит"],"a":0,"e":"Тасмола — Орталық Қазақстанның ерте темір дәуіріндегі археологиялық мәдениеті.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-058","t":"Қазақстанның мемлекеттік тәуелсіздігі туралы Конституциялық заң қашан қабылданды?","o":["1990 жылғы 25 қазанда","1992 жылғы 4 маусымда","1991 жылғы 16 желтоқсанда","1993 жылғы 28 қаңтарда"],"a":2,"e":"1991 жылғы 16 желтоқсан Қазақстанның мемлекеттік тәуелсіздігін заң жүзінде бекітті.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":252}},{"id":"hm-017","t":"Түрксібтің солтүстік және оңтүстік бөліктері 1930 жылы қай станцияда түйісті?","o":["Айнабұлақ","Арыс","Қандыағаш","Шу"],"a":0,"e":"Түрксіб жолының екі бөлігі 1930 жылы Айнабұлақта түйісті.","l":"A","topic":"Индустрияландыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":254}},{"id":"hi-023","t":"Сырдарияның төменгі ағысында отаршылдыққа қарсы көтеріліс басқарған батыр кім?","o":["Амангелді Иманов","Махамбет Өтемісұлы","Жанқожа Нұрмұхамедұлы","Саржан Қасымұлы"],"a":2,"e":"Жанқожа Нұрмұхамедұлы Сыр бойында Хиуа езгісіне және Ресей отарлауына қарсы күресті.","l":"A","topic":"Жанқожа және Есет көтерілістері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":168}},{"id":"hi-098","t":"Қазақстан аумағындағы Азамат соғысының негізгі жылдарын көрсетіңіз.","o":["1905–1907 жылдар","1929–1931 жылдар","1918–1920 жылдар","1914–1916 жылдар"],"a":2,"e":"Қазақстанда азамат соғысының негізгі әскери қимылдары 1918–1920 жылдары жүрді.","l":"A","topic":"Азамат соғысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":285}},{"id":"ha-123","t":"Қазбада жергілікті қыш ыдыстар, шетелдік теңгелер және мал сүйектері қатар табылды. Қай қорытынды деректердің бәрімен үйлеседі?","o":["Мал сүйектері халықаралық сауданың болмағанын көрсетеді","Қала жергілікті өндіріс, сыртқы сауда және дала шаруашылығымен байланысқан","Теңгелер тек мал шаруашылығының болғанын дәлелдейді","Қалада қолөнер болмаған, барлық өнім тек сырттан әкелінген"],"a":1,"e":"Қыш ыдыстар жергілікті өндірісті, шетелдік теңгелер сыртқы айырбасты, мал өнімдері қаланың даламен байланысын зерттеуге мүмкіндік береді.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}}],"contexts":[{"id":"hce-08","title":"Берелдегі сақталу жағдайы","text":"Берел қорымы Шығыс Қазақстандағы Алтай өңірімен байланысты. Қорғандардан адамдармен бірге жерленген аттар мен ат әбзелдері табылған. Кейбір қабірдегі табиғи жағдай ағаш, тері және тоқыма сияқты органикалық материалдардың сақталуына ықпал етті. Бұл бұйымдар ежелгі шеберліктің ұсақ бөлшектерін зерттеуге мүмкіндік береді. Жылқыны бірге жерлеу ғұрып пен әлеуметтік мәртебені талдауға негіз болады. Бірақ бір қабірдегі салтты барлық көшпеліге өзгеріссіз таратуға болмайды. Зат материалы, сақталу ортасы және орналасуы бірге қарастырылады. Табиғи орта адамның тіршілігіне ғана емес, археологиялық деректің бізге жетуіне де әсер етеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":73},"questions":[{"id":"hce-08-1","t":"«Берелдегі сақталу жағдайы» контексі: Берел қай өңірмен байланысты?","o":["Қаратау","Үстірт","Торғай","Алтай"],"a":3,"e":"Мәтіндегі деректер «Алтай» деген жауапты негіздейді. Ағаш пен тері органикалық материалға жатады.","l":"A","topic":"Берелдегі сақталу жағдайы"},{"id":"hce-08-2","t":"«Берелдегі сақталу жағдайы» контексі: Адаммен бірге жерленген жануар қайсы?","o":["Піл","Кенгуру","Жылқы","Түйеқұс"],"a":2,"e":"Мәтіндегі деректер «Жылқы» деген жауапты негіздейді. Ағаш пен тері органикалық материалға жатады.","l":"A","topic":"Берелдегі сақталу жағдайы"},{"id":"hce-08-3","t":"«Берелдегі сақталу жағдайы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Ағаш пен тері органикалық материалға жатады","Берел тек теңіз сауда порты болған","Органикалық материал барлық қорымда бірдей сақталады","Ат әбзелі тек егіншілік құралы болған"],"a":0,"e":"Мәтіндегі деректер «Ағаш пен тері органикалық материалға жатады» деген жауапты негіздейді. Ағаш пен тері органикалық материалға жатады.","l":"B","topic":"Берелдегі сақталу жағдайы"},{"id":"hce-08-4","t":"«Берелдегі сақталу жағдайы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Сақталу ортасы зерттеушіге жеткен деректің толықтығына ықпал етеді","Жақсы сақталған зат міндетті түрде кейінгі ғасырда жасалған","Бір қабір бүкіл көшпелі қоғамның салтын толық дәлелдейді","Табиғи жағдай археологиялық олжаға әсер етпейді"],"a":0,"e":"Мәтіндегі деректер «Сақталу ортасы зерттеушіге жеткен деректің толықтығына ықпал етеді» деген жауапты негіздейді. Ағаш пен тері органикалық материалға жатады.","l":"B","topic":"Берелдегі сақталу жағдайы"},{"id":"hce-08-5","t":"«Берелдегі сақталу жағдайы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Берел қорымы Шығыс Қазақстандағы Алтай өңірімен байланысты.","Органикалық материал барлық қорымда бірдей сақталады","Ағаш пен тері органикалық материалға жатады","Сақталу ортасы зерттеушіге жеткен деректің толықтығына ықпал етеді"],"a":1,"e":"Мәтіндегі деректер «Органикалық материал барлық қорымда бірдей сақталады» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сақталу ортасы зерттеушіге жеткен деректің толықтығына ықпал етеді.","l":"C","topic":"Берелдегі сақталу жағдайы"}]},{"id":"hcl-08","title":"Шоқан Уәлихановтың ғылыми қызметі","text":"XIX ғасырдағы қазақ ағартушылары ғылым мен мәдениеттің дамуына үлес қосты. Шоқанның зерттеулері халық ауыз әдебиетін, этнографияны және Орталық Азия туралы білімді ұштастырды.\n\nШоқан Уәлиханов қырғыздың «Манас» жырын зерттеп, оның бір бөлігін жазып алды. Шоқан халықтардың тұрмысын, салтын және тарихын зерттеген этнограф болды. Ол Омбыдағы Сібір кадет корпусында білім алды. Қашғарияға жасаған сапары Орталық Азия туралы ғылыми мәліметтерді толықтырды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-08-1","t":"«Шоқан Уәлихановтың ғылыми қызметі» контексі: «Манас» жырын зерттеп, бір бөлігін жазып алған ғалым кім?","o":["Міржақып Дулатұлы","Шоқан Уәлиханов","Ахмет Байтұрсынұлы","Ыбырай Алтынсарин"],"a":1,"e":"Шоқан Уәлиханов қырғыздың «Манас» жырын зерттеп, оның бір бөлігін жазып алды.","l":"A","topic":"Шоқан Уәлихановтың ғылыми қызметі"},{"id":"hcl-08-2","t":"«Шоқан Уәлихановтың ғылыми қызметі» контексі: Шоқанның қызметіне сәйкес келетін сала қайсы?","o":["Этнография","Ядролық физика","Ғарыш техникасы","Молекулалық генетика"],"a":0,"e":"Шоқан халықтардың тұрмысын, салтын және тарихын зерттеген этнограф болды.","l":"A","topic":"Шоқан Уәлихановтың ғылыми қызметі"},{"id":"hcl-08-3","t":"«Шоқан Уәлихановтың ғылыми қызметі» контексі: Екі деректі сәйкестендіріңіз. 1) «Манас» жырын зерттеп, бір бөлігін жазып алған ғалым кім. 2) Шоқан білім алған әскери оқу орны қай қалада еді.","o":["1 — Шоқан Уәлиханов; 2 — Түркістанда","1 — Ахмет Байтұрсынұлы; 2 — Қоқанда","1 — Ыбырай Алтынсарин; 2 — Омбыда","1 — Шоқан Уәлиханов; 2 — Омбыда"],"a":3,"e":"Шоқан Уәлиханов қырғыздың «Манас» жырын зерттеп, оның бір бөлігін жазып алды. Ол Омбыдағы Сібір кадет корпусында білім алды.","l":"B","topic":"Шоқан Уәлихановтың ғылыми қызметі"},{"id":"hcl-08-4","t":"«Шоқан Уәлихановтың ғылыми қызметі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Шоқанның қызметіне сәйкес келетін сала қайсы? 2) Шоқанның құпия сапарымен байланысты аймақ қайсы?","o":["1 — Этнография; 2 — Қашғария","1 — Ядролық физика; 2 — Қашғария","1 — Этнография; 2 — Скандинавия","1 — Ғарыш техникасы; 2 — Оңтүстік Америка"],"a":0,"e":"Шоқан халықтардың тұрмысын, салтын және тарихын зерттеген этнограф болды. Қашғарияға жасаған сапары Орталық Азия туралы ғылыми мәліметтерді толықтырды.","l":"B","topic":"Шоқан Уәлихановтың ғылыми қызметі"},{"id":"hcl-08-5","t":"«Шоқан Уәлихановтың ғылыми қызметі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Шоқанның мұрасы далалық зерттеу мен жазба талдауды біріктірген ғылыми ағартушылықтың үлгісі болды.","Шоқанның кадет корпусында оқуы оның зерттеулерінің тек әскери есептермен шектелгенін білдіреді.","Қашғария сапары этнографиялық бақылаудан гөрі жергілікті халық туралы бұрынғы мәліметтерді қайталаумен шектелді.","Манас жырын жазып алу ауыз әдебиетінен бас тартып, тек шетелдік жазба деректерге сүйену бағытын көрсетті."],"a":0,"e":"Шоқанның мұрасы далалық зерттеу мен жазба талдауды біріктірген ғылыми ағартушылықтың үлгісі болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Шоқан Уәлихановтың ғылыми қызметі"}]}]},{"number":9,"questions":[{"id":"hi-092","t":"1916 жылғы Жетісу көтерілісінің көпұлтты сипатын не көрсетеді?","o":["Қозғалыстың тек Еуропада өтуі","Қазақтармен бірге қырғыздар мен ұйғырлардың қатысуы","Көтерілісшілердің барлығының шетел әскерінен болуы","Оған тек бір қазақ ауылының қатысуы"],"a":1,"e":"Жетісудағы қозғалысқа бірнеше халықтың өкілдері қатысты. Сондықтан оның сипаты көпұлтты болды.","l":"A","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-117","t":"Соғыс кезіндегі Қазақстанды сипаттайтын қатарды таңдаңыз: әскери үлес; өнеркәсіптік үлес; ауыл шаруашылығының міндеті.","o":["Ядролық полигонды жабу; көшірілген кәсіпорындарды іске қосу; азық-түлік салғыртын алғаш енгізу","Қазақстандықтардың майданда шайқасуы; теңгені енгізу; тың жерлерді жаппай игеру","Қазақстандықтардың майданда шайқасуы; көшірілген кәсіпорындарды іске қосу; майданды азықпен қамту","БҰҰ-ға кіру; әскери зауыттарды түгел жабу; тек жеке сауданы кеңейту"],"a":2,"e":"1941–1945 жылдары Қазақстан майданға адам жіберді, эвакуацияланған кәсіпорындарды қабылдады және армияны азық-түлікпен қамтамасыз етті.","l":"C","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hk-105","t":"Қазақ хандығының құрылу үдерісін себеп-салдар ретімен орналастырыңыз.","o":["Жетісуға көшу → Әбілқайыр билігіне наразылық → дербес хандықтың қалыптасуы","Әбілқайыр билігіне наразылық → Жетісуға көшу → дербес хандықтың қалыптасуы","Дербес хандықтың қалыптасуы → Жетісуға көшу → Әбілқайыр билігіне наразылық","Әбілқайыр билігіне наразылық → дербес хандықтың қалыптасуы → Жетісуға көшу"],"a":1,"e":"Наразылық қозғалысқа түрткі болды, Моғолстанның батысындағы қоныс жаңа саяси бірлестіктің қалыптасуына жағдай жасады.","l":"C","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":101}},{"id":"ha-082","t":"Зерттеу бағытына Айша бибі және Бабаджа қатын кесенелері енгізілді. Экспедиция қай қала өңіріне баруы керек?","o":["Сарайшық","Сығанақ","Сауран","Тараз"],"a":3,"e":"Айша бибі мен Бабаджа қатын кесенелері Тараз маңында орналасқан.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":50}},{"id":"hi-077","t":"1867–1868 жылғы бөліністе Орал және Торғай облыстары қай генерал-губернаторлыққа кірді?","o":["Батыс Сібір","Кавказ","Орынбор","Түркістан"],"a":2,"e":"Орынбор генерал-губернаторлығына Орал мен Торғай облыстары бағынды.","l":"B","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":169}},{"id":"hm-052","t":"Желтоқсан оқиғасы қай жылы болды?","o":["1991 жылы","1959 жылы","1986 жылы","1979 жылы"],"a":2,"e":"Алматыдағы жастар наразылығы 1986 жылғы желтоқсанда өтті.","l":"A","topic":"Қайта құру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"ha-032","t":"Үйсін билеушісінің ордасы қай қалада болған?","o":["Сығанақ","Янгикент","Сарайшық","Чигу"],"a":3,"e":"Үйсін күнбиінің ордасы Чигу қаласында орналасқан.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-028","t":"Хақназар хан «ант беріскен шартты» қай Бұхар билеушісімен жасасты?","o":["Нәдір шахпен","Мұхаммед Шайбанимен","II Абдаллахпен","Имамқұлимен"],"a":2,"e":"Хақназар II Абдаллахпен шарт жасасып, оңтүстіктегі саяси жағдайын нығайтуды көздеді.","l":"A","topic":"Хақназар ханның сыртқы саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":108}},{"id":"hk-002","t":"Керей мен Жәнібекті өз жеріне қабылдаған Моғолстан билеушісі кім?","o":["Тоқтамыс","Есен-бұға","Өзбек хан","Батый"],"a":1,"e":"Моғолстан ханы Есен-бұға екі сұлтанға өз мемлекетінің батыс бөлігінен қоныс берді.","l":"A","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":99}},{"id":"ha-014","t":"Беғазы-Дәндібай мәдениеті қай кезеңге жатады?","o":["Ерте орта ғасыр","Кейінгі қола дәуірі","Ерте палеолит","Мезолит"],"a":1,"e":"Беғазы-Дәндібай мәдениеті Қазақстанның кейінгі қола дәуіріндегі қоғамын сипаттайды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}}],"contexts":[{"id":"hce-09","title":"Үйсіндердің билігі мен шаруашылығы","text":"Үйсіндер туралы мәлімет қытай жазба деректерінде кездеседі. Негізгі қоныстанған аймағы Жетісу болды. Билеушісі күнби деп аталды, орталығы Чигу қаласымен байланыстырылады. Үйсін шаруашылығында мал өсіру маңызды орын алды, сонымен бірге егіншілік те болды. Қоныстар мен қорымдардан табылған заттар жазба мәліметті толықтырады. Қытаймен қатынаста елшілік және әулеттік байланыс қолданылды. Бұл далалық бірлестіктің сыртқы саясат жүргізгенін көрсетеді. Мал шаруашылығының болуы отырықшы кәсіптің болмағанын білдірмейді. Бір қоғамда бірнеше шаруашылық түрі қатар өмір сүре алады. Жазба және заттай деректерді салыстыру осы байланысты нақтылауға мүмкіндік береді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2},"questions":[{"id":"hce-09-1","t":"«Үйсіндердің билігі мен шаруашылығы» контексі: Үйсін билеушісінің атағы қандай?","o":["Жабғу","Күнби","Қаған","Сюбашы"],"a":1,"e":"Мәтіндегі деректер «Күнби» деген жауапты негіздейді. Үйсіндердің негізгі аймағы Жетісу болды.","l":"A","topic":"Үйсіндердің билігі мен шаруашылығы"},{"id":"hce-09-2","t":"«Үйсіндердің билігі мен шаруашылығы» контексі: Үйсін орталығы ретінде аталған қала қайсы?","o":["Чигу","Сарай-Бату","Суяб","Жаңакент"],"a":0,"e":"Мәтіндегі деректер «Чигу» деген жауапты негіздейді. Үйсіндердің негізгі аймағы Жетісу болды.","l":"A","topic":"Үйсіндердің билігі мен шаруашылығы"},{"id":"hce-09-3","t":"«Үйсіндердің билігі мен шаруашылығы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Үйсіндерде егіншілік мүлде болмаған","Чигу Алтын Орданың Еділдегі қаласы болған","Үйсіндердің негізгі аймағы Жетісу болды","Күнби тек әскер басшысының атағы болған"],"a":2,"e":"Мәтіндегі деректер «Үйсіндердің негізгі аймағы Жетісу болды» деген жауапты негіздейді. Үйсіндердің негізгі аймағы Жетісу болды.","l":"B","topic":"Үйсіндердің билігі мен шаруашылығы"},{"id":"hce-09-4","t":"«Үйсіндердің билігі мен шаруашылығы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Елшілік тек соғыс болмаған қоғамда ғана кездеседі","Мал өсірген қауым егіншілікпен айналыса алмайды","Қытай дерегі археологияны қажетсіз етеді","Мал шаруашылығы мен егіншілік бір қоғамда ұштаса алады"],"a":3,"e":"Мәтіндегі деректер «Мал шаруашылығы мен егіншілік бір қоғамда ұштаса алады» деген жауапты негіздейді. Үйсіндердің негізгі аймағы Жетісу болды.","l":"B","topic":"Үйсіндердің билігі мен шаруашылығы"},{"id":"hce-09-5","t":"«Үйсіндердің билігі мен шаруашылығы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Мал шаруашылығы мен егіншілік бір қоғамда ұштаса алады","Үйсіндерде егіншілік мүлде болмаған","Үйсіндер туралы мәлімет қытай жазба деректерінде кездеседі.","Үйсіндердің негізгі аймағы Жетісу болды"],"a":1,"e":"Мәтіндегі деректер «Үйсіндерде егіншілік мүлде болмаған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Мал шаруашылығы мен егіншілік бір қоғамда ұштаса алады.","l":"C","topic":"Үйсіндердің билігі мен шаруашылығы"}]},{"id":"hcl-09","title":"Ыбырай Алтынсарин және мектеп","text":"Ыбырай Алтынсарин қазақ балаларының білім алуын кеңейтуді көздеді. Оның қызметі мектеп ашумен қатар, оқыту мазмұнын және балаларға арналған оқу құралдарын жасаумен байланысты болды.\n\nЫбырай Алтынсарин балаларға арналған «Қазақ хрестоматиясын» құрастырды. Ол зайырлы мектептер ашып, балаларға пайдалы білім беруге ұмтылды. Торғайдағы қазақ балаларына арналған мектеп 1864 жылы ашылды. Ыбырай қыз балалардың білім алуын да ұйымдастырып, оқу мүмкіндігін кеңейтті.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-09-1","t":"«Ыбырай Алтынсарин және мектеп» контексі: «Қазақ хрестоматиясының» авторы кім?","o":["Мұхтар Әуезов","Қаныш Сәтбаев","Шоқан Уәлиханов","Ыбырай Алтынсарин"],"a":3,"e":"Ыбырай Алтынсарин балаларға арналған «Қазақ хрестоматиясын» құрастырды.","l":"A","topic":"Ыбырай Алтынсарин және мектеп"},{"id":"hcl-09-2","t":"«Ыбырай Алтынсарин және мектеп» контексі: Ыбырайдың ағартушылық қызметінің негізгі бағыты қандай?","o":["Шекара бекінісін салу","Зайырлы білім беру","Кен орнын игеру","Хандық жасақ құру"],"a":1,"e":"Ол зайырлы мектептер ашып, балаларға пайдалы білім беруге ұмтылды.","l":"A","topic":"Ыбырай Алтынсарин және мектеп"},{"id":"hcl-09-3","t":"«Ыбырай Алтынсарин және мектеп» контексі: Екі деректі сәйкестендіріңіз. 1) «Қазақ хрестоматиясының» авторы кім. 2) Ыбырайдың Торғайда ашқан мектебі қай жылы жұмысын бастады.","o":["1 — Ыбырай Алтынсарин; 2 — 1864 жылы","1 — Қаныш Сәтбаев; 2 — 1913 жылы","1 — Ыбырай Алтынсарин; 2 — 1822 жылы","1 — Шоқан Уәлиханов; 2 — 1864 жылы"],"a":0,"e":"Ыбырай Алтынсарин балаларға арналған «Қазақ хрестоматиясын» құрастырды. Торғайдағы қазақ балаларына арналған мектеп 1864 жылы ашылды.","l":"B","topic":"Ыбырай Алтынсарин және мектеп"},{"id":"hcl-09-4","t":"«Ыбырай Алтынсарин және мектеп» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Ыбырайдың ағартушылық қызметінің негізгі бағыты қандай? 2) Ыбырай қолдаған білім беру бағыттарының бірі қайсы?","o":["1 — Кен орнын игеру; 2 — Мектептерді жабу","1 — Зайырлы білім беру; 2 — Тек сұлтандарды оқыту","1 — Хандық жасақ құру; 2 — Қыз балаларды оқыту","1 — Зайырлы білім беру; 2 — Қыз балаларды оқыту"],"a":3,"e":"Ол зайырлы мектептер ашып, балаларға пайдалы білім беруге ұмтылды. Ыбырай қыз балалардың білім алуын да ұйымдастырып, оқу мүмкіндігін кеңейтті.","l":"B","topic":"Ыбырай Алтынсарин және мектеп"},{"id":"hcl-09-5","t":"«Ыбырай Алтынсарин және мектеп» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Мектеп пен оқулық жасау білім беруді тек діни мекемелер аясында сақтауға бағытталды.","Мектеп, оқулық және қыздар білімі жөніндегі бастамалар қоғамды білім арқылы жаңарту мақсатын көрсетті.","Торғай мектебінің ашылуы ағартушылықты күнделікті өмірден бөліп, тек әдеби тәжірибеге айналдырды.","Қыздар мектебін қолдау жалпы білім мүмкіндігін кеңейтуден гөрі балаларды оқытуға шектеу қоюды көздеді."],"a":1,"e":"Мектеп, оқулық және қыздар білімі жөніндегі бастамалар қоғамды білім арқылы жаңарту мақсатын көрсетті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Ыбырай Алтынсарин және мектеп"}]}]},{"number":10,"questions":[{"id":"hi-107","t":"XIX ғасырдағы қозғалыстарды уақыт ретімен көрсетіңіз: 1) Маңғыстау көтерілісі; 2) Исатай–Махамбет көтерілісі; 3) Жанқожаның Ресейге қарсы көтерілісі.","o":["1 → 2 → 3","2 → 1 → 3","2 → 3 → 1","3 → 2 → 1"],"a":2,"e":"Исатай–Махамбет көтерілісі 1836–1838 жылдары, Жанқожа көтерілісі 1856–1857 жылдары өтті. Маңғыстау көтерілісі 1870 жылы болды.","l":"C","topic":"Ұлт-азаттық қозғалыстар хронологиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":184}},{"id":"hm-081","t":"Тың игерудің демографиялық әсерінің бірі қандай болды?","o":["Өзге республикалардан қоныс аударушылар санының артуы","Тек маусымдық туристердің көбеюі","Қалалардағы халықтың толық жойылуы","Барлық көші-қонның тоқтауы"],"a":0,"e":"Тың игеруге жұмыс күші қажет болғандықтан, Қазақстанға басқа республикалардан қоныс аудару күшейді.","l":"B","topic":"Тың игеру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"hi-014","t":"Исатай мен Махамбет көтерілісі кезінде Бөкей Ордасының ханы кім болды?","o":["Керей хан","Әбілқайыр хан","Жәңгір хан","Қасым хан"],"a":2,"e":"Көтеріліс Жәңгір хан билік құрған Бөкей Ордасында өтті. Оның себептеріне жер тапшылығы мен әлеуметтік қысым жатты.","l":"A","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":151}},{"id":"hm-046","t":"Тың игеру кезінде топыраққа қауіп төндірген экологиялық үдеріс қандай?","o":["Мұхит тасуы","Мәңгі мұздықтың ұлғаюы","Жанартаудың атқылауы","Жел эрозиясы"],"a":3,"e":"Далалық жерді шамадан тыс жырту жел эрозиясын күшейтті.","l":"A","topic":"Тың игеру","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hk-100","t":"Жиембет пен Бұқардың қай тарихи кезеңдермен байланысы дұрыс көрсетілген?","o":["Жиембет — Есім дәуірі, Бұқар — Абылай дәуірі","Жиембет — Керей дәуірі, Бұқар — Жәңгір дәуірі","Жиембет — Тәуке дәуірі, Бұқар — Хақназар дәуірі","Жиембет — Қасым дәуірі, Бұқар — Тәуекел дәуірі"],"a":0,"e":"Жиембет XVII ғасырдағы Есім дәуірімен, ал Бұқар XVIII ғасырдағы Абылай дәуірімен байланысты.","l":"B","topic":"Жыраулар дәуірін салыстыру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"ha-068","t":"Ақ Орданы XIV ғасырдың екінші жартысында күшейткен билеуші кім?","o":["Бумын қаған","Мұса хан","Ұрыс хан","Сұлу қаған"],"a":2,"e":"Ұрыс хан тұсында Ақ Орда нығайып, Жошы ұлысының шығыс бөлігіндегі саяси ықпалы артты.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hk-086","t":"1723 жылғы ауыр босқыншылықтың негізгі сыртқы себебі қайсы?","o":["Бұхар билеушілерінің Жетісуды түгел басып алуы","Ресейдің барлық жүзде хандық билікті жоюы","Моғолстан әскерінің Сыр бойына келуі","Жоңғар әскерінің кең көлемді шапқыншылығы"],"a":3,"e":"Жоңғар шапқыншылығы қоныстардан айырылуға, халықтың көшуіне және шаруашылықтың күйзелуіне әкелді.","l":"A","topic":"Ақтабан шұбырынды","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":155}},{"id":"ha-117","t":"Ноғай Ордасы мен Әбілқайыр хандығын салыстырған қай пікір дұрыс?","o":["Екеуінің негізгі орталығы бір ғана Суяб қаласы болған","Екеуін де Сатұқ Боғра хан құрған","Екеуі де Түргеш қағанатының тікелей VI ғасырдағы мұрагері","Екеуі де Алтын Орда әлсіреген дәуірдегі Дешті Қыпшақ саяси кеңістігімен байланысты"],"a":3,"e":"Екі бірлестік Алтын Ордадан кейінгі саяси өзгерістер барысында қалыптасты; олардың орталықтары мен билеушілері бөлек болды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-065","t":"Ресейдегі монархияны құлатқан 1917 жылғы оқиға қандай?","o":["Бірінші дүниежүзілік соғыстың басталуы","Азамат соғысының аяқталуы","Қазан төңкерісі","Ақпан революциясы"],"a":3,"e":"1917 жылғы Ақпан революциясынан кейін патша монархиясы құлады.","l":"A","topic":"1917 жылғы революциялар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":233}},{"id":"hm-035","t":"Соғыс жылдарындағы тыл еңбеккері, әйгілі тары өсірушіні атаңыз.","o":["Шығанақ Берсиев","Геннадий Колбин","Әлкей Марғұлан","Ермұхан Бекмаханов"],"a":0,"e":"Ш.Берсиев тарыдан жоғары өнім алған тыл еңбеккері ретінде танылды.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":285}}],"contexts":[{"id":"hce-10","title":"Қаңлылардың Сырдариядағы кеңістігі","text":"Қаңлылардың негізгі қоныстанған аумағы Сырдарияның орта ағысымен байланысты. Өзен аңғарлары егіншілік пен тұрақты қоныстарға жағдай жасады. Мал шаруашылығы да маңызды болды. Қытай жазбалары мен археологиялық материалдар қаңлы тарихын зерттеуге көмектеседі. Қалалар мен қоныстар дала және отырықшы аймақ арасындағы байланысты күшейтті. Сауда жолдары көршілермен қатынасты кеңейтті. Өзен бойындағы өмірді тек бір кәсіппен шектеу дұрыс емес. Табиғи орта әртүрлі шаруашылықты ұштастыруға мүмкіндік берді. Заттай және жазба мәліметтің сәйкес келетін тұсын салыстыру қажет. Бір дерек түрі екіншісін толығымен алмастырмайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6},"questions":[{"id":"hce-10-1","t":"«Қаңлылардың Сырдариядағы кеңістігі» контексі: Қаңлылардың негізгі аймағы қай өзенмен байланысты?","o":["Ертіс","Іле","Еділ","Сырдария"],"a":3,"e":"Мәтіндегі деректер «Сырдария» деген жауапты негіздейді. Қытай жазбалары мен археология қаңлы тарихын толықтырады.","l":"A","topic":"Қаңлылардың Сырдариядағы кеңістігі"},{"id":"hce-10-2","t":"«Қаңлылардың Сырдариядағы кеңістігі» контексі: Өзен аңғары қандай кәсіпке қолайлы болды?","o":["Егіншілікке","Кеме құрастыруға","Мұхит балықшылығына","Орман шаруашылығына"],"a":0,"e":"Мәтіндегі деректер «Егіншілікке» деген жауапты негіздейді. Қытай жазбалары мен археология қаңлы тарихын толықтырады.","l":"A","topic":"Қаңлылардың Сырдариядағы кеңістігі"},{"id":"hce-10-3","t":"«Қаңлылардың Сырдариядағы кеңістігі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Қытай жазбалары мен археология қаңлы тарихын толықтырады","Қаңлы тарихы туралы еш жазба дерек жоқ","Қаңлылар тек бір ғана шаруашылықпен айналысқан","Сауда жолдары көршілермен байланысты толық үзген"],"a":0,"e":"Мәтіндегі деректер «Қытай жазбалары мен археология қаңлы тарихын толықтырады» деген жауапты негіздейді. Қытай жазбалары мен археология қаңлы тарихын толықтырады.","l":"B","topic":"Қаңлылардың Сырдариядағы кеңістігі"},{"id":"hce-10-4","t":"«Қаңлылардың Сырдариядағы кеңістігі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Қала мен дала арасында шаруашылық байланыс орнаған","Өзен бойында мал шаруашылығы мүмкін болмаған","Бір жазба барлық қоныстың орнын толық дәлелдейді","Сауда тек саяси оқшаулануға әкелген"],"a":0,"e":"Мәтіндегі деректер «Қала мен дала арасында шаруашылық байланыс орнаған» деген жауапты негіздейді. Қытай жазбалары мен археология қаңлы тарихын толықтырады.","l":"B","topic":"Қаңлылардың Сырдариядағы кеңістігі"},{"id":"hce-10-5","t":"«Қаңлылардың Сырдариядағы кеңістігі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Қаңлылардың негізгі қоныстанған аумағы Сырдарияның орта ағысымен байланысты.","Қаңлылар тек бір ғана шаруашылықпен айналысқан","Қытай жазбалары мен археология қаңлы тарихын толықтырады","Қала мен дала арасында шаруашылық байланыс орнаған"],"a":1,"e":"Мәтіндегі деректер «Қаңлылар тек бір ғана шаруашылықпен айналысқан» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Қала мен дала арасында шаруашылық байланыс орнаған.","l":"C","topic":"Қаңлылардың Сырдариядағы кеңістігі"}]},{"id":"hcl-10","title":"Абайдың рухани мұрасы","text":"Қазақ қоғамының рухани жаңаруында Абай шығармалары ерекше орын алды. Ақын білім, еңбек, адамгершілік туралы ойларын өлеңмен де, қара сөзбен де жеткізді.\n\nАбай Құнанбайұлының «Қарасөздері» адам мен қоғам туралы философиялық ойларға құрылған. Абай қазақ жазба әдебиетінің дамуына шешуші үлес қосты. Ақын білімге ұмтылуды, адал еңбекті және адамгершілікті жоғары бағалады. Абай XIX ғасырдың екінші жартысы мен XX ғасырдың басында өмір сүрді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-10-1","t":"«Абайдың рухани мұрасы» контексі: «Қарасөздердің» авторы кім?","o":["Санжар Асфендияров","Сәкен Сейфуллин","Махамбет Өтемісұлы","Абай Құнанбайұлы"],"a":3,"e":"Абай Құнанбайұлының «Қарасөздері» адам мен қоғам туралы философиялық ойларға құрылған.","l":"A","topic":"Абайдың рухани мұрасы"},{"id":"hcl-10-2","t":"«Абайдың рухани мұрасы» контексі: Абай қандай әдебиеттің негізін қалаушылардың бірі?","o":["Латын шежіресінің","Ежелгі грек драмасының","Көне мысыр жазуының","Қазақ жазба әдебиетінің"],"a":3,"e":"Абай қазақ жазба әдебиетінің дамуына шешуші үлес қосты.","l":"A","topic":"Абайдың рухани мұрасы"},{"id":"hcl-10-3","t":"«Абайдың рухани мұрасы» контексі: Екі деректі сәйкестендіріңіз. 1) «Қарасөздердің» авторы кім. 2) Абайдың ағартушылық ойына сәйкес құндылық қайсы.","o":["1 — Сәкен Сейфуллин; 2 — Рулық өшпенділік","1 — Махамбет Өтемісұлы; 2 — Білім мен еңбек","1 — Абай Құнанбайұлы; 2 — Білімнен бас тарту","1 — Абай Құнанбайұлы; 2 — Білім мен еңбек"],"a":3,"e":"Абай Құнанбайұлының «Қарасөздері» адам мен қоғам туралы философиялық ойларға құрылған. Ақын білімге ұмтылуды, адал еңбекті және адамгершілікті жоғары бағалады.","l":"B","topic":"Абайдың рухани мұрасы"},{"id":"hcl-10-4","t":"«Абайдың рухани мұрасы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Абай қандай әдебиеттің негізін қалаушылардың бірі? 2) Абай шығармашылығы қай ғасырлар тоғысына жатады?","o":["1 — Ежелгі грек драмасының; 2 — XIX–XX ғасырлар","1 — Латын шежіресінің; 2 — XIII–XIV ғасырлар","1 — Қазақ жазба әдебиетінің; 2 — XIX–XX ғасырлар","1 — Қазақ жазба әдебиетінің; 2 — XV–XVI ғасырлар"],"a":2,"e":"Абай қазақ жазба әдебиетінің дамуына шешуші үлес қосты. Абай XIX ғасырдың екінші жартысы мен XX ғасырдың басында өмір сүрді.","l":"B","topic":"Абайдың рухани мұрасы"},{"id":"hcl-10-5","t":"«Абайдың рухани мұрасы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Абайдың өлеңдері мен қарасөздері қоғам мәселесін жеке адамның мінезі мен еңбегінен бөлек қарастырды.","Білімді дәріптеуі Абайдың ұлттық әдебиеттен бас тартып, тек басқа тілдегі үлгілерді қайталағанын көрсетеді.","Абайдың әдеби және философиялық мұрасы жеке адамның дамуын қоғамның рухани жаңаруымен байланыстырды.","Қарасөздердің философиялық сипаты олардың ағартушылық және қоғамдық маңызын шектеп тастады."],"a":2,"e":"Абайдың әдеби және философиялық мұрасы жеке адамның дамуын қоғамның рухани жаңаруымен байланыстырды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Абайдың рухани мұрасы"}]}]},{"number":11,"questions":[{"id":"ha-078","t":"Сопылық идеяларды түркі тіліндегі өлеңдер арқылы таратқан ортағасырлық мұраны көрсетіңіз.","o":["Диуани хикмет","Кодекс Куманикус","Диуани лұғат ат-түрік","Жамиғ ат-тауарих"],"a":0,"e":"Ясауи хикметтері діни-адамгершілік ойларды халық түсінетін түркі тілінде жеткізді.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"ha-054","t":"Қимақ қағанатының негізгі аумағы қай өзенмен байланысты?","o":["Ертіс","Шу","Жайық","Талас"],"a":0,"e":"Қимақтардың саяси орталығы мен негізгі қоныстары Ертіс бойында орналасты.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":22}},{"id":"hk-101","t":"Қазақ хандарын ертеден кейінге қарай дұрыс орналастырыңыз.","o":["Керей → Бұрындық → Қасым → Хақназар","Қасым → Керей → Хақназар → Бұрындық","Бұрындық → Хақназар → Қасым → Керей","Хақназар → Бұрындық → Керей → Қасым"],"a":0,"e":"Алдымен Керей, одан кейін Бұрындық, XVI ғасырдың басында Қасым, кейін Хақназар билік құрды.","l":"C","topic":"Қазақ хандарының хронологиясы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hi-047","t":"Торғайда қазақ балалары үшін мектеп ашқан ағартушы кім?","o":["Ыбырай Алтынсарин","Мұрат Мөңкеұлы","Құрманғазы Сағырбайұлы","Шоқан Уәлиханов"],"a":0,"e":"Ыбырай Алтынсарин қазақ даласында зайырлы білім беруді дамытты. Оның Торғай мектебі 1864 жылы ашылды.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"hi-067","t":"1822 және 1824 жылғы реформалардың ортақ нәтижесі қандай болды?","o":["Жүздер арасындағы барлық шекараның жойылуы","Бүкіл қазақ жерінің тәуелсіздік алуы","Қазақ хандығы аумағының кеңеюі","Орта және Кіші жүзде хандық биліктің жойылуы"],"a":3,"e":"Екі реформа да хандық билікті жойып, империялық әкімшілік бақылауды күшейтті.","l":"B","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":195}},{"id":"hm-022","t":"Карлаг атауы қандай мекемені білдіреді?","o":["Түрксіб басқармасын","Алматы кинофабрикасын","Қазақ педагогикалық институтын","Қарағанды еңбекпен түзеу лагерін"],"a":3,"e":"Карлаг кеңестік жазалау жүйесіне кірген Қарағанды еңбекпен түзеу лагері болды.","l":"A","topic":"Қуғын-сүргін","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hk-005","t":"Қазақ хандығының қалыптасуы жөнінде мәлімет беретін Дулатидің еңбегін көрсетіңіз.","o":["«Ақиқат сыйы»","«Құтты білік»","«Диуани хикмет»","«Тарих-и Рашиди»"],"a":3,"e":"«Тарих-и Рашиди» Моғолстан мен Қазақ хандығы тарихына қатысты маңызды жазба дерек саналады.","l":"A","topic":"Тарихи деректер","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":94}},{"id":"hm-113","t":"Ядролық полигон тарихына қатысты дұрыс тұжырымдар жиынтығын табыңыз: I — алғашқы сынақ 1949 жылы өтті; II — «Невада–Семей» сынақтарға қарсы шықты; III — полигон 1991 жылы жабылды; IV — қозғалыс тың жерді жыртуды ұйымдастыру үшін құрылды.","o":["II, III және IV","I, II және III","I, III және IV","I, II және IV"],"a":1,"e":"Семейдегі алғашқы сынақ 1949 жылы жасалды. «Невада–Семей» антиядролық қозғалыс болды, ал полигон 1991 жылы жабылды.","l":"C","topic":"Ядролық полигон","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"ha-011","t":"Энеолит дәуірінің Шебір қонысы орналасқан өңірді атаңыз.","o":["Сарыарқа","Алтай","Маңғыстау","Жетісу"],"a":2,"e":"Шебір — Маңғыстау аумағындағы энеолиттік тұрақ.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":78}},{"id":"hk-013","t":"Қазақ хандығындағы ең жоғары билеушінің лауазымы қандай болды?","o":["Хан","Би","Жасауыл","Ауыл ақсақалы"],"a":0,"e":"Хан мемлекеттің жоғарғы билеушісі болды, ал би мен ақсақалдың қызметі өзге міндеттерді қамтыды.","l":"A","topic":"Қазақ хандығының басқарылуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}}],"contexts":[{"id":"hce-11","title":"Ғұндардың саяси ұйымдасуы","text":"Ғұндардың жоғарғы билеушісі шаньюй деп аталды. Мөде тұсында саяси бірлестік күшейді. Әскери бағыныштылық кең аумақты басқаруда маңызды болды. Қытаймен қатынаста соғыс та, келіссөз де қолданылды. Елшілік пен шекара мәселелері көрші елдердің мүдделері тоғысқанын көрсетеді. Ғұндарды тек үздіксіз соғыс жүргізген қауым деп сипаттау толық емес. Жазба деректерді пайдаланғанда оларды қалдырған ортаның көзқарасын ескеру қажет. Саяси билік, әскери құрылым және сыртқы байланыс өзара ұштасқан. Бір ғана әскери хабар қоғам өмірінің барлық жағын толық ашпайды. Сондықтан әртүрлі деректерді салыстыру тарихи түсінікті кеңейтеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":71},"questions":[{"id":"hce-11-1","t":"«Ғұндардың саяси ұйымдасуы» контексі: Ғұн билеушісінің жоғарғы атағы қайсы?","o":["Беклербек","Шаньюй","Жабғу","Қазы"],"a":1,"e":"Мәтіндегі деректер «Шаньюй» деген жауапты негіздейді. Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды.","l":"A","topic":"Ғұндардың саяси ұйымдасуы"},{"id":"hce-11-2","t":"«Ғұндардың саяси ұйымдасуы» контексі: Ғұн бірлестігін күшейткен тұлға кім?","o":["Қасым","Мөде","Сұлу","Едіге"],"a":1,"e":"Мәтіндегі деректер «Мөде» деген жауапты негіздейді. Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды.","l":"A","topic":"Ғұндардың саяси ұйымдасуы"},{"id":"hce-11-3","t":"«Ғұндардың саяси ұйымдасуы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Шаньюй тек саудагерлердің басшысы болған","Ғұндар көршілерімен тек соғыс арқылы ғана қатынасқан","Мөде Қарахан мемлекетінің билеушісі болған","Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды"],"a":3,"e":"Мәтіндегі деректер «Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды» деген жауапты негіздейді. Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды.","l":"B","topic":"Ғұндардың саяси ұйымдасуы"},{"id":"hce-11-4","t":"«Ғұндардың саяси ұйымдасуы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Жазба авторының ортасын ескерудің қажеті жоқ","Бір шайқас барлық қоғамдық қатынасты толық түсіндіреді","Келіссөздің болуы әскери қауіптің болмағанын дәлелдейді","Әскери құрылым мен дипломатияны бірге қарастыру саяси тарихты толықтырады"],"a":3,"e":"Мәтіндегі деректер «Әскери құрылым мен дипломатияны бірге қарастыру саяси тарихты толықтырады» деген жауапты негіздейді. Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды.","l":"B","topic":"Ғұндардың саяси ұйымдасуы"},{"id":"hce-11-5","t":"«Ғұндардың саяси ұйымдасуы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Ғұндардың жоғарғы билеушісі шаньюй деп аталды.","Әскери құрылым мен дипломатияны бірге қарастыру саяси тарихты толықтырады","Қытаймен қатынаста әскери және дипломатиялық тәсілдер қолданылды","Ғұндар көршілерімен тек соғыс арқылы ғана қатынасқан"],"a":3,"e":"Мәтіндегі деректер «Ғұндар көршілерімен тек соғыс арқылы ғана қатынасқан» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Әскери құрылым мен дипломатияны бірге қарастыру саяси тарихты толықтырады.","l":"C","topic":"Ғұндардың саяси ұйымдасуы"}]},{"id":"hcl-11","title":"Қазақтың күй өнері","text":"XIX ғасырдағы қазақ мәдениетінде күйшілік мектептер дамыды. Домбыра күйлері халықтың тұрмысын, еркіндікке ұмтылысын және туған жерге деген сезімін бейнеледі.\n\nҚұрманғазы Сағырбайұлы «Адай» сияқты төкпе күйлердің авторы ретінде белгілі. Тәттімбет Қазанғапұлының «Саржайлау» күйі шертпе күй дәстүрімен байланысты. Домбыра қазақтың күй мұрасын жеткізген негізгі ұлттық аспаптардың бірі болды. Күйшілік дәстүр ұрпақтан ұрпаққа берілетін рухани мәдениет саласы саналады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10},"questions":[{"id":"hcl-11-1","t":"«Қазақтың күй өнері» контексі: «Адай» күйінің авторы кім?","o":["Құрманғазы Сағырбайұлы","Ақан сері","Біржан сал","Тәттімбет Қазанғапұлы"],"a":0,"e":"Құрманғазы Сағырбайұлы «Адай» сияқты төкпе күйлердің авторы ретінде белгілі.","l":"A","topic":"Қазақтың күй өнері"},{"id":"hcl-11-2","t":"«Қазақтың күй өнері» контексі: «Саржайлау» күйін кім шығарған?","o":["Құрманғазы Сағырбайұлы","Тәттімбет Қазанғапұлы","Жаяу Мұса","Мұхит Мерәліұлы"],"a":1,"e":"Тәттімбет Қазанғапұлының «Саржайлау» күйі шертпе күй дәстүрімен байланысты.","l":"A","topic":"Қазақтың күй өнері"},{"id":"hcl-11-3","t":"«Қазақтың күй өнері» контексі: Екі деректі сәйкестендіріңіз. 1) «Адай» күйінің авторы кім. 2) Күйлер негізінен қандай аспаппен орындалды.","o":["1 — Құрманғазы Сағырбайұлы; 2 — Домбырамен","1 — Тәттімбет Қазанғапұлы; 2 — Домбырамен","1 — Ақан сері; 2 — Саксофонмен","1 — Құрманғазы Сағырбайұлы; 2 — Рояльмен"],"a":0,"e":"Құрманғазы Сағырбайұлы «Адай» сияқты төкпе күйлердің авторы ретінде белгілі. Домбыра қазақтың күй мұрасын жеткізген негізгі ұлттық аспаптардың бірі болды.","l":"B","topic":"Қазақтың күй өнері"},{"id":"hcl-11-4","t":"«Қазақтың күй өнері» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) «Саржайлау» күйін кім шығарған? 2) Күйшілік мұра қай мәдениет түріне жатады?","o":["1 — Жаяу Мұса; 2 — Әскери әкімшілікке","1 — Тәттімбет Қазанғапұлы; 2 — Рухани мәдениетке","1 — Құрманғазы Сағырбайұлы; 2 — Рухани мәдениетке","1 — Тәттімбет Қазанғапұлы; 2 — Тау-кен технологиясына"],"a":1,"e":"Тәттімбет Қазанғапұлының «Саржайлау» күйі шертпе күй дәстүрімен байланысты. Күйшілік дәстүр ұрпақтан ұрпаққа берілетін рухани мәдениет саласы саналады.","l":"B","topic":"Қазақтың күй өнері"},{"id":"hcl-11-5","t":"«Қазақтың күй өнері» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Күй авторларының белгілі болуы шығармалардың халық жадында таралуын тоқтатқанын көрсетеді.","Домбырада орындалуы күйді тек тұрмыстық дағдыға айналдырып, рухани мұра ретінде қарастыруға мүмкіндік бермейді.","Төкпе мен шертпе мектептерінің айырмасы олардың бір ұлттық мәдени кеңістікке жатпайтынын дәлелдейді.","Авторлары мен орындаушылық мектептері әртүрлі болғанымен, күй мұрасы ұлттық рухани мәдениеттің ортақ бөлігін құрады."],"a":3,"e":"Авторлары мен орындаушылық мектептері әртүрлі болғанымен, күй мұрасы ұлттық рухани мәдениеттің ортақ бөлігін құрады. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қазақтың күй өнері"}]}]},{"number":12,"questions":[{"id":"ha-021","t":"Кир патшаға қарсы күреспен байланысты сақ билеушісін атаңыз.","o":["Бумын","Едіге","Томирис","Сұлу"],"a":2,"e":"Томирис парсы патшасы Кирге қарсы күрескен массагеттердің билеушісі ретінде белгілі.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hm-038","t":"КСРО-да соғыстан кейін азық-түлікке арналған карточкалық жүйе қай жылы жойылды?","o":["1947 жылы","1965 жылы","1941 жылы","1954 жылы"],"a":0,"e":"Карточкалық жүйе 1947 жылы жойылып, ақша реформасы жүргізілді.","l":"A","topic":"Соғыстан кейінгі Қазақстан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"hi-111","t":"Ағартушылық оқиғаларды реттеңіз: 1) «Қазақ хрестоматиясының» басылуы; 2) Бөкей Ордасындағы зайырлы мектептің ашылуы; 3) Торғай мектебінің ашылуы.","o":["3 → 2 → 1","2 → 1 → 3","2 → 3 → 1","1 → 2 → 3"],"a":2,"e":"Бөкей Ордасындағы мектеп 1841 жылы, Торғай мектебі 1864 жылы ашылды. Хрестоматия 1879 жылы жарық көрді.","l":"C","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":191}},{"id":"hk-036","t":"Тәуекел ханның Мауараннахрға соңғы ірі жорығы қай жылы болды?","o":["1598 жылы","1511 жылы","1680 жылы","1779 жылы"],"a":0,"e":"Тәуекел 1598 жылы Мауараннахрға жорық жасады; сол жылы жарақаттан кейін қайтыс болды.","l":"A","topic":"Тәуекел хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":111}},{"id":"hm-080","t":"Қ.Сәтбаев пен Е.Бекмахановтың ғылыми бағыттарын дұрыс ажыратыңыз.","o":["Сәтбаев — геология, Бекмаханов — тарих","Сәтбаев — музыка, Бекмаханов — ботаника","Сәтбаев — театр, Бекмаханов — химия","Сәтбаев — құқық, Бекмаханов — астрономия"],"a":0,"e":"Қ.Сәтбаев кен қорларын зерттеген геолог, Е.Бекмаханов Қазақстан тарихын зерттеген тарихшы болды.","l":"B","topic":"Ғылым","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hi-040","t":"XIX ғасырдың екінші жартысында Омбы мен Семей арасындағы су қатынасы қай өзенмен жүргізілді?","o":["Сырдариямен","Ертіспен","Шумен","Таласпен"],"a":1,"e":"Омбы мен Семей Ертіс бойында орналасқан. Пароход қатынасы осы өзен арқылы дамыды.","l":"A","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":161}},{"id":"ha-107","t":"Қай тұжырымдар дұрыс? I. Ботай — энеолит. II. Беғазы-Дәндібай — ерте темір дәуірі. III. Тасмола — ерте темір дәуірі.","o":["I және III","II және III","Тек II","I және II"],"a":0,"e":"Ботай энеолитке, Беғазы-Дәндібай қола дәуіріне, Тасмола ерте темір дәуіріне жатады.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-097","t":"XV–XVI ғасырлардағы Моғолстан мен Қазақ хандығын бірге зерттегенде қай еңбекті таңдау орынды?","o":["«Құтты білік»","«Кодекс Куманикус»","«Диуани луғат ат-түрік»","«Тарих-и Рашиди»"],"a":3,"e":"Дулатидің еңбегі осы екі мемлекеттің өзара байланыстары мен алғашқы қазақ хандары жөнінде мәлімет береді.","l":"B","topic":"Жазба деректер","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":94}},{"id":"hi-007","t":"Табын руының батыры, XIX ғасырдың 20-жылдарында отарлық саясатқа қарсы күрескен тұлға кім?","o":["Амангелді Иманов","Балуан Шолақ","Бекболат Әшекеев","Жоламан Тіленшіұлы"],"a":3,"e":"Жоламан Тіленшіұлы жердің тартып алынуына қарсы көтеріліс басқарды.","l":"A","topic":"Жоламан және Саржан көтерілістері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":159}},{"id":"hm-051","t":"1979 жылы неміс автономиясын құру жоспарына қарсылық қай қалада көрінді?","o":["Қызылорда","Атырау","Тараз","Целиноград"],"a":3,"e":"1979 жылғы Целиноград оқиғалары неміс автономиясын құру жоспарына қарсы наразылықпен байланысты болды.","l":"A","topic":"Тоқырау","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}}],"contexts":[{"id":"hce-12","title":"Ұлы Даланың тарихи-мәдени қызметі","text":"Ұлы Даланың табиғи жағдайы көшпелі мал шаруашылығына ықпал етті. Маусымдық жайылымды пайдалану малға азық табуға көмектесті. Дала отырықшы өңірлерден оқшау болған жоқ. Керуен жолдары тауарлармен бірге технология мен мәдени түсініктерді таратты. Далалық кеңістік Шығыс пен Батыс арасындағы көлік дәлізі қызметін атқарды. Табиғи орта маңызды болғанымен, барлық тарихи өзгерісті тек климатпен түсіндіруге болмайды. Қоғамдық ұйымдасу мен көрші елдермен байланыс та әсер етті. Көшпелі және отырықшы шаруашылық өзара ықпалдасты. Айырбас екі ортаның қажеттіліктерін ұштастырды. Сондықтан даланың тарихын бірнеше факторды қатар ескеріп талдаған дұрыс.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":81},"questions":[{"id":"hce-12-1","t":"«Ұлы Даланың тарихи-мәдени қызметі» контексі: Маусымдық жайылым қай кәсіпке тән?","o":["Кеме жасауға","Орман бағбандығына","Көшпелі мал шаруашылығына","Теңіз балықшылығына"],"a":2,"e":"Мәтіндегі деректер «Көшпелі мал шаруашылығына» деген жауапты негіздейді. Керуен арқылы тауармен қатар мәдени түсініктер де таралды.","l":"A","topic":"Ұлы Даланың тарихи-мәдени қызметі"},{"id":"hce-12-2","t":"«Ұлы Даланың тарихи-мәдени қызметі» контексі: Дала қандай бағыттарды байланыстыратын дәліз болды?","o":["Тек Африка мен Антарктиданы","Тек Исландия мен Гренландияны","Тек Америка мен Австралияны","Шығыс пен Батысты"],"a":3,"e":"Мәтіндегі деректер «Шығыс пен Батысты» деген жауапты негіздейді. Керуен арқылы тауармен қатар мәдени түсініктер де таралды.","l":"A","topic":"Ұлы Даланың тарихи-мәдени қызметі"},{"id":"hce-12-3","t":"«Ұлы Даланың тарихи-мәдени қызметі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Барлық тарихи өзгерісті тек климат анықтады","Керуен арқылы тауармен қатар мәдени түсініктер де таралды","Керуен жолдары тек әскери мақсатқа пайдаланылды","Дала қоғамы отырықшы дүниемен толық оқшау өмір сүрді"],"a":1,"e":"Мәтіндегі деректер «Керуен арқылы тауармен қатар мәдени түсініктер де таралды» деген жауапты негіздейді. Керуен арқылы тауармен қатар мәдени түсініктер де таралды.","l":"B","topic":"Ұлы Даланың тарихи-мәдени қызметі"},{"id":"hce-12-4","t":"«Ұлы Даланың тарихи-мәдени қызметі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Шаруашылық пен сыртқы қатынас бір-біріне әсер етпейді","Табиғи және қоғамдық факторларды бірге қарастыру қажет","Көшпелі қоғамда ұйымдасу еш рөл атқармайды","Айырбас тек бір тарапқа ғана пайдалы болуы мүмкін"],"a":1,"e":"Мәтіндегі деректер «Табиғи және қоғамдық факторларды бірге қарастыру қажет» деген жауапты негіздейді. Керуен арқылы тауармен қатар мәдени түсініктер де таралды.","l":"B","topic":"Ұлы Даланың тарихи-мәдени қызметі"},{"id":"hce-12-5","t":"«Ұлы Даланың тарихи-мәдени қызметі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Ұлы Даланың табиғи жағдайы көшпелі мал шаруашылығына ықпал етті.","Дала қоғамы отырықшы дүниемен толық оқшау өмір сүрді","Табиғи және қоғамдық факторларды бірге қарастыру қажет","Керуен арқылы тауармен қатар мәдени түсініктер де таралды"],"a":1,"e":"Мәтіндегі деректер «Дала қоғамы отырықшы дүниемен толық оқшау өмір сүрді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Табиғи және қоғамдық факторларды бірге қарастыру қажет.","l":"C","topic":"Ұлы Даланың тарихи-мәдени қызметі"}]},{"id":"hcl-12","title":"Қарқаралы петициясы","text":"XX ғасырдың басында қазақ зиялылары халықтың талаптарын заңды өтініштер арқылы жеткізуге тырысты. Ұжымдық петициялар жер, білім, дін және саяси құқықтар мәселелерін көтерді.\n\nҚарқаралы петициясы 1905 жылғы саяси қозғалыс жағдайында жазылды. Петицияны дайындауға Әлихан Бөкейхан, Ахмет Байтұрсынұлы және Жақып Ақбаев қатысты. Петиция — билікке көпшілік атынан тапсырылатын жазбаша талап-өтініш. Өтініште жерді қорғау, білім және азаматтық құқықтарға қатысты талаптар көтерілді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10},"questions":[{"id":"hcl-12-1","t":"«Қарқаралы петициясы» контексі: Қарқаралы петициясы қай жылы жазылды?","o":["1841 жылы","1824 жылы","1905 жылы","1937 жылы"],"a":2,"e":"Қарқаралы петициясы 1905 жылғы саяси қозғалыс жағдайында жазылды.","l":"A","topic":"Қарқаралы петициясы"},{"id":"hcl-12-2","t":"«Қарқаралы петициясы» контексі: Петицияны дайындауға қатысқан тұлға кім?","o":["Әлихан Бөкейхан","Қаныш Сәтбаев","Дінмұхамед Қонаев","Нұрғиса Тілендиев"],"a":0,"e":"Петицияны дайындауға Әлихан Бөкейхан, Ахмет Байтұрсынұлы және Жақып Ақбаев қатысты.","l":"A","topic":"Қарқаралы петициясы"},{"id":"hcl-12-3","t":"«Қарқаралы петициясы» контексі: Екі деректі сәйкестендіріңіз. 1) Қарқаралы петициясы қай жылы жазылды. 2) Петиция дегеніміз не.","o":["1 — 1905 жылы; 2 — Жасырын әскери бұйрық","1 — 1824 жылы; 2 — Көпшілік атынан жолданатын жазбаша өтініш","1 — 1841 жылы; 2 — Жеке сауда келісімшарты","1 — 1905 жылы; 2 — Көпшілік атынан жолданатын жазбаша өтініш"],"a":3,"e":"Қарқаралы петициясы 1905 жылғы саяси қозғалыс жағдайында жазылды. Петиция — билікке көпшілік атынан тапсырылатын жазбаша талап-өтініш.","l":"B","topic":"Қарқаралы петициясы"},{"id":"hcl-12-4","t":"«Қарқаралы петициясы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Петицияны дайындауға қатысқан тұлға кім? 2) Петиция талаптарының бірі қандай мәселе болды?","o":["1 — Қаныш Сәтбаев; 2 — Тың игеруді бастау","1 — Әлихан Бөкейхан; 2 — Жер және азаматтық құқықтар","1 — Әлихан Бөкейхан; 2 — Ғарыш станциясын салу","1 — Дінмұхамед Қонаев; 2 — Жер және азаматтық құқықтар"],"a":1,"e":"Петицияны дайындауға Әлихан Бөкейхан, Ахмет Байтұрсынұлы және Жақып Ақбаев қатысты. Өтініште жерді қорғау, білім және азаматтық құқықтарға қатысты талаптар көтерілді.","l":"B","topic":"Қарқаралы петициясы"},{"id":"hcl-12-5","t":"«Қарқаралы петициясы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Петиция жер мәселесін көтергендіктен, білім мен азаматтық құқықтар туралы талаптар екінші құжатта ғана қаралды.","Петиция отарлық жағдайдағы қоғамдық мүддені бейбіт құқықтық жолмен білдіру әрекеті болды.","Ұжымдық өтініш дайындау зиялылардың халық мүддесін құқықтық жолмен білдіруден бас тартқанын көрсетеді.","Құжаттың билікке жолдануы онда көтерілген барлық талаптың дереу орындалғанын дәлелдейді."],"a":1,"e":"Петиция отарлық жағдайдағы қоғамдық мүддені бейбіт құқықтық жолмен білдіру әрекеті болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қарқаралы петициясы"}]}]},{"number":13,"questions":[{"id":"ha-100","t":"Археологиялық қабатта Ботай, Беғазы-Дәндібай және Тасмола мәдениеттері салыстырылды. Ертеден кейінге дұрыс ретті таңдаңыз.","o":["Ботай → Тасмола → Беғазы-Дәндібай","Тасмола → Ботай → Беғазы-Дәндібай","Беғазы-Дәндібай → Тасмола → Ботай","Ботай → Беғазы-Дәндібай → Тасмола"],"a":3,"e":"Энеолиттен кейін қола дәуірі, одан кейін ерте темір дәуірі өтеді; мәдениеттер осы ретпен орналасады.","l":"B","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-011","t":"Исатаймен бірге күресіп, көтеріліс идеясын өлеңмен жеткізген ақын кім?","o":["Шортанбай Қанайұлы","Дулат Бабатайұлы","Мұрат Мөңкеұлы","Махамбет Өтемісұлы"],"a":3,"e":"Махамбет Өтемісұлы көтеріліске қатысып, еркіндік пен күресті жырлады.","l":"A","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":144}},{"id":"hk-025","t":"Қасым ханнан кейін хандық билікке келген оның ұлы кім?","o":["Тәуекел","Абылай","Мамаш","Жәңгір"],"a":2,"e":"Қасым ханнан кейін Мамаш хан билікке келді; кейін хандықта ішкі саяси дағдарыс күшейді.","l":"A","topic":"Қазақ хандары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hk-104","t":"Құқықтық жинақтарды пайда болу кезеңіне қарай реттеңіз.","o":["«Есім ханның ескі жолы» → «Жеті жарғы» → «Қасым ханның қасқа жолы»","«Қасым ханның қасқа жолы» → «Жеті жарғы» → «Есім ханның ескі жолы»","«Қасым ханның қасқа жолы» → «Есім ханның ескі жолы» → «Жеті жарғы»","«Жеті жарғы» → «Қасым ханның қасқа жолы» → «Есім ханның ескі жолы»"],"a":2,"e":"Қасым дәуірі XVI ғасырдың басына, Есім дәуірі XVII ғасырдың басына, Тәуке дәуірі XVII ғасырдың соңы мен XVIII ғасырдың басына жатады.","l":"C","topic":"Қазақ құқығының сабақтастығы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":83}},{"id":"hm-032","t":"1941–1945 жылдары Қазақстан экономикасы қандай міндетке бейімделді?","o":["Ядролық полигонды жабуға","Майданды қажетті өніммен қамтамасыз етуге","Жаппай жекешелендіруге","Тек туристік қызмет көрсетуге"],"a":1,"e":"Соғыс кезінде өнеркәсіп пен ауыл шаруашылығы майдан қажетіне жұмылдырылды.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hm-108","t":"Қай қатарда үш тұлғаның қызметі де дұрыс сәйкестендірілген?","o":["Қ.Сәтбаев — Жезқазғанды зерттеу; Е.Бекмаханов — Кенесары қозғалысын зерттеу; Т.Бигелдинов — шабуылдаушы авиация","Қ.Сәтбаев — Жезқазғанды зерттеу; Е.Бекмаханов — шабуылдаушы авиация; Т.Бигелдинов — Кенесары қозғалысын зерттеу","Қ.Сәтбаев — шабуылдаушы авиация; Е.Бекмаханов — Кенесары қозғалысын зерттеу; Т.Бигелдинов — Жезқазғанды зерттеу","Қ.Сәтбаев — Кенесары қозғалысын зерттеу; Е.Бекмаханов — Жезқазғанды зерттеу; Т.Бигелдинов — шабуылдаушы авиация"],"a":0,"e":"Сәтбаев — геолог, Бекмаханов — тарихшы, Бигелдинов — әскери ұшқыш. Сәйкестендіру олардың нақты еңбектеріне сүйенеді.","l":"C","topic":"Тұлғалар","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-084","t":"Шоқанның Қашғарияға сапарының басты ғылыми нәтижесі қандай?","o":["Қазақ хандығын құруы","Қазақ әліпбиін латынға көшіруі","Аймақтың тарихы мен тұрмысы жөнінде жаңа мәліметтер жинауы","Жетісуда генерал-губернаторлық құруы"],"a":2,"e":"Шоқан Қашғария туралы құнды географиялық, тарихи және этнографиялық материал жинады.","l":"B","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":152}},{"id":"ha-042","t":"Түріктердің әскери қуатын нығайтқан кәсіптің бірін көрсетіңіз.","o":["Темір өндіру және өңдеу","Қағаз басу","Мақта иіру","Қант қайнату"],"a":0,"e":"Темір өндіру мен металл өңдеу түріктерді қару-жарақпен қамтамасыз етті.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-023","t":"Қасым хан тұсында дипломатиялық байланыс орнаған солтүстіктегі мемлекет қайсы?","o":["Сефеви мемлекеті","Мәскеу мемлекеті","Бұхар хандығы","Моғолстан"],"a":1,"e":"Қасым хан тұсында Қазақ хандығы Мәскеу мемлекетімен дипломатиялық қатынас орната бастады.","l":"A","topic":"Қасым ханның сыртқы саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":125}},{"id":"ha-066","t":"Алтын Ордада исламның мемлекеттік дінге айналуын қай ханмен байланыстырады?","o":["Барақ хан","Тоқтамыс хан","Өзбек хан","Батый хан"],"a":2,"e":"Өзбек хан тұсында ислам мемлекеттік дін ретінде орнығып, мұсылмандық институттар нығайды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}}],"contexts":[{"id":"hce-13","title":"Түрік қағанатының құрылу сызбасы","text":"552 жылы Бумын бастаған түріктер Жужан билігіне қарсы шығып, қағанаттың негізін қалады. Естеми батыс бағыттағы жорықтар мен байланыстарда маңызды рөл атқарды. Түріктердің әскери қуатына металл өңдеу тәжірибесі ықпал етті. Тарихи сызба: Жужан билігіне қарсылық → Түрік қағанатының құрылуы → аумақтық ықпалдың кеңеюі. Кең аумақты басқару билеуші әулет пен тайпалардың байланысын қажет етті. Қағанаттың қалыптасуын тек бір шайқаспен түсіндіру жеткіліксіз. Әскери күш, шаруашылық мүмкіндік және саяси ұйымдасу ұштасқан. Кейін ішкі және сыртқы жағдайлар қағанаттың бөлінуіне әсер етті. Сызба оқиғалардың өзара сабақтастығын көрсетеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":144},"questions":[{"id":"hce-13-1","t":"«Түрік қағанатының құрылу сызбасы» контексі: Түрік қағанатын құрған тұлға кім?","o":["Бумын","Мұса","Батый","Сұлу"],"a":0,"e":"Мәтіндегі деректер «Бумын» деген жауапты негіздейді. Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты.","l":"A","topic":"Түрік қағанатының құрылу сызбасы"},{"id":"hce-13-2","t":"«Түрік қағанатының құрылу сызбасы» контексі: Қағанаттың құрылған жылы қайсы?","o":["704","552","603","942"],"a":1,"e":"Мәтіндегі деректер «552» деген жауапты негіздейді. Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты.","l":"A","topic":"Түрік қағанатының құрылу сызбасы"},{"id":"hce-13-3","t":"«Түрік қағанатының құрылу сызбасы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Металл өңдеу әскери қуатқа әсер етпеген","Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты","Түрік қағанаты тек бір қаладан тұрған","Естеми негізінен теңіз флотын басқарған"],"a":1,"e":"Мәтіндегі деректер «Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты» деген жауапты негіздейді. Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты.","l":"B","topic":"Түрік қағанатының құрылу сызбасы"},{"id":"hce-13-4","t":"«Түрік қағанатының құрылу сызбасы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Шаруашылық мүмкіндік саяси ұйымдасуға қатыссыз","Қағанаттың кейінгі бөлінуі оның ешқашан құрылмағанын дәлелдейді","Сызба қарсылық, мемлекет құру және кеңею арасындағы байланысты көрсетеді","Барлық кезең бір күнде толық аяқталған"],"a":2,"e":"Мәтіндегі деректер «Сызба қарсылық, мемлекет құру және кеңею арасындағы байланысты көрсетеді» деген жауапты негіздейді. Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты.","l":"B","topic":"Түрік қағанатының құрылу сызбасы"},{"id":"hce-13-5","t":"«Түрік қағанатының құрылу сызбасы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["552 жылы Бумын бастаған түріктер Жужан билігіне қарсы шығып, қағанаттың негізін қалады.","Түрік қағанаты тек бір қаладан тұрған","Естеми батыс бағыттағы саяси-әскери әрекеттермен байланысты","Сызба қарсылық, мемлекет құру және кеңею арасындағы байланысты көрсетеді"],"a":1,"e":"Мәтіндегі деректер «Түрік қағанаты тек бір қаладан тұрған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сызба қарсылық, мемлекет құру және кеңею арасындағы байланысты көрсетеді.","l":"C","topic":"Түрік қағанатының құрылу сызбасы"}]},{"id":"hcl-13","title":"Ұлттық баспасөздің қалыптасуы","text":"XX ғасыр басындағы баспасөз қоғамдық ойды таратудың маңызды арнасына айналды. Газет пен журналдар білім, жер және елдің болашағы туралы пікірталастарға мүмкіндік берді.\n\n«Қазақ» газеті 1913 жылы Орынборда шыға бастады. Газеттің редакторы Ахмет Байтұрсынұлы болды. «Айқап» журналын Мұхамеджан Сералин басқарды. Ұлттық басылымдар жер, оқу-ағарту, мәдениет және қоғамдық даму мәселелерін көтерді. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7},"questions":[{"id":"hcl-13-1","t":"«Ұлттық баспасөздің қалыптасуы» контексі: «Қазақ» газеті қай жылы шыға бастады?","o":["1946 жылы","1864 жылы","1913 жылы","1928 жылы"],"a":2,"e":"«Қазақ» газеті 1913 жылы Орынборда шыға бастады.","l":"A","topic":"Ұлттық баспасөздің қалыптасуы"},{"id":"hcl-13-2","t":"«Ұлттық баспасөздің қалыптасуы» контексі: «Қазақ» газетінің редакторы кім болды?","o":["Қаныш Сәтбаев","Дінмұхамед Қонаев","Әлкей Марғұлан","Ахмет Байтұрсынұлы"],"a":3,"e":"Газеттің редакторы Ахмет Байтұрсынұлы болды.","l":"A","topic":"Ұлттық баспасөздің қалыптасуы"},{"id":"hcl-13-3","t":"«Ұлттық баспасөздің қалыптасуы» контексі: Екі деректі сәйкестендіріңіз. 1) «Қазақ» газеті қай жылы шыға бастады. 2) «Айқап» журналының редакторы кім.","o":["1 — 1864 жылы; 2 — Мұхамеджан Сералин","1 — 1913 жылы; 2 — Міржақып Дулатұлы","1 — 1913 жылы; 2 — Мұхамеджан Сералин","1 — 1928 жылы; 2 — Сәкен Сейфуллин"],"a":2,"e":"«Қазақ» газеті 1913 жылы Орынборда шыға бастады. «Айқап» журналын Мұхамеджан Сералин басқарды.","l":"B","topic":"Ұлттық баспасөздің қалыптасуы"},{"id":"hcl-13-4","t":"«Ұлттық баспасөздің қалыптасуы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) «Қазақ» газетінің редакторы кім болды? 2) Ұлттық басылымдар қандай мәселелерді талқылады?","o":["1 — Қаныш Сәтбаев; 2 — Жер, оқу-ағарту және қоғамдық даму","1 — Әлкей Марғұлан; 2 — Тек теңіз саудасын","1 — Ахмет Байтұрсынұлы; 2 — Жер, оқу-ағарту және қоғамдық даму","1 — Ахмет Байтұрсынұлы; 2 — Тек спорт нәтижелерін"],"a":2,"e":"Газеттің редакторы Ахмет Байтұрсынұлы болды. Ұлттық басылымдар жер, оқу-ағарту, мәдениет және қоғамдық даму мәселелерін көтерді.","l":"B","topic":"Ұлттық баспасөздің қалыптасуы"},{"id":"hcl-13-5","t":"«Ұлттық баспасөздің қалыптасуы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Ұлттық басылымдар ортақ мәселелерді көтергенімен, оқырман пікірін қалыптастыруға ықпал ете алмады.","Баспасөздегі жер туралы пікірталастар ұлттық саяси санаға емес, тек жеке шаруашылық есебіне қатысты болды.","Ұлттық баспасөз ақпарат таратумен қатар қоғамдық пікір мен ұлттық сана қалыптастыруға ықпал етті.","Әртүрлі редакторлардың болуы газет пен журналдың ағартушылық міндеттері бір-бірін жоққа шығарғанын білдіреді."],"a":2,"e":"Ұлттық баспасөз ақпарат таратумен қатар қоғамдық пікір мен ұлттық сана қалыптастыруға ықпал етті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Ұлттық баспасөздің қалыптасуы"}]}]},{"number":14,"questions":[{"id":"hm-004","t":"Қазақ АКСР-інің астанасы 1929 жылы қай қалаға көшірілді?","o":["Түркістан","Орал","Петропавл","Алматы"],"a":3,"e":"1929 жылы астана Қызылордадан Алматыға ауысты.","l":"A","topic":"Қазақ АКСР","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":229}},{"id":"hi-121","t":"1917 жылғы автономиялық қозғалыстардың дұрыс сәйкестігін таңдаңыз.","o":["Алашорда — II Николай; Түркістан автономиясы — II Александр","Алашорда — Амангелді Иманов; Түркістан автономиясы — Шоқан Уәлиханов","Алашорда — Әлихан Бөкейхан; Түркістан автономиясы — Мұстафа Шоқай","Алашорда — Кенесары Қасымұлы; Түркістан автономиясы — Құрманғазы"],"a":2,"e":"Әлихан Бөкейхан Алашорда үкіметін басқарды. Мұстафа Шоқай Түркістан автономиясы жетекшілерінің бірі болды.","l":"C","topic":"Алаш және Түркістан автономиялары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":229}},{"id":"hm-069","t":"Түрксіб құрылысының экономикалық маңызы неде?","o":["Сыртқы сауданы заңмен жойды","Барлық мал шаруашылығын бірден тоқтатты","Өңірлер арасындағы жүк және шикізат тасымалын кеңейтті","Қазақстанды теміржол желісінен ажыратты"],"a":2,"e":"Теміржол көлік байланысын жақсартып, өндірістік және ауылшаруашылық аудандарын біріктірді.","l":"A","topic":"Индустрияландыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":235}},{"id":"hi-056","t":"«Кішкентай» күйінің авторы кім?","o":["Тәттімбет Қазанғапұлы","Дәулеткерей Шығайұлы","Құрманғазы Сағырбайұлы","Ықылас Дүкенұлы"],"a":2,"e":"«Кішкентай» — Құрманғазының белгілі күйлерінің бірі. Оның шығармашылығында еркіндік тақырыбы көрініс тапты.","l":"A","topic":"XIX ғасырдағы музыка","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":146}},{"id":"ha-020","t":"Сақтардың массагет тайпалары туралы дерек қалдырған грек тарихшысы кім?","o":["Феофан","Птолемей","Геродот","Прокопий"],"a":2,"e":"Геродот еңбектерінде массагеттер мен олардың парсыларға қарсы күресі туралы мәліметтер бар.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":17}},{"id":"hk-051","t":"Тәуке хан тұсында басқаруда кімдердің ықпалы артты?","o":["Билердің","Зауыт директорларының","Мемлекеттік Дума депутаттарының","Генерал-губернаторлардың"],"a":0,"e":"Тәуке дәуірінде билер кеңесінің рөлі күшейіп, билер дауларды шешуге және саяси мәселелерге қатысты.","l":"A","topic":"Тәуке ханның басқаруы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}},{"id":"ha-110","t":"Оқиғаларды ертеден кейінге қарай реттеңіз: 1) Батпақ шайқасы; 2) Атлах шайқасы; 3) Моңғол империясының құрылуы; 4) Терек шайқасы.","o":["2 → 3 → 4 → 1","2 → 3 → 1 → 4","2 → 1 → 3 → 4","3 → 2 → 1 → 4"],"a":1,"e":"Атлах 751, Моңғол империясы 1206, Батпақ 1365, Терек шайқасы 1395 жылға жатады.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-032","t":"1867 жылы Түркістан генерал-губернаторлығына кірген облыстардың бірін көрсетіңіз.","o":["Торғай облысы","Ақмола облысы","Орал облысы","Жетісу облысы"],"a":3,"e":"Түркістан генерал-губернаторлығына Жетісу мен Сырдария облыстары кірді.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":169}},{"id":"hm-093","t":"Жекешелендірудің мәнін анықтаңыз.","o":["Барлық ақшаны айналымнан алу","Мемлекеттік мүлікті жеке меншікке беру","Тек шекара белгілерін орнату","Барлық жеке мүлікті мемлекетке өткізу"],"a":1,"e":"Жекешелендіру нарыққа көшу кезінде меншік құрылымын өзгертудің бір жолы болды.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hk-099","t":"«Жеті жарғы» мен билер кеңесін қатар зерттеу қай тақырыпты ашуға көмектеседі?","o":["Қазақ қоғамының құқықтық және саяси ұйымдасуын","Моғолстандағы әскери ондық жүйесін","Бұхардағы хан тағын мұралау тәртібін","Алтын Ордадағы ақша реформасын"],"a":0,"e":"Заңдар мен билердің қызметі хандықтағы басқару, сот және қоғамдық келісім жүйесін сипаттайды.","l":"B","topic":"Тәуке хан дәуірі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":109}}],"contexts":[{"id":"hce-14","title":"Батыс Түрік қағанатының он оқ жүйесі","text":"603 жылы Түрік қағанаты бөлініп, Батыс Түрік қағанаты қалыптасты. Оның негізгі орталық аймағы Жетісу болды. Суяб маңызды саяси орталық саналды. Тайпалар он оқ жүйесімен ұйымдасты, дулу мен нушиби топтары саяси өмірге қатысты. Тайпалық тартыстар билеушінің беделіне және мемлекеттің тұтастығына әсер етті. Сонымен бірге қалалар мен керуен жолдары шаруашылық байланысты күшейтті. Қағанат өмірін тек әскери көшпенділікпен шектеуге болмайды. Қала, сауда және дипломатия да маңызды болды. Ішкі бірлік пен сыртқы қысым тұрақтылықты қатар айқындады. Әртүрлі қызметті салыстыру мемлекеттің құрылымын толығырақ түсіндіреді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":144},"questions":[{"id":"hce-14-1","t":"«Батыс Түрік қағанатының он оқ жүйесі» контексі: Қағанаттың маңызды орталығы қайсы?","o":["Сығанақ","Суяб","Жаңакент","Сарай-Бату"],"a":1,"e":"Мәтіндегі деректер «Суяб» деген жауапты негіздейді. Батыс Түрік қағанатының орталық аймағы Жетісу болды.","l":"A","topic":"Батыс Түрік қағанатының он оқ жүйесі"},{"id":"hce-14-2","t":"«Батыс Түрік қағанатының он оқ жүйесі» контексі: Он оқ құрамындағы топтар жұбы қайсы?","o":["Дулу мен нушиби","Арғын мен уақ","Қоңырат пен алшын","Найман мен керей"],"a":0,"e":"Мәтіндегі деректер «Дулу мен нушиби» деген жауапты негіздейді. Батыс Түрік қағанатының орталық аймағы Жетісу болды.","l":"A","topic":"Батыс Түрік қағанатының он оқ жүйесі"},{"id":"hce-14-3","t":"«Батыс Түрік қағанатының он оқ жүйесі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Қағанатта қалалық өмір мүлде болмаған","Суяб Еділ бойында орналасқан","Батыс Түрік қағанатының орталық аймағы Жетісу болды","Он оқ жүйесі тек егіншілердің салығы болған"],"a":2,"e":"Мәтіндегі деректер «Батыс Түрік қағанатының орталық аймағы Жетісу болды» деген жауапты негіздейді. Батыс Түрік қағанатының орталық аймағы Жетісу болды.","l":"B","topic":"Батыс Түрік қағанатының он оқ жүйесі"},{"id":"hce-14-4","t":"«Батыс Түрік қағанатының он оқ жүйесі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Ішкі тайпалық қатынас пен сыртқы қысым тұрақтылыққа бірге әсер етті","Тайпалық тартыс орталық билікке әсер етпеді","Қалалардың болуы көшпелі шаруашылықты толық жоққа шығарды","Тек әскер саны барлық саяси жағдайды анықтады"],"a":0,"e":"Мәтіндегі деректер «Ішкі тайпалық қатынас пен сыртқы қысым тұрақтылыққа бірге әсер етті» деген жауапты негіздейді. Батыс Түрік қағанатының орталық аймағы Жетісу болды.","l":"B","topic":"Батыс Түрік қағанатының он оқ жүйесі"},{"id":"hce-14-5","t":"«Батыс Түрік қағанатының он оқ жүйесі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["603 жылы Түрік қағанаты бөлініп, Батыс Түрік қағанаты қалыптасты.","Батыс Түрік қағанатының орталық аймағы Жетісу болды","Ішкі тайпалық қатынас пен сыртқы қысым тұрақтылыққа бірге әсер етті","Қағанатта қалалық өмір мүлде болмаған"],"a":3,"e":"Мәтіндегі деректер «Қағанатта қалалық өмір мүлде болмаған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Ішкі тайпалық қатынас пен сыртқы қысым тұрақтылыққа бірге әсер етті.","l":"C","topic":"Батыс Түрік қағанатының он оқ жүйесі"}]},{"id":"hcl-14","title":"Алаш автономиясы","text":"1917 жылғы саяси өзгерістер ұлттық мемлекеттілік мәселесін қайта көтеруге жол ашты. Қазақ зиялылары автономия құруды және халықтың саяси құқықтарын қорғауды ұсынды.\n\nАлаш автономиясы 1917 жылғы желтоқсандағы Екінші жалпықазақ съезінде жарияланды. Алашорда үкіметінің төрағасы болып Әлихан Бөкейхан сайланды. Автономия туралы шешім қабылдаған съезд Орынбор қаласында өтті. Алаш қайраткерлері ұлттық автономия мен мемлекеттілік дәстүрін жаңғыртуға ұмтылды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4},"questions":[{"id":"hcl-14-1","t":"«Алаш автономиясы» контексі: Алаш автономиясы қай жылы жарияланды?","o":["1936 жылы","1905 жылы","1917 жылы","1822 жылы"],"a":2,"e":"Алаш автономиясы 1917 жылғы желтоқсандағы Екінші жалпықазақ съезінде жарияланды.","l":"A","topic":"Алаш автономиясы"},{"id":"hcl-14-2","t":"«Алаш автономиясы» контексі: Алашорда үкіметінің төрағасы кім болды?","o":["Жамбыл Жабаев","Мұхамеджан Сералин","Әлихан Бөкейхан","Қаныш Сәтбаев"],"a":2,"e":"Алашорда үкіметінің төрағасы болып Әлихан Бөкейхан сайланды.","l":"A","topic":"Алаш автономиясы"},{"id":"hcl-14-3","t":"«Алаш автономиясы» контексі: Екі деректі сәйкестендіріңіз. 1) Алаш автономиясы қай жылы жарияланды. 2) Екінші жалпықазақ съезі қай қалада өтті.","o":["1 — 1905 жылы; 2 — Қоқанда","1 — 1822 жылы; 2 — Орынборда","1 — 1917 жылы; 2 — Верныйда","1 — 1917 жылы; 2 — Орынборда"],"a":3,"e":"Алаш автономиясы 1917 жылғы желтоқсандағы Екінші жалпықазақ съезінде жарияланды. Автономия туралы шешім қабылдаған съезд Орынбор қаласында өтті.","l":"B","topic":"Алаш автономиясы"},{"id":"hcl-14-4","t":"«Алаш автономиясы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Алашорда үкіметінің төрағасы кім болды? 2) Алаш қозғалысының негізгі саяси мақсаты қандай?","o":["1 — Мұхамеджан Сералин; 2 — Ұлттық автономия және мемлекеттілік","1 — Әлихан Бөкейхан; 2 — Отарлық тәуелділікті мәңгі сақтау","1 — Қаныш Сәтбаев; 2 — Тың игеруді бастау","1 — Әлихан Бөкейхан; 2 — Ұлттық автономия және мемлекеттілік"],"a":3,"e":"Алашорда үкіметінің төрағасы болып Әлихан Бөкейхан сайланды. Алаш қайраткерлері ұлттық автономия мен мемлекеттілік дәстүрін жаңғыртуға ұмтылды.","l":"B","topic":"Алаш автономиясы"},{"id":"hcl-14-5","t":"«Алаш автономиясы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Алашорда құру ұлттық қозғалыстың баспасөз бен өтініштен саяси институт қалыптастыруға өткенін көрсетті.","Алашорда төрағасын сайлау автономия идеясын жеке әулеттің мұрагерлік билігімен алмастырды.","Съезд пен үкімет құру ұлттық өкілдікке емес, бұрынғы отарлық әкімшілікті өзгеріссіз сақтауға бағытталды.","Автономия жариялау ұлттық қозғалыстың саяси ұйым құрудан бас тартып, тек баспасөз жұмысын таңдағанын көрсетті."],"a":0,"e":"Алашорда құру ұлттық қозғалыстың баспасөз бен өтініштен саяси институт қалыптастыруға өткенін көрсетті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Алаш автономиясы"}]}]},{"number":15,"questions":[{"id":"ha-059","t":"1206 жылғы құрылтайда Темүжінге қандай атақ берілді?","o":["Әмір","Илхан","Гурхан","Шыңғыс хан"],"a":3,"e":"1206 жылғы құрылтайда Темүжін барлық моңғолдардың билеушісі болып жарияланып, Шыңғыс хан атанды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":94}},{"id":"hm-054","t":"Қазақ КСР-інде тілдер туралы заң қай жылы қабылданды?","o":["1989 жылы","1995 жылы","1936 жылы","1954 жылы"],"a":0,"e":"1989 жылғы заң қазақ тіліне мемлекеттік тіл мәртебесін берді.","l":"A","topic":"Қайта құру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hk-034","t":"1594 жылғы қазақ елшілігін басқарған тұлға кім?","o":["Құл-Мұхаммед","Семен Мальцев","Алексей Тевкелев","Томас Аткинсон"],"a":0,"e":"Құл-Мұхаммед Тәуекел ханның елшісі ретінде Мәскеуге барды.","l":"A","topic":"Тәуекел ханның елшілігі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":89}},{"id":"ha-052","t":"Оғыз мемлекетінің негізгі орталығы болған қаланы көрсетіңіз.","o":["Янгикент","Сарай-Бату","Суяб","Баласағұн"],"a":0,"e":"Сырдарияның төменгі ағысындағы Янгикент Оғыз мемлекетінің орталығы болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":32}},{"id":"hi-036","t":"Досан Тәжіұлы мен Иса Тіленбайұлы басқарған көтеріліс қай өңірде болды?","o":["Сарыарқада","Ертіс бойында","Жетісуда","Маңғыстауда"],"a":3,"e":"Досан Тәжіұлы мен Иса Тіленбайұлы 1870 жылғы Маңғыстау көтерілісін басқарды.","l":"A","topic":"1868–1870 жылдардағы көтерілістер","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":154}},{"id":"ha-097","t":"Көшпелі малшылар қыс пен жазда әртүрлі қонысты пайдаланған. Мұның шаруашылық мәні қандай?","o":["Маусымдық жайылым мен су қорын тиімді пайдалану","Жайылымды егіншілікке толық ауыстыру","Мал санын әдейі азайту","Бүкіл жылдық азықты қаладан сатып алу"],"a":0,"e":"Маусымдық көші-қон малға жыл бойы қолайлы жайылым мен су табуға бейімделген.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-085","t":"Ыбырай Алтынсариннің қыз балалар білімін дамытудағы қызметін анықтаңыз.","o":["Қыздардың мектепке баруына тыйым салды","Барлық мектепті тек әскери мекемеге айналдырды","Зайырлы білім беруден толық бас тартты","Қазақ қыздарына арналған мектептер ашуға атсалысты"],"a":3,"e":"Ыбырай қыз балалардың білім алуын қолдап, олардың мектептерін ұйымдастыруға үлес қосты.","l":"B","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":183}},{"id":"hk-070","t":"Сырдария қалаларының Қазақ хандығына экономикалық маңызын дұрыс түсіндіретін жауапты табыңыз.","o":["Көшпелі және отырықшы аймақтарды оқшаулады","Сыртқы саудаға қажеттілікті түгел жойды","Қала мен дала арасындағы айырбасқа жағдай жасады","Хандықтағы мал шаруашылығын толық алмастырды"],"a":2,"e":"Отырықшы қалалардан астық пен қолөнер өнімдері келді, ал көшпелілер мал және мал өнімдерін жеткізді.","l":"A","topic":"Сырдария қалалары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":83}},{"id":"hm-105","t":"Қазақ мемлекеттілігінің мәртебелерін салыстырыңыз. Дұрыс тұжырымдар жұбын таңдаңыз.","o":["1920 жылы тәуелсіз мемлекет құрылды; 1936 жылы РКФСР құрамындағы автономия болды","1920 жылы одақтас республика құрылды; 1936 жылы хандық билік қалпына келді","1920 жылы РКФСР құрамындағы автономия құрылды; 1936 жылы КСРО құрамындағы одақтас республика болды","1920 жылы КСРО-дан шықты; 1936 жылы тәуелсіз республика болды"],"a":2,"e":"1920 жылғы Қазақ АКСР-і РКФСР құрамындағы автономия болды. 1936 жылы Қазақ КСР-і одақтас республика мәртебесін алды, бірақ толық тәуелсіздік 1991 жылы бекітілді.","l":"C","topic":"Хронология","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hk-121","t":"Қасым мен Тәуке хандардың қызметіндегі ортақ бағытты табыңыз.","o":["Хандық билікті жойып, сұлтандарды биліктен шеттету","Дәстүрлі құқықты реттеу арқылы мемлекеттік бірлікті нығайту","Сыр қалаларынан толық бас тартып, тек Жетісуды сақтау","Дәстүрлі құқық орнына көрші хандықтың заңын түгел көшіру"],"a":1,"e":"Қасымның «Қасқа жолы» мен Тәукенің «Жеті жарғысы» құқықтық ережелер арқылы қоғамдық тәртіпті бекітуге бағытталды.","l":"C","topic":"Қазақ хандарының реформалары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}}],"contexts":[{"id":"hce-15","title":"Түргештер: сыртқы қауіп және ішкі бірлік","text":"Түргеш қағанаты Жетісуда VIII ғасырдың басында күшейді. Оның негізін Үшлік қалады. Сұлу қаған арабтардың ілгерілеуіне қарсы күресті. Шығыстағы күштермен қатынас та маңызды болды. Бірнеше бағыттан қауіп төнуі әскери әрекетпен қатар дипломатияны қажет етті. Суяб пен Тараз саяси және экономикалық тірек болды. Билеуші қайтыс болғаннан кейінгі тартыстар мемлекетті әлсіретті. Қағанат тарихы сыртқы басқыншылық пен ішкі қатынастардың байланысын көрсетеді. Бір ғана қарсыласты атау барлық саяси мәселені толық түсіндірмейді. Қала тірегі, билік бірлігі және елшілік саясат мемлекеттің қорғаныс мүмкіндігіне қатар ықпал еткен.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":147},"questions":[{"id":"hce-15-1","t":"«Түргештер: сыртқы қауіп және ішкі бірлік» контексі: Түргеш қағанатының негізін қалаған кім?","o":["Батый","Үшлік","Тоғылық Темір","Бумын"],"a":1,"e":"Мәтіндегі деректер «Үшлік» деген жауапты негіздейді. Түргештердің негізгі саяси өңірі Жетісу болды.","l":"A","topic":"Түргештер: сыртқы қауіп және ішкі бірлік"},{"id":"hce-15-2","t":"«Түргештер: сыртқы қауіп және ішкі бірлік» контексі: Арабтарға қарсы күрескен қаған кім?","o":["Берке","Өзбек","Сұлу","Мұса"],"a":2,"e":"Мәтіндегі деректер «Сұлу» деген жауапты негіздейді. Түргештердің негізгі саяси өңірі Жетісу болды.","l":"A","topic":"Түргештер: сыртқы қауіп және ішкі бірлік"},{"id":"hce-15-3","t":"«Түргештер: сыртқы қауіп және ішкі бірлік» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Түргештердің негізгі саяси өңірі Жетісу болды","Сұлу дипломатияны мүлде қолданбаған","Суяб пен Тараз саяси өмірге қатыспаған","Түргештердің барлық мәселесі тек бір қарсыласпен шектелді"],"a":0,"e":"Мәтіндегі деректер «Түргештердің негізгі саяси өңірі Жетісу болды» деген жауапты негіздейді. Түргештердің негізгі саяси өңірі Жетісу болды.","l":"B","topic":"Түргештер: сыртқы қауіп және ішкі бірлік"},{"id":"hce-15-4","t":"«Түргештер: сыртқы қауіп және ішкі бірлік» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Сыртқы қауіп пен ішкі тартыстарды бірге талдау қажет","Ішкі билік қатынастары қорғанысқа ықпал етпейді","Әскери әрекет дипломатияны әрдайым жоққа шығарады","Бір қаланың болуы қағанаттың барлық аумағын анықтайды"],"a":0,"e":"Мәтіндегі деректер «Сыртқы қауіп пен ішкі тартыстарды бірге талдау қажет» деген жауапты негіздейді. Түргештердің негізгі саяси өңірі Жетісу болды.","l":"B","topic":"Түргештер: сыртқы қауіп және ішкі бірлік"},{"id":"hce-15-5","t":"«Түргештер: сыртқы қауіп және ішкі бірлік» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Түргеш қағанаты Жетісуда VIII ғасырдың басында күшейді.","Түргештердің негізгі саяси өңірі Жетісу болды","Түргештердің барлық мәселесі тек бір қарсыласпен шектелді","Сыртқы қауіп пен ішкі тартыстарды бірге талдау қажет"],"a":2,"e":"Мәтіндегі деректер «Түргештердің барлық мәселесі тек бір қарсыласпен шектелді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сыртқы қауіп пен ішкі тартыстарды бірге талдау қажет.","l":"C","topic":"Түргештер: сыртқы қауіп және ішкі бірлік"}]},{"id":"hcl-15","title":"Түркістан автономиясы","text":"1917 жылғы революциялардан кейін Түркістан өлкесінде де өзін-өзі басқару идеясы көтерілді. Автономия жақтастары өлкенің тұрғындарына саяси құқықтар мен жергілікті басқару мүмкіндігін беруді көздеді.\n\nТүркістан автономиясы Қоқан қаласында жарияланғандықтан Қоқан автономиясы деп те аталады. Мұстафа Шоқай Түркістан автономиясының жетекшілерінің бірі болды. Автономия 1917 жылғы революциялар туғызған саяси өзгерістер жағдайында пайда болды. Түркістан автономиясы өлкенің өзін-өзі басқаруы мен халықтың саяси құқықтарын көздеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9},"questions":[{"id":"hcl-15-1","t":"«Түркістан автономиясы» контексі: Түркістан автономиясының орталығы қай қала болды?","o":["Қоқан","Орынбор","Семей","Омбы"],"a":0,"e":"Түркістан автономиясы Қоқан қаласында жарияланғандықтан Қоқан автономиясы деп те аталады.","l":"A","topic":"Түркістан автономиясы"},{"id":"hcl-15-2","t":"«Түркістан автономиясы» контексі: Автономиямен байланысты қазақ қайраткері кім?","o":["Абай Құнанбайұлы","Дінмұхамед Қонаев","Мұстафа Шоқай","Ыбырай Алтынсарин"],"a":2,"e":"Мұстафа Шоқай Түркістан автономиясының жетекшілерінің бірі болды.","l":"A","topic":"Түркістан автономиясы"},{"id":"hcl-15-3","t":"«Түркістан автономиясы» контексі: Екі деректі сәйкестендіріңіз. 1) Түркістан автономиясының орталығы қай қала болды. 2) Автономия қай саяси кезеңде пайда болды.","o":["1 — Омбы; 2 — Екінші дүниежүзілік соғыстан кейін","1 — Орынбор; 2 — 1917 жылғы революциялардан кейін","1 — Қоқан; 2 — 1917 жылғы революциялардан кейін","1 — Қоқан; 2 — 1822 жылғы жарғыға дейін"],"a":2,"e":"Түркістан автономиясы Қоқан қаласында жарияланғандықтан Қоқан автономиясы деп те аталады. Автономия 1917 жылғы революциялар туғызған саяси өзгерістер жағдайында пайда болды.","l":"B","topic":"Түркістан автономиясы"},{"id":"hcl-15-4","t":"«Түркістан автономиясы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Автономиямен байланысты қазақ қайраткері кім? 2) Автономия идеясының өзегі қандай болды?","o":["1 — Мұстафа Шоқай; 2 — Өлкенің өзін-өзі басқаруы","1 — Абай Құнанбайұлы; 2 — Тек сыртқы сауданы тоқтату","1 — Ыбырай Алтынсарин; 2 — Өлкенің өзін-өзі басқаруы","1 — Мұстафа Шоқай; 2 — Отарлық басқаруды өзгеріссіз сақтау"],"a":0,"e":"Мұстафа Шоқай Түркістан автономиясының жетекшілерінің бірі болды. Түркістан автономиясы өлкенің өзін-өзі басқаруы мен халықтың саяси құқықтарын көздеді.","l":"B","topic":"Түркістан автономиясы"},{"id":"hcl-15-5","t":"«Түркістан автономиясы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Алаш пен Түркістан автономияларының әртүрлі орталықта құрылуы олардың саяси құқықтар мәселесінде еш ұқсастығы болмағанын көрсетеді.","Мұстафа Шоқайдың жетекшілік қызметі автономияның қоғамдық өкілдік емес, тек жеке билік жобасы болғанын дәлелдейді.","Қоқанда жарияланған автономияның мақсаты жергілікті өзін-өзі басқарудан гөрі орталықтың тікелей әкімшілік бақылауын кеңейту болды.","Қоқан және Алаш автономиялары әртүрлі аумақта пайда болғанымен, өзін-өзі басқару талабымен байланысты болды."],"a":3,"e":"Қоқан және Алаш автономиялары әртүрлі аумақта пайда болғанымен, өзін-өзі басқару талабымен байланысты болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Түркістан автономиясы"}]}]},{"number":16,"questions":[{"id":"hi-002","t":"1822 жылғы Сібір қазақтарын басқару реформасының жобасын әзірлеген қайраткерді көрсетіңіз.","o":["Григорий Колпаковский","Петр Рычков","Николай Игельстром","Михаил Сперанский"],"a":3,"e":"Реформаның жобасын М.М. Сперанский әзірледі. Құжат Орта жүздің басқару жүйесін өзгертті.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":167}},{"id":"hm-041","t":"Е.Бекмахановтың қуғындалуына байланысты аталған саяси науқан қандай?","o":["«Кіші Қазан»","«Невада–Семей»","«Жас тұлпар»","«Бекмаханов ісі»"],"a":3,"e":"«Бекмаханов ісі» соғыстан кейінгі ғылымға жасалған идеологиялық қысымның көрінісі болды.","l":"A","topic":"Соғыстан кейінгі Қазақстан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":229}},{"id":"hm-012","t":"Күштеп ұжымдастырудың Қазақстандағы аса ауыр зардабы қандай болды?","o":["1931–1933 жылдардағы ашаршылық","1723 жылғы жоңғар шапқыншылығы","1870 жылғы Маңғыстау көтерілісі","1993 жылғы валюта реформасы"],"a":0,"e":"Күштеп ұжымдастыру мен мал шаруашылығын күйрету 1931–1933 жылдардағы ашаршылыққа әкелді.","l":"A","topic":"Ұжымдастыру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hi-026","t":"1854 жылы Жетісуда негізі қаланған бекініс қалай аталды?","o":["Верный","Өскемен","Петропавл","Орынбор"],"a":0,"e":"Верный бекінісі 1854 жылы салынды. Ол қазіргі Алматы қаласының тарихымен байланысты.","l":"A","topic":"Оңтүстік Қазақстанның қосылуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"ha-115","t":"Жазба деректе 1219 жылғы қоршау, ал қазбада өртенген ғимараттар мен қираған су жүйесі көрсетілген. Деректерді біріктіріп қандай қорытынды жасауға болады?","o":["Су жүйесі сауда байланыстарына ешқашан әсер етпеген","Қалада өрт тек бейбіт құрылыс жұмыстарынан болған","Моңғол шапқыншылығы қала мен егіншілік инфрақұрылымына зиян келтірген","Соғыс тек алыс жайылымдарға әсер еткен"],"a":2,"e":"Қоршау туралы жазба мен қирау қабаты бірін-бірі толықтырып, соғыстың қала шаруашылығына зардабын көрсетеді.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-119","t":"1917 жылғы оқиғалардың дұрыс себеп-салдарлық байланысын таңдаңыз.","o":["Қазан төңкерісі → 1822 жылғы жарғы → Ақпан революциясы","Азамат соғысының аяқталуы → Бірінші дүниежүзілік соғыстың басталуы → Ақпан революциясы","Монархияның құлауы → Қазақ хандығының XV ғасырда құрылуы → жоңғар шапқыншылығы","Монархияның құлауы → саяси еркіндіктің кеңеюі → ұлттық ұйымдардың белсенділігі"],"a":3,"e":"Ақпан революциясы монархияны құлатты. Жаңа саяси жағдайда ұлттық съездер мен ұйымдардың белсенділігі артты.","l":"C","topic":"1917 жылғы революциялар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":241}},{"id":"hk-037","t":"Тәуекел Сырдария қалалары үшін негізінен қай хандықпен күресті?","o":["Бұхар хандығымен","Қазан хандығымен","Сібір хандығымен","Қырым хандығымен"],"a":0,"e":"Сырдария бойындағы қалалар үшін күрес Қазақ және Бұхар хандықтарының қатынасында маңызды орын алды.","l":"A","topic":"Тәуекел ханның сыртқы саясаты","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8}},{"id":"hk-081","t":"Есім мен Тұрсын арасындағы күрес хандықтағы қандай мәселені көрсетеді?","o":["Орталық билік пен дербестікке ұмтылған билеуші арасындағы қайшылықты","Хандықтағы дінбасылардың толық үстемдігін","Тек мал салығын жинау тәртібіндегі дауды","Көшпелі және қала халқының тілдік айырмашылығын"],"a":0,"e":"Тұрсынның жеке билікке ұмтылысы Қазақ хандығындағы саяси тұтастыққа қауіп төндірді.","l":"B","topic":"Есім хан және Тұрсын хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":103}},{"id":"ha-061","t":"Шыңғыс хан жорығына қарсы Отырар қорғанысын басқарған тұлға кім?","o":["Едіге","Тоғылық Темір","Қайыр хан","Ұрыс хан"],"a":2,"e":"Қайыр хан 1219 жылы басталған моңғол шапқыншылығында Отырарды қорғады.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-076","t":"Соғыс жылдарындағы эвакуацияның Қазақстан өнеркәсібіне әсері қандай болды?","o":["Жаңа өндірістер мен мамандардың келуі өндірісті ұлғайтты","Өндірістік байланыстар түгел жойылды","Өнеркәсіп тек ауыл шаруашылығына ауысты","Барлық зауыт біржола таратылды"],"a":0,"e":"Көшірілген кәсіпорындар мен мамандар Қазақстанның тылдағы өндірістік қуатын арттырды.","l":"B","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}}],"contexts":[{"id":"hce-16","title":"Атлах: оқиға мен ұзақ үдеріс","text":"751 жылы Талас маңындағы Атлахта араб және Тан әскерлері шайқасты. Қарлұқтардың арабтар жағына шығуы шайқасқа ықпал етті. Тан әскерінің жеңілуі оның Орталық Азиядағы ықпалын шектеді. Сызба: әскери қақтығыс → күштер арақатынасының өзгеруі → жаңа саяси жағдай. Исламның таралуы бұдан ұзақ және күрделі үдеріс болды. Сауда, қалалық өмір және кейінгі мемлекеттердің саясаты рухани өзгерістерге әсер етті. Бір шайқастан кейін бүкіл халықтың діні бірден ауысты деу дұрыс емес. Тікелей әскери нәтижені ұзақ мерзімді мәдени өзгерістен ажырату қажет. Аймақтық тайпалар ірі державалар күресінде белсенді рөл атқарды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15},"questions":[{"id":"hce-16-1","t":"«Атлах: оқиға мен ұзақ үдеріс» контексі: Атлах шайқасы қай жылы болды?","o":["751","1219","552","960"],"a":0,"e":"Мәтіндегі деректер «751» деген жауапты негіздейді. Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді.","l":"A","topic":"Атлах: оқиға мен ұзақ үдеріс"},{"id":"hce-16-2","t":"«Атлах: оқиға мен ұзақ үдеріс» контексі: Арабтарға қолдау көрсеткендер кімдер?","o":["Сарматтар","Ноғайлар","Қарлұқтар","Жоңғарлар"],"a":2,"e":"Мәтіндегі деректер «Қарлұқтар» деген жауапты негіздейді. Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді.","l":"A","topic":"Атлах: оқиға мен ұзақ үдеріс"},{"id":"hce-16-3","t":"«Атлах: оқиға мен ұзақ үдеріс» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Атлахтан кейін бүкіл халық бір күнде исламға өтті","Атлах Қарахан мемлекетінің астанасы болған","Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді","Қарлұқтар шайқасқа қатыспаған"],"a":2,"e":"Мәтіндегі деректер «Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді» деген жауапты негіздейді. Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді.","l":"B","topic":"Атлах: оқиға мен ұзақ үдеріс"},{"id":"hce-16-4","t":"«Атлах: оқиға мен ұзақ үдеріс» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Шайқас нәтижесі мен исламның таралуын бөлек уақыттық аяда қарастыру керек","Сауда мен қала өмірінің дін таралуына қатысы жоқ","Бір әскери жеңіс барлық мәдени өзгерісті бірден аяқтайды","Жергілікті тайпалар ірі державалар күресіне әсер ете алмады"],"a":0,"e":"Мәтіндегі деректер «Шайқас нәтижесі мен исламның таралуын бөлек уақыттық аяда қарастыру керек» деген жауапты негіздейді. Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді.","l":"B","topic":"Атлах: оқиға мен ұзақ үдеріс"},{"id":"hce-16-5","t":"«Атлах: оқиға мен ұзақ үдеріс» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Атлахтан кейін бүкіл халық бір күнде исламға өтті","751 жылы Талас маңындағы Атлахта араб және Тан әскерлері шайқасты.","Шайқас нәтижесі мен исламның таралуын бөлек уақыттық аяда қарастыру керек","Тан әскерінің жеңілуі оның аймақтағы ықпалын шектеді"],"a":0,"e":"Мәтіндегі деректер «Атлахтан кейін бүкіл халық бір күнде исламға өтті» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Шайқас нәтижесі мен исламның таралуын бөлек уақыттық аяда қарастыру керек.","l":"C","topic":"Атлах: оқиға мен ұзақ үдеріс"}]},{"id":"hcl-16","title":"1916 жылғы Торғай көтерілісі","text":"Бірінші дүниежүзілік соғыс кезіндегі ауыртпалық отарлық қайшылықтарды күшейтті. 1916 жылғы патша жарлығы бұрыннан жиналған наразылықтың кең көлемді көтеріліске ұласуына түрткі болды.\n\n1916 жылғы 25 маусым жарлығы жергілікті ер адамдарды тыл жұмыстарына алуды көздеді. Торғайдағы көтерілісте Амангелді Иманұлы сардарбек ретінде танылды. Торғай көтерілісшілері Әбдіғапар Жанбосынұлын хан етіп сайлады. Жердің тартып алынуы мен отарлық алымдар халық наразылығын ұзақ уақыт күшейтті.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":43},"questions":[{"id":"hcl-16-1","t":"«1916 жылғы Торғай көтерілісі» контексі: 1916 жылғы жарлық қазақтарды қандай жұмысқа алуды көздеді?","o":["Теңіз флотын басқаруға","Тыл жұмыстарына","Ғарыш құрылысына","Хан сайлауына"],"a":1,"e":"1916 жылғы 25 маусым жарлығы жергілікті ер адамдарды тыл жұмыстарына алуды көздеді.","l":"A","topic":"1916 жылғы Торғай көтерілісі"},{"id":"hcl-16-2","t":"«1916 жылғы Торғай көтерілісі» контексі: Торғайдағы көтерілістің белгілі сардарбегі кім?","o":["Бөгенбай Ақшаұлы","Досан Тәжіұлы","Амангелді Иманұлы","Жанқожа Нұрмұхамедұлы"],"a":2,"e":"Торғайдағы көтерілісте Амангелді Иманұлы сардарбек ретінде танылды.","l":"A","topic":"1916 жылғы Торғай көтерілісі"},{"id":"hcl-16-3","t":"«1916 жылғы Торғай көтерілісі» контексі: Екі деректі сәйкестендіріңіз. 1) 1916 жылғы жарлық қазақтарды қандай жұмысқа алуды көздеді. 2) Торғай көтерілісшілері хан етіп кімді сайлады.","o":["1 — Ғарыш құрылысына; 2 — Шерғазы ханды","1 — Тыл жұмыстарына; 2 — Әбдіғапар Жанбосынұлы","1 — Тыл жұмыстарына; 2 — Кенесары Қасымұлын","1 — Хан сайлауына; 2 — Әбдіғапар Жанбосынұлы"],"a":1,"e":"1916 жылғы 25 маусым жарлығы жергілікті ер адамдарды тыл жұмыстарына алуды көздеді. Торғай көтерілісшілері Әбдіғапар Жанбосынұлын хан етіп сайлады.","l":"B","topic":"1916 жылғы Торғай көтерілісі"},{"id":"hcl-16-4","t":"«1916 жылғы Торғай көтерілісі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Торғайдағы көтерілістің белгілі сардарбегі кім? 2) Көтерілістің терең себептерінің бірі қандай?","o":["1 — Жанқожа Нұрмұхамедұлы; 2 — Отарлық жер және салық саясаты","1 — Амангелді Иманұлы; 2 — Отарлық жер және салық саясаты","1 — Амангелді Иманұлы; 2 — Тың игеру жоспары","1 — Досан Тәжіұлы; 2 — Ғарыш жарысы"],"a":1,"e":"Торғайдағы көтерілісте Амангелді Иманұлы сардарбек ретінде танылды. Жердің тартып алынуы мен отарлық алымдар халық наразылығын ұзақ уақыт күшейтті.","l":"B","topic":"1916 жылғы Торғай көтерілісі"},{"id":"hcl-16-5","t":"«1916 жылғы Торғай көтерілісі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Жер мен салық қысымы тек көтерілістен кейін пайда болғандықтан, қозғалыстың жалғыз себебі маусым жарлығы болды.","Хан мен сардарбек сайлау көтерілістің отарлық саясатқа емес, тек ішкі қызмет бөлуге бағытталғанын көрсетеді.","Тыл жұмыстарына алу жарлығы бұрынғы әлеуметтік қайшылықтарды бәсеңдетіп, наразылықтың таралуын тоқтатты.","Маусым жарлығы көтеріліске тікелей түрткі болды, ал жер мен салық қысымы оның терең әлеуметтік себептеріне жатты."],"a":3,"e":"Маусым жарлығы көтеріліске тікелей түрткі болды, ал жер мен салық қысымы оның терең әлеуметтік себептеріне жатты. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1916 жылғы Торғай көтерілісі"}]}]},{"number":17,"questions":[{"id":"hk-068","t":"Ортақ тіл, салт-дәстүр және тарихи аумақтың жақындасуы қазақ тайпаларына қандай үдерісте негіз болды?","o":["Этникалық және саяси бірігуінде","Әулеттік биліктің бірден жойылуында","Қалалық және далалық халықтың толық бөлінуінде","Тайпалардың бір-бірінен толық оқшаулануында"],"a":0,"e":"Ортақ мәдени және аумақтық байланыстар тайпалардың бір халық және мемлекет аясында топтасуын қолдады.","l":"A","topic":"Қазақ халқының қалыптасуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":113}},{"id":"hi-086","t":"Абайдың ағартушылық көзқарасына сәйкес келетін тұжырымды таңдаңыз.","o":["Адамның жетілуі тек атаққа байланысты","Білім алуға талпыну зиян","Ғылым қоғамдық өмірге қажет емес","Білім мен еңбек адамды жетілдіреді"],"a":3,"e":"Абай шығармаларында білім, еңбек және адамгершілік адам дамуының негізі ретінде көрсетіледі.","l":"B","topic":"XIX ғасырдағы әдебиет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hm-026","t":"И.Панфилов басқарған 316-атқыштар дивизиясы қай қаланы қорғауда танылды?","o":["Берлинді","Парижді","Мәскеуді","Римді"],"a":2,"e":"Панфилов дивизиясы 1941 жылы Мәскеу түбіндегі қорғаныс ұрыстарында ерлік көрсетті.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":213}},{"id":"hm-120","t":"Тәуелсіздіктің алғашқы жылдарындағы қадамдарды олардың қызметімен сәйкестендіріңіз: А — БҰҰ мүшелігі; Ә — теңге; Б — Конституция. 1 — ақша-несие дербестігі; 2 — халықаралық құқық субъектілігін нығайту; 3 — мемлекеттік құрылыстың құқықтық қағидалары.","o":["А–2, Ә–1, Б–3","А–1, Ә–2, Б–3","А–2, Ә–3, Б–1","А–3, Ә–1, Б–2"],"a":0,"e":"БҰҰ мүшелігі халықаралық орынды нығайтты, теңге дербес ақша саясатын жүргізуге мүмкіндік берді. Конституция мемлекеттік құрылыстың құқықтық негізін белгіледі.","l":"C","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hk-093","t":"Шежіренің қоғамдағы қызметін ең дәл сипаттайтын тұжырым қайсы?","o":["Тек қала базарларындағы бағаны реттеді","Тек әскери жасақтың күнделікті есебін жүргізді","Ұрпақ сабақтастығы мен тарихи жадты сақтады","Тек сыртқы елшілердің шығынын белгіледі"],"a":2,"e":"Шежіре ата-тек туралы біліммен қатар қауымның өткен оқиғалар туралы жадын жеткізді.","l":"A","topic":"Шежіре және тарихи жад","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"ha-028","t":"Берел қорымының ескерткіштері орналасқан таулы өңірді атаңыз.","o":["Қаратау","Мұғалжар","Ұлытау","Алтай"],"a":3,"e":"Берел қорымы Шығыс Қазақстандағы Алтай өңірінде орналасқан.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"ha-026","t":"Тасмола мәдениетінің ерекше жерлеу ескерткіштері қалай аталады?","o":["Мұртты обалар","Керуен сарайлар","Сардобалар","Балбалсыз кесенелер"],"a":0,"e":"Тасмола мәдениетіне тас тізбектері шығысқа созылған мұртты обалар тән.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-052","t":"Абайдың адамгершілік, білім және қоғам туралы прозалық ойлары жинақталған еңбек қалай аталады?","o":["Диуани лұғат ат-түрк","Шежірелер жинағы","Тарих-и Рашиди","Қарасөздер"],"a":3,"e":"Абайдың «Қарасөздері» адам, білім, еңбек және қоғам мәселелерін қозғайды.","l":"A","topic":"XIX ғасырдағы әдебиет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"ha-088","t":"Зерттеуші Ясы мен Түркістан атауларын екі бөлек астана ретінде санады. Қай түзету дұрыс?","o":["Екі атау да бір таудың атауы","Түркістан — Сарайшықтың кейінгі атауы","Ясы — Оғыз мемлекетінің Янгикент астанасы","Ясы — Түркістан қаласының бұрынғы атауы"],"a":3,"e":"Түркістанның ортағасырлық бұрынғы атауы Ясы болғандықтан, оларды екі бөлек қала деп санауға болмайды.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hk-118","t":"Орбұлақ шайқасы, Қарақұм құрылтайы және Ақтабан шұбырындыны реттеңіз.","o":["Орбұлақ → Ақтабан шұбырынды → Қарақұм","Қарақұм → Орбұлақ → Ақтабан шұбырынды","Орбұлақ → Қарақұм → Ақтабан шұбырынды","Ақтабан шұбырынды → Орбұлақ → Қарақұм"],"a":2,"e":"Орбұлақ 1643 жылы, Қарақұм құрылтайы 1710 жылы өтті, ал Ақтабан шұбырынды 1723 жылы басталды.","l":"C","topic":"Қазақ-жоңғар соғыстары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":155}}],"contexts":[{"id":"hce-17","title":"Қарлұқтардың саяси және шаруашылық тіректері","text":"VIII ғасырдың екінші жартысында Жетісуда қарлұқтардың ықпалы күшейді. 756 жыл олардың мемлекетінің қалыптасуымен байланысты. Билеуші жабғу атағын қолданған. Суяб пен Тараз маңызды орталық болып қала берді. Даладағы мал өнімі қала қолөнеріне айырбасталып, шаруашылық байланыс орнады. Керуен жолдарын бақылау саяси ықпалдың көзі болды. Кейін Қарахан мемлекеті қалыптасқан ортада қарлұқ тайпалары маңызды рөл атқарды. Биліктің ауысуы халық пен шаруашылық байланыстарының толық үзілуін білдірмейді. Жаңа құрылым бұрынғы қатынастарды пайдалана алды. Сондықтан мемлекеттік шекаралармен қатар аймақтық сабақтастықты да ескеру қажет.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":144},"questions":[{"id":"hce-17-1","t":"«Қарлұқтардың саяси және шаруашылық тіректері» контексі: Қарлұқ билеушісінің атағы қайсы?","o":["Патша","Қазы","Шаньюй","Жабғу"],"a":3,"e":"Мәтіндегі деректер «Жабғу» деген жауапты негіздейді. Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды.","l":"A","topic":"Қарлұқтардың саяси және шаруашылық тіректері"},{"id":"hce-17-2","t":"«Қарлұқтардың саяси және шаруашылық тіректері» контексі: Мемлекеттің қалыптасуымен байланысты жыл қайсы?","o":["552","756","1243","1465"],"a":1,"e":"Мәтіндегі деректер «756» деген жауапты негіздейді. Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды.","l":"A","topic":"Қарлұқтардың саяси және шаруашылық тіректері"},{"id":"hce-17-3","t":"«Қарлұқтардың саяси және шаруашылық тіректері» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды","Билік ауысқанда барлық шаруашылық байланыс міндетті түрде үзілді","Қарлұқтар тек теңіз саудасына сүйенді","Суяб пен Тараз бір ғана қаланың екі атауы"],"a":0,"e":"Мәтіндегі деректер «Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды» деген жауапты негіздейді. Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды.","l":"B","topic":"Қарлұқтардың саяси және шаруашылық тіректері"},{"id":"hce-17-4","t":"«Қарлұқтардың саяси және шаруашылық тіректері» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Әр жаңа мемлекетте халық түгел ауысады","Саяси өзгеріске қарамастан аймақтық байланыстар жалғаса алады","Керуен жолдарының еш саяси маңызы болмады","Мал өнімі қалалық тұтынуға қатыссыз болды"],"a":1,"e":"Мәтіндегі деректер «Саяси өзгеріске қарамастан аймақтық байланыстар жалғаса алады» деген жауапты негіздейді. Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды.","l":"B","topic":"Қарлұқтардың саяси және шаруашылық тіректері"},{"id":"hce-17-5","t":"«Қарлұқтардың саяси және шаруашылық тіректері» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["VIII ғасырдың екінші жартысында Жетісуда қарлұқтардың ықпалы күшейді.","Қала мен дала арасында мал өнімі мен қолөнер бұйымы айырбасталды","Билік ауысқанда барлық шаруашылық байланыс міндетті түрде үзілді","Саяси өзгеріске қарамастан аймақтық байланыстар жалғаса алады"],"a":2,"e":"Мәтіндегі деректер «Билік ауысқанда барлық шаруашылық байланыс міндетті түрде үзілді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Саяси өзгеріске қарамастан аймақтық байланыстар жалғаса алады.","l":"C","topic":"Қарлұқтардың саяси және шаруашылық тіректері"}]},{"id":"hcl-17","title":"1916 жылғы Жетісу көтерілісі","text":"Жетісудағы 1916 жылғы қарсылыққа түрлі халық өкілдері қатысты. Жазалау шаралары мен қақтығыстар бейбіт тұрғындардың өміріне ауыр зардап әкелді.\n\nБекболат Әшекеев Жетісудағы көтерілістің белгілі басшыларының бірі болды. Қозғалысқа қазақтармен бірге қырғыздар мен басқа жергілікті халық өкілдері қатысты. Қарқара жәрмеңкесі маңы Жетісудағы көтеріліс ошақтарының бірі болды. Жазалау шараларынан кейін халықтың бір бөлігі Қытай аумағына босып кетуге мәжбүр болды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8},"questions":[{"id":"hcl-17-1","t":"«1916 жылғы Жетісу көтерілісі» контексі: Жетісудағы 1916 жылғы көтеріліс басшыларының бірі кім?","o":["Бекболат Әшекеев","Әлихан Бөкейхан","Исатай Тайманұлы","Сырым Датұлы"],"a":0,"e":"Бекболат Әшекеев Жетісудағы көтерілістің белгілі басшыларының бірі болды.","l":"A","topic":"1916 жылғы Жетісу көтерілісі"},{"id":"hcl-17-2","t":"«1916 жылғы Жетісу көтерілісі» контексі: Жетісу көтерілісінің ерекшелігі қандай?","o":["Әртүрлі ұлт өкілдерінің қатысуы","Тек шетел саудагерлерінің қатысуы","Тек теңізшілердің қатысуы","Тек бір отбасының қатысуы"],"a":0,"e":"Қозғалысқа қазақтармен бірге қырғыздар мен басқа жергілікті халық өкілдері қатысты.","l":"A","topic":"1916 жылғы Жетісу көтерілісі"},{"id":"hcl-17-3","t":"«1916 жылғы Жетісу көтерілісі» контексі: Екі деректі сәйкестендіріңіз. 1) Жетісудағы 1916 жылғы көтеріліс басшыларының бірі кім. 2) Қозғалыспен байланысты жәрмеңке қайсы.","o":["1 — Бекболат Әшекеев; 2 — Ирбит","1 — Әлихан Бөкейхан; 2 — Қарқара","1 — Бекболат Әшекеев; 2 — Қарқара","1 — Исатай Тайманұлы; 2 — Мәкәржі"],"a":2,"e":"Бекболат Әшекеев Жетісудағы көтерілістің белгілі басшыларының бірі болды. Қарқара жәрмеңкесі маңы Жетісудағы көтеріліс ошақтарының бірі болды.","l":"B","topic":"1916 жылғы Жетісу көтерілісі"},{"id":"hcl-17-4","t":"«1916 жылғы Жетісу көтерілісі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Жетісу көтерілісінің ерекшелігі қандай? 2) Жазалаудан құтылуға тырысқан халықтың бір бөлігі қайда көшті?","o":["1 — Әртүрлі ұлт өкілдерінің қатысуы; 2 — Қытайға","1 — Әртүрлі ұлт өкілдерінің қатысуы; 2 — Канадаға","1 — Тек теңізшілердің қатысуы; 2 — Бразилияға","1 — Тек бір отбасының қатысуы; 2 — Қытайға"],"a":0,"e":"Қозғалысқа қазақтармен бірге қырғыздар мен басқа жергілікті халық өкілдері қатысты. Жазалау шараларынан кейін халықтың бір бөлігі Қытай аумағына босып кетуге мәжбүр болды.","l":"B","topic":"1916 жылғы Жетісу көтерілісі"},{"id":"hcl-17-5","t":"«1916 жылғы Жетісу көтерілісі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Босқыншылық тек экономикалық мүмкіндік іздеумен түсіндіріліп, жазалау шараларымен байланыстырылмайды.","Қозғалысқа әртүрлі халықтардың қатысуы олардың отарлық жағдайында ортақ мәселелер болмағанын көрсетеді.","Қарқарадағы қарсылықтың болуы Жетісудағы бүкіл қозғалыстың тек жәрмеңке саудасымен шектелгенін дәлелдейді.","Қозғалыстың көпұлтты сипаты мен босқыншылық отарлық дағдарыстың бүкіл өңірге әсер еткенін көрсетеді."],"a":3,"e":"Қозғалыстың көпұлтты сипаты мен босқыншылық отарлық дағдарыстың бүкіл өңірге әсер еткенін көрсетеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1916 жылғы Жетісу көтерілісі"}]}]},{"number":18,"questions":[{"id":"hm-036","t":"Қазақ КСР Ғылым академиясы қай жылы құрылды?","o":["1961 жылы","1946 жылы","1936 жылы","1920 жылы"],"a":1,"e":"Қазақ КСР Ғылым академиясы 1946 жылы ашылды.","l":"A","topic":"Ғылым","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":214}},{"id":"hi-048","t":"Ыбырай Алтынсариннің Торғайдағы мектебі қай жылы ашылды?","o":["1909 жылы","1853 жылы","1864 жылы","1841 жылы"],"a":2,"e":"Ыбырайдың Торғайдағы мектебі 1864 жылы оқушылар қабылдады.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":153}},{"id":"ha-106","t":"Мемлекеттерді орталықтарымен сәйкестендіріңіз: 1) Ақ Орда; 2) Моғолстан; 3) Ноғай Ордасы. А) Сарайшық; Ә) Сығанақ; Б) Алмалық.","o":["1–Ә, 2–А, 3–Б","1–Ә, 2–Б, 3–А","1–Б, 2–Ә, 3–А","1–А, 2–Б, 3–Ә"],"a":1,"e":"Ақ Орданың орталығы Сығанақ, Моғолстандікі Алмалық, Ноғай Ордасынікі Сарайшық болды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hk-056","t":"«Ақтабан шұбырынды, Алқакөл сұлама» басталған жылды көрсетіңіз.","o":["1771 жыл","1723 жыл","1643 жыл","1731 жыл"],"a":1,"e":"1723 жылғы жоңғар шапқыншылығы халықтың ауыр босқыншылыққа ұшырауына әкелді.","l":"A","topic":"Ақтабан шұбырынды","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":155}},{"id":"hi-025","t":"Ресей әскері 1853 жылы Сырдария бойындағы қай бекіністі алды?","o":["Қапал","Ақмешіт","Верный","Семей"],"a":1,"e":"Ақмешіт бекінісі 1853 жылы Ресей әскерінің қолына өтті. Кейін ол Перовск деп аталды.","l":"A","topic":"Оңтүстік Қазақстанның қосылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":145}},{"id":"hk-096","t":"Тәуке ханның заңдарды жүйелеуі мен билер беделін күшейтуі қандай ортақ мақсатқа бағытталды?","o":["Әдет-ғұрып құқығын толық жоюға","Руларды тұрақты түрде бір-бірінен оқшаулауға","Хан билігін түгел көрші мемлекетке өткізуге","Ішкі тұрақтылық пен ел бірлігін нығайтуға"],"a":3,"e":"Ортақ құқықтық ережелер мен билердің мәмілегерлігі руаралық қайшылықтарды реттеуге көмектесті.","l":"B","topic":"Құқықтық тәртіп","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}},{"id":"hm-059","t":"Қазақстан БҰҰ-ға қашан мүше болды?","o":["1991 жылғы 1 желтоқсанда","1995 жылғы 30 тамызда","1993 жылғы 15 қарашада","1992 жылғы 2 наурызда"],"a":3,"e":"Қазақстан БҰҰ мүшелігіне 1992 жылғы 2 наурызда қабылданды.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":209}},{"id":"hi-110","t":"Үш тұлға мен қызметін дұрыс сәйкестендіріңіз: Шоқан; Ыбырай; Абай.","o":["Поэзия және қарасөздер; Қашғарияны зерттеу; мектеп пен оқулық","Қашғарияны зерттеу; хан сайлау; округ реформасын әзірлеу","Қашғарияны зерттеу; мектеп пен оқулық; поэзия және қарасөздер","Мектеп пен оқулық; поэзия және қарасөздер; Қашғарияны зерттеу"],"a":2,"e":"Шоқан ғылыми саяхаттарымен, Ыбырай педагогтік қызметімен, Абай әдеби-философиялық мұрасымен белгілі.","l":"C","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":152}},{"id":"ha-062","t":"Шыңғыс ханның Қазақстан мен Орта Азияға жорығы басталған жылды көрсетіңіз.","o":["1236 жыл","1227 жыл","1206 жыл","1219 жыл"],"a":3,"e":"Отырарға шабуылмен байланысты ірі моңғол жорығы 1219 жылы басталды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":93}},{"id":"hm-100","t":"Қазақтың алғашқы кәсіби театры 1926 жылы ашылған қаланы анықтаңыз.","o":["Ақмола","Орынбор","Қызылорда","Қарағанды"],"a":2,"e":"1926 жылы алғашқы қазақ кәсіби театры сол кездегі астана Қызылордада ашылды.","l":"B","topic":"Мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}}],"contexts":[{"id":"hce-18","title":"Оғыздардың билік атақтары","text":"Оғыз мемлекеті Сырдарияның төменгі ағысы мен Арал маңында қалыптасты. Жаңакент саяси орталық саналды. Жоғарғы билеуші жабғу, әскер басшысы сюбашы деп аталды. Бұл атақтар билік пен әскери қызметтің айырмасын көрсетеді. Оғыздар көршілермен одақтасып та, соғысып та отырды. Қала мен дала арасындағы айырбас шаруашылықты толықтырды. Ішкі тайпалық қатынастарды реттеу маңызды болды. Кейін қыпшақтардың күшеюі саяси жағдайға әсер етті. Мемлекет тарихында ішкі ұйымдасу мен сыртқы қысым қатар көрінеді. Билеуші атағын әскер басшысының атағымен шатастыру саяси құрылымды қате түсіндіруге әкеледі.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":145},"questions":[{"id":"hce-18-1","t":"«Оғыздардың билік атақтары» контексі: Оғыз мемлекетінің орталығы қайсы?","o":["Жаңакент","Сарай-Бату","Суяб","Сығанақ"],"a":0,"e":"Мәтіндегі деректер «Жаңакент» деген жауапты негіздейді. Жабғу мен сюбашы әртүрлі қызметті білдірді.","l":"A","topic":"Оғыздардың билік атақтары"},{"id":"hce-18-2","t":"«Оғыздардың билік атақтары» контексі: Оғыз әскер басшысы қалай аталды?","o":["Күнби","Басқақ","Қаған","Сюбашы"],"a":3,"e":"Мәтіндегі деректер «Сюбашы» деген жауапты негіздейді. Жабғу мен сюбашы әртүрлі қызметті білдірді.","l":"A","topic":"Оғыздардың билік атақтары"},{"id":"hce-18-3","t":"«Оғыздардың билік атақтары» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Қыпшақтардың күшеюі оғыздарға еш әсер етпеген","Оғыздардың орталығы Алтайда болған","Жабғу мен сюбашы міндетті түрде бір қызметтің екі атауы","Жабғу мен сюбашы әртүрлі қызметті білдірді"],"a":3,"e":"Мәтіндегі деректер «Жабғу мен сюбашы әртүрлі қызметті білдірді» деген жауапты негіздейді. Жабғу мен сюбашы әртүрлі қызметті білдірді.","l":"B","topic":"Оғыздардың билік атақтары"},{"id":"hce-18-4","t":"«Оғыздардың билік атақтары» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Әскери басшы атағын білу барлық ішкі қатынасты толық ашады","Қалалық айырбас көшпелі шаруашылыққа қатыссыз болды","Ішкі тайпалық қатынас мемлекеттің өміріне әсер етпейді","Атақтың мағынасын ажырату мемлекеттік құрылымды түсіндіруге көмектеседі"],"a":3,"e":"Мәтіндегі деректер «Атақтың мағынасын ажырату мемлекеттік құрылымды түсіндіруге көмектеседі» деген жауапты негіздейді. Жабғу мен сюбашы әртүрлі қызметті білдірді.","l":"B","topic":"Оғыздардың билік атақтары"},{"id":"hce-18-5","t":"«Оғыздардың билік атақтары» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Жабғу мен сюбашы міндетті түрде бір қызметтің екі атауы","Оғыз мемлекеті Сырдарияның төменгі ағысы мен Арал маңында қалыптасты.","Атақтың мағынасын ажырату мемлекеттік құрылымды түсіндіруге көмектеседі","Жабғу мен сюбашы әртүрлі қызметті білдірді"],"a":0,"e":"Мәтіндегі деректер «Жабғу мен сюбашы міндетті түрде бір қызметтің екі атауы» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Атақтың мағынасын ажырату мемлекеттік құрылымды түсіндіруге көмектеседі.","l":"C","topic":"Оғыздардың билік атақтары"}]},{"id":"hcl-18","title":"Азамат соғысы кезіндегі Қазақстан","text":"1917 жылдан кейінгі билік үшін күрес Қазақстан аумағын да қамтыды. Азамат соғысы шаруашылықты күйретіп, халықтың күнделікті тұрмысына және саяси ұйымдардың тағдырына ықпал етті.\n\nҚазақстандағы Азамат соғысының негізгі қимылдары 1918–1920 жылдары жүрді. Азамат соғысы әртүрлі саяси күштердің ел ішіндегі билік үшін қарулы күресі болды. Азамат соғысы жағдайында кеңес билігі әскери коммунизм саясатын жүргізді. Қарулы қақтығыстар өндірісті әлсіретіп, ауыл шаруашылығы мен көлік қатынасын күйзеліске ұшыратты.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15},"questions":[{"id":"hcl-18-1","t":"«Азамат соғысы кезіндегі Қазақстан» контексі: Қазақстандағы Азамат соғысының негізгі кезеңі қай жылдарға жатады?","o":["1918–1920 жылдарға","1931–1933 жылдарға","1941–1945 жылдарға","1837–1847 жылдарға"],"a":0,"e":"Қазақстандағы Азамат соғысының негізгі қимылдары 1918–1920 жылдары жүрді.","l":"A","topic":"Азамат соғысы кезіндегі Қазақстан"},{"id":"hcl-18-2","t":"«Азамат соғысы кезіндегі Қазақстан» контексі: Азамат соғысының басты саяси сипаты қандай?","o":["Тек сыртқы сауда келісімі","Тек археологиялық экспедиция","Тек мектеп реформасы","Ел ішіндегі билік үшін қарулы күрес"],"a":3,"e":"Азамат соғысы әртүрлі саяси күштердің ел ішіндегі билік үшін қарулы күресі болды.","l":"A","topic":"Азамат соғысы кезіндегі Қазақстан"},{"id":"hcl-18-3","t":"«Азамат соғысы кезіндегі Қазақстан» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстандағы Азамат соғысының негізгі кезеңі қай жылдарға жатады. 2) Соғыс жылдарында большевиктер қандай экономикалық саясат жүргізді.","o":["1 — 1837–1847 жылдарға; 2 — Әскери коммунизм","1 — 1931–1933 жылдарға; 2 — Нарықтық жекешелендіру","1 — 1918–1920 жылдарға; 2 — Жаңа экономикалық саясат","1 — 1918–1920 жылдарға; 2 — Әскери коммунизм"],"a":3,"e":"Қазақстандағы Азамат соғысының негізгі қимылдары 1918–1920 жылдары жүрді. Азамат соғысы жағдайында кеңес билігі әскери коммунизм саясатын жүргізді.","l":"B","topic":"Азамат соғысы кезіндегі Қазақстан"},{"id":"hcl-18-4","t":"«Азамат соғысы кезіндегі Қазақстан» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Азамат соғысының басты саяси сипаты қандай? 2) Соғыстың шаруашылыққа әсері қандай болды?","o":["1 — Тек сыртқы сауда келісімі; 2 — Өндіріс пен шаруашылықтың күйреуі","1 — Ел ішіндегі билік үшін қарулы күрес; 2 — Өндіріс пен шаруашылықтың күйреуі","1 — Тек археологиялық экспедиция; 2 — Салықтың толық жойылуы","1 — Ел ішіндегі билік үшін қарулы күрес; 2 — Барлық саланың кедергісіз өсуі"],"a":1,"e":"Азамат соғысы әртүрлі саяси күштердің ел ішіндегі билік үшін қарулы күресі болды. Қарулы қақтығыстар өндірісті әлсіретіп, ауыл шаруашылығы мен көлік қатынасын күйзеліске ұшыратты.","l":"B","topic":"Азамат соғысы кезіндегі Қазақстан"},{"id":"hcl-18-5","t":"«Азамат соғысы кезіндегі Қазақстан» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Саяси қақтығыс пен төтенше экономикалық саясат қоғамның шаруашылық дағдарысын тереңдетті.","Шаруашылықтың күйреуі саяси күрестен бөлек жүріп, соғыс барысына тәуелсіз қалыптасты.","Соғыс кезіндегі экономикалық шаралар өндірістің күйзелісін өздігінен жойып, шаруашылықты дағдарыстан бірден шығарды.","Әскери коммунизм ресурстарды жинағандықтан, оның шаруалардың жағдайына қайшылықты әсері болуы мүмкін емес еді."],"a":0,"e":"Саяси қақтығыс пен төтенше экономикалық саясат қоғамның шаруашылық дағдарысын тереңдетті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Азамат соғысы кезіндегі Қазақстан"}]}]},{"number":19,"questions":[{"id":"ha-040","t":"Түрік қағанатының негізін қалаған билеуші кім?","o":["Бумын","Сатұқ Боғра","Сұлу","Білге Күл Қадыр"],"a":0,"e":"Бумын қаған Түрік қағанатының негізін қалаушы ретінде белгілі.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":146}},{"id":"hk-119","t":"Даталар мен оқиғалардың дұрыс сәйкестігін таңдаңыз.","o":["1580 — Тәуекел елшілігі; 1594 — Есімнің таққа келуі; 1598 — Хақназардың қазасы","1580 — Хақназардың қазасы; 1594 — Есімнің таққа келуі; 1598 — Тәуекел елшілігі","1580 — Хақназардың қазасы; 1594 — Тәуекел елшілігі; 1598 — Есімнің таққа келуі","1580 — Есімнің таққа келуі; 1594 — Хақназардың қазасы; 1598 — Тәуекел елшілігі"],"a":2,"e":"Хақназар 1580 жылы қаза тапты; Мәскеу елшілігі 1594 жылы жіберілді; Есім билігі 1598 жылы басталды.","l":"C","topic":"Даталар және билеушілер","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hk-058","t":"XVIII ғасырдың 20-жылдарының соңында жоңғарларға қарсы өткен ірі шайқас қайсы?","o":["Атлах","Аңырақай","Батпақ","Қатуан"],"a":1,"e":"Аңырақай шайқасы 1729–1730 жылдармен байланыстырылып, қазақ-жоңғар соғыстарының маңызды жеңісі саналады.","l":"A","topic":"Аңырақай шайқасы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hk-062","t":"Абылайдың хан болып сайланған жылы қайсы?","o":["1723 жыл","1837 жыл","1710 жыл","1771 жыл"],"a":3,"e":"1771 жылы Түркістанда Абылай хан сайланды.","l":"A","topic":"Абылай хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hm-106","t":"Құжаттар мен реформаларды реттеңіз: 1 — ұлттық валютаның енгізілуі; 2 — егемендік декларациясы; 3 — 1995 жылғы Конституция; 4 — тәуелсіздік туралы заң; 5 — тәуелсіз елдің алғашқы Конституциясы.","o":["2–4–1–5–3","4–2–5–1–3","2–5–4–3–1","2–4–5–1–3"],"a":3,"e":"Декларация 1990 жылы, тәуелсіздік заңы 1991 жылы қабылданды. 1993 жылғы Конституция қаңтарда, теңге қарашада, жаңа Конституция 1995 жылы қабылданды.","l":"C","topic":"Хронология","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"ha-080","t":"Түркі қағандарының ел басқару қызметін өз дәуірінің жазба ескерткіштері арқылы зерттеу үшін қай деректі таңдау керек?","o":["Алаш партиясының бағдарламасы","Күлтегін мен Білге қаған жазбалары","Қазақ КСР Конституциясы","Қарқаралы петициясы"],"a":1,"e":"VIII ғасырдағы Орхон жазбалары түркі билеушілерінің қызметі мен ел бірлігі туралы өз дәуірінің деректерін сақтаған.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":22}},{"id":"hi-037","t":"Маңғыстаудағы ірі отаршылдыққа қарсы көтеріліс қай жылы өтті?","o":["1847 жылы","1870 жылы","1905 жылы","1838 жылы"],"a":1,"e":"Маңғыстау көтерілісі 1870 жылы болды. Оның себептерінің бірі жаңа әкімшілік және салық тәртібіне қарсылық еді.","l":"A","topic":"1868–1870 жылдардағы көтерілістер","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":156}},{"id":"hi-083","t":"Шоқан Уәлиханов пен Ыбырай Алтынсарин қызметінің ортақ бағытын көрсетіңіз.","o":["Хандық басқаруды 1841 жылы енгізу","Кеңестік ұжымдастыруды ұйымдастыру","Білім мен ғылымды дамыту","Патша әскеріне қарсы бір көтерілісті басқару"],"a":2,"e":"Шоқан ғылыми зерттеулер жүргізді, Ыбырай мектептер ашып, оқулықтар жазды. Екеуі де ағартушылыққа үлес қосты.","l":"B","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":34}},{"id":"hm-010","t":"Ф.Голощекин Қазақстанның өлкелік партия ұйымын қай жылдары басқарды?","o":["1954–1964 жылдары","1925–1933 жылдары","1938–1946 жылдары","1917–1920 жылдары"],"a":1,"e":"Голощекиннің 1925–1933 жылдардағы басшылығы ұжымдастыру мен ашаршылық кезеңіне сәйкес келді.","l":"A","topic":"Ұжымдастыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":238}},{"id":"ha-072","t":"Ноғай Ордасының қалыптасуында үлкен рөл атқарған әмірді атаңыз.","o":["Бумын","Сұлу","Едіге","Қайыр хан"],"a":2,"e":"Едігенің билігі мен маңғыт әмірлерінің ықпалы Ноғай Ордасының қалыптасуына негіз болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":149}}],"contexts":[{"id":"hce-19","title":"Қимақ-қыпшақ саяси сабақтастығы","text":"Қимақ қағанаты IX–XI ғасырлардағы Қазақстан тарихымен байланысты. Негізгі аумағы Ертіс бойын және оған жақын өңірлерді қамтыды. Бірлестік құрамында қыпшақ тайпалары да болды. Жоғарғы билеуші қаған атағын қолданды. Бұл саяси мәртебенің өскенін көрсетеді. Мал шаруашылығы негізгі кәсіптердің бірі еді. Кейін қыпшақ ықпалы артып, күштер арақатынасы өзгерді. Бір одақ құрамындағы тайпа кейін дербес саяси рөл атқара алады. Мұндай өзгеріс халықтың бірден жоғалғанын білдірмейді. Қимақтар мен қыпшақтардың байланысы тайпалық бірлестік және мемлекет арасындағы сабақтастықты талдауға мүмкіндік береді. Уақыт пен саяси жағдайды нақтылау маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":144},"questions":[{"id":"hce-19-1","t":"«Қимақ-қыпшақ саяси сабақтастығы» контексі: Қимақтардың негізгі өзені қайсы?","o":["Сырдария","Іле","Еділ","Ертіс"],"a":3,"e":"Мәтіндегі деректер «Ертіс» деген жауапты негіздейді. Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді.","l":"A","topic":"Қимақ-қыпшақ саяси сабақтастығы"},{"id":"hce-19-2","t":"«Қимақ-қыпшақ саяси сабақтастығы» контексі: Қимақ құрамында кейін күшейген тайпа қайсы?","o":["Қидан","Жоңғар","Қыпшақ","Манчжур"],"a":2,"e":"Мәтіндегі деректер «Қыпшақ» деген жауапты негіздейді. Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді.","l":"A","topic":"Қимақ-қыпшақ саяси сабақтастығы"},{"id":"hce-19-3","t":"«Қимақ-қыпшақ саяси сабақтастығы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Бір одақтағы тайпа кейін дербес күшке айнала алмайды","Қимақтар Ертіс өңірімен байланыспаған","Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді","Қыпшақтардың күшеюі халықтың түгел жойылуын білдірді"],"a":2,"e":"Мәтіндегі деректер «Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді» деген жауапты негіздейді. Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді.","l":"B","topic":"Қимақ-қыпшақ саяси сабақтастығы"},{"id":"hce-19-4","t":"«Қимақ-қыпшақ саяси сабақтастығы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Қаған атағы тек діни қызметті білдірген","Жаңа билік пайда болса бұрынғы тайпалардың бәрі жоғалады","Саяси бірлестіктер арасында халықтық және аумақтық сабақтастық болуы мүмкін","Мал шаруашылығы мемлекеттік ұйымдасуды жоққа шығарады"],"a":2,"e":"Мәтіндегі деректер «Саяси бірлестіктер арасында халықтық және аумақтық сабақтастық болуы мүмкін» деген жауапты негіздейді. Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді.","l":"B","topic":"Қимақ-қыпшақ саяси сабақтастығы"},{"id":"hce-19-5","t":"«Қимақ-қыпшақ саяси сабақтастығы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Саяси бірлестіктер арасында халықтық және аумақтық сабақтастық болуы мүмкін","Қаған атағы билеушінің жоғары саяси мәртебесін көрсетеді","Бір одақтағы тайпа кейін дербес күшке айнала алмайды","Қимақ қағанаты IX–XI ғасырлардағы Қазақстан тарихымен байланысты."],"a":2,"e":"Мәтіндегі деректер «Бір одақтағы тайпа кейін дербес күшке айнала алмайды» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Саяси бірлестіктер арасында халықтық және аумақтық сабақтастық болуы мүмкін.","l":"C","topic":"Қимақ-қыпшақ саяси сабақтастығы"}]},{"id":"hcl-19","title":"Қазақ автономиясының құрылуы","text":"Кеңес билігі орнағаннан кейін қазақ жерлерін бір әкімшілік құрылымға біріктіру мәселесі көтерілді. Автономия құру ұлттық аумақтық мемлекеттіліктің кеңестік үлгісін қалыптастырды.\n\n1920 жылы Қазақ автономиялық республикасы құрылды, сол кездегі ресми атауда «Қырғыз» сөзі қолданылды. Құрылған автономияның алғашқы астанасы Орынбор қаласы болды. 1925 жылы республика атауында «қазақ» этнонимі ресми қалпына келтірілді. 1936 жылы Қазақ АКСР-і одақтас республика — Қазақ КСР-і болып қайта құрылды. Хронологиялық сызба: 1920 — автономия; 1925 — қазақ атауы; 1936 — одақтас республика.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-19-1","t":"«Қазақ автономиясының құрылуы» контексі: Қазақ автономиялық республикасы қай жылы құрылды?","o":["1936 жылы","1991 жылы","1920 жылы","1913 жылы"],"a":2,"e":"1920 жылы Қазақ автономиялық республикасы құрылды, сол кездегі ресми атауда «Қырғыз» сөзі қолданылды.","l":"A","topic":"Қазақ автономиясының құрылуы"},{"id":"hcl-19-2","t":"«Қазақ автономиясының құрылуы» контексі: Республиканың алғашқы астанасы қай қала болды?","o":["Түркістан","Ақмола","Орынбор","Алматы"],"a":2,"e":"Құрылған автономияның алғашқы астанасы Орынбор қаласы болды.","l":"A","topic":"Қазақ автономиясының құрылуы"},{"id":"hcl-19-3","t":"«Қазақ автономиясының құрылуы» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақ автономиялық республикасы қай жылы құрылды. 2) 1925 жылы республика атауындағы қандай этноним қалпына келді.","o":["1 — 1936 жылы; 2 — Оғыз","1 — 1920 жылы; 2 — Қыпшақ","1 — 1913 жылы; 2 — Қазақ","1 — 1920 жылы; 2 — Қазақ"],"a":3,"e":"1920 жылы Қазақ автономиялық республикасы құрылды, сол кездегі ресми атауда «Қырғыз» сөзі қолданылды. 1925 жылы республика атауында «қазақ» этнонимі ресми қалпына келтірілді.","l":"B","topic":"Қазақ автономиясының құрылуы"},{"id":"hcl-19-4","t":"«Қазақ автономиясының құрылуы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Республиканың алғашқы астанасы қай қала болды? 2) 1936 жылы республика қандай мәртебе алды?","o":["1 — Ақмола; 2 — Жеке империя","1 — Орынбор; 2 — Одақтас республика","1 — Орынбор; 2 — Тәуелсіз хандық","1 — Алматы; 2 — Одақтас республика"],"a":1,"e":"Құрылған автономияның алғашқы астанасы Орынбор қаласы болды. 1936 жылы Қазақ АКСР-і одақтас республика — Қазақ КСР-і болып қайта құрылды.","l":"B","topic":"Қазақ автономиясының құрылуы"},{"id":"hcl-19-5","t":"«Қазақ автономиясының құрылуы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["1920 жылы автономия құрылуы мен 1936 жылғы мәртебе өзгерісі құқықтық жағынан бірдей оқиға болды.","1920 және 1936 жылдардағы өзгерістер кеңестік мемлекеттілік мәртебесінің әртүрлі сатыларын білдіреді.","Астананың Орынборда болуы ұлттық аумақтық мемлекеттілікті қалыптастыруға ұмтылыс болмағанын көрсетеді.","1925 жылғы атау өзгерісі автономияны сол жылы-ақ одақтас республикаға айналдырды."],"a":1,"e":"1920 және 1936 жылдардағы өзгерістер кеңестік мемлекеттілік мәртебесінің әртүрлі сатыларын білдіреді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қазақ автономиясының құрылуы"}]}]},{"number":20,"questions":[{"id":"hk-089","t":"Абылайдың Ресей және Қытаймен қатар байланыс ұстауы қандай саяси міндетке қызмет етті?","o":["Қазақ хандығының дербестігін сақтауға","Жоңғарияның билік жүйесін қазақтарға енгізуге","Хандықтың сыртқы саясатын көршілерге толық беруге","Қазақ жүздерін бір-бірінен саяси оқшаулауға"],"a":0,"e":"Абылай ірі көршілер арасындағы тепе-теңдікті пайдаланып, хандықтың мүддесі мен дербестігін қорғауға тырысты.","l":"B","topic":"Абылай ханның дипломатиясы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"ha-111","t":"Алтын Орда мен Ақ Орданың тарихи байланысын түсіндіретін екі белгіні таңдаңыз: I. Жошы әулеті биледі. II. Билік Қарахан әулетіне тиесілі болды. III. Жошы ұлысының саяси мұрасымен байланысты. IV. Екеуі де VI ғасырда құрылды.","o":["III және IV","I және III","I және II","II және IV"],"a":1,"e":"Екі мемлекеттің билеушілері Жошы әулетінен шықты және олардың аумақтық-саяси тарихы Жошы ұлысымен байланысты.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-057","t":"Бұланты бойындағы жеңіске байланысты қалыптасқан жер атауы қайсы?","o":["Қалмаққырылған","Қозыбасы","Орбұлақ","Қатуан"],"a":0,"e":"Бұланты-Білеуті шайқасындағы жеңіс «Қалмаққырылған» атауымен байланыстырылады.","l":"A","topic":"Бұланты шайқасы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hi-015","t":"Кенесары Қасымұлы бастаған ұлт-азаттық қозғалыстың мерзімі қандай?","o":["1916–1917 жылдар","1783–1797 жылдар","1836–1838 жылдар","1837–1847 жылдар"],"a":3,"e":"Кенесары қозғалысы 1837 жылдан 1847 жылға дейін жалғасты.","l":"A","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":17}},{"id":"hm-086","t":"Урбанизация ұғымы Қазақстанның кеңестік тарихында нені білдіреді?","o":["Қала халқы мен қалалардың рөлінің өсуін","Ауыл халқының тек көшпелі өмірге оралуын","Барлық қаланың ауылға айналуын","Мемлекет шекарасының белгіленуін"],"a":0,"e":"Өнеркәсіптің дамуы еңбек күшін қалаларға тартып, қала тұрғындарының үлесін арттырды.","l":"B","topic":"Тоқырау","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hm-034","t":"Ұлы Отан соғысы жылдарында ферроқорытпа зауыты іске қосылған қаланы көрсетіңіз.","o":["Көкшетау","Ақтөбе","Талдықорған","Түркістан"],"a":1,"e":"Ақтөбе ферроқорытпа зауыты соғыс кезіндегі металлургиялық өндірісті толықтырды.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"hi-060","t":"Мұхамеджан Сералин редакторлық еткен журналды көрсетіңіз.","o":["Түркістан уалаятының газеті","Айқап","Еңбекші қазақ","Қазақ"],"a":1,"e":"«Айқап» журналын Мұхамеджан Сералин басқарды. Журнал ағарту және қоғамдық мәселелерді талқылады.","l":"A","topic":"XX ғасыр басындағы баспасөз","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":168}},{"id":"hi-108","t":"Оқиғалардың дұрыс ретін таңдаңыз: 1) Верный бекінісінің салынуы; 2) Ақмешіттің алынуы; 3) Ұзынағаш шайқасы.","o":["2 → 3 → 1","1 → 2 → 3","3 → 1 → 2","2 → 1 → 3"],"a":3,"e":"Ақмешіт 1853 жылы алынды, Верный 1854 жылы салынды, Ұзынағаш шайқасы 1860 жылы өтті.","l":"C","topic":"Оңтүстік Қазақстан хронологиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":165}},{"id":"hm-045","t":"Тың игерудің мал шаруашылығына кері әсерінің бірін көрсетіңіз.","o":["Барлық жайылымның кеңеюі","Жайылымдардың жыртылуы","Жердің жыртылмай қалуы","Мал санының міндетті түрде он есе өсуі"],"a":1,"e":"Егістік көлемін шұғыл ұлғайту жайылым алқаптарын қысқартты.","l":"A","topic":"Тың игеру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"ha-064","t":"Алтын Орданың негізін қалаған хан кім?","o":["Батый","Әбілқайыр","Барақ","Есенбұға"],"a":0,"e":"Батыйдың батыс жорықтары мен билігі Алтын Орданың қалыптасуына негіз болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":133}}],"contexts":[{"id":"hce-20","title":"Қарахан мемлекеті: ресми дін және қоғам","text":"Қарахан мемлекеті X ғасырда Жетісу мен Мәуереннахрда қалыптасты. 960 жылы Мұса хан тұсында ислам мемлекеттік дін ретінде қабылданды. Баласағұн мен Қашғар маңызды орталықтар болды. Мешіттер, медреселер және кесенелер қалалық мәдениеттің дамуын көрсетеді. Мемлекеттік шешім діни институттарға қолдау берді. Бірақ бүкіл тұрғынның сенімі бір мезетте өзгерген жоқ. Исламның таралуына сауда мен білім ортасы да ықпал етті. Ресми мәртебе мен қоғамдағы таралу қарқынын ажырату қажет. Діни өзгеріс саяси билікпен және қалалық өмірмен ұштасқан. Бір күнді білу ұзақ мәдени үдерістің барлық қырын толық түсіндірмейді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":144},"questions":[{"id":"hce-20-1","t":"«Қарахан мемлекеті: ресми дін және қоғам» контексі: Исламға мемлекеттік мәртебе берген билеуші кім?","o":["Тоғылық Темір","Мұса хан","Бумын","Батый"],"a":1,"e":"Мәтіндегі деректер «Мұса хан» деген жауапты негіздейді. Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды.","l":"A","topic":"Қарахан мемлекеті: ресми дін және қоғам"},{"id":"hce-20-2","t":"«Қарахан мемлекеті: ресми дін және қоғам» контексі: Мәтінде аталған ресми қабылдау жылы қайсы?","o":["1206","960","1465","751"],"a":1,"e":"Мәтіндегі деректер «960» деген жауапты негіздейді. Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды.","l":"A","topic":"Қарахан мемлекеті: ресми дін және қоғам"},{"id":"hce-20-3","t":"«Қарахан мемлекеті: ресми дін және қоғам» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Медреселер тек әскери қойма болған","Қарахан мемлекетінде қалалық өмір болмаған","960 жылы барлық тұрғынның сенімі бір мезетте өзгерді","Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды"],"a":3,"e":"Мәтіндегі деректер «Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды» деген жауапты негіздейді. Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды.","l":"B","topic":"Қарахан мемлекеті: ресми дін және қоғам"},{"id":"hce-20-4","t":"«Қарахан мемлекеті: ресми дін және қоғам» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Сауда мен білім дін таралуына ықпал етпеді","Мемлекеттік шешім мен қоғамдағы дін таралуы бірдей жылдамдықпен жүрмейді","Ресми күн бүкіл мәдени үдерісті толық сипаттайды","Мешіттердің болуы басқа мәдени байланыстардың бәрін тоқтатты"],"a":1,"e":"Мәтіндегі деректер «Мемлекеттік шешім мен қоғамдағы дін таралуы бірдей жылдамдықпен жүрмейді» деген жауапты негіздейді. Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды.","l":"B","topic":"Қарахан мемлекеті: ресми дін және қоғам"},{"id":"hce-20-5","t":"«Қарахан мемлекеті: ресми дін және қоғам» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Мемлекеттік шешім мен қоғамдағы дін таралуы бірдей жылдамдықпен жүрмейді","Қарахан мемлекеті X ғасырда Жетісу мен Мәуереннахрда қалыптасты.","Баласағұн мен Қашғар Қарахан дәуірінің орталықтары болды","960 жылы барлық тұрғынның сенімі бір мезетте өзгерді"],"a":3,"e":"Мәтіндегі деректер «960 жылы барлық тұрғынның сенімі бір мезетте өзгерді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Мемлекеттік шешім мен қоғамдағы дін таралуы бірдей жылдамдықпен жүрмейді.","l":"C","topic":"Қарахан мемлекеті: ресми дін және қоғам"}]},{"id":"hcl-20","title":"Әскери коммунизмнің ерекшелігі","text":"Азамат соғысы кезінде билік ресурстарды төтенше тәсілдермен жинауға ұмтылды. Әскери коммунизм саясатындағы мәжбүрлеу шаруалардың ынтасын әлсіретіп, экономикалық қиындықтарды күшейтті.\n\nӘскери коммунизм кезінде шаруалардан азық-түлік салғырты арқылы өнім жиналды. Салғырт шаруалардың өнімін міндетті түрде тапсыруын талап етті. Бұл саясат Азамат соғысы кезіндегі төтенше қажеттіліктермен байланысты жүргізілді. 1921 жылы әскери коммунизмнен жаңа экономикалық саясатқа көшу басталды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-20-1","t":"«Әскери коммунизмнің ерекшелігі» контексі: Азық-түлік салғырты қандай саясатқа тән?","o":["Әскери коммунизмге","Жаңа экономикалық саясатқа","Нарықтық жекешелендіруге","Тың игеруге"],"a":0,"e":"Әскери коммунизм кезінде шаруалардан азық-түлік салғырты арқылы өнім жиналды.","l":"A","topic":"Әскери коммунизмнің ерекшелігі"},{"id":"hcl-20-2","t":"«Әскери коммунизмнің ерекшелігі» контексі: Салғырттың негізгі сипаты қандай?","o":["Шетелдік инвестиция","Еркін нарықтағы несие","Тек ерікті қайырымдылық","Өнімді міндетті түрде алып қою"],"a":3,"e":"Салғырт шаруалардың өнімін міндетті түрде тапсыруын талап етті.","l":"A","topic":"Әскери коммунизмнің ерекшелігі"},{"id":"hcl-20-3","t":"«Әскери коммунизмнің ерекшелігі» контексі: Екі деректі сәйкестендіріңіз. 1) Азық-түлік салғырты қандай саясатқа тән. 2) Әскери коммунизм қай жағдаймен байланысты болды.","o":["1 — Әскери коммунизмге; 2 — Азамат соғысымен","1 — Тың игеруге; 2 — ЭКСПО көрмесімен","1 — Жаңа экономикалық саясатқа; 2 — Азамат соғысымен","1 — Әскери коммунизмге; 2 — Тың игерумен"],"a":0,"e":"Әскери коммунизм кезінде шаруалардан азық-түлік салғырты арқылы өнім жиналды. Бұл саясат Азамат соғысы кезіндегі төтенше қажеттіліктермен байланысты жүргізілді.","l":"B","topic":"Әскери коммунизмнің ерекшелігі"},{"id":"hcl-20-4","t":"«Әскери коммунизмнің ерекшелігі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Салғырттың негізгі сипаты қандай? 2) 1921 жылы әскери коммунизмнің орнына не енгізілді?","o":["1 — Өнімді міндетті түрде алып қою; 2 — Жаңа экономикалық саясат","1 — Тек ерікті қайырымдылық; 2 — Жаңа экономикалық саясат","1 — Өнімді міндетті түрде алып қою; 2 — Отарлық округтік жүйе","1 — Еркін нарықтағы несие; 2 — Күштеп ұжымдастыру"],"a":0,"e":"Салғырт шаруалардың өнімін міндетті түрде тапсыруын талап етті. 1921 жылы әскери коммунизмнен жаңа экономикалық саясатқа көшу басталды.","l":"B","topic":"Әскери коммунизмнің ерекшелігі"},{"id":"hcl-20-5","t":"«Әскери коммунизмнің ерекшелігі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Салғыртты салықпен алмастыру әскери коммунизмнің мәжбүрлеу тәсілін өзгеріссіз жалғастыру болды.","Әскери коммунизмнің Азамат соғысымен байланысы оның бейбіт кезеңдегі шаруашылыққа да еш қиындықсыз жарағанын дәлелдейді.","Мәжбүрлі өнім жинау дағдарысы шаруашылық ынтасын қалпына келтіретін жаңа саясатқа көшу қажеттігін туғызды.","Өнімді міндетті жинау шаруаның жеке ынтасын күшейтіп, жаңа саясатқа көшу қажеттігін жойды."],"a":2,"e":"Мәжбүрлі өнім жинау дағдарысы шаруашылық ынтасын қалпына келтіретін жаңа саясатқа көшу қажеттігін туғызды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Әскери коммунизмнің ерекшелігі"}]}]},{"number":21,"questions":[{"id":"hk-024","t":"Қасым хан үшін оңтүстіктегі маңызды саяси мақсат қандай болды?","o":["Сырдария бойындағы қалаларды қарату","Шығыс Түркістандағы барлық қалаларды бағындыру","Еділ бойындағы қалаларды толық қарату","Мәскеу мемлекетінің тағына ықпал ету"],"a":0,"e":"Сырдария қалалары сауда, егіншілік және стратегиялық жолдар үшін маңызды болды.","l":"A","topic":"Қасым ханның сыртқы саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":83}},{"id":"hi-049","t":"«Қазақ хрестоматиясының» авторы кім?","o":["Абай Құнанбайұлы","Ыбырай Алтынсарин","Дулат Бабатайұлы","Шоқан Уәлиханов"],"a":1,"e":"Ыбырай Алтынсарин 1879 жылы «Қазақ хрестоматиясын» шығарды. Оқулық оқу-ағарту ісіне арналды.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":34}},{"id":"ha-006","t":"Мыс пен қалайыны қосу арқылы алынатын қорытпа қайсы?","o":["Шойын","Болат","Қола","Жез"],"a":2,"e":"Қола мыс пен қалайының қорытпасы болып табылады.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-107","t":"1991–1995 жылдар оқиғаларын реттеңіз: 1 — БҰҰ мүшелігі; 2 — теңгенің енгізілуі; 3 — Семей полигонының жабылуы; 4 — жаңа Конституцияның референдумда қабылдануы; 5 — ту мен елтаңбаның бекітілуі.","o":["3–1–5–2–4","3–1–2–5–4","3–5–1–2–4","1–3–5–4–2"],"a":0,"e":"Полигон 1991 жылы жабылды. БҰҰ мүшелігі — 1992 жылғы наурыз, рәміздер — сол жылғы маусым, теңге — 1993, Конституция — 1995 жыл.","l":"C","topic":"Хронология","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":209}},{"id":"ha-093","t":"Сұлу қағанның арабтардың шығысқа қарай ілгерілеуіне қарсы тұруын қандай мақсат түсіндіреді?","o":["Араб халифатының астанасын Жетісуға көшіру","Сырдариядағы барлық қалаларды жою","Алтын Ордадағы билікті мұралау","Қағанаттың саяси дербестігін қорғау"],"a":3,"e":"Түргештердің қарсыласуы сыртқы үстемдіктен қорғанып, Жетісудағы дербес билікті сақтауға бағытталды.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hk-107","t":"Тақырып пен құқық саласының дұрыс сәйкестігін анықтаңыз: 1. Жер дауы. 2. Қосын жасақтау.","o":["1 — мүлік заңы; 2 — әскери заң","1 — жұртшылық заңы; 2 — қылмыс заңы","1 — әскери заң; 2 — елшілік заңы","1 — елшілік заңы; 2 — мүлік заңы"],"a":0,"e":"Жер дауы меншік қатынасына жатады, ал қосын жасақтау әскери міндеттерді реттейді.","l":"C","topic":"Қасым ханның заңдары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}},{"id":"ha-045","t":"Батыс Түрік қағанатының тайпалық құрылымы қандай атаумен белгілі?","o":["Тоғыз оғыз","Жеті жарғы","Үш жүз","Он оқ будун"],"a":3,"e":"Он оқ будун бірлестігі бес дулу және бес нушеби тайпалық тобына негізделді.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":84}},{"id":"hm-013","t":"1929–1931 жылдардағы ауылдық көтерілістер негізінен қай саясатқа қарсы бағытталды?","o":["Жаңа астананы көшіруге","Тың игеруге","Ғарыш айлағын салуға","Күштеп ұжымдастыруға"],"a":3,"e":"Ауылдағы қарсылық ұжымдастыру, тәркілеу және күштеу шараларымен байланысты болды.","l":"A","topic":"Ұжымдастыру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hk-021","t":"Қасым хан заңдарындағы жер дауы қай салаға жатты?","o":["Жұртшылық заңына","Елшілік заңына","Әскери заңға","Мүлік заңына"],"a":3,"e":"Жер мен малға қатысты меншік мәселелері мүлік заңдарына кірді.","l":"A","topic":"Қасым ханның заңдары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}},{"id":"hi-068","t":"Жоламан Тіленшіұлы қозғалысының туындауына тікелей әсер еткен мәселе қандай?","o":["Кеңестік жазу реформасы","Жайылымдық жерлердің тартып алынуы","Ғарыш айлағының салынуы","Ұжымдастырудың басталуы"],"a":1,"e":"Жаңа шептердің салынуы қазақтардың дәстүрлі қоныстарына қолжетімділігін шектеді. Жер мәселесі қарсылықтың басты себептерінің бірі болды.","l":"B","topic":"Жоламан және Саржан көтерілістері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":159}}],"contexts":[{"id":"hce-21","title":"Иқта жүйесіндегі құқық пен қызмет","text":"Қарахан мемлекетінде иқта жүйесі қалыптасты. Билеуші белгілі аумақтан салық жинау құқығын әскери немесе мемлекеттік қызмет үшін бере алды. Құқық иеленуші жердегі барлық тұрғынды өзінің жеке меншігіне айналдырған жоқ. Иқта қызмет, табыс және билік арасындағы байланысты көрсетеді. Оны қазіргі мағынадағы жерді шексіз жеке меншікке сату деп түсіну дәл емес. Мемлекет салық арқылы әскер мен әкімшілікті қамтамасыз етті. Тарихи терминді өз дәуірінің жағдайында талдау қажет. Құқықтың нені қамтығанын ажырату әлеуметтік қатынастарды түсіндіреді. Шаруашылық ресурстары саяси басқарумен тығыз байланысты болды. Бір сөздің қазіргі қолданысы оның ортағасырлық мазмұнын толық алмастырмайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13},"questions":[{"id":"hce-21-1","t":"«Иқта жүйесіндегі құқық пен қызмет» контексі: Иқта мәтінде қай мемлекетпен байланысты?","o":["Жоңғар","Ноғай","Ғұн","Қарахан"],"a":3,"e":"Мәтіндегі деректер «Қарахан» деген жауапты негіздейді. Иқта әскери немесе мемлекеттік қызметпен байланысты болды.","l":"A","topic":"Иқта жүйесіндегі құқық пен қызмет"},{"id":"hce-21-2","t":"«Иқта жүйесіндегі құқық пен қызмет» контексі: Иқта иесіне негізгі қандай құқық берілді?","o":["Барлық тұрғынды көшіру","Хан атағын мұралау","Әліпби өзгерту","Салық жинау"],"a":3,"e":"Мәтіндегі деректер «Салық жинау» деген жауапты негіздейді. Иқта әскери немесе мемлекеттік қызметпен байланысты болды.","l":"A","topic":"Иқта жүйесіндегі құқық пен қызмет"},{"id":"hce-21-3","t":"«Иқта жүйесіндегі құқық пен қызмет» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Иқта барлық тұрғынға шексіз жеке меншік құқығын берді","Иқта қазіргі сайлау округімен толық бірдей","Иқта әскери немесе мемлекеттік қызметпен байланысты болды","Иқта тек діни лауазым болды"],"a":2,"e":"Мәтіндегі деректер «Иқта әскери немесе мемлекеттік қызметпен байланысты болды» деген жауапты негіздейді. Иқта әскери немесе мемлекеттік қызметпен байланысты болды.","l":"B","topic":"Иқта жүйесіндегі құқық пен қызмет"},{"id":"hce-21-4","t":"«Иқта жүйесіндегі құқық пен қызмет» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Шаруашылық табыс мемлекеттік қызметке қатыссыз болды","Салық жинау құқығын шексіз жер меншігімен теңестіруге болмайды","Тарихи терминді қазіргі мағынасымен ғана түсіндіру жеткілікті","Иқта беру мемлекеттің салыққа мұқтаж болмағанын дәлелдейді"],"a":1,"e":"Мәтіндегі деректер «Салық жинау құқығын шексіз жер меншігімен теңестіруге болмайды» деген жауапты негіздейді. Иқта әскери немесе мемлекеттік қызметпен байланысты болды.","l":"B","topic":"Иқта жүйесіндегі құқық пен қызмет"},{"id":"hce-21-5","t":"«Иқта жүйесіндегі құқық пен қызмет» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Иқта әскери немесе мемлекеттік қызметпен байланысты болды","Қарахан мемлекетінде иқта жүйесі қалыптасты.","Иқта барлық тұрғынға шексіз жеке меншік құқығын берді","Салық жинау құқығын шексіз жер меншігімен теңестіруге болмайды"],"a":2,"e":"Мәтіндегі деректер «Иқта барлық тұрғынға шексіз жеке меншік құқығын берді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Салық жинау құқығын шексіз жер меншігімен теңестіруге болмайды.","l":"C","topic":"Иқта жүйесіндегі құқық пен қызмет"}]},{"id":"hcl-21","title":"Жаңа экономикалық саясат","text":"Азамат соғысынан кейін күйзелген шаруашылықты қалпына келтіру қажет болды. Жаңа экономикалық саясат мемлекет бақылауын сақтай отырып, сауда мен шағын кәсіпке белгілі еркіндік берді.\n\n1921 жылы большевиктер партиясының X съезінен кейін ЖЭС-ке көшу басталды. Азық-түлік салғыртының орнына алдын ала белгіленетін азық-түлік салығы енгізілді. Шаруалар салықтан қалған өнімін нарықта сатып, жеке ынтасын арттыра алды. ЖЭС шаруашылықты қалпына келтіруге және халықтың тұрмысын жақсартуға бағытталды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7},"questions":[{"id":"hcl-21-1","t":"«Жаңа экономикалық саясат» контексі: Жаңа экономикалық саясатқа көшу қай жылы басталды?","o":["1921 жылы","1954 жылы","1937 жылы","1913 жылы"],"a":0,"e":"1921 жылы большевиктер партиясының X съезінен кейін ЖЭС-ке көшу басталды.","l":"A","topic":"Жаңа экономикалық саясат"},{"id":"hcl-21-2","t":"«Жаңа экономикалық саясат» контексі: ЖЭС кезінде азық-түлік салғырты немен алмастырылды?","o":["Жалпы әскери міндеткерлікпен","Округтік алыммен","Азық-түлік салығымен","Тың жоспарының тапсырмасымен"],"a":2,"e":"Азық-түлік салғыртының орнына алдын ала белгіленетін азық-түлік салығы енгізілді.","l":"A","topic":"Жаңа экономикалық саясат"},{"id":"hcl-21-3","t":"«Жаңа экономикалық саясат» контексі: Екі деректі сәйкестендіріңіз. 1) Жаңа экономикалық саясатқа көшу қай жылы басталды. 2) Салықтан қалған өнімге қатысты қандай мүмкіндік берілді.","o":["1 — 1937 жылы; 2 — Оны міндетті түрде жасыруға","1 — 1913 жылы; 2 — Оны нарықта сатуға","1 — 1921 жылы; 2 — Оны түгел өртеп жіберуге","1 — 1921 жылы; 2 — Оны нарықта сатуға"],"a":3,"e":"1921 жылы большевиктер партиясының X съезінен кейін ЖЭС-ке көшу басталды. Шаруалар салықтан қалған өнімін нарықта сатып, жеке ынтасын арттыра алды.","l":"B","topic":"Жаңа экономикалық саясат"},{"id":"hcl-21-4","t":"«Жаңа экономикалық саясат» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) ЖЭС кезінде азық-түлік салғырты немен алмастырылды? 2) ЖЭС-тің негізгі экономикалық мақсаты қандай?","o":["1 — Округтік алыммен; 2 — Хандықты қайта құру","1 — Жалпы әскери міндеткерлікпен; 2 — Шаруашылықты қалпына келтіру","1 — Азық-түлік салығымен; 2 — Барлық шаруашылықты тоқтату","1 — Азық-түлік салығымен; 2 — Шаруашылықты қалпына келтіру"],"a":3,"e":"Азық-түлік салғыртының орнына алдын ала белгіленетін азық-түлік салығы енгізілді. ЖЭС шаруашылықты қалпына келтіруге және халықтың тұрмысын жақсартуға бағытталды.","l":"B","topic":"Жаңа экономикалық саясат"},{"id":"hcl-21-5","t":"«Жаңа экономикалық саясат» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["ЖЭС нарық элементтерін шектеулі пайдаланып, өндірушінің ынтасын арттыру арқылы экономиканы қалпына келтіруге ұмтылды.","Өнімнің бір бөлігін сатуға рұқсат беру ЖЭС кезінде мемлекеттік экономикалық бақылау түгел жойылғанын білдіреді.","Сауда еркіндігі ЖЭС-тің шаруашылықты қалпына келтіру мақсатына қатысы жоқ бөлек шара болды.","Салғыртты салықпен алмастыру шаруаның өнімге билігін азайтып, өндіруге ынтасын әлсіретуге бағытталды."],"a":0,"e":"ЖЭС нарық элементтерін шектеулі пайдаланып, өндірушінің ынтасын арттыру арқылы экономиканы қалпына келтіруге ұмтылды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Жаңа экономикалық саясат"}]}]},{"number":22,"questions":[{"id":"hm-067","t":"Азық-түлік салығы шаруаның өнім өндіруге ынтасын неліктен күшейтті?","o":["Егін егуге тыйым салынды","Нарықтағы барлық сауда жабылды","Барлық өнімі міндетті түрде тәркіленді","Салықтан артылған өнім шаруаның өзінде қалды"],"a":3,"e":"Белгіленген салықтан кейінгі өнімді пайдалану құқығы шаруаның экономикалық мүддесін арттырды.","l":"A","topic":"ЖЭС","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":272}},{"id":"hi-044","t":"Қашғарияны ғылыми тұрғыдан зерттеген қазақ ғалымы кім?","o":["Ыбырай Алтынсарин","Махамбет Өтемісұлы","Шоқан Уәлиханов","Абай Құнанбайұлы"],"a":2,"e":"Шоқан Уәлиханов Қашғарияға саяхат жасап, оның тарихы мен географиясы туралы ғылыми деректер жинады.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":167}},{"id":"hk-069","t":"Жаңадан құрылған Қазақ хандығының алғашқы міндетіне қайсысы сәйкес келеді?","o":["Жошы ұрпақтарының билігін түгел тоқтату","Қазақ тайпалары мен этникалық аумақты біріктіру","Сырдария қалаларынан біржола бас тарту","Барлық тайпаны Жетісудан тыс жерге көшіру"],"a":1,"e":"XV ғасырдағы хандық алдында тайпаларды топтастыру, жайылымдарды реттеу және Сыр қалаларына орнығу міндеттері тұрды.","l":"B","topic":"Алғашқы хандықтың міндеттері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":140}},{"id":"hk-032","t":"Тәуекел Баба сұлтанды қай жылы жеңді?","o":["1643 жылы","1723 жылы","1582 жылы","1465 жылы"],"a":2,"e":"1582 жылғы жеңіс Тәуекелдің әскери беделін арттырған оқиғалардың бірі болды.","l":"A","topic":"Тәуекел хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":90}},{"id":"hi-050","t":"Ыбырай Алтынсариннің «Қазақ хрестоматиясы» қай жылы жарық көрді?","o":["1864 жылы","1913 жылы","1841 жылы","1879 жылы"],"a":3,"e":"«Қазақ хрестоматиясы» 1879 жылы басылды. Ол қазақ балаларының оқуына арналған.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":191}},{"id":"hm-020","t":"Жезқазған мыс қорларын зерттеумен тығыз байланысты ғалым кім?","o":["Мұхтар Әуезов","Санжар Асфендияров","Ермұхан Бекмаханов","Қаныш Сәтбаев"],"a":3,"e":"Қ.Сәтбаевтың геологиялық зерттеулері Жезқазған кен ауданын игеруге негіз болды.","l":"A","topic":"Ғылым","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hm-083","t":"1956 жылғы ХХ съезд пен «жылымық» арасындағы байланысты көрсетіңіз.","o":["Съезд ұлттық валютаны енгізді","Съезд ұжымдастыруды алғаш бастады","Съезд Қазақ хандығын құрды","Жеке басқа табынуды сынау қоғамдық өзгерістерге серпін берді"],"a":3,"e":"Сталиндік саясатты сынау ішінара ақтау мен қоғамдық өмірдің жұмсаруына жол ашты.","l":"B","topic":"Жылымық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":264}},{"id":"ha-065","t":"Алтын Орданың Сарай-Бату қаласы қай өзен бойында орналасқан?","o":["Ертіс","Талас","Еділ","Іле"],"a":2,"e":"Сарай-Бату Еділдің төменгі ағысында орналасқан Алтын Орданың астанасы болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"ha-101","t":"Үш мемлекет билеушісінің атауларын сәйкестендіріңіз: 1) Үйсін; 2) Ғұн; 3) Оғыз. А) Шаньюй; Ә) Жабғу; Б) Күнби.","o":["1–Б, 2–Ә, 3–А","1–Ә, 2–Б, 3–А","1–А, 2–Ә, 3–Б","1–Б, 2–А, 3–Ә"],"a":3,"e":"Үйсін билеушісі күнби, ғұн билеушісі шаньюй, оғыз билеушісі жабғу аталды.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-120","t":"Алаш партиясы мен Алашорда үкіметін ажырататын дұрыс тұжырым қандай?","o":["Алаш — саяси партия, Алашорда — ұлттық автономияның үкіметі","Алаш — уезд, Алашорда — генерал-губернаторлық","Алаш — әскери бекініс, Алашорда — жәрмеңке","Алаш — оқу орны, Алашорда — журнал"],"a":0,"e":"Алаш саяси ұйым ретінде қалыптасты. Алашорда Екінші жалпықазақ съезінде құрылған ұлттық үкімет болды.","l":"C","topic":"Алаш қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":218}}],"contexts":[{"id":"hce-22","title":"Қыпшақ атаулары және тарихи кеңістік","text":"XI–XIII ғасырлардың басында қыпшақтардың ықпалы Еуразия даласында кеңейді. Дешті Қыпшақ атауы Қыпшақ даласы дегенді білдіреді. Батыс деректерінде олар құман, орыс жылнамаларында половец деген атаумен де белгілі. Сырдария қалалары үшін көршілермен күрес жүргізілді. Қалаға ықпал сауда жолдары мен қыстауға қол жеткізуге көмектесті. Әртүрлі сыртқы атау бір тарихи бірлестікке қатысты болуы мүмкін. Атау айырмасы халықтардың міндетті түрде байланыссыз болғанын дәлелдемейді. Деректерді география және уақытпен бірге салыстыру қажет. Қыпшақ саясаты далалық және қалалық мүдделердің ұштасқанын көрсетеді. Тек жорықтармен шектелген сипаттама оның экономикалық негізін толық ашпайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":140},"questions":[{"id":"hce-22-1","t":"«Қыпшақ атаулары және тарихи кеңістік» контексі: Дешті Қыпшақ атауының мағынасы қандай?","o":["Қыпшақ даласы","Моңғол орманы","Парсы теңізі","Түрік қаласы"],"a":0,"e":"Мәтіндегі деректер «Қыпшақ даласы» деген жауапты негіздейді. Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты.","l":"A","topic":"Қыпшақ атаулары және тарихи кеңістік"},{"id":"hce-22-2","t":"«Қыпшақ атаулары және тарихи кеңістік» контексі: Қыпшақтардың батыс деректеріндегі атауы қайсы?","o":["Дулу","Нушиби","Құман","Манчжур"],"a":2,"e":"Мәтіндегі деректер «Құман» деген жауапты негіздейді. Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты.","l":"A","topic":"Қыпшақ атаулары және тарихи кеңістік"},{"id":"hce-22-3","t":"«Қыпшақ атаулары және тарихи кеңістік» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Қыпшақтардың қала өмірімен байланысы болмаған","Дешті Қыпшақ тек бір қаланың атауы","Құман мен қыпшақ атауы мүлде байланыссыз халықтарды міндетті түрде білдіреді","Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты"],"a":3,"e":"Мәтіндегі деректер «Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты» деген жауапты негіздейді. Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты.","l":"B","topic":"Қыпшақ атаулары және тарихи кеңістік"},{"id":"hce-22-4","t":"«Қыпшақ атаулары және тарихи кеңістік» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір сыртқы атау барлық тайпаның төл атауын толық дәлелдейді","Әртүрлі деректегі атауларды уақыт және география арқылы салыстыру керек","Қала үшін күрес тек діни мәселе болған","Атауы бөлек болса тарихи байланыс мүлде болмайды"],"a":1,"e":"Мәтіндегі деректер «Әртүрлі деректегі атауларды уақыт және география арқылы салыстыру керек» деген жауапты негіздейді. Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты.","l":"B","topic":"Қыпшақ атаулары және тарихи кеңістік"},{"id":"hce-22-5","t":"«Қыпшақ атаулары және тарихи кеңістік» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Әртүрлі деректегі атауларды уақыт және география арқылы салыстыру керек","XI–XIII ғасырлардың басында қыпшақтардың ықпалы Еуразия даласында кеңейді.","Құман мен қыпшақ атауы мүлде байланыссыз халықтарды міндетті түрде білдіреді","Сырдария қалаларына ықпал сауда және қыстау мүдделерімен байланысты"],"a":2,"e":"Мәтіндегі деректер «Құман мен қыпшақ атауы мүлде байланыссыз халықтарды міндетті түрде білдіреді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Әртүрлі деректегі атауларды уақыт және география арқылы салыстыру керек.","l":"C","topic":"Қыпшақ атаулары және тарихи кеңістік"}]},{"id":"hcl-22","title":"Индустрияландыру және Түрксіб","text":"1920 жылдардың екінші жартысында кеңес билігі ауыр өнеркәсіпті дамытуға басымдық берді. Қазақстандағы ірі құрылыстар табиғи ресурстарды игерумен және көлік желісін кеңейтумен қатар жүрді.\n\nТүрксіб — Түркістан–Сібір теміржолының қысқартылған атауы. Түрксіб Орта Азияны Сібірмен байланыстырып, жүк тасымалын кеңейтті. Кеңестік индустрияландыру ауыр өнеркәсіп пен кен өндірісін дамытуға басымдық берді. Қазақстан өнеркәсібінде кен, мұнай және басқа шикізаттарды өндіру бағыты басым болды.","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":234},"questions":[{"id":"hcl-22-1","t":"«Индустрияландыру және Түрксіб» контексі: Түрксіб атауы қандай теміржолға қатысты?","o":["Байкал–Амур магистраліне","Транссібірдің бүкіл желісіне","Түркістан–Сібір теміржолына","Орынбор–Ташкент теміржолына"],"a":2,"e":"Түрксіб — Түркістан–Сібір теміржолының қысқартылған атауы.","l":"A","topic":"Индустрияландыру және Түрксіб"},{"id":"hcl-22-2","t":"«Индустрияландыру және Түрксіб» контексі: Түрксіб қандай екі ірі өңірді байланыстырды?","o":["Балтық пен Скандинавияны","Орта Азия мен Сібірді","Кавказ бен Қырымды","Жапония мен Кореяны"],"a":1,"e":"Түрксіб Орта Азияны Сібірмен байланыстырып, жүк тасымалын кеңейтті.","l":"A","topic":"Индустрияландыру және Түрксіб"},{"id":"hcl-22-3","t":"«Индустрияландыру және Түрксіб» контексі: Екі деректі сәйкестендіріңіз. 1) Түрксіб атауы қандай теміржолға қатысты. 2) Индустрияландыруда қандай салаға басымдық берілді.","o":["1 — Транссібірдің бүкіл желісіне; 2 — Тек аңшылыққа","1 — Орынбор–Ташкент теміржолына; 2 — Ауыр өнеркәсіпке","1 — Түркістан–Сібір теміржолына; 2 — Ауыр өнеркәсіпке","1 — Түркістан–Сібір теміржолына; 2 — Тек қолжазба көшіруге"],"a":2,"e":"Түрксіб — Түркістан–Сібір теміржолының қысқартылған атауы. Кеңестік индустрияландыру ауыр өнеркәсіп пен кен өндірісін дамытуға басымдық берді.","l":"B","topic":"Индустрияландыру және Түрксіб"},{"id":"hcl-22-4","t":"«Индустрияландыру және Түрксіб» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Түрксіб қандай екі ірі өңірді байланыстырды? 2) Қазақстан индустриясының айқын бағыты қандай болды?","o":["1 — Кавказ бен Қырымды; 2 — Тек теңіз кемесін жасау","1 — Орта Азия мен Сібірді; 2 — Тек дайын компьютер шығару","1 — Балтық пен Скандинавияны; 2 — Шикізат өндіру","1 — Орта Азия мен Сібірді; 2 — Шикізат өндіру"],"a":3,"e":"Түрксіб Орта Азияны Сібірмен байланыстырып, жүк тасымалын кеңейтті. Қазақстан өнеркәсібінде кен, мұнай және басқа шикізаттарды өндіру бағыты басым болды.","l":"B","topic":"Индустрияландыру және Түрксіб"},{"id":"hcl-22-5","t":"«Индустрияландыру және Түрксіб» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Ауыр өнеркәсіпке басымдық беру көлік құрылысының экономикалық қажеттілігін жойды.","Көлік құрылысы өнеркәсіптің дамуын жеделдетті, бірақ шикізатқа бағдарланған құрылым толық жойылған жоқ.","Көлік желісінің кеңеюі кен өндіруді шектеп, өнеркәсіп орталықтарының байланысын әлсіретті.","Түрксібтің салынуы Қазақстанның шикізаттық мамандануын толық жойып, барлық өндірісті дайын өнімге көшірді."],"a":1,"e":"Көлік құрылысы өнеркәсіптің дамуын жеделдетті, бірақ шикізатқа бағдарланған құрылым толық жойылған жоқ. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Индустрияландыру және Түрксіб"}]}]},{"number":23,"questions":[{"id":"hi-100","t":"Қазақ АКСР-ін құру туралы декрет қай жылы қабылданды?","o":["1916 жылы","1917 жылы","1920 жылы","1936 жылы"],"a":2,"e":"Қазақ АКСР-ін құру туралы декрет 1920 жылғы 26 тамызда қабылданды.","l":"A","topic":"Қазревком және Қазақ АКСР","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":242}},{"id":"ha-017","t":"Сақ тайпалары Қазақстан тарихының қай кезеңіне жатады?","o":["Жаңа заман","Кейінгі орта ғасыр","Ерте темір дәуірі","Орта тас дәуірі"],"a":2,"e":"Сақ тайпаларының мәдениеті мен қоғамдық қатынастары ерте темір дәуіріне тән.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-079","t":"1868–1869 жылғы Орал–Торғай және 1870 жылғы Маңғыстау көтерілістерін біріктірген себеп қандай?","o":["Отарлық әкімшілік және салық реформаларына қарсылық","Жоңғар шапқыншылығын тоқтату","Тың игеруге қарсы күрес","Кеңестік ұжымдастыруға қарсылық"],"a":0,"e":"Бұл көтерілістердің екеуі де патша үкіметінің жаңа ережелеріне, салықтарына және отарлық қысымына қарсы бағытталды.","l":"B","topic":"1868–1870 жылдардағы көтерілістер","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":166}},{"id":"hk-065","t":"«Көмекей әулие» атанған XVIII ғасыр жырауы кім?","o":["Бұқар жырау","Махамбет Өтемісұлы","Дулат Бабатайұлы","Жиембет жырау"],"a":0,"e":"Бұқар жырау толғауларымен және Абылай ханға айтқан кеңестерімен танылды.","l":"A","topic":"Бұқар жырау","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":153}},{"id":"hk-116","t":"«Бір хан тұсында заңдар жүйеленіп, үш белгілі бидің ықпалы күшейді» деген сипаттамаға қай сәйкестік дәл келеді?","o":["Абылай хан — «Ескі жол» — билер кеңесі","Қасым хан — «Жеті жарғы» — үш би","Тәуке хан — «Жеті жарғы» — билер кеңесі","Есім хан — «Қасқа жол» — сұлтандар кеңесі"],"a":2,"e":"Құқықты жүйелеу мен үш бидің саяси рөлінің күшеюі Тәуке хан дәуіріне тән.","l":"C","topic":"Құқық және басқару","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":109}},{"id":"hk-016","t":"XV ғасырдың соңы мен XVI ғасырдың басында Қазақ хандығын басқарған хан кім?","o":["Тәуке","Абылай","Бұрындық","Жәңгір"],"a":2,"e":"Бұрындық хан Қасым ханнан бұрын билік құрды және ерте хандық кезеңінің билеушісі болды.","l":"A","topic":"Қазақ хандары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"hm-109","t":"Экономикалық саясат туралы тұжырымдарды бағалаңыз: I — ЖЭС салықтан артылған өнімді сатуға жол ашты; II — ұжымдастыру жеке шаруа қожалықтарын ұжымға біріктірді; III — ЖЭС кезінде барлық жеке саудаға тыйым салынды; IV — байларды тәркілеу ЖЭС-тен бұрын басталды.","o":["I және II дұрыс","III және IV дұрыс","I және III дұрыс","II және IV дұрыс"],"a":0,"e":"ЖЭС 1921 жылдан жеке саудаға ішінара мүмкіндік берді; тәркілеу 1928 жылы басталды. Ұжымдастыру жеке шаруашылықтарды ұжымдық жүйеге біріктіруді көздеді.","l":"C","topic":"Экономикалық саясат","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":2}},{"id":"ha-012","t":"Андрон мәдениеті қай тарихи дәуірге жатады?","o":["Мезолит","Қола дәуірі","Кейінгі темір дәуірі","Ерте орта ғасыр"],"a":1,"e":"Андрон мәдени-тарихи қауымдастығы қола дәуіріндегі Еуразия тұрғындарының мұрасын қамтиды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":62}},{"id":"hm-029","t":"Мәншүк Мәметова қандай қарумен шайқасқан жауынгер ретінде белгілі?","o":["Ұшақпен","Пулеметпен","Торпедамен","Зеңбірек тартқышымен"],"a":1,"e":"М.Мәметова пулеметші болып, Невель түбіндегі ұрыста ерлікпен қаза тапты.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"ha-096","t":"Қатардағы қабірлер қарапайым, ал кей обаларда алтын әшекей мен қару көп. Бұл айырмашылық нені білдіреді?","o":["Қоғамда қолөнершілер болмағанын","Мүліктік және әлеуметтік жіктелудің болғанын","Барлық қабірдің бір әулетке тиесілі екенін","Барлық адамның қоғамдағы орны тең болғанын"],"a":1,"e":"Жерлеу бұйымдарының байлығы мен құрылыстың ауқымы қоғам мүшелерінің мәртебесі мен мүлкі әртүрлі болғанын көрсетеді.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}}],"contexts":[{"id":"hce-23","title":"Қыпшақтар мен көрші мемлекеттер","text":"Қыпшақтар селжұқтармен, Қарахан әулетімен және Хорезммен күрделі қатынаста болды. Маңғыстау мен Каспийдің шығыс жағалауы саяси күрес аймақтарына айналды. Жент пен Жаңакент сияқты Сырдария қалаларына ықпал ету де маңызды еді. Қатынастар тек соғыстан тұрмады: одақ пен айырбас та қолданылды. Белгілі бір өңірдің уақытша тәуелділігі бүкіл даланың біржола бағынғанын білдірмейді. Сондықтан деректегі аймақ пен кезеңді нақтылау қажет. Қала мен дала мүдделері сыртқы саясатта тоғысты. Географиялық жағдай басымдықтарға ықпал етті. Бір оқиғаға сүйеніп барлық ғасырдағы қатынасқа бірдей баға беру тарихи көріністі бұрмалайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":140},"questions":[{"id":"hce-23-1","t":"«Қыпшақтар мен көрші мемлекеттер» контексі: Мәтіндегі қыпшақтардың көршілерінің бірі қайсы?","o":["Корея","Жапония","Хорезм","Португалия"],"a":2,"e":"Мәтіндегі деректер «Хорезм» деген жауапты негіздейді. Жент пен Жаңакент төменгі Сырдария өңірімен байланысты.","l":"A","topic":"Қыпшақтар мен көрші мемлекеттер"},{"id":"hce-23-2","t":"«Қыпшақтар мен көрші мемлекеттер» контексі: Маңғыстау қай теңізге жақын?","o":["Жерорта","Каспий","Қызыл","Балтық"],"a":1,"e":"Мәтіндегі деректер «Каспий» деген жауапты негіздейді. Жент пен Жаңакент төменгі Сырдария өңірімен байланысты.","l":"A","topic":"Қыпшақтар мен көрші мемлекеттер"},{"id":"hce-23-3","t":"«Қыпшақтар мен көрші мемлекеттер» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Маңғыстау Қара теңіздің батысында орналасқан","Бір өңірдің уақытша тәуелділігі бүкіл даланың мәңгі бағынғанын дәлелдейді","Жент пен Жаңакент төменгі Сырдария өңірімен байланысты","Қыпшақтар барлық көршісімен тек бірдей қатынас ұстанды"],"a":2,"e":"Мәтіндегі деректер «Жент пен Жаңакент төменгі Сырдария өңірімен байланысты» деген жауапты негіздейді. Жент пен Жаңакент төменгі Сырдария өңірімен байланысты.","l":"B","topic":"Қыпшақтар мен көрші мемлекеттер"},{"id":"hce-23-4","t":"«Қыпшақтар мен көрші мемлекеттер» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Қатынастың нақты уақыты мен аумағын ескеріп қорытынды жасау қажет","Сауда байланысы әскери тартыстың болуын жоққа шығарады","Бір шайқас барлық дәуірдегі қатынасты толық түсіндіреді","Одақ болған жерде саяси қайшылық ешқашан болмайды"],"a":0,"e":"Мәтіндегі деректер «Қатынастың нақты уақыты мен аумағын ескеріп қорытынды жасау қажет» деген жауапты негіздейді. Жент пен Жаңакент төменгі Сырдария өңірімен байланысты.","l":"B","topic":"Қыпшақтар мен көрші мемлекеттер"},{"id":"hce-23-5","t":"«Қыпшақтар мен көрші мемлекеттер» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Қатынастың нақты уақыты мен аумағын ескеріп қорытынды жасау қажет","Жент пен Жаңакент төменгі Сырдария өңірімен байланысты","Бір өңірдің уақытша тәуелділігі бүкіл даланың мәңгі бағынғанын дәлелдейді","Қыпшақтар селжұқтармен, Қарахан әулетімен және Хорезммен күрделі қатынаста болды."],"a":2,"e":"Мәтіндегі деректер «Бір өңірдің уақытша тәуелділігі бүкіл даланың мәңгі бағынғанын дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Қатынастың нақты уақыты мен аумағын ескеріп қорытынды жасау қажет.","l":"C","topic":"Қыпшақтар мен көрші мемлекеттер"}]},{"id":"hcl-23","title":"Күштеп ұжымдастыру","text":"1920 жылдардың соңында ауыл шаруашылығын өзгерту науқаны әкімшілік қысыммен жүргізілді. Көшпелі және жартылай көшпелі шаруашылықтың ерекшеліктерін ескермеу ауыр зардаптарға әкелді.\n\nҰжымдастыру жеке шаруашылықтарды колхоздарға біріктіруді көздеді. Мәжбүрлі отырықшыландыру көшпелі және жартылай көшпелі мал шаруашылығының қалыптасқан тәртібін бұзды. Филипп Голощекин Қазақстанда «Кіші Қазан» бағытын ұсынды. Мәжбүрлі шаралар мал санының күрт кемуіне және азық-түлік тапшылығына әкелді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4},"questions":[{"id":"hcl-23-1","t":"«Күштеп ұжымдастыру» контексі: Ұжымдастыру кезінде шаруалар қандай ұйымдарға біріктірілді?","o":["Хан кеңестеріне","Колхоздарға","Цехтарға","Жәрмеңке комитеттеріне"],"a":1,"e":"Ұжымдастыру жеке шаруашылықтарды колхоздарға біріктіруді көздеді.","l":"A","topic":"Күштеп ұжымдастыру"},{"id":"hcl-23-2","t":"«Күштеп ұжымдастыру» контексі: Күштеп отырықшыландыру әсіресе қай шаруашылыққа соққы болды?","o":["Теңіз балықшылығына","Ғарыш өнеркәсібіне","Тек қалалық саудаға","Көшпелі мал шаруашылығына"],"a":3,"e":"Мәжбүрлі отырықшыландыру көшпелі және жартылай көшпелі мал шаруашылығының қалыптасқан тәртібін бұзды.","l":"A","topic":"Күштеп ұжымдастыру"},{"id":"hcl-23-3","t":"«Күштеп ұжымдастыру» контексі: Екі деректі сәйкестендіріңіз. 1) Ұжымдастыру кезінде шаруалар қандай ұйымдарға біріктірілді. 2) «Кіші Қазан» идеясын ұсынған кім.","o":["1 — Колхоздарға; 2 — Филипп Голощекин","1 — Колхоздарға; 2 — Михаил Сперанский","1 — Цехтарға; 2 — Филипп Голощекин","1 — Хан кеңестеріне; 2 — Петр Столыпин"],"a":0,"e":"Ұжымдастыру жеке шаруашылықтарды колхоздарға біріктіруді көздеді. Филипп Голощекин Қазақстанда «Кіші Қазан» бағытын ұсынды.","l":"B","topic":"Күштеп ұжымдастыру"},{"id":"hcl-23-4","t":"«Күштеп ұжымдастыру» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Күштеп отырықшыландыру әсіресе қай шаруашылыққа соққы болды? 2) Ұжымдастырудың ауыр салдарының бірі қандай?","o":["1 — Көшпелі мал шаруашылығына; 2 — Мал санының күрт кемуі","1 — Тек қалалық саудаға; 2 — Еркін шаруашылықтың кеңеюі","1 — Көшпелі мал шаруашылығына; 2 — Барлық салықтың жойылуы","1 — Теңіз балықшылығына; 2 — Мал санының күрт кемуі"],"a":0,"e":"Мәжбүрлі отырықшыландыру көшпелі және жартылай көшпелі мал шаруашылығының қалыптасқан тәртібін бұзды. Мәжбүрлі шаралар мал санының күрт кемуіне және азық-түлік тапшылығына әкелді.","l":"B","topic":"Күштеп ұжымдастыру"},{"id":"hcl-23-5","t":"«Күштеп ұжымдастыру» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Отырықшыландыру шаруашылықты бейімдеу мүмкіндігін кеңейткендіктен, мәжбүрлеудің әлеуметтік зардабы болған жоқ.","Әкімшілік мәжбүрлеу мен жергілікті шаруашылық ерекшелігін елемеу өндірістік және әлеуметтік дағдарысты күшейтті.","Жеке шаруашылықтарды біріктіру жергілікті мал шаруашылығының дәстүрлі тәртібін өзгеріссіз сақтап қалды.","Мал санының кемуі шаруашылықты қайта құруға қатыссыз болып, әкімшілік тәсілдердің тиімділігін көрсетті."],"a":1,"e":"Әкімшілік мәжбүрлеу мен жергілікті шаруашылық ерекшелігін елемеу өндірістік және әлеуметтік дағдарысты күшейтті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Күштеп ұжымдастыру"}]}]},{"number":24,"questions":[{"id":"hk-015","t":"Қазақ қоғамында сұлтан мәртебесінің басты негізі не еді?","o":["Ірі сауда керуендерін иеленуі","Әскерді жорықта басқаруы","Билер кеңесіне қатысуы","Шыңғыс хан әулетінен тарауы"],"a":3,"e":"Сұлтан атағы төре әулетімен байланысты болды; ол жай ғана байлықтың немесе қызметтің атауы емес.","l":"A","topic":"Қазақ хандығының басқарылуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-006","t":"1822 жылғы реформа Орта жүзде қандай жаңа әкімшілік бірлікті енгізді?","o":["Генерал-губернаторлық","Округ","Кантон","Ұлыс"],"a":1,"e":"Орта жүзде округ–болыс–ауыл жүйесі енгізілді. Округтерді округтік приказдар басқарды.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":167}},{"id":"hi-122","t":"1917 жылғы ұлттық съездерде автономия мәселесінің көтерілуі қандай саяси қажеттілікпен байланысты болды?","o":["Жоңғар хандығына қосылу","Бұрынғы қағанаттарға алым төлеу","Қазақ мектептерін жаппай жабу","Халықтың өзін-өзі басқаруы мен ұлттық мүдделерін қорғау"],"a":3,"e":"Автономия идеясы жер, басқару, құқық және ұлттық мүдде мәселелерін өз деңгейінде шешуге ұмтылысты білдірді.","l":"C","topic":"Алаш қозғалысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hi-043","t":"Жәңгір хан Бөкей Ордасында зайырлы мектеп ашқан жылды көрсетіңіз.","o":["1879 жыл","1864 жыл","1841 жыл","1822 жыл"],"a":2,"e":"Жәңгір ханның бастамасымен 1841 жылы Бөкей Ордасында зайырлы мектеп ашылды.","l":"A","topic":"XIX ғасырдағы білім","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":169}},{"id":"hm-088","t":"1989 жылғы тілдер туралы заңның ұлттық мәдениет үшін маңызы қандай?","o":["Барлық мектепті жабуы","Кирилл жазуын бірден араб жазуына ауыстыруы","Қазақ тілін толық тыйым салуы","Қазақ тілінің мемлекеттік мәртебесін бекітуі"],"a":3,"e":"Заң қазақ тілінің қоғамдық қолданысын кеңейтуге құқықтық негіз қалады.","l":"B","topic":"Қайта құру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"ha-118","t":"Зерттеуші сақтардың киімі, қаруы және өнерін бір мезгілде зерттемек. Қай деректер жиыны мақсатқа тікелей сәйкес келеді?","o":["Орхон жазбалары, Баласағұни дастаны, Қашғари сөздігі","Қарлұқ қалалары, Моғолстан шежіресі, Ноғай жырлары","Алтын Орда теңгелері, Сарай-Бату мешіттері, Ясауи кесенесі","Есік киім әшекейлері, Бесшатыр жерлеулері, Берел ат әбзелдері"],"a":3,"e":"Бірінші қатардағы олжалар сақ дәуірінің материалдық мәдениетіне жатады, қалған қатарлар негізінен ортағасырлық мұрадан тұрады.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hk-095","t":"Хандық билікке әулеттік құқықтың болуы қандай қоғамдық ерекшелікті білдіреді?","o":["Хан тек ең көп мал иесі болғанын","Шыңғыс әулетінің саяси мәртебесі ерекше болғанын","Ханды тек қала қолөнершілері ұсынғанын","Хан лауазымы тек діни білім арқылы берілгенін"],"a":1,"e":"Қазақ хандығында хан әулеттен сайланды; сұлтандардың төрелік мәртебесі билікке үміткерлікпен байланысты болды.","l":"B","topic":"Хандық биліктің сипаты","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-066","t":"ЖЭС-тің «әскери коммунизмнен» негізгі айырмашылығы қайсы?","o":["Өнімнің барлығын өтеусіз алуы","Барлық сауданы толық жоюы","Ақша қатынасын толық тоқтатуы","Салықтан артылған өнімді сатуға мүмкіндік беруі"],"a":3,"e":"ЖЭС нарықтық тетіктерді ішінара пайдаланды; «әскери коммунизмде» салғырт пен қатаң бөлу үстем болды.","l":"A","topic":"ЖЭС","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":257}},{"id":"ha-053","t":"Оғыз мемлекетінің жоғарғы билеушісі қалай аталды?","o":["Күнби","Шаньюй","Жабғу","Гурхан"],"a":2,"e":"Оғыз бірлестігінің жоғарғы билеушісі жабғу атанды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hm-025","t":"Кеңес Одағы үшін Ұлы Отан соғысы қашан басталды?","o":["1941 жылғы 22 маусымда","1942 жылғы 2 ақпанда","1939 жылғы 1 қыркүйекте","1945 жылғы 9 мамырда"],"a":0,"e":"Германия 1941 жылғы 22 маусымда КСРО-ға шабуыл жасады.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}}],"contexts":[{"id":"hce-24","title":"Керейіттер мен наймандар: хронология","text":"XII–XIII ғасырлар тоғысында найман, керейіт және жалайыр бірлестіктері Орталық Азияда маңызды рөл атқарды. Темүжіннің күшеюі одақтар мен қарсыластықтарды өзгертті. 1203 жылы керейіттер, 1204 жылы наймандар жеңілді. Хронологиялық сызба: керейіттердің жеңілуі → наймандардың жеңілуі → кейінгі саяси қайта топтасулар. Жеңілген топтардың адамдары түрлі аймаққа таралып, жаңа үдерістерге қатысты. Әскери жеңіліс тайпа атауының немесе барлық халқының бірден жоғалғанын білдірмейді. Кейін осы атаулар қазақ халқының құрамында сақталды. Саяси құрылым мен этникалық жалғасуды ажырату қажет. Бірлестіктің күйреуі халық тарихының толық аяқталуымен тең емес.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8},"questions":[{"id":"hce-24-1","t":"«Керейіттер мен наймандар: хронология» контексі: 1203 жылы жеңілген бірлестік қайсы?","o":["Жоңғарлар","Наймандар","Қарахандар","Керейіттер"],"a":3,"e":"Мәтіндегі деректер «Керейіттер» деген жауапты негіздейді. Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды.","l":"A","topic":"Керейіттер мен наймандар: хронология"},{"id":"hce-24-2","t":"«Керейіттер мен наймандар: хронология» контексі: 1204 жылғы жеңіліс кімдерге қатысты?","o":["Оғыздарға","Наймандарға","Түргештерге","Сарматтарға"],"a":1,"e":"Мәтіндегі деректер «Наймандарға» деген жауапты негіздейді. Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды.","l":"A","topic":"Керейіттер мен наймандар: хронология"},{"id":"hce-24-3","t":"«Керейіттер мен наймандар: хронология» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды","Наймандар керейіттерден бұрын жеңілді","Темүжіннің күшеюі одақтарға еш әсер етпеді","Әскери жеңіліс тайпаның барлық адамы бірден жоғалғанын дәлелдейді"],"a":0,"e":"Мәтіндегі деректер «Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды» деген жауапты негіздейді. Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды.","l":"B","topic":"Керейіттер мен наймандар: хронология"},{"id":"hce-24-4","t":"«Керейіттер мен наймандар: хронология» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Жеңіліс тек шаруашылық құралдардың ауысуы болған","Бір атаудың сақталуы барлық саяси институт өзгермеді дегенді білдіреді","Жаңа бірлестік пайда болса бұрынғы тайпа атауы міндетті түрде жойылады","Саяси құрылым күйресе де халық пен тарихи атау сақтала алады"],"a":3,"e":"Мәтіндегі деректер «Саяси құрылым күйресе де халық пен тарихи атау сақтала алады» деген жауапты негіздейді. Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды.","l":"B","topic":"Керейіттер мен наймандар: хронология"},{"id":"hce-24-5","t":"«Керейіттер мен наймандар: хронология» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["XII–XIII ғасырлар тоғысында найман, керейіт және жалайыр бірлестіктері Орталық Азияда маңызды рөл атқарды.","Әскери жеңіліс тайпаның барлық адамы бірден жоғалғанын дәлелдейді","Саяси құрылым күйресе де халық пен тарихи атау сақтала алады","Керейіттердің жеңілуі наймандардың жеңілуінен бұрын болды"],"a":1,"e":"Мәтіндегі деректер «Әскери жеңіліс тайпаның барлық адамы бірден жоғалғанын дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Саяси құрылым күйресе де халық пен тарихи атау сақтала алады.","l":"C","topic":"Керейіттер мен наймандар: хронология"}]},{"id":"hcl-24","title":"1931–1933 жылдардағы аштық","text":"Күштеп ұжымдастыру мен шаруашылықты бұзу Қазақстан халқы үшін апатқа айналды. Аштықтың зардабы адам шығынымен ғана шектелмей, көші-қонға және демографиялық құрылымға әсер етті.\n\n1931–1933 жылдар Қазақстандағы жаппай аштықтың ең ауыр кезеңі болды. Күштеп ұжымдастыру мен малды жаппай тартып алу азық-түлік дағдарысын тереңдетті. Аштық адам өліміне, халық санының кемуіне және босқыншылыққа әкелді. 1932 жылғы «Бесеудің хаты» ауылдағы ауыр жағдай мен саясат қателіктерін көтерді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4},"questions":[{"id":"hcl-24-1","t":"«1931–1933 жылдардағы аштық» контексі: Қазақстандағы жаппай аштықтың ең ауыр кезеңі қай жылдар?","o":["1931–1933 жылдар","1867–1868 жылдар","1905–1907 жылдар","1954–1956 жылдар"],"a":0,"e":"1931–1933 жылдар Қазақстандағы жаппай аштықтың ең ауыр кезеңі болды.","l":"A","topic":"1931–1933 жылдардағы аштық"},{"id":"hcl-24-2","t":"«1931–1933 жылдардағы аштық» контексі: Аштыққа алып келген саясаттардың бірі қандай?","o":["ЖЭС кезіндегі еркін сауда","Күштеп ұжымдастыру","Тәуелсіздік кезіндегі жекешелендіру","Тың игеру"],"a":1,"e":"Күштеп ұжымдастыру мен малды жаппай тартып алу азық-түлік дағдарысын тереңдетті.","l":"A","topic":"1931–1933 жылдардағы аштық"},{"id":"hcl-24-3","t":"«1931–1933 жылдардағы аштық» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстандағы жаппай аштықтың ең ауыр кезеңі қай жылдар. 2) Аштықтың демографиялық салдары қандай.","o":["1 — 1905–1907 жылдар; 2 — Көші-қонның толық тоқтауы","1 — 1931–1933 жылдар; 2 — Халық санының күрт азаюы","1 — 1867–1868 жылдар; 2 — Халық санының күрт азаюы","1 — 1931–1933 жылдар; 2 — Халық санының шығынсыз өсуі"],"a":1,"e":"1931–1933 жылдар Қазақстандағы жаппай аштықтың ең ауыр кезеңі болды. Аштық адам өліміне, халық санының кемуіне және босқыншылыққа әкелді.","l":"B","topic":"1931–1933 жылдардағы аштық"},{"id":"hcl-24-4","t":"«1931–1933 жылдардағы аштық» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Аштыққа алып келген саясаттардың бірі қандай? 2) 1932 жылы билікке жағдай туралы үндеу жолдаған құжат қайсы?","o":["1 — Тың игеру; 2 — Қарқаралы петициясы","1 — ЖЭС кезіндегі еркін сауда; 2 — «Бесеудің хаты»","1 — Күштеп ұжымдастыру; 2 — «Жеті жарғы»","1 — Күштеп ұжымдастыру; 2 — «Бесеудің хаты»"],"a":3,"e":"Күштеп ұжымдастыру мен малды жаппай тартып алу азық-түлік дағдарысын тереңдетті. 1932 жылғы «Бесеудің хаты» ауылдағы ауыр жағдай мен саясат қателіктерін көтерді.","l":"B","topic":"1931–1933 жылдардағы аштық"},{"id":"hcl-24-5","t":"«1931–1933 жылдардағы аштық» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Халық санының кемуі аштықтың нәтижесі емес, тек қалаларға жоспарлы қоныстанудың көрінісі болды.","Аштықтың ауқымы оның себептерін ұжымдастырудан бөлек, тек сыртқы көші-қоннан іздеу қажет екенін көрсетеді.","Билікке хат жолдануы жағдайдың ауыр болмағанын және шаруашылық дағдарыстың толық шешілгенін дәлелдейді.","Аштық шаруашылық дағдарысын демографиялық апатқа айналдырып, қоғамның ұзақ мерзімді дамуына зиян келтірді."],"a":3,"e":"Аштық шаруашылық дағдарысын демографиялық апатқа айналдырып, қоғамның ұзақ мерзімді дамуына зиян келтірді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1931–1933 жылдардағы аштық"}]}]},{"number":25,"questions":[{"id":"ha-037","t":"Еуропадағы ғұн бірлестігінің V ғасырдағы атақты билеушісін атаңыз.","o":["Білге","Тоныкөк","Аттила","Тоғылық Темір"],"a":2,"e":"Аттила V ғасырда Еуропадағы ғұндардың саяси және әскери қуатын арттырған билеуші болды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":71}},{"id":"hk-033","t":"Тәуекел ханның Мәскеуге елшілігі қай жылы аттанды?","o":["1538 жылы","1594 жылы","1643 жылы","1710 жылы"],"a":1,"e":"1594 жылы Мәскеуге Құл-Мұхаммед бастаған қазақ елшілігі жіберілді.","l":"A","topic":"Тәуекел ханның елшілігі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":86}},{"id":"hk-125","t":"«Абылай Ресеймен де, Қытаймен де байланыс ұстағандықтан, хандықтың дербес мүддесі болмаған» деген қорытындыны бағалаңыз.","o":["Дұрыс: көпжақты байланыс дербес саясаттың тоқтауын білдіреді","Қате: бірнеше көршімен қатынас дербес мүддені қорғау тәсілі бола алады","Дұрыс: екі мемлекетпен қатынас бір хандыққа бірігуді дәлелдейді","Қате: Абылай тек Бұхармен келіссөз жүргізген"],"a":1,"e":"Абылайдың дипломатиясы ірі державалардың арасында тепе-теңдік іздеуге бағытталды; көпжақты байланыс дербес мүдденің жоқтығын дәлелдемейді.","l":"C","topic":"Тарихи тұжырымды бағалау","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hk-047","t":"Дәстүрлі деректерде Орбұлақта Жәңгір бастаған бастапқы жасақ саны қанша деп көрсетіледі?","o":["6 мың жауынгер","600 мың жауынгер","60 мың жауынгер","600 жауынгер"],"a":3,"e":"Оқу материалдарында Жәңгірдің тар шатқалда қорғанған бастапқы жасағы 600 адам болғаны көрсетіледі.","l":"A","topic":"Орбұлақ шайқасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":83}},{"id":"ha-030","t":"Сарматтар негізінен Қазақстанның қай бөлігін мекендеді?","o":["Оңтүстік Алтайды","Балқаштың шығыс жағалауын","Батыс Қазақстанды","Іле аңғарын"],"a":2,"e":"Сармат тайпаларының негізгі таралған аумағына Батыс Қазақстан, Жайық пен Еділ маңы кірді.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hm-122","t":"Зерттеуші ашаршылық кезіндегі халық шығынын анықтау үшін санақтарды салыстырды, босқындар есебін және замандас хаттарын пайдаланды. Қай әдістемелік ескерту ең негізді?","o":["Замандас хаттар бар болса, барлық сандық дерек өздігінен дәл болады","Халық санының кемуін түгел өлім деп есептемей, көші-қон мен деректердің толықтығын да ескеру керек","Екі санақ арасындағы барлық айырманы еш тексерусіз тек өлімге жатқызу керек","Босқындар дерегі бар болса, санақ пен хаттарды пайдалануға болмайды"],"a":1,"e":"Халық санына өліммен қатар туу мен көші-қон да әсер етеді. Әртүрлі деректерді салыстыру және олардың толықтығын тексеру демографиялық шығынды дұрыс бағалауға қажет.","l":"C","topic":"Тарихи дерек","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-038","t":"XIX ғасырда Қарқаралы маңында жұмыс істеген әйгілі жәрмеңке қалай аталды?","o":["Темір","Қоянды","Ойыл","Қарқара"],"a":1,"e":"Қоянды жәрмеңкесі Қарқаралы маңында ашылды. Ол даладағы ірі сауда орталығына айналды.","l":"A","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":182}},{"id":"hm-064","t":"Дүниежүзі қазақтарының бірінші құрылтайы қай жылы өтті?","o":["1986 жылы","2003 жылы","1995 жылы","1992 жылы"],"a":3,"e":"Дүниежүзі қазақтарының тұңғыш құрылтайы 1992 жылы өткізілді.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-072","t":"Кенесары қозғалысының ауқымын өзге көптеген XIX ғасыр көтерілістерінен ерекшелендірген белгі қандай?","o":["Үш жүз өкілдерінің қатысуы","Тек қала жұмысшыларының қатысуы","Тек бір ауылдың қатысуы","Тек шетелдік жасақтардың қатысуы"],"a":0,"e":"Қозғалысқа үш жүздің өкілдері қатысты. Бұл оның кең аумақты қамтығанын көрсетеді.","l":"B","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":174}},{"id":"ha-090","t":"1365 жылғы Батпақ шайқасында Ілияс Қожаның жеңуі қандай қорытындыға негіз болады?","o":["Моғолстан әскері Әмір Темір одағына қарсы жеңіске жетті","Алтын Орда ханы Өзбек жеңіске жетті","Батый Жетісуда жаңа мемлекет құрды","Әмір Темір Моғолстанды бірден жойды"],"a":0,"e":"Батпақ шайқасында Ілияс Қожа Әмір Темір мен Әмір Хұсайынның әскерін жеңді.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}}],"contexts":[{"id":"hce-25","title":"Көне түркі жазбаларындағы саяси үндеу","text":"Күлтегін, Білге қаған және Тоныкөк ескерткіштері көне түркі жазба дәстүрімен байланысты. Мәтіндерде ел бірлігі, билеуші жауапкершілігі және сыртқы қауіп туралы айтылады. Олар оқиғаларды тізіп қана қоймай, саяси ойды жеткізеді. Орхон-Енисей жазба дәстүрі түркі қоғамының тарихи жадын тануға мүмкіндік береді. Мәтінді кімнің атынан және кімге арнап жазғанын ескеру қажет. Бірлікке шақыру оның әрдайым қиындықсыз сақталғанын білдірмейді. Үндеу мен нақты жағдай бөлек талданады. Жазу, ескерткіш және тарихи орта бірге қарастырылғанда дерек мағынасы ашылады. Автордың саяси мақсаты деректі қажетсіз етпейді, бірақ оны сыни пайдалануды талап етеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":17},"questions":[{"id":"hce-25-1","t":"«Көне түркі жазбаларындағы саяси үндеу» контексі: Мәтіндегі ескерткіштер қай жазба дәстүріне жатады?","o":["Кирилл баспасы","Мысыр иероглифі","Көне түркі","Латын баспасы"],"a":2,"e":"Мәтіндегі деректер «Көне түркі» деген жауапты негіздейді. Ел бірлігіне шақыру саяси ойды білдіреді.","l":"A","topic":"Көне түркі жазбаларындағы саяси үндеу"},{"id":"hce-25-2","t":"«Көне түркі жазбаларындағы саяси үндеу» контексі: Аталған қайраткерлер жұбы қайсы?","o":["Білге қаған мен Тоныкөк","Абылай мен Кенесары","Қасым мен Тәуке","Батый мен Өзбек"],"a":0,"e":"Мәтіндегі деректер «Білге қаған мен Тоныкөк» деген жауапты негіздейді. Ел бірлігіне шақыру саяси ойды білдіреді.","l":"A","topic":"Көне түркі жазбаларындағы саяси үндеу"},{"id":"hce-25-3","t":"«Көне түркі жазбаларындағы саяси үндеу» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Бұл ескерткіштер тек салық есебі болған","Бірлікке үндеу қоғамда еш қайшылық болмағанын дәлелдейді","Мәтіннің кімге арналғаны талдауға қатыссыз","Ел бірлігіне шақыру саяси ойды білдіреді"],"a":3,"e":"Мәтіндегі деректер «Ел бірлігіне шақыру саяси ойды білдіреді» деген жауапты негіздейді. Ел бірлігіне шақыру саяси ойды білдіреді.","l":"B","topic":"Көне түркі жазбаларындағы саяси үндеу"},{"id":"hce-25-4","t":"«Көне түркі жазбаларындағы саяси үндеу» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Ескерткіштің қазіргі орны ғана оның мағынасын анықтайды","Жазбадағы әр талап толық орындалғанын білдіреді","Үндеу мазмұны мен нақты тарихи жағдайды ажырату керек","Саяси мақсат бар дерек еш ақпарат бере алмайды"],"a":2,"e":"Мәтіндегі деректер «Үндеу мазмұны мен нақты тарихи жағдайды ажырату керек» деген жауапты негіздейді. Ел бірлігіне шақыру саяси ойды білдіреді.","l":"B","topic":"Көне түркі жазбаларындағы саяси үндеу"},{"id":"hce-25-5","t":"«Көне түркі жазбаларындағы саяси үндеу» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Үндеу мазмұны мен нақты тарихи жағдайды ажырату керек","Ел бірлігіне шақыру саяси ойды білдіреді","Күлтегін, Білге қаған және Тоныкөк ескерткіштері көне түркі жазба дәстүрімен байланысты.","Бірлікке үндеу қоғамда еш қайшылық болмағанын дәлелдейді"],"a":3,"e":"Мәтіндегі деректер «Бірлікке үндеу қоғамда еш қайшылық болмағанын дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Үндеу мазмұны мен нақты тарихи жағдайды ажырату керек.","l":"C","topic":"Көне түркі жазбаларындағы саяси үндеу"}]},{"id":"hcl-25","title":"Саяси қуғын-сүргін және лагерьлер","text":"Сталиндік кезеңде билікке күмәнді деп танылған адамдар саяси айыптауларға ұшырады. Қуғын-сүргін зиялыларды, шаруаларды және әртүрлі әлеуметтік топтарды қамтыды.\n\n1937–1938 жылдары саяси қуғын-сүргін жаппай сипат алды. Қарағанды еңбекпен түзеу лагері кеңестік лагерьлер жүйесінің ірі бөліктерінің бірі болды. АЛЖИР-де «отанын сатқандардың әйелдері» деп айыпталған әйелдер қамауда ұсталды. Қуғын-сүргін ұлттық зиялы қауымға ауыр соққы беріп, мәдени дамуды шектеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13},"questions":[{"id":"hcl-25-1","t":"«Саяси қуғын-сүргін және лагерьлер» контексі: Жаппай саяси қуғын-сүргін шарықтаған кезең қайсы?","o":["1867–1868 жылдар","1822–1824 жылдар","1991–1992 жылдар","1937–1938 жылдар"],"a":3,"e":"1937–1938 жылдары саяси қуғын-сүргін жаппай сипат алды.","l":"A","topic":"Саяси қуғын-сүргін және лагерьлер"},{"id":"hcl-25-2","t":"«Саяси қуғын-сүргін және лагерьлер» контексі: Карлаг қай жүйеге кірді?","o":["Жәрмеңкелер одағына","Халықаралық ғылыми орталықтарға","Хандық билер кеңесіне","Кеңестік еңбекпен түзеу лагерлері жүйесіне"],"a":3,"e":"Қарағанды еңбекпен түзеу лагері кеңестік лагерьлер жүйесінің ірі бөліктерінің бірі болды.","l":"A","topic":"Саяси қуғын-сүргін және лагерьлер"},{"id":"hcl-25-3","t":"«Саяси қуғын-сүргін және лагерьлер» контексі: Екі деректі сәйкестендіріңіз. 1) Жаппай саяси қуғын-сүргін шарықтаған кезең қайсы. 2) АЛЖИР-де кімдер қамауда ұсталды.","o":["1 — 1822–1824 жылдар; 2 — Саяси айыпталғандардың әйелдері","1 — 1937–1938 жылдар; 2 — Саяси айыпталғандардың әйелдері","1 — 1867–1868 жылдар; 2 — Тек патша генералдары","1 — 1937–1938 жылдар; 2 — Тек шетел дипломаттары"],"a":1,"e":"1937–1938 жылдары саяси қуғын-сүргін жаппай сипат алды. АЛЖИР-де «отанын сатқандардың әйелдері» деп айыпталған әйелдер қамауда ұсталды.","l":"B","topic":"Саяси қуғын-сүргін және лагерьлер"},{"id":"hcl-25-4","t":"«Саяси қуғын-сүргін және лагерьлер» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Карлаг қай жүйеге кірді? 2) Қуғын-сүргіннің мәдениетке әсері қандай?","o":["1 — Кеңестік еңбекпен түзеу лагерлері жүйесіне; 2 — Сөз бостандығының шексіз кеңеюі","1 — Жәрмеңкелер одағына; 2 — Цензураның толық жойылуы","1 — Хандық билер кеңесіне; 2 — Зиялы қауымның ауыр шығынға ұшырауы","1 — Кеңестік еңбекпен түзеу лагерлері жүйесіне; 2 — Зиялы қауымның ауыр шығынға ұшырауы"],"a":3,"e":"Қарағанды еңбекпен түзеу лагері кеңестік лагерьлер жүйесінің ірі бөліктерінің бірі болды. Қуғын-сүргін ұлттық зиялы қауымға ауыр соққы беріп, мәдени дамуды шектеді.","l":"B","topic":"Саяси қуғын-сүргін және лагерьлер"},{"id":"hcl-25-5","t":"«Саяси қуғын-сүргін және лагерьлер» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Саяси қысым жеке адамдармен қатар отбасылар мен ұлттық мәдениетке де зардап әкелді.","Зиялылардың қудалануы ұлттық мәдениетке емес, тек мемлекеттік мекемелердің жұмыс кестесіне әсер етті.","Отбасы мүшелерінің қамалуы саяси қуғын-сүргін тек нақты жеке құқық бұзушылықтарға негізделгенін көрсетеді.","Лагерьлердегі еңбек саяси қысымнан бөлек болғандықтан, оларды қуғын-сүргін жүйесімен байланыстыруға негіз жоқ."],"a":0,"e":"Саяси қысым жеке адамдармен қатар отбасылар мен ұлттық мәдениетке де зардап әкелді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Саяси қуғын-сүргін және лагерьлер"}]}]},{"number":26,"questions":[{"id":"ha-122","t":"Билеушілерді мемлекеттерімен сәйкестендіріңіз: 1) Тоғылық Темір; 2) Өзбек хан; 3) Ұрыс хан. А) Ақ Орда; Ә) Моғолстан; Б) Алтын Орда.","o":["1–А, 2–Ә, 3–Б","1–Б, 2–А, 3–Ә","1–Ә, 2–Б, 3–А","1–Ә, 2–А, 3–Б"],"a":2,"e":"Тоғылық Темір Моғолстанды, Өзбек хан Алтын Орданы, Ұрыс хан Ақ Орданы биледі.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"ha-009","t":"Ботай қонысы Қазақстанның қай бөлігінде орналасқан?","o":["Маңғыстауда","Солтүстік Қазақстанда","Оңтүстік Қазақстанда","Батыс Жетісуда"],"a":1,"e":"Ботай қонысы Солтүстік Қазақстан аумағында, Иманбұрлық өзені маңында орналасқан.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-001","t":"Қазақ автономиялық кеңестік республикасы қай жылы құрылды?","o":["1920 жылы","1936 жылы","1925 жылы","1917 жылы"],"a":0,"e":"Қазақ АКСР-ін құру туралы декрет 1920 жылы қабылданды.","l":"A","topic":"Қазақ АКСР","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hi-045","t":"Шоқан Уәлиханов 1853 жылы қай оқу орнын аяқтады?","o":["Санкт-Петербург орман институтын","Омбыдағы Сібір кадет корпусын","Қазан университетін","Орынбор мұғалімдер мектебін"],"a":1,"e":"Шоқан 1853 жылы Омбыдағы Сібір кадет корпусын бітірді.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":152}},{"id":"hm-043","t":"Тың игерудің негізгі мақсаты қандай болды?","o":["Жеке сауданы толық жою","Ядролық сынақтарды тоқтату","Астық өндірісін арттыру","Көшпелі мал шаруашылығын қалпына келтіру"],"a":2,"e":"Кеңес басшылығы жаңа жерлерді жырту арқылы астық көлемін көбейтуді көздеді.","l":"A","topic":"Тың игеру","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-113","t":"Қарқаралы петициясы мен ұлттық баспасөздің дамуы нені көрсетеді?","o":["Ұлттық зиялылардың қоғамдық өмірден толық кетуін","Құқықтарды саяси және қоғамдық жолмен қорғаудың күшеюін","Қазақ хандығының XV ғасырда құрылуын","Жоңғар мемлекетінің қайта құрылуын"],"a":1,"e":"Петициялар билікке талап жеткізсе, баспасөз қоғамды талқылауға тартты. Екеуі де ұлттық саяси сананың өсуін көрсетті.","l":"C","topic":"XX ғасыр басындағы қоғамдық ой","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":149}},{"id":"hm-077","t":"Майдан мен тылдың өзара байланысын қай мысал ашады?","o":["Әскери өнім шығаруды толық тоқтату","Көлік қатынасын түгел жабу","Тыл зауыттарының әскерге оқ-дәрі мен техника шығаруы","Егін өнімін ешкімге бермеу"],"a":2,"e":"Тылдағы еңбек майданды қару-жарақпен, азықпен және басқа қажетті заттармен қамтыды.","l":"B","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hi-027","t":"1860 жылы Ресей және Қоқан әскерлері арасындағы шайқас қай жерде өтті?","o":["Тастөбеде","Атлахта","Орбұлақта","Ұзынағашта"],"a":3,"e":"Ұзынағаш шайқасы 1860 жылы өтті. Бұл оңтүстік-шығыс Қазақстандағы Ресей–Қоқан текетіресінің оқиғасы болды.","l":"A","topic":"Оңтүстік Қазақстанның қосылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":165}},{"id":"hk-042","t":"1611 жылы Ташкент маңындағы шайқаста Есім ханның қарсыласы кім болды?","o":["Батый хан","Мөде шаньюй","Бумын қаған","Имамқұли хан"],"a":3,"e":"1611 жылғы қақтығыс Қазақ хандығы мен Бұхар билеушісі Имамқұли арасындағы қатынастарға жатады.","l":"A","topic":"Есім ханның сыртқы саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":132}},{"id":"hk-087","t":"«Қалмаққырылған» атауы қазақтардың қандай тарихи тәжірибесін бейнелейді?","o":["Мәскеуге жіберілген алғашқы елшілікті","Ноғай Ордасынан қазақтардың бөлінуін","Жоңғарларға қарсы әскери жеңісін","Сырдариядағы егіншілік жүйесінің өзгеруін"],"a":2,"e":"Бұл атау Бұланты-Білеуті маңындағы жеңіспен байланысты тарихи жадта сақталған.","l":"B","topic":"Бұланты шайқасы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}}],"contexts":[{"id":"hce-26","title":"Ұлы Жібек жолының желілік сипаты","text":"Ұлы Жібек жолы Еуразияның шығысы мен батысын байланыстырған жолдар желісі болды. Қазақстандағы тармақтары Жетісу мен Оңтүстік Қазақстан қалалары арқылы өтті. Керуендер жібекпен бірге басқа тауарлар тасыды. Саудагерлер, елшілер және діни уағызшылар идеялардың таралуына ықпал етті. Жол бағыттары саяси тұрақтылық пен табиғи жағдайға қарай өзгерді. Сондықтан оны ғасырлар бойы өзгермеген жалғыз соқпақ деп қарастыру дұрыс емес. Қалаларда қолөнер мен қызмет көрсету дамыды. Айырбас далалық және қалалық шаруашылықты байланыстырды. Жолдың маңызы бір ғана тауармен шектелмейді. Өзара байланысқан бағыттар әр кезеңде әртүрлі рөл атқара алды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":81},"questions":[{"id":"hce-26-1","t":"«Ұлы Жібек жолының желілік сипаты» контексі: Жол атауымен байланысты негізгі тауар қайсы?","o":["Көмір","Мұнай","Жібек","Резеңке"],"a":2,"e":"Мәтіндегі деректер «Жібек» деген жауапты негіздейді. Жол арқылы тауармен қатар мәдени және діни идеялар таралды.","l":"A","topic":"Ұлы Жібек жолының желілік сипаты"},{"id":"hce-26-2","t":"«Ұлы Жібек жолының желілік сипаты» контексі: Қазақстандағы маңызды аймақтар жұбы қайсы?","o":["Тек Маңғыстау мен Чукотка","Жетісу мен Оңтүстік Қазақстан","Тек Алтай мен Аляска","Тек Торғай мен Исландия"],"a":1,"e":"Мәтіндегі деректер «Жетісу мен Оңтүстік Қазақстан» деген жауапты негіздейді. Жол арқылы тауармен қатар мәдени және діни идеялар таралды.","l":"A","topic":"Ұлы Жібек жолының желілік сипаты"},{"id":"hce-26-3","t":"«Ұлы Жібек жолының желілік сипаты» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Жібек жолы барлық ғасырда өзгермеген бір соқпақ болды","Жолдың қалалық қызметке еш әсері болмады","Керуендер тек бір тауар тасыды","Жол арқылы тауармен қатар мәдени және діни идеялар таралды"],"a":3,"e":"Мәтіндегі деректер «Жол арқылы тауармен қатар мәдени және діни идеялар таралды» деген жауапты негіздейді. Жол арқылы тауармен қатар мәдени және діни идеялар таралды.","l":"B","topic":"Ұлы Жібек жолының желілік сипаты"},{"id":"hce-26-4","t":"«Ұлы Жібек жолының желілік сипаты» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Сауда жолы саяси жағдайдан тәуелсіз болды","Бір бағыттың әлсіреуі барлық айырбастың біржола тоқтауын білдіреді","Идея алмасу тек әскери жорық арқылы жүрген","Желі ұғымы өзгеретін және өзара байланысқан бағыттарды білдіреді"],"a":3,"e":"Мәтіндегі деректер «Желі ұғымы өзгеретін және өзара байланысқан бағыттарды білдіреді» деген жауапты негіздейді. Жол арқылы тауармен қатар мәдени және діни идеялар таралды.","l":"B","topic":"Ұлы Жібек жолының желілік сипаты"},{"id":"hce-26-5","t":"«Ұлы Жібек жолының желілік сипаты» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Жол арқылы тауармен қатар мәдени және діни идеялар таралды","Жібек жолы барлық ғасырда өзгермеген бір соқпақ болды","Желі ұғымы өзгеретін және өзара байланысқан бағыттарды білдіреді","Ұлы Жібек жолы Еуразияның шығысы мен батысын байланыстырған жолдар желісі болды."],"a":1,"e":"Мәтіндегі деректер «Жібек жолы барлық ғасырда өзгермеген бір соқпақ болды» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Желі ұғымы өзгеретін және өзара байланысқан бағыттарды білдіреді.","l":"C","topic":"Ұлы Жібек жолының желілік сипаты"}]},{"id":"hcl-26","title":"Кеңестік театр мен киноның басталуы","text":"XX ғасырдың алғашқы жартысында Қазақстанда кәсіби өнер мекемелері қалыптасты. Халықтық өнер дәстүрлері жаңа театр және кино үлгілерімен ұштаса бастады.\n\n1926 жылы Қазақтың тұңғыш кәсіби театры Қызылордада ашылды. 1926 жыл кәсіби қазақ театрының қалыптасуындағы маңызды меже болды. 1938 жылы «Амангелді» дыбысты көркем фильмі жарыққа шықты. Театр сахналық өнерді, ал кино экрандық өнерді дамытқан кәсіби мәдениет салалары болды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3},"questions":[{"id":"hcl-26-1","t":"«Кеңестік театр мен киноның басталуы» контексі: Қазақтың тұңғыш кәсіби театры қай қалада ашылды?","o":["Ақмолада","Қызылордада","Оралда","Омбыда"],"a":1,"e":"1926 жылы Қазақтың тұңғыш кәсіби театры Қызылордада ашылды.","l":"A","topic":"Кеңестік театр мен киноның басталуы"},{"id":"hcl-26-2","t":"«Кеңестік театр мен киноның басталуы» контексі: Театр ашылған жыл қайсы?","o":["1841 жыл","1926 жыл","1954 жыл","1913 жыл"],"a":1,"e":"1926 жыл кәсіби қазақ театрының қалыптасуындағы маңызды меже болды.","l":"A","topic":"Кеңестік театр мен киноның басталуы"},{"id":"hcl-26-3","t":"«Кеңестік театр мен киноның басталуы» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақтың тұңғыш кәсіби театры қай қалада ашылды. 2) Алғашқы қазақ дыбысты көркем фильмі қайсы.","o":["1 — Ақмолада; 2 — «Амангелді»","1 — Омбыда; 2 — «Менің атым Қожа»","1 — Қызылордада; 2 — «Қыз Жібек»","1 — Қызылордада; 2 — «Амангелді»"],"a":3,"e":"1926 жылы Қазақтың тұңғыш кәсіби театры Қызылордада ашылды. 1938 жылы «Амангелді» дыбысты көркем фильмі жарыққа шықты.","l":"B","topic":"Кеңестік театр мен киноның басталуы"},{"id":"hcl-26-4","t":"«Кеңестік театр мен киноның басталуы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Театр ашылған жыл қайсы? 2) Театр мен кино қай мәдениет салаларына жатады?","o":["1 — 1913 жыл; 2 — Жер салығына","1 — 1926 жыл; 2 — Сахналық және экрандық өнерге","1 — 1926 жыл; 2 — Әкімшілік басқаруға","1 — 1841 жыл; 2 — Сахналық және экрандық өнерге"],"a":1,"e":"1926 жыл кәсіби қазақ театрының қалыптасуындағы маңызды меже болды. Театр сахналық өнерді, ал кино экрандық өнерді дамытқан кәсіби мәдениет салалары болды.","l":"B","topic":"Кеңестік театр мен киноның басталуы"},{"id":"hcl-26-5","t":"«Кеңестік театр мен киноның басталуы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Кәсіби театрдың ашылуы халықтық өнер дәстүрлерінің қоғамда таралуын толық тоқтатты.","Жаңа кәсіби мекемелер ұлттық мәдениетті сақтай отырып, оны сахна және экран арқылы тарату мүмкіндігін кеңейтті.","Театр мен киноның қалыптасуы жаңа көркем құралдардан гөрі тек әкімшілік басқарудың өзгергенін білдірді.","Дыбысты киноның пайда болуы ұлттық мәдениетті таратуда театрдың бұрынғы қызметін бірден қажетсіз етті."],"a":1,"e":"Жаңа кәсіби мекемелер ұлттық мәдениетті сақтай отырып, оны сахна және экран арқылы тарату мүмкіндігін кеңейтті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Кеңестік театр мен киноның басталуы"}]}]},{"number":27,"questions":[{"id":"ha-070","t":"Моғолстанның саяси орталығы болған қаланы көрсетіңіз.","o":["Алмалық","Сығанақ","Сарайшық","Сарай-Бату"],"a":0,"e":"Алмалық Моғолстан билеушілерінің негізгі саяси орталығы ретінде белгілі.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hi-074","t":"Жанқожа Нұрмұхамедұлы күрескен екі отарлық қысым көзін анықтаңыз.","o":["Хиуа хандығы және Ресей империясы","Ғұндар және Қытай империясы","Жоңғар хандығы және Қарахан мемлекеті","Ноғай Ордасы және Ақ Орда"],"a":0,"e":"Жанқожа Сыр бойын Хиуа езгісінен қорғап, кейін Ресейдің отарлық саясатына қарсы шықты.","l":"B","topic":"Жанқожа және Есет көтерілістері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":168}},{"id":"hk-040","t":"Есім хан тұсында хандықтың маңызды саяси орталығы болған қала қайсы?","o":["Орынбор","Петропавл","Түркістан","Саратов"],"a":2,"e":"Түркістан Есім хан дәуірінде Қазақ хандығының саяси орталығы болды.","l":"A","topic":"Есім хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"ha-087","t":"Қытай деректерінде Испиджаб, ал Махмұд Қашғари еңбегінде Сайрам аталған мекенді салыстыру қандай қорытындыға әкеледі?","o":["Бұлар Еділ бойындағы екі бөлек астана","Сайрам Испиджабтан Маңғыстауға көшірілген","Бұл бір қаланың әр кезеңде қолданылған атаулары","Екеуі де тек көшпелі тайпалардың атауы"],"a":2,"e":"Испиджаб пен Сайрам атаулары бір тарихи қалаға қатысты.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hi-035","t":"1868–1869 жылдары әкімшілік реформаларға қарсы көтерілістер қай облыстарда болды?","o":["Ақмола мен Сырдарияда","Орал мен Торғайда","Жетісу мен Семейде","Түркістан мен Ферғанада"],"a":1,"e":"1868–1869 жылғы көтерілістер Орал мен Торғай облыстарын қамтыды.","l":"A","topic":"1868–1870 жылдардағы көтерілістер","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":171}},{"id":"ha-058","t":"«Дешті Қыпшақ» атауының мағынасы қандай?","o":["Түрік тауы","Моңғол ордасы","Қыпшақ даласы","Оғыз қаласы"],"a":2,"e":"Парсы тіліндегі дешт сөзі дала деген мағынаны білдіреді.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-124","t":"Қарақұмдағы бірігу шешімі мен Бұланты, Аңырақай жеңістерін байланыстыратын ең орынды түсіндіру қайсы?","o":["Құрылтай әскери ынтымақты қажетсіз деп тапты","Күшті біріктіру жауға қарсы күрестің нәтижелілігін арттырды","Жеңістер сыртқы қауіптің мүлдем болмағанын көрсетеді","Барлық жеңіс бір ғана жүздің әрекетінен туды"],"a":1,"e":"Құрылтайдағы ынтымақ идеясы мен кейінгі бірлескен күрес сыртқы қауіпке ұйымдасқан түрде қарсы тұрудың маңызын көрсетеді.","l":"C","topic":"Қазақ-жоңғар соғыстарын талдау","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-110","t":"1928 жылғы тәркілеу, күштеп отырықшыландыру және 1931–1933 жылдардағы ашаршылық арасындағы байланысты қай түсіндіру дұрыс ашады?","o":["Отырықшыландыру ЖЭС саудасын кеңейтіп, барлық маусымдық жайылымды сақтады","Ашаршылық алдымен басталып, 1928 жылғы тәркілеудің кейін қабылдануына себеп болды","Тәркілеу жеке меншікті күшейтіп, босқыншылықты толық тоқтатты","Күштеу шаралары дәстүрлі мал шаруашылығын бұзып, азық тапшылығы мен босқыншылықты тереңдетті"],"a":3,"e":"Тәркілеу мен күштеу мал шаруашылығының өндірістік негізін күйретті. Ашаршылықтың адам шығыны мен босқыншылық салдары осы саясатпен тығыз байланысты.","l":"C","topic":"Ашаршылық","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hm-014","t":"1933 жылы ашаршылық туралы Сталинге хат жазған қайраткер кім?","o":["Шоқан Уәлиханов","Әлкей Марғұлан","Ыбырай Алтынсарин","Тұрар Рысқұлов"],"a":3,"e":"Т.Рысқұлов 1933 жылғы хатында Қазақстандағы аштық пен босқыншылық жағдайын көтерді.","l":"A","topic":"Ашаршылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":222}},{"id":"hk-053","t":"1710 жылғы жалпы қазақ кеңесі қай жерде өтті?","o":["Отырарда","Орбұлақта","Сарайшықта","Қарақұмда"],"a":3,"e":"1710 жылғы Қарақұм құрылтайы жоңғар қаупіне қарсы ортақ әрекет мәселесін қарады.","l":"A","topic":"Қарақұм құрылтайы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}}],"contexts":[{"id":"hce-27","title":"Қала құрылымы: цитадель, шахристан, рабад","text":"Ортағасырлық қалалардың құрылымында цитадель, шахристан және рабад ажыратылады. Цитадель билеуші ордасы мен қорғанысқа байланысты болды. Шахристан негізгі ішкі бөлікті білдірді. Рабадта қолөнер мен сауда дамыды. Дуалдар қауіпсіздікке, базар шаруашылық байланысқа қызмет етті. Бұл бөліктер әр қалада бірдей көлемде көрінбеуі мүмкін. Археологтер құрылыс пен табылған заттарды салыстырады. Өндіріс қалдықтарының шоғырлануы шеберхана аймағын тануға көмектеседі. Қала құрылымы билік, қорғаныс және шаруашылықтың байланысын көрсетеді. Қазіргі көрініске ғана қарап ортағасырлық қызметті анықтау жеткіліксіз. Ескерткіштің уақыт ішіндегі өзгерісін де ескеру қажет.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":54},"questions":[{"id":"hce-27-1","t":"«Қала құрылымы: цитадель, шахристан, рабад» контексі: Бекіністі билеуші ордасы орналасқан бөлік қайсы?","o":["Қыстау","Жайлау","Цитадель","Рабад"],"a":2,"e":"Мәтіндегі деректер «Цитадель» деген жауапты негіздейді. Шахристан қаланың негізгі ішкі бөлігін білдіреді.","l":"A","topic":"Қала құрылымы: цитадель, шахристан, рабад"},{"id":"hce-27-2","t":"«Қала құрылымы: цитадель, шахристан, рабад» контексі: Қолөнер мен сауда дамыған қала маңы бөлігі қайсы?","o":["Иқта","Ұлыс","Жасақ","Рабад"],"a":3,"e":"Мәтіндегі деректер «Рабад» деген жауапты негіздейді. Шахристан қаланың негізгі ішкі бөлігін білдіреді.","l":"A","topic":"Қала құрылымы: цитадель, шахристан, рабад"},{"id":"hce-27-3","t":"«Қала құрылымы: цитадель, шахристан, рабад» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Цитадель тек мал жайылымы болған","Шахристан қаланың негізгі ішкі бөлігін білдіреді","Қаланың барлық бөлігі тек бірдей қызмет атқарған","Рабад міндетті түрде жеке мемлекет болған"],"a":1,"e":"Мәтіндегі деректер «Шахристан қаланың негізгі ішкі бөлігін білдіреді» деген жауапты негіздейді. Шахристан қаланың негізгі ішкі бөлігін білдіреді.","l":"B","topic":"Қала құрылымы: цитадель, шахристан, рабад"},{"id":"hce-27-4","t":"«Қала құрылымы: цитадель, шахристан, рабад» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Базардың болуы биліктің болмағанын көрсетеді","Қазіргі көше атауы ортағасырлық барлық қызметті толық дәлелдейді","Құрылыс пен өндіріс қалдықтарын салыстыру қала қызметін ашады","Қорғанысы бар қалада сауда болмайды"],"a":2,"e":"Мәтіндегі деректер «Құрылыс пен өндіріс қалдықтарын салыстыру қала қызметін ашады» деген жауапты негіздейді. Шахристан қаланың негізгі ішкі бөлігін білдіреді.","l":"B","topic":"Қала құрылымы: цитадель, шахристан, рабад"},{"id":"hce-27-5","t":"«Қала құрылымы: цитадель, шахристан, рабад» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Құрылыс пен өндіріс қалдықтарын салыстыру қала қызметін ашады","Қаланың барлық бөлігі тек бірдей қызмет атқарған","Шахристан қаланың негізгі ішкі бөлігін білдіреді","Ортағасырлық қалалардың құрылымында цитадель, шахристан және рабад ажыратылады."],"a":1,"e":"Мәтіндегі деректер «Қаланың барлық бөлігі тек бірдей қызмет атқарған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Құрылыс пен өндіріс қалдықтарын салыстыру қала қызметін ашады.","l":"C","topic":"Қала құрылымы: цитадель, шахристан, рабад"}]},{"id":"hcl-27","title":"Қаныш Сәтбаев және ғылым","text":"Қазақстандағы ғылымның дамуы табиғи ресурстарды зерттеумен және ғылыми мекемелер құрумен байланысты болды. Ғалымдардың ұйымдастырушылық қызметі зерттеу нәтижелерін ел экономикасымен ұштастырды.\n\nҚазақ КСР Ғылым академиясының алғашқы президенті Қаныш Сәтбаев болды. Қазақ КСР Ғылым академиясы 1946 жылы құрылды. Қаныш Сәтбаев геология мен пайдалы қазбаларды зерттеу саласында еңбек етті. Жезқазғанның мыс кендерін зерттеу Сәтбаевтың ғылыми қызметінде маңызды орын алды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8},"questions":[{"id":"hcl-27-1","t":"«Қаныш Сәтбаев және ғылым» контексі: Қазақ КСР Ғылым академиясының алғашқы президенті кім?","o":["Ыбырай Алтынсарин","Ахмет Байтұрсынұлы","Ермұхан Бекмаханов","Қаныш Сәтбаев"],"a":3,"e":"Қазақ КСР Ғылым академиясының алғашқы президенті Қаныш Сәтбаев болды.","l":"A","topic":"Қаныш Сәтбаев және ғылым"},{"id":"hcl-27-2","t":"«Қаныш Сәтбаев және ғылым» контексі: Ғылым академиясы қай жылы құрылды?","o":["1920 жылы","1946 жылы","1913 жылы","1991 жылы"],"a":1,"e":"Қазақ КСР Ғылым академиясы 1946 жылы құрылды.","l":"A","topic":"Қаныш Сәтбаев және ғылым"},{"id":"hcl-27-3","t":"«Қаныш Сәтбаев және ғылым» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақ КСР Ғылым академиясының алғашқы президенті кім. 2) Қаныш Сәтбаевтың негізгі ғылыми саласы қайсы.","o":["1 — Қаныш Сәтбаев; 2 — Тіл білімі","1 — Ермұхан Бекмаханов; 2 — Геология","1 — Ахмет Байтұрсынұлы; 2 — Педиатрия","1 — Қаныш Сәтбаев; 2 — Геология"],"a":3,"e":"Қазақ КСР Ғылым академиясының алғашқы президенті Қаныш Сәтбаев болды. Қаныш Сәтбаев геология мен пайдалы қазбаларды зерттеу саласында еңбек етті.","l":"B","topic":"Қаныш Сәтбаев және ғылым"},{"id":"hcl-27-4","t":"«Қаныш Сәтбаев және ғылым» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Ғылым академиясы қай жылы құрылды? 2) Сәтбаев зерттеулерімен ерекше байланысты кенді аудан қайсы?","o":["1 — 1946 жылы; 2 — Жезқазған","1 — 1913 жылы; 2 — Жезқазған","1 — 1920 жылы; 2 — Сауран","1 — 1946 жылы; 2 — Қарқара"],"a":0,"e":"Қазақ КСР Ғылым академиясы 1946 жылы құрылды. Жезқазғанның мыс кендерін зерттеу Сәтбаевтың ғылыми қызметінде маңызды орын алды.","l":"B","topic":"Қаныш Сәтбаев және ғылым"},{"id":"hcl-27-5","t":"«Қаныш Сәтбаев және ғылым» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Жезқазғанды зерттеу ғылыми мекемелердің қалыптасуына қатысы жоқ, тек жергілікті кәсіптік тәжірибе болды.","Ғылым академиясының құрылуы геологиялық зерттеулерді өндірістің сұраныстарынан толығымен бөлді.","Ғылымды ұйымдастыруға көңіл бөлу Сәтбаевтың нақты ғылыми зерттеулерден бас тартқанын көрсетеді.","Табиғи ресурстарды зерттеу мен ғылымды ұйымдастыру Қазақстанның ғылыми және өндірістік дамуын байланыстырды."],"a":3,"e":"Табиғи ресурстарды зерттеу мен ғылымды ұйымдастыру Қазақстанның ғылыми және өндірістік дамуын байланыстырды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қаныш Сәтбаев және ғылым"}]}]},{"number":28,"questions":[{"id":"hk-092","t":"Бұқар жыраудың Абылайға арнаған толғауларын қандай мақсатта пайдалануға болады?","o":["Қасым хан заңдарының толық жазбаша мәтінін қалпына келтіруге","Хандық дәуірдің саяси ойы мен қоғамдық мұратын зерттеуге","XV ғасырдағы барлық тайпаның санын дәл есептеуге","Алғашқы қазақ елшілігінің шарттарын түгел анықтауға"],"a":1,"e":"Жырау мұрасы сол дәуірдегі ел бірлігі, билік пен сыртқы қауіп туралы көзқарастарды жеткізеді.","l":"B","topic":"Бұқар жырау","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":157}},{"id":"hm-099","t":"1920 жылдардағы «Қызыл отаулардың» қоғамдық қызметін сипаттаңыз.","o":["Әскери ұшақ құрастыру","Ядролық сынақ жүргізу","Әйелдер арасында сауат ашу мен ағарту жұмысын жүргізу","Тек пайдалы қазба өндіру"],"a":2,"e":"«Қызыл отаулар» қазақ әйелдері арасындағы сауатсыздықты жоюға атсалысты.","l":"B","topic":"Мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-106","t":"Облысты әскери губернатор, уезді уезд бастығы басқаруы реформаның қандай сипатын көрсетеді?","o":["Әскери-әкімшілік және отарлық бақылаудың күшеюін","Жергілікті хандық биліктің толық қалпына келуін","Қазақтардың империядан бөлінуін","Далада орталық биліктің мүлде болмағанын"],"a":0,"e":"Басқарудың негізгі сатылары империялық лауазым иелеріне берілді. Бұл жергілікті дербестікті шектеп, отарлық бақылауды күшейтті.","l":"C","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":150}},{"id":"ha-116","t":"Құндызша (1391) мен Терек (1395) шайқастарының ортақ нәтижесін таңдаңыз.","o":["Екі шайқас Қарахан мемлекетін құрды","Тоқтамыстың жеңілісі Алтын Орданың әлсіреуін күшейтті","Шайқастар Алтын Орда мен Түрік қағанатын біріктірді","Тоқтамыс Әмір Темірді екі рет жеңіп, Моғолстанды қосты"],"a":1,"e":"Әмір Темірдің екі жеңісі Тоқтамыстың күшін әлсіретіп, Алтын Орданың саяси-экономикалық дағдарысын тереңдетті.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"ha-023","t":"Шырақтың ерлігі қандай күреспен байланысты?","o":["Сақтардың парсыларға қарсы күресімен","Түргештердің қарақытайларға қарсы күресімен","Қимақтардың моңғолдарға қарсы күресімен","Оғыздардың қыпшақтарға қарсы күресімен"],"a":0,"e":"Шырақ туралы аңыз сақтардың Дарий әскеріне қарсы күресін сипаттайды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":53}},{"id":"hm-070","t":"Көшпелі шаруашылықты күшпен отырықшыландыру неліктен дағдарыс туғызды?","o":["Мал азығы өздігінен шексіз көбейді","Шаруаларға еркін таңдау толық берілді","Дәстүрлі мал бағу жүйесі мен маусымдық көшу бұзылды","Барлық жайылым өзгеріссіз сақталды"],"a":2,"e":"Күштеу шаралары малдың маусымдық жайылымдарын пайдалану тәртібін бұзды.","l":"A","topic":"Ұжымдастыру","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":2}},{"id":"hi-039","t":"Қоянды жәрмеңкесі қай жылы ашылды?","o":["1905 жылы","1822 жылы","1867 жылы","1848 жылы"],"a":3,"e":"Қоянды жәрмеңкесінің негізі 1848 жылы қаланды.","l":"A","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":162}},{"id":"hk-043","t":"Есім хан дәуірімен байланысты жырауды көрсетіңіз.","o":["Бұқар","Жиембет","Тәтіқара","Үмбетей"],"a":1,"e":"Жиембет жырау Есім хан дәуірінде өмір сүріп, сол кезеңнің саяси оқиғаларын жырлады.","l":"A","topic":"Жыраулар мұрасы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"hi-053","t":"Абай қазақ тіліне үзінділерін аударған Пушкин шығармасын көрсетіңіз.","o":["Өлі жандар","Евгений Онегин","Соғыс және бейбітшілік","Ревизор"],"a":1,"e":"Абай Пушкиннің «Евгений Онегинінен» үзінділер аударды. Татьяна хаттары қазақ арасына кең тарады.","l":"A","topic":"XIX ғасырдағы әдебиет","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":145}},{"id":"hm-074","t":"Карлаг, АЛЖИР және Степлагқа ортақ тарихи сипаттама қайсы?","o":["Ортағасырлық сауда қалалары","Кеңестік жазалау лагерлері","Тәуелсіздік кезеңіндегі университеттер","Ерікті ауылшаруашылық жәрмеңкелері"],"a":1,"e":"Бұл лагерлер кеңестік мәжбүрлеу және жазалау жүйесінің құрамына кірді.","l":"A","topic":"Қуғын-сүргін","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}}],"contexts":[{"id":"hce-28","title":"Тараздың қалалық қызметтері","text":"Тараз ортағасырлық Оңтүстік Қазақстанның ірі қаласы болды. Керуен жолдары, қолөнер және сауда оның дамуына ықпал етті. Қарахан дәуірінде сәулет пен қалалық қызмет өркендеді. Монша мен су жүйесі туралы археологиялық мәліметтер тұрмысты зерттеуге көмектеседі. Тараз маңындағы Айша бибі мен Бабаджа қатын кесенелері сәулет мұрасына жатады. Қаланың маңызын тек қорғаныс дуалымен өлшеу жеткіліксіз. Экономикалық және мәдени қызмет те ескеріледі. Жол бағыты өзгерсе қала тіршілігіне әсер етуі мүмкін. Қалалық даму сауда, билік және қолөнердің байланысымен түсіндіріледі. Бір құрылыс бүкіл қаланың барлық дәуірін толық сипаттамайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":54},"questions":[{"id":"hce-28-1","t":"«Тараздың қалалық қызметтері» контексі: Мәтінде сипатталған қала қайсы?","o":["Тараз","Қазан","Сарай-Бату","Омбы"],"a":0,"e":"Мәтіндегі деректер «Тараз» деген жауапты негіздейді. Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді.","l":"A","topic":"Тараздың қалалық қызметтері"},{"id":"hce-28-2","t":"«Тараздың қалалық қызметтері» контексі: Тараз маңындағы кесенелер жұбы қайсы?","o":["Айша бибі мен Бабаджа қатын","Бекет ата мен Шақпақ ата","Қорқыт ата мен Домалақ ана","Жошы хан мен Алаша хан"],"a":0,"e":"Мәтіндегі деректер «Айша бибі мен Бабаджа қатын» деген жауапты негіздейді. Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді.","l":"A","topic":"Тараздың қалалық қызметтері"},{"id":"hce-28-3","t":"«Тараздың қалалық қызметтері» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Сәулет ескерткіші шаруашылық туралы еш мәлімет бере алмайды","Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді","Қолөнер қаланың дамуына қатыспаған","Тараздың маңызын тек дуал биіктігі толық анықтайды"],"a":1,"e":"Мәтіндегі деректер «Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді» деген жауапты негіздейді. Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді.","l":"B","topic":"Тараздың қалалық қызметтері"},{"id":"hce-28-4","t":"«Тараздың қалалық қызметтері» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Қаланы экономикалық, мәдени және қорғаныс қызметімен бірге бағалау керек","Монша табылса қалада басқа қызмет болмаған","Бір кесененің мерзімі барлық көшенің жасын анықтайды","Керуен жолының өзгеруі қала өміріне еш әсер етпейді"],"a":0,"e":"Мәтіндегі деректер «Қаланы экономикалық, мәдени және қорғаныс қызметімен бірге бағалау керек» деген жауапты негіздейді. Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді.","l":"B","topic":"Тараздың қалалық қызметтері"},{"id":"hce-28-5","t":"«Тараздың қалалық қызметтері» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Тараз ортағасырлық Оңтүстік Қазақстанның ірі қаласы болды.","Монша мен су жүйесі қалалық тұрмыстық қызметті көрсетеді","Қаланы экономикалық, мәдени және қорғаныс қызметімен бірге бағалау керек","Тараздың маңызын тек дуал биіктігі толық анықтайды"],"a":3,"e":"Мәтіндегі деректер «Тараздың маңызын тек дуал биіктігі толық анықтайды» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Қаланы экономикалық, мәдени және қорғаныс қызметімен бірге бағалау керек.","l":"C","topic":"Тараздың қалалық қызметтері"}]},{"id":"hcl-28","title":"Мәскеу шайқасындағы қазақстандықтар","text":"Екінші дүниежүзілік соғыс кезінде Қазақстанда жасақталған бөлімдер майданға аттанды. Мәскеу түбіндегі шайқас кеңес әскерінің қорғанысы мен қарсы шабуылында маңызды орын алды.\n\nБауыржан Момышұлы Мәскеу түбіндегі шайқаста батальон басқарған қолбасшы ретінде танылды. Иван Панфилов басқарған 316-атқыштар дивизиясы Алматыда жасақталды. Дивизияның жасақталуына Алматы мен Жетісу тұрғындары қатысты. 1941 жылғы Мәскеу шайқасы соғыстың алғашқы кезеңіндегі ірі оқиға болды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9},"questions":[{"id":"hcl-28-1","t":"«Мәскеу шайқасындағы қазақстандықтар» контексі: Мәскеу шайқасында ерлігімен танылған қазақ офицері кім?","o":["Дінмұхамед Қонаев","Бауыржан Момышұлы","Шоқан Уәлиханов","Жанқожа Нұрмұхамедұлы"],"a":1,"e":"Бауыржан Момышұлы Мәскеу түбіндегі шайқаста батальон басқарған қолбасшы ретінде танылды.","l":"A","topic":"Мәскеу шайқасындағы қазақстандықтар"},{"id":"hcl-28-2","t":"«Мәскеу шайқасындағы қазақстандықтар» контексі: Панфилов басқарған дивизияның бастапқы нөмірі қандай?","o":["316","28","8","100"],"a":0,"e":"Иван Панфилов басқарған 316-атқыштар дивизиясы Алматыда жасақталды.","l":"A","topic":"Мәскеу шайқасындағы қазақстандықтар"},{"id":"hcl-28-3","t":"«Мәскеу шайқасындағы қазақстандықтар» контексі: Екі деректі сәйкестендіріңіз. 1) Мәскеу шайқасында ерлігімен танылған қазақ офицері кім. 2) Дивизия қай қалада жасақталды.","o":["1 — Жанқожа Нұрмұхамедұлы; 2 — Орынборда","1 — Бауыржан Момышұлы; 2 — Алматыда","1 — Шоқан Уәлиханов; 2 — Алматыда","1 — Бауыржан Момышұлы; 2 — Қоқанда"],"a":1,"e":"Бауыржан Момышұлы Мәскеу түбіндегі шайқаста батальон басқарған қолбасшы ретінде танылды. Дивизияның жасақталуына Алматы мен Жетісу тұрғындары қатысты.","l":"B","topic":"Мәскеу шайқасындағы қазақстандықтар"},{"id":"hcl-28-4","t":"«Мәскеу шайқасындағы қазақстандықтар» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Панфилов басқарған дивизияның бастапқы нөмірі қандай? 2) Мәскеу түбіндегі негізгі шайқас қай жылы болды?","o":["1 — 8; 2 — 1941 жылы","1 — 28; 2 — 1933 жылы","1 — 316; 2 — 1916 жылы","1 — 316; 2 — 1941 жылы"],"a":3,"e":"Иван Панфилов басқарған 316-атқыштар дивизиясы Алматыда жасақталды. 1941 жылғы Мәскеу шайқасы соғыстың алғашқы кезеңіндегі ірі оқиға болды.","l":"B","topic":"Мәскеу шайқасындағы қазақстандықтар"},{"id":"hcl-28-5","t":"«Мәскеу шайқасындағы қазақстандықтар» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Дивизияның Алматыда жасақталуы оның соғыс қимылдарын тек Қазақстан аумағында жүргізгенін білдіреді.","Жеке командирдің ерлігі көпұлтты дивизияның ортақ жауынгерлік үлесін жоққа шығарады.","Мәскеу түбіндегі қорғанысқа қатысу Қазақстандағы тылдық әскери даярлықпен байланыссыз құбылыс болды.","Қазақстандағы әскери жасақтау мен майдандағы ерлік елдің ортақ қорғанысқа қатысқанын көрсетеді."],"a":3,"e":"Қазақстандағы әскери жасақтау мен майдандағы ерлік елдің ортақ қорғанысқа қатысқанын көрсетеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Мәскеу шайқасындағы қазақстандықтар"}]}]},{"number":29,"questions":[{"id":"hi-071","t":"Кенесары көтерілісінің негізгі саяси мақсаты қандай болды?","o":["Қазақ жерін бірнеше отарға бөлу","Ресейдің әкімшілік бөлінісін тереңдету","Қазақ жерінің тұтастығы мен дербес мемлекеттілікті қалпына келтіру","Қоқанға толық бағынышты болу"],"a":2,"e":"Кенесары хандық билікті қалпына келтіріп, отарлық қысымнан азат болуды көздеді.","l":"B","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":199}},{"id":"hi-001","t":"Орта жүздегі хандық басқаруды жоюға негіз болған 1822 жылғы құжат қалай аталды?","o":["Жеті жарғы","Сібір қырғыздары туралы жарғы","Түркістан өлкесін басқару туралы ереже","Орынбор қырғыздары туралы жарғы"],"a":1,"e":"1822 жылғы «Сібір қырғыздары туралы жарғы» Орта жүзде хандық билікті жойып, округтік басқаруды енгізді.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"hm-065","t":"Қазақстан халқы Ассамблеясы қай жылы құрылды?","o":["1920 жылы","1989 жылы","1995 жылы","2001 жылы"],"a":2,"e":"Қазақстан халқы Ассамблеясы 1995 жылы құрылды.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"ha-031","t":"Үйсіндер мемлекеті билеушісінің атауын көрсетіңіз.","o":["Жабғу","Инақ","Күнби","Шаньюй"],"a":2,"e":"Үйсіндердің жоғарғы билеушісі қытай деректерінде күнби деп аталады.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-039","t":"Есім ханның атымен байланысты заңдар қалай аталды?","o":["«Қасым ханның қасқа жолы»","«Далалық ереже»","«Жеті жарғы»","«Есім ханның ескі жолы»"],"a":3,"e":"Есім хан тұсында бұрынғы құқықтық дәстүр жалғастырылып, «Есім ханның ескі жолы» қалыптасты.","l":"A","topic":"Есім ханның заңдары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"ha-094","t":"Батыс Түрік қағанатының Жетісуды иеленуі оның халықаралық ықпалына неге әсер етті?","o":["Жетісудан өткен керуен жолдарын бақылауға мүмкіндік берді","Жібек жолын тек теңіз бағытына ауыстырды","Қала мен дала арасындағы сауданы қажетсіз етті","Қағанатты Еуропадағы жалғыз мемлекетке айналдырды"],"a":0,"e":"Жетісудың керуен жолдары торабында орналасуы сауда мен дипломатиялық қатынастарға ықпал етті.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":82}},{"id":"hk-049","t":"Тәуке хан дәуірінде жүйеленген заңдар жинағы қалай аталады?","o":["«Жеті жарғы»","«Түрік шежіресі»","«Сібір қырғыздары туралы жарғы»","«Яса»"],"a":0,"e":"«Жеті жарғы» қазақтың әдет-ғұрып құқығына сүйенген құқықтық ережелер жинағы болды.","l":"A","topic":"Тәуке ханның заңдары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":89}},{"id":"ha-057","t":"Қыпшақтарды Еуропа деректерінде қалай атаған?","o":["Савроматтар","Тиграхаудалар","Нушебилер","Құмандар"],"a":3,"e":"Батыс Еуропа деректеріндегі құман атауы қыпшақтарға қатысты қолданылды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hk-108","t":"1594 жылы Мәскеуге қазақ елшісі барып, 1595 жылы орыс елшісі Қазақ хандығына келді. Осы екі деректен қандай қорытынды дәлелді?","o":["Қазақ хандығы сыртқы саясатын мүлдем тоқтатты","Барлық шекаралық мәселе толық шешілді","Дипломатиялық байланыс екіжақты сипат алды","Екі мемлекет бірден бір мемлекетке бірікті"],"a":2,"e":"Елшілік алмасу екі тараптың да келіссөзге қатысқанын көрсетеді; ол бірігу немесе барлық мәселенің шешілуін өздігінен дәлелдемейді.","l":"C","topic":"XVI ғасырдағы дипломатия","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":105}},{"id":"hm-114","t":"Қазақ АКСР-і астаналарының ауысуын тиісті жылдармен сәйкестендіріңіз. Дұрыс қатарды таңдаңыз.","o":["1920 — Орынбор; 1925 — Қызылорда; 1929 — Алматы","1920 — Орынбор; 1925 — Алматы; 1929 — Қызылорда","1920 — Қызылорда; 1925 — Орынбор; 1929 — Алматы","1920 — Алматы; 1925 — Қызылорда; 1929 — Орынбор"],"a":0,"e":"Алғашқы астана Орынбор болды. Астана 1925 жылы Қызылордаға, 1929 жылы Алматыға көшірілді.","l":"C","topic":"Қазақ АКСР","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":259}}],"contexts":[{"id":"hce-29","title":"Сауранның бірнеше қызметі","text":"Сауран Оңтүстік Қазақстандағы ортағасырлық қалалардың бірі болды. Авторлар оның қорғаныс құрылыстарын атап өтеді. Қала Сырдария өңірінің саяси және сауда байланыстарына қатысты. Дуал қауіпсіздікке қызмет етсе, қала маңындағы шаруашылық азықпен қамтамасыз етті. Әр кезеңде қаланың саяси рөлі өзгеріп отырды. Бір ғасырдағы жағдайды барлық уақытқа тарату дұрыс емес. Жазба сипаттаманы археологиялық зерттеумен салыстыру қажет. Қаланың әскери маңызы сауда қызметін жоққа шығармайды. Бірнеше қызметтің қатар болуы ортағасырлық қалаға тән. Тарихи баға беру үшін уақыт, құрылыс және шаруашылық мәліметті бірге қарастыру керек. Бір сыртқы сипаттама барлық кезеңді толық қамтымайды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":158},"questions":[{"id":"hce-29-1","t":"«Сауранның бірнеше қызметі» контексі: Сауран қай тарихи аймақта орналасқан?","o":["Батыс Еуропа","Оңтүстік Қазақстан","Қиыр Шығыс","Солтүстік Сібір"],"a":1,"e":"Мәтіндегі деректер «Оңтүстік Қазақстан» деген жауапты негіздейді. Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті.","l":"A","topic":"Сауранның бірнеше қызметі"},{"id":"hce-29-2","t":"«Сауранның бірнеше қызметі» контексі: Қала дуалының негізгі қызметі қандай?","o":["Теңге құю","Жазу үйрету","Қорғаныс","Мал таңбалау"],"a":2,"e":"Мәтіндегі деректер «Қорғаныс» деген жауапты негіздейді. Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті.","l":"A","topic":"Сауранның бірнеше қызметі"},{"id":"hce-29-3","t":"«Сауранның бірнеше қызметі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Сауранның бір ғасырдағы рөлі барлық дәуірде өзгермеген","Қорғанысы бар қалада айырбас болмаған","Қала маңы шаруашылығы тұрғындарға еш әсер етпеген","Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті"],"a":3,"e":"Мәтіндегі деректер «Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті» деген жауапты негіздейді. Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті.","l":"B","topic":"Сауранның бірнеше қызметі"},{"id":"hce-29-4","t":"«Сауранның бірнеше қызметі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір саяхатшы сипаттамасы барлық ғасырды толық көрсетеді","Қаланың әскери, сауда және шаруашылық қызметі қатар өмір сүре алады","Археология мен жазбаны салыстырудың қажеті жоқ","Саяси рөл өзгерсе қаланың барлық тұрғыны міндетті түрде ауысады"],"a":1,"e":"Мәтіндегі деректер «Қаланың әскери, сауда және шаруашылық қызметі қатар өмір сүре алады» деген жауапты негіздейді. Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті.","l":"B","topic":"Сауранның бірнеше қызметі"},{"id":"hce-29-5","t":"«Сауранның бірнеше қызметі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Қала маңындағы шаруашылық тұрғындарды азықпен қамтамасыз етті","Қаланың әскери, сауда және шаруашылық қызметі қатар өмір сүре алады","Сауранның бір ғасырдағы рөлі барлық дәуірде өзгермеген","Сауран Оңтүстік Қазақстандағы ортағасырлық қалалардың бірі болды."],"a":2,"e":"Мәтіндегі деректер «Сауранның бір ғасырдағы рөлі барлық дәуірде өзгермеген» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Қаланың әскери, сауда және шаруашылық қызметі қатар өмір сүре алады.","l":"C","topic":"Сауранның бірнеше қызметі"}]},{"id":"hcl-29","title":"Мәншүк пен Әлияның ерлігі","text":"Соғыс жылдарында қазақстандық әйелдер де майданда ерлік көрсетті. Әртүрлі әскери мамандықтарды меңгерген жауынгерлердің өмір жолы халық жадында сақталды.\n\nМәншүк Мәметова пулеметші ретінде шайқастарға қатысты. Әлия Молдағұлова мерген ретінде ерлігімен танылды. Мәншүк Мәметова Невель маңындағы шайқаста ерлікпен қаза тапты. Екі жауынгерге де қаза болғаннан кейін Кеңес Одағының Батыры атағы берілді. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9},"questions":[{"id":"hcl-29-1","t":"«Мәншүк пен Әлияның ерлігі» контексі: Мәншүк Мәметованың әскери мамандығы қандай?","o":["Ұшқыш","Әскери аудармашы","Теңізші","Пулеметші"],"a":3,"e":"Мәншүк Мәметова пулеметші ретінде шайқастарға қатысты.","l":"A","topic":"Мәншүк пен Әлияның ерлігі"},{"id":"hcl-29-2","t":"«Мәншүк пен Әлияның ерлігі» контексі: Әлия Молдағұлованың әскери мамандығы қандай?","o":["Пулеметші","Танк жүргізуші","Мерген","Кеме командирі"],"a":2,"e":"Әлия Молдағұлова мерген ретінде ерлігімен танылды.","l":"A","topic":"Мәншүк пен Әлияның ерлігі"},{"id":"hcl-29-3","t":"«Мәншүк пен Әлияның ерлігі» контексі: Екі деректі сәйкестендіріңіз. 1) Мәншүк Мәметованың әскери мамандығы қандай. 2) Мәншүк ерлігімен байланысты қала қайсы.","o":["1 — Теңізші; 2 — Қызылорда","1 — Ұшқыш; 2 — Невель","1 — Пулеметші; 2 — Невель","1 — Пулеметші; 2 — Тараз"],"a":2,"e":"Мәншүк Мәметова пулеметші ретінде шайқастарға қатысты. Мәншүк Мәметова Невель маңындағы шайқаста ерлікпен қаза тапты.","l":"B","topic":"Мәншүк пен Әлияның ерлігі"},{"id":"hcl-29-4","t":"«Мәншүк пен Әлияның ерлігі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Әлия Молдағұлованың әскери мамандығы қандай? 2) Екі жауынгерге де берілген жоғары атақ қайсы?","o":["1 — Пулеметші; 2 — Кеңес Одағының Батыры","1 — Мерген; 2 — Кеңес Одағының Батыры","1 — Мерген; 2 — Социалистік Еңбек Ері","1 — Танк жүргізуші; 2 — Алашорда төрағасы"],"a":1,"e":"Әлия Молдағұлова мерген ретінде ерлігімен танылды. Екі жауынгерге де қаза болғаннан кейін Кеңес Одағының Батыры атағы берілді.","l":"B","topic":"Мәншүк пен Әлияның ерлігі"},{"id":"hcl-29-5","t":"«Мәншүк пен Әлияның ерлігі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Әскери мамандықтары бөлек болғанымен, екі жауынгердің ерлігі ортақ тарихи жад пен құрметке негіз болды.","Ерлікке кейіннен баға берілуі майдандағы нақты қызметтен гөрі тек бейбіт кезеңдегі жұмысты бағалағанын көрсетеді.","Екі жауынгерге ортақ атақ берілуі олардың әскери мамандықтары да бірдей болғанын дәлелдейді.","Әртүрлі қарумен шайқасуы олардың ерлігін ортақ тарихи жадта салыстырып қарауға мүмкіндік бермейді."],"a":0,"e":"Әскери мамандықтары бөлек болғанымен, екі жауынгердің ерлігі ортақ тарихи жад пен құрметке негіз болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Мәншүк пен Әлияның ерлігі"}]}]},{"number":30,"questions":[{"id":"hi-116","t":"1916 жылғы көтерілістің негізгі себептері мен тікелей түрткісін ажырататын жауапты таңдаңыз.","o":["Себебі — ғарыш айлағы; түрткісі — хан сайлауы","Себебі — моңғол шапқыншылығы; түрткісі — Жеті жарғы","Себептері — отарлық қысым мен жер мәселесі; түрткісі — тыл жұмыстарына алу жарлығы","Себебі — ұжымдастыру; түрткісі — тың игеру"],"a":2,"e":"Ұзақ мерзімді наразылық отарлық езгі мен жер мәселесінен жиналды. 25 маусым жарлығы сол наразылықтың ашық көтеріліске ұласуына тікелей түрткі болды.","l":"C","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":219}},{"id":"ha-015","t":"Қола дәуіріндегі металлургияның дамуы қандай өзгеріске жағдай жасады?","o":["Теміржол көлігі пайда болды","Еңбек құралдары мен қару жасау жетілді","Қағаз ақша айналымға енді","Жазба баспасөз жаппай тарады"],"a":1,"e":"Металл өңдеу берік құралдар мен қару түрлерін жасауға мүмкіндік берді.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-075","t":"Тұтас этностардың Қазақстанға күштеп көшірілуі қалай аталады?","o":["Индустрияландыру","Эмансипация","Урбанизация","Депортация"],"a":3,"e":"Депортация — адамдарды немесе халықтарды еркінен тыс басқа аумаққа көшіру.","l":"A","topic":"Қуғын-сүргін","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":113}},{"id":"hm-023","t":"АЛЖИР лагеріне қамалғандардың негізгі санаты кімдер болды?","o":["Тек шетелдік дипломаттар","Тек жоғары оқу орны студенттері","Тек әскери тұтқын ерлер","«Отанын сатқандардың» әйелдері"],"a":3,"e":"АЛЖИР репрессияланғандардың әйелдерін қамауға арналған лагерь ретінде белгілі.","l":"A","topic":"Қуғын-сүргін","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"ha-112","t":"Ақ Орданың Шығыс Дешті Қыпшақ тайпаларын біріктіруі мен Сырдария қалаларына ұмтылуын бірге қарастырғанда қандай қорытынды негізді?","o":["Бірігу тек діни мекемелердің шешімімен жүзеге асқан","Саяси бірігу сауда және егіншілік орталықтарына сүйенумен ұштасқан","Қала экономикасы мен дала тайпалары бір-біріне әсер етпеген","Хандық билік қалалармен байланыс орнатудан бас тартқан"],"a":1,"e":"Тайпалардың саяси бірігуі мен қалалық ресурстарды бақылау мемлекетті күшейтетін өзара байланысты бағыттар болды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-018","t":"XVI ғасырдың басында Қазақ хандығын күшейткен билеушіні көрсетіңіз.","o":["Кенесары хан","Қасым хан","Тәуке хан","Абылай хан"],"a":1,"e":"Қасым ханның билігі XVI ғасырдың алғашқы ширегіне жатады және хандықтың өрлеуімен байланысты.","l":"A","topic":"Қасым хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hk-084","t":"Төле, Қазыбек және Әйтеке билердің ортақ тарихи қызметін таңдаңыз.","o":["Көшпелі шаруашылықтың орнына тек егіншілік енгізу","Моғолстанда жаңа әулеттің билігін орнату","Сұлтандарды түгел хандық биліктен шеттету","Қазақ қоғамындағы бірлік пен құқықтық тәртіпті нығайту"],"a":3,"e":"Үш би Тәуке дәуіріндегі бірлік, мәміле және әдет-ғұрып құқығын жүйелеумен байланысты.","l":"B","topic":"Билердің рөлі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":109}},{"id":"hm-085","t":"Тоқырау кезеңіндегі экономикалық қайшылықтың бірін көрсетіңіз.","o":["Тек жеке кәсіпкерлік үстем болды","Барлық жоспарлау бірден жойылды","Өндіріс өсімімен қатар басқарудың тиімсіздігі күшейді","Өнеркәсіп толығымен тоқтады"],"a":2,"e":"Жоспарлы шаруашылықтағы әкімшілік басқару экономикалық тиімділікті шектеді.","l":"B","topic":"Тоқырау","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-020","t":"Кенесарының бауыры әрі көтеріліс басшыларының бірі кім?","o":["Наурызбай Қасымұлы","Исатай Тайманұлы","Сырым Датұлы","Есет Көтібарұлы"],"a":0,"e":"Наурызбай Қасымұлы ағасы Кенесарымен бірге ұлт-азаттық қозғалысқа қатысты.","l":"A","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":160}},{"id":"hi-016","t":"Кенесары Қасымұлы қай жылы хан болып сайланды?","o":["1836 жылы","1822 жылы","1841 жылы","1867 жылы"],"a":2,"e":"1841 жылы Кенесары хан сайланды. Ол қазақ мемлекеттілігін қалпына келтіруді көздеді.","l":"A","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":199}}],"contexts":[{"id":"hce-30","title":"Әл-Фараби және ғылыми байланыстар","text":"Әл-Фараби Отырар өңірінен шыққан ортағасырлық ойшыл ретінде белгілі. Ол философия, логика және музыка салаларына еңбек арнады. Ғылыми қызметі ислам дүниесінің білім орталықтарымен байланысты болды. Оның мұрасы білімнің аймақтар арасында алмасқанын көрсетеді. Туған жері мен еңбек еткен ортасын ажырату маңызды. Бір өңірден шығу бүкіл өмірін сол жерде өткізді дегенді білдірмейді. Ғалымдар түрлі тілдегі білім дәстүрін пайдаланған. Мұндай мұраны зерттеу қала мәдениеті мен халықаралық ғылыми байланысты ашады. Қазақстан тарихын әлемдік өркениет аясында қарастыруға осы мысал мүмкіндік береді. Тұлғаның көпсалалы қызметін тек бір еңбекпен шектеу оның үлесін тарылтады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12},"questions":[{"id":"hce-30-1","t":"«Әл-Фараби және ғылыми байланыстар» контексі: Әл-Фарабидің шыққан өңірі қайсы?","o":["Сарай","Маңғыстау","Отырар","Қазан"],"a":2,"e":"Мәтіндегі деректер «Отырар» деген жауапты негіздейді. Оның қызметі аймақаралық ғылыми байланысты көрсетеді.","l":"A","topic":"Әл-Фараби және ғылыми байланыстар"},{"id":"hce-30-2","t":"«Әл-Фараби және ғылыми байланыстар» контексі: Мәтінде аталған ғылымдар жұбы қайсы?","o":["Генетика мен ғарыш техникасы","Логика мен музыка","Баспа мен электротехника","Теміржол мен телеграф"],"a":1,"e":"Мәтіндегі деректер «Логика мен музыка» деген жауапты негіздейді. Оның қызметі аймақаралық ғылыми байланысты көрсетеді.","l":"A","topic":"Әл-Фараби және ғылыми байланыстар"},{"id":"hce-30-3","t":"«Әл-Фараби және ғылыми байланыстар» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Оның қызметі аймақаралық ғылыми байланысты көрсетеді","Әл-Фараби тек әскери жорықтармен танылған","Ғылым орталықтары бір-бірінен толық оқшау тұрған","Ғалымның туған жері бүкіл өмірін өткізген жалғыз мекені болған"],"a":0,"e":"Мәтіндегі деректер «Оның қызметі аймақаралық ғылыми байланысты көрсетеді» деген жауапты негіздейді. Оның қызметі аймақаралық ғылыми байланысты көрсетеді.","l":"B","topic":"Әл-Фараби және ғылыми байланыстар"},{"id":"hce-30-4","t":"«Әл-Фараби және ғылыми байланыстар» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Өмірбаянда туған жері мен қызмет еткен ортасын ажырату қажет","Бір ғылым саласында еңбек ету өзге саланы зерттеуге кедергі","Әртүрлі тілдегі білім дәстүрі өзара ықпалдаса алмайды","Басқа қалада еңбек ету туған өңірмен байланысын толық жоққа шығарады"],"a":0,"e":"Мәтіндегі деректер «Өмірбаянда туған жері мен қызмет еткен ортасын ажырату қажет» деген жауапты негіздейді. Оның қызметі аймақаралық ғылыми байланысты көрсетеді.","l":"B","topic":"Әл-Фараби және ғылыми байланыстар"},{"id":"hce-30-5","t":"«Әл-Фараби және ғылыми байланыстар» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Әл-Фараби Отырар өңірінен шыққан ортағасырлық ойшыл ретінде белгілі.","Оның қызметі аймақаралық ғылыми байланысты көрсетеді","Ғалымның туған жері бүкіл өмірін өткізген жалғыз мекені болған","Өмірбаянда туған жері мен қызмет еткен ортасын ажырату қажет"],"a":2,"e":"Мәтіндегі деректер «Ғалымның туған жері бүкіл өмірін өткізген жалғыз мекені болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Өмірбаянда туған жері мен қызмет еткен ортасын ажырату қажет.","l":"C","topic":"Әл-Фараби және ғылыми байланыстар"}]},{"id":"hcl-30","title":"Соғыс кезіндегі тыл еңбегі","text":"Майдандағы күрес тылдағы өндіріс пен ауыл шаруашылығының еңбегіне сүйенді. Қазақстанға кәсіпорындар көшіріліп, жұмысшылар мен шаруалар әскерді жабдықтауға үлес қосты.\n\nҚауіпті аймақтардан кәсіпорындар мен тұрғындарды көшіру эвакуация деп аталды. Ақтөбеде соғыс кезінде ферроқорытпа зауыты іске қосылды. Шығанақ Берсиев тарыдан жоғары өнім алған тыл еңбеккері ретінде танылды. Жамбыл Жабаев «Ленинградтық өренім» өлеңінде қоршаудағы қалаға рухани қолдау білдірді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14},"questions":[{"id":"hcl-30-1","t":"«Соғыс кезіндегі тыл еңбегі» контексі: Соғыс кезіндегі кәсіпорындарды қауіпсіз аймаққа көшіру қалай аталады?","o":["Эвакуация","Демаркация","Жекешелендіру","Репатриация"],"a":0,"e":"Қауіпті аймақтардан кәсіпорындар мен тұрғындарды көшіру эвакуация деп аталды.","l":"A","topic":"Соғыс кезіндегі тыл еңбегі"},{"id":"hcl-30-2","t":"«Соғыс кезіндегі тыл еңбегі» контексі: Соғыс жылдарында ферроқорытпа зауыты іске қосылған қала қайсы?","o":["Түркістан","Сауран","Қарқаралы","Ақтөбе"],"a":3,"e":"Ақтөбеде соғыс кезінде ферроқорытпа зауыты іске қосылды.","l":"A","topic":"Соғыс кезіндегі тыл еңбегі"},{"id":"hcl-30-3","t":"«Соғыс кезіндегі тыл еңбегі» контексі: Екі деректі сәйкестендіріңіз. 1) Соғыс кезіндегі кәсіпорындарды қауіпсіз аймаққа көшіру қалай аталады. 2) Жоғары өнім алған белгілі тыл еңбеккері кім.","o":["1 — Эвакуация; 2 — Әлихан Бөкейхан","1 — Репатриация; 2 — Шоқан Уәлиханов","1 — Эвакуация; 2 — Шығанақ Берсиев","1 — Жекешелендіру; 2 — Шығанақ Берсиев"],"a":2,"e":"Қауіпті аймақтардан кәсіпорындар мен тұрғындарды көшіру эвакуация деп аталды. Шығанақ Берсиев тарыдан жоғары өнім алған тыл еңбеккері ретінде танылды.","l":"B","topic":"Соғыс кезіндегі тыл еңбегі"},{"id":"hcl-30-4","t":"«Соғыс кезіндегі тыл еңбегі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Соғыс жылдарында ферроқорытпа зауыты іске қосылған қала қайсы? 2) Жамбылдың қоршаудағы қала тұрғындарына арналған өлеңі қайсы?","o":["1 — Қарқаралы; 2 — «Қарасөздер»","1 — Түркістан; 2 — «Ленинградтық өренім»","1 — Ақтөбе; 2 — «Оян, қазақ!»","1 — Ақтөбе; 2 — «Ленинградтық өренім»"],"a":3,"e":"Ақтөбеде соғыс кезінде ферроқорытпа зауыты іске қосылды. Жамбыл Жабаев «Ленинградтық өренім» өлеңінде қоршаудағы қалаға рухани қолдау білдірді.","l":"B","topic":"Соғыс кезіндегі тыл еңбегі"},{"id":"hcl-30-5","t":"«Соғыс кезіндегі тыл еңбегі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Жоғары өнім алған шаруалардың жетістігі өнеркәсіп өндірісімен байланыссыз, тек жергілікті тұрмысқа қызмет етті.","Рухани қолдаудың болуы материалдық жабдықтаудың тыл міндеттеріне кірмегенін көрсетеді.","Кәсіпорындардың көшірілуі ауыл шаруашылығы еңбегінің майдан үшін маңызын жойды.","Өнеркәсіп, ауыл шаруашылығы және рухани қолдау майданды қамтамасыз етудің бірін-бірі толықтырған бағыттары болды."],"a":3,"e":"Өнеркәсіп, ауыл шаруашылығы және рухани қолдау майданды қамтамасыз етудің бірін-бірі толықтырған бағыттары болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Соғыс кезіндегі тыл еңбегі"}]}]},{"number":31,"questions":[{"id":"hk-001","t":"Керей мен Жәнібек бастаған тайпалар қай мемлекеттің құрамынан бөлінді?","o":["Қимақ қағанатынан","Әбілқайыр хандығынан","Батыс Түрік қағанатынан","Қарахан мемлекетінен"],"a":1,"e":"Керей мен Жәнібек Әбілқайыр билігіне наразы топтарды бастап, Моғолстанның батысына көшті.","l":"A","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8}},{"id":"ha-098","t":"Көшпелі билеушілердің Сырдария қалаларына ұмтылысын қай байланыс дұрыс түсіндіреді?","o":["Қалаларда қолөнер мен базар болған жоқ","Қала саудасы мен егіншілігі дала шаруашылығын толықтырды","Қала мен дала арасында тек әскери байланыс болды","Көшпелілерге қала өнімдері мүлде қажет болмады"],"a":1,"e":"Қалалар астық, қолөнер өнімдері және сауда кірісін беріп, көшпелі шаруашылықтың мүмкіндігін толықтырды.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-066","t":"1822 жылғы округтік басқару жүйесінде әкімшілік бірліктердің дұрыс ретін табыңыз.","o":["Ауыл → округ → болыс","Округ → болыс → ауыл","Болыс → округ → ауыл","Облыс → губерния → ауыл"],"a":1,"e":"1822 жылғы реформа Орта жүзде округтерді енгізді. Округ болыстарға, болыс ауылдарға бөлінді.","l":"B","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":171}},{"id":"hm-037","t":"Қазақ КСР Ғылым академиясының алғашқы президенті кім болды?","o":["Дінмұхамед Қонаев","Санжар Асфендияров","Қаныш Сәтбаев","Мұхтар Әуезов"],"a":2,"e":"1946 жылы құрылған академияның тұңғыш президенті Қ.Сәтбаев болды.","l":"A","topic":"Ғылым","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hk-114","t":"Қазақ халқының тайпалық негізі мен Қазақ хандығының құрылуын салыстырғанда қай қорытынды дұрыс?","o":["Қазақ халқы тек бір ханның ұрпақтарынан қалыптасты","Хандықтың құрылуы барлық тайпалық байланысты бірден жойды","Этникалық бірігу тек сыртқы елшілік нәтижесі болды","Мемлекеттің қалыптасуы ұзақ этникалық бірігу үдерісіне сүйенді"],"a":3,"e":"Тайпалардың тілдік, мәдени және аумақтық жақындасуы жаңа мемлекеттің әлеуметтік негізін қалыптастырды.","l":"C","topic":"Қазақ этногенезі және мемлекет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"ha-071","t":"Моғолстанның құрылу жылы қайсы?","o":["1206 жыл","1428 жыл","1465 жыл","1348 жыл"],"a":3,"e":"Моғолстан Шағатай ұлысының шығыс бөлігінде 1348 жылы қалыптасты.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":120}},{"id":"ha-005","t":"Тас құралдың жүзін ұсақ кертіктер арқылы өткірлеу тәсілі қалай аталады?","o":["Ирригация","Мелиорация","Ретушь","Ассимиляция"],"a":2,"e":"Ретушь кезінде тас құралдың жиегіне ұсақ кертіктер түсіріліп, жүзі өткірленеді.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":5}},{"id":"hi-008","t":"«Түрмеден қашқан» күйін шығарған композитор кім?","o":["Тәттімбет Қазанғапұлы","Құрманғазы Сағырбайұлы","Дәулеткерей Шығайұлы","Ықылас Дүкенұлы"],"a":1,"e":"«Түрмеден қашқан» — Құрманғазы Сағырбайұлының күйі. Оның шығармаларында күрес пен еркіндік тақырыбы көрініс тапты.","l":"A","topic":"XIX ғасырдағы музыка","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":146}},{"id":"hm-104","t":"Оқиғалардың дұрыс ретін табыңыз: 1 — Семейдегі алғашқы ядролық сынақ; 2 — Мәскеу үшін шайқас; 3 — Ғылым академиясының құрылуы; 4 — карточкалық жүйенің жойылуы; 5 — тың игерудің басталуы.","o":["2–4–3–1–5","2–3–4–1–5","3–2–1–4–5","2–3–1–5–4"],"a":1,"e":"Мәскеу шайқасы — 1941, академия — 1946, карточкалық жүйенің жойылуы — 1947, алғашқы сынақ — 1949, тың игеру — 1954 жыл.","l":"C","topic":"Хронология","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"hk-035","t":"1595 жылы Тәуекел ханға келген орыс елшісі кім?","o":["Вельямин Степанов","Иван Лихарев","Василий Радлов","Алексей Левшин"],"a":0,"e":"Вельямин Степановтың келуі XVI ғасырдың соңындағы өзара елшілік байланыстарға жатады.","l":"A","topic":"Тәуекел ханның елшілігі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":102}}],"contexts":[{"id":"hce-31","title":"Құтты білік: ұсынылған басқару үлгісі","text":"Жүсіп Баласағұни XI ғасырда «Құтты білік» еңбегін жазды. Түркі тіліндегі шығармада әділет, парасат және басқару мәселелері көркем түрде талқыланады. Еңбек билеушіге кеңес беру дәстүрімен байланысты. Ол қоғамдағы құндылықтар мен мінсіз басқару туралы түсінікті көрсетеді. Бірақ автор ұсынған үлгіні барлық билеуші дәл орындады деп санауға болмайды. Нормативтік ой мен күнделікті тәжірибені ажырату қажет. Әдеби туынды тарихи ақпарат бере алады. Оны пайдаланғанда жанр, мақсат және орта ескеріледі. Көркемдік тәсіл деректің маңызын жоймайды, бірақ талдау әдісіне әсер етеді. Бір кеңестің мәтінде берілуі оның міндетті заң болғанын дәлелдемейді.","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":100},"questions":[{"id":"hce-31-1","t":"«Құтты білік: ұсынылған басқару үлгісі» контексі: Құтты білік авторы кім?","o":["Махмұд Қашқари","Қадырғали Жалайыри","Мұхаммед Хайдар Дулати","Жүсіп Баласағұни"],"a":3,"e":"Мәтіндегі деректер «Жүсіп Баласағұни» деген жауапты негіздейді. Шығарма әділет пен басқару туралы ойды жеткізеді.","l":"A","topic":"Құтты білік: ұсынылған басқару үлгісі"},{"id":"hce-31-2","t":"«Құтты білік: ұсынылған басқару үлгісі» контексі: Еңбек қай ғасырда жазылды?","o":["VI ғасыр","XI ғасыр","XVIII ғасыр","XV ғасыр"],"a":1,"e":"Мәтіндегі деректер «XI ғасыр» деген жауапты негіздейді. Шығарма әділет пен басқару туралы ойды жеткізеді.","l":"A","topic":"Құтты білік: ұсынылған басқару үлгісі"},{"id":"hce-31-3","t":"«Құтты білік: ұсынылған басқару үлгісі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Көркем мәтін еш тарихи мәлімет бермейді","Шығармадағы барлық кеңесті барлық хан толық орындаған","Шығарма әділет пен басқару туралы ойды жеткізеді","Еңбек тек салық жинау тізімі болған"],"a":2,"e":"Мәтіндегі деректер «Шығарма әділет пен басқару туралы ойды жеткізеді» деген жауапты негіздейді. Шығарма әділет пен басқару туралы ойды жеткізеді.","l":"B","topic":"Құтты білік: ұсынылған басқару үлгісі"},{"id":"hce-31-4","t":"«Құтты білік: ұсынылған басқару үлгісі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Жанр тарихи талдауға еш әсер етпейді","Ұсынылған басқару үлгісін нақты тәжірибемен теңестірмеу керек","Шығарма тілін білу оның барлық мазмұнын түсіндіреді","Автор ұсынған әр ой міндетті түрде орындалған заң болған"],"a":1,"e":"Мәтіндегі деректер «Ұсынылған басқару үлгісін нақты тәжірибемен теңестірмеу керек» деген жауапты негіздейді. Шығарма әділет пен басқару туралы ойды жеткізеді.","l":"B","topic":"Құтты білік: ұсынылған басқару үлгісі"},{"id":"hce-31-5","t":"«Құтты білік: ұсынылған басқару үлгісі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Жүсіп Баласағұни XI ғасырда «Құтты білік» еңбегін жазды.","Шығармадағы барлық кеңесті барлық хан толық орындаған","Ұсынылған басқару үлгісін нақты тәжірибемен теңестірмеу керек","Шығарма әділет пен басқару туралы ойды жеткізеді"],"a":1,"e":"Мәтіндегі деректер «Шығармадағы барлық кеңесті барлық хан толық орындаған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Ұсынылған басқару үлгісін нақты тәжірибемен теңестірмеу керек.","l":"C","topic":"Құтты білік: ұсынылған басқару үлгісі"}]},{"id":"hcl-31","title":"Соғыстан кейінгі шаруашылық","text":"Соғыс аяқталған соң халық бейбіт өмірге оралып, шаруашылықты қалпына келтіре бастады. Алайда өндірісті қайта құру мен ауыл шаруашылығындағы қиындықтар тұрмысқа әсер етті.\n\nАзық-түлік пен тауар бөлудің карточкалық жүйесі 1947 жылы жойылды. Басты міндет соғыс зардабын жойып, өндіріс пен халық тұрмысын қалпына келтіру болды. Қазақстанда тау-кен өндірісі мен металлургияның маңызы арта түсті. Ауылда еңбек күші мен техника тапшылығы және өндірістік қиындықтар сақталды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7},"questions":[{"id":"hcl-31-1","t":"«Соғыстан кейінгі шаруашылық» контексі: КСРО-да карточкалық жүйе қай жылы жойылды?","o":["1947 жылы","1936 жылы","1921 жылы","1965 жылы"],"a":0,"e":"Азық-түлік пен тауар бөлудің карточкалық жүйесі 1947 жылы жойылды.","l":"A","topic":"Соғыстан кейінгі шаруашылық"},{"id":"hcl-31-2","t":"«Соғыстан кейінгі шаруашылық» контексі: Соғыстан кейінгі экономиканың негізгі міндеті қандай болды?","o":["Алғашқы адамдарды қоныстандыру","Жоңғар шапқыншылығын тоқтату","Бейбіт шаруашылықты қалпына келтіру","Хандық билікті қалпына келтіру"],"a":2,"e":"Басты міндет соғыс зардабын жойып, өндіріс пен халық тұрмысын қалпына келтіру болды.","l":"A","topic":"Соғыстан кейінгі шаруашылық"},{"id":"hcl-31-3","t":"«Соғыстан кейінгі шаруашылық» контексі: Екі деректі сәйкестендіріңіз. 1) КСРО-да карточкалық жүйе қай жылы жойылды. 2) Ауыр өнеркәсіпте басым болған салалардың бірі қайсы.","o":["1 — 1947 жылы; 2 — Ғарыш туризмі","1 — 1921 жылы; 2 — Тау-кен және металлургия","1 — 1947 жылы; 2 — Тау-кен және металлургия","1 — 1936 жылы; 2 — Тек қағазсыз сауда"],"a":2,"e":"Азық-түлік пен тауар бөлудің карточкалық жүйесі 1947 жылы жойылды. Қазақстанда тау-кен өндірісі мен металлургияның маңызы арта түсті.","l":"B","topic":"Соғыстан кейінгі шаруашылық"},{"id":"hcl-31-4","t":"«Соғыстан кейінгі шаруашылық» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Соғыстан кейінгі экономиканың негізгі міндеті қандай болды? 2) Ауыл шаруашылығының жағдайын қай тұжырым сипаттайды?","o":["1 — Хандық билікті қалпына келтіру; 2 — Мал шаруашылығы толық тоқтады","1 — Жоңғар шапқыншылығын тоқтату; 2 — Еңбек пен техника тапшылығы сақталды","1 — Бейбіт шаруашылықты қалпына келтіру; 2 — Барлық қиындық бірден жойылды","1 — Бейбіт шаруашылықты қалпына келтіру; 2 — Еңбек пен техника тапшылығы сақталды"],"a":3,"e":"Басты міндет соғыс зардабын жойып, өндіріс пен халық тұрмысын қалпына келтіру болды. Ауылда еңбек күші мен техника тапшылығы және өндірістік қиындықтар сақталды.","l":"B","topic":"Соғыстан кейінгі шаруашылық"},{"id":"hcl-31-5","t":"«Соғыстан кейінгі шаруашылық» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Бейбіт өмірге көшу маңызды өзгерістер әкелгенімен, шаруашылықтың барлық мәселесі бірден шешілген жоқ.","Ауыр өнеркәсіптің дамуы соғыстан кейінгі қалпына келтіру тек ауылдық жерлерде жүргенін көрсетеді.","Карточкалық жүйенің жойылуы ауыл шаруашылығындағы еңбек пен техника тапшылығы да сол сәтте шешілгенін дәлелдейді.","Бейбіт шаруашылыққа көшу бұрынғы өндірістік байланыстарды қалпына келтіру қажеттігін жойды."],"a":0,"e":"Бейбіт өмірге көшу маңызды өзгерістер әкелгенімен, шаруашылықтың барлық мәселесі бірден шешілген жоқ. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Соғыстан кейінгі шаруашылық"}]}]},{"number":32,"questions":[{"id":"hk-074","t":"Қасым мен Есімнің құқықтық дәстүрлерін кейінгі кезеңде жалғастырған жинақ қайсы?","o":["«Кодекс Куманикус»","«Жеті жарғы»","«Тарих-и Рашиди»","«Құтты білік»"],"a":1,"e":"Тәуке хан тұсындағы «Жеті жарғы» бұрынғы әдет-ғұрып құқығының тәжірибесіне сүйенді.","l":"B","topic":"Дәстүрлі құқық сабақтастығы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":83}},{"id":"hi-117","t":"Торғай мен Жетісу көтерілістерін бір қозғалыс аясында қарастыруға қандай белгі негіз болады?","o":["Екеуін де Кенесарының басқаруы","Екеуінің де тек жәрмеңке ашуды көздеуі","Екеуінің де 1838 жылы аяқталуы","Екеуінің де 1916 жылғы отаршылдыққа қарсы жалпыұлттық қарсылықтың бөлігі болуы"],"a":3,"e":"Өңірлік ерекшеліктеріне қарамастан, екі орталық та 1916 жылғы ортақ отарлық қысымға қарсы шықты.","l":"C","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hk-020","t":"«Қасым ханның қасқа жолы» дәстүрлі түрде неше негізгі бөлімнен тұрады деп оқытылады?","o":["Екі","Сегіз","Бес","Он екі"],"a":2,"e":"Бұл құқықтық жүйе мүлік, қылмыс, әскери, елшілік және жұртшылық мәселелерін қамтитын бес бөліммен сипатталады.","l":"A","topic":"Қасым ханның заңдары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8}},{"id":"hi-096","t":"Мұстафа Шоқай мен Мұхамеджан Тынышбайұлының қызметі қай автономиямен байланысты?","o":["Түркістан автономиясымен","Сібір автономиясымен","Еділ немістері автономиясымен","Бурят автономиясымен"],"a":0,"e":"Екі қайраткер де 1917 жылы Қоқанда жарияланған Түркістан автономиясының жетекшілері болды.","l":"A","topic":"Түркістан автономиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":229}},{"id":"hm-007","t":"ЖЭС кезінде азық-түлік салғыртының орнына не енгізілді?","o":["Барлық егінді тартып алу","Азық-түлік салығы","Жалпыға бірдей тәркілеу","Тегін еңбек міндеткерлігі"],"a":1,"e":"Салғырттың салықпен алмастырылуы шаруаның өнімнің қалған бөлігін пайдалануына жол ашты.","l":"A","topic":"ЖЭС","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":257}},{"id":"ha-051","t":"756 жылы Жетісуда Түргеш қағанатының орнына келген бірлестік қайсы?","o":["Қимақ қағанаты","Ноғай Ордасы","Қарлұқ мемлекеті","Оғыз мемлекеті"],"a":2,"e":"VIII ғасырдың ортасында Жетісуда саяси үстемдік қарлұқтарға өтті.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":11}},{"id":"ha-121","t":"Кезеңдерді салыстырған қай тұжырымдар дұрыс? I. Сақ қорымдары — ерте темір дәуірі. II. Орхон түркі жазбалары — ерте орта ғасыр. III. Ботай — Қарахан дәуірі.","o":["II және III","Тек III","I және II","I және III"],"a":2,"e":"Сақ қорымдары ерте темір дәуірін, Орхон ескерткіштері ерте ортағасырлық түркілерді сипаттайды; Ботай энеолитке жатады.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":22}},{"id":"hm-089","t":"«Невада–Семей» қозғалысының азаматтық қоғамға ықпалын көрсетіңіз.","o":["Азық-түлік салғыртын енгізді","Қоғамның ортақ экологиялық талаппен ұйымдасуын көрсетті","Жеке саудаға тыйым салды","Жаңа хан әулетін сайлады"],"a":1,"e":"Қозғалыс азаматтардың қоғамдық мәселені шешуге бірігіп қатысуының көрінісі болды.","l":"B","topic":"Қайта құру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":285}},{"id":"hi-009","t":"Исатай Тайманұлы мен Махамбет Өтемісұлы басқарған көтерілістің жылдарын анықтаңыз.","o":["1868–1869 жылдар","1837–1847 жылдар","1836–1838 жылдар","1822–1824 жылдар"],"a":2,"e":"Бөкей Ордасындағы Исатай мен Махамбет көтерілісі 1836–1838 жылдары өтті.","l":"A","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":183}},{"id":"hm-011","t":"Бай шаруашылықтарын тәркілеу науқаны басталған жылды көрсетіңіз.","o":["1921 жыл","1928 жыл","1937 жыл","1946 жыл"],"a":1,"e":"1928 жылғы тәркілеу ірі мал иелерінің шаруашылықтарын тартып алуды көздеді.","l":"A","topic":"Ұжымдастыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":265}}],"contexts":[{"id":"hce-32","title":"Махмұд Қашқари: тіл тарихи дерек ретінде","text":"Махмұд Қашқари XI ғасырда «Диуани лұғат ат-түрік» еңбегін құрастырды. Онда түркі тілдеріне қатысты сөздер, мақалдар және мәдени мәліметтер берілген. Сөздік тіл тарихымен бірге тұрмыс пен дүниетанымды зерттеуге де маңызды. Автор сөзді түсіндіру арқылы сол дәуірдегі ұғымды жеткізеді. Бір сөздің кездесуі оның барлық тайпада бірдей қолданылғанын білдірмейді. Тілдік айырмашылық пен автор қамтыған ортаны ескеру қажет. Сөздік мәліметті басқа тарихи дерекпен салыстыру кеңірек түсінік береді. Тіл қоғам тарихын танытатын дерек бола алады. Бір терминнің мағынасын қазіргі қолданысымен ғана шектеу ортағасырлық мазмұнды тарылтады.","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":89},"questions":[{"id":"hce-32-1","t":"«Махмұд Қашқари: тіл тарихи дерек ретінде» контексі: Диуани лұғат ат-түрік авторы кім?","o":["Махмұд Қашқари","Әл-Фараби","Рашид ад-Дин","Ахмет Йүгнеки"],"a":0,"e":"Мәтіндегі деректер «Махмұд Қашқари» деген жауапты негіздейді. Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді.","l":"A","topic":"Махмұд Қашқари: тіл тарихи дерек ретінде"},{"id":"hce-32-2","t":"«Махмұд Қашқари: тіл тарихи дерек ретінде» контексі: Еңбектің негізгі сипаты қандай?","o":["Түркі тілдерінің сөздігі","Хан жарлықтары тізімі","Теңге сарайы есебі","Әскери шекара картасы"],"a":0,"e":"Мәтіндегі деректер «Түркі тілдерінің сөздігі» деген жауапты негіздейді. Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді.","l":"A","topic":"Махмұд Қашқари: тіл тарихи дерек ретінде"},{"id":"hce-32-3","t":"«Махмұд Қашқари: тіл тарихи дерек ретінде» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Сөздіктегі әр сөз барлық тайпада бірдей қолданылған","Еңбек тек бір билеушінің өмірбаяны болған","Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді","Тілдік дерек қоғам тарихына қатыссыз"],"a":2,"e":"Мәтіндегі деректер «Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді» деген жауапты негіздейді. Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді.","l":"B","topic":"Махмұд Қашқари: тіл тарихи дерек ретінде"},{"id":"hce-32-4","t":"«Махмұд Қашқари: тіл тарихи дерек ретінде» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Сөздің таралу аясын басқа дерекпен салыстырып зерттеу қажет","Бір сөз саяси шекараны өзгеріссіз анықтайды","Тілдік айырма тарихи байланыс болмағанын міндетті дәлелдейді","Автор қамтыған орта талдауға қажет емес"],"a":0,"e":"Мәтіндегі деректер «Сөздің таралу аясын басқа дерекпен салыстырып зерттеу қажет» деген жауапты негіздейді. Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді.","l":"B","topic":"Махмұд Қашқари: тіл тарихи дерек ретінде"},{"id":"hce-32-5","t":"«Махмұд Қашқари: тіл тарихи дерек ретінде» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Махмұд Қашқари XI ғасырда «Диуани лұғат ат-түрік» еңбегін құрастырды.","Сөздіктегі әр сөз барлық тайпада бірдей қолданылған","Сөздің таралу аясын басқа дерекпен салыстырып зерттеу қажет","Сөздік тұрмыс пен дүниетаным туралы да мәлімет береді"],"a":1,"e":"Мәтіндегі деректер «Сөздіктегі әр сөз барлық тайпада бірдей қолданылған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сөздің таралу аясын басқа дерекпен салыстырып зерттеу қажет.","l":"C","topic":"Махмұд Қашқари: тіл тарихи дерек ретінде"}]},{"id":"hcl-32","title":"Ермұхан Бекмаханов ісі","text":"Соғыстан кейін ғылым мен мәдениетке идеологиялық бақылау күшейді. Тарихты зерттеу кейде ғылыми пікірталастан шығып, саяси айыптаулардың нысанына айналды.\n\nТарихшы Ермұхан Бекмаханов соғыстан кейінгі кезеңде саяси қудалауға ұшырады. Оның зерттеулерінде XIX ғасырдағы Кенесары Қасымұлы қозғалысы қарастырылды. Бекмахановқа тарихты «ұлтшылдық» тұрғыда түсіндіреді деген саяси айып тағылды. Бекмаханов ісі ғылыми зерттеулерге саяси-идеологиялық қысымның болғанын көрсетті. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8},"questions":[{"id":"hcl-32-1","t":"«Ермұхан Бекмаханов ісі» контексі: 1940–1950 жылдары саяси қудалауға ұшыраған тарихшы кім?","o":["Қаныш Сәтбаев","Мұхамеджан Тынышпаев","Әлкей Марғұлан","Ермұхан Бекмаханов"],"a":3,"e":"Тарихшы Ермұхан Бекмаханов соғыстан кейінгі кезеңде саяси қудалауға ұшырады.","l":"A","topic":"Ермұхан Бекмаханов ісі"},{"id":"hcl-32-2","t":"«Ермұхан Бекмаханов ісі» контексі: Бекмаханов зерттеген қозғалыс басшысы кім?","o":["Сұлу қаған","Кенесары Қасымұлы","Томирис","Бумын қаған"],"a":1,"e":"Оның зерттеулерінде XIX ғасырдағы Кенесары Қасымұлы қозғалысы қарастырылды.","l":"A","topic":"Ермұхан Бекмаханов ісі"},{"id":"hcl-32-3","t":"«Ермұхан Бекмаханов ісі» контексі: Екі деректі сәйкестендіріңіз. 1) 1940–1950 жылдары саяси қудалауға ұшыраған тарихшы кім. 2) Ғалымға тағылған саяси айып қандай сипатта болды.","o":["1 — Қаныш Сәтбаев; 2 — «Ұлтшылдық» туралы","1 — Ермұхан Бекмаханов; 2 — «Ұлтшылдық» туралы","1 — Ермұхан Бекмаханов; 2 — Теңіз қарақшылығы туралы","1 — Әлкей Марғұлан; 2 — Шетел патшасы болу туралы"],"a":1,"e":"Тарихшы Ермұхан Бекмаханов соғыстан кейінгі кезеңде саяси қудалауға ұшырады. Бекмахановқа тарихты «ұлтшылдық» тұрғыда түсіндіреді деген саяси айып тағылды.","l":"B","topic":"Ермұхан Бекмаханов ісі"},{"id":"hcl-32-4","t":"«Ермұхан Бекмаханов ісі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Бекмаханов зерттеген қозғалыс басшысы кім? 2) Бұл іс қандай құбылысты көрсетеді?","o":["1 — Сұлу қаған; 2 — Цензураның жойылғанын","1 — Кенесары Қасымұлы; 2 — Ғылыми еркіндіктің шексіздігін","1 — Кенесары Қасымұлы; 2 — Ғылымға идеологиялық қысымды","1 — Томирис; 2 — Ғылымға идеологиялық қысымды"],"a":2,"e":"Оның зерттеулерінде XIX ғасырдағы Кенесары Қасымұлы қозғалысы қарастырылды. Бекмаханов ісі ғылыми зерттеулерге саяси-идеологиялық қысымның болғанын көрсетті.","l":"B","topic":"Ермұхан Бекмаханов ісі"},{"id":"hcl-32-5","t":"«Ермұхан Бекмаханов ісі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Кенесары қозғалысын зерттеу саяси бақылаудың тек ежелгі тарихқа бағытталғанын көрсетеді.","Тарихшыға саяси айып тағылуы оның зерттеуіндегі барлық тұжырымның деректік тұрғыдан терістелгенін дәлелдейді.","Тарихи зерттеуге саяси айып тағу ғылыми тұжырымның дәлелін идеологиялық талаппен алмастыру қаупін көрсетеді.","Зерттеуді идеологиялық бағалау ғылыми пікірталас еркіндігін шектемей, оны толық қамтамасыз етті."],"a":2,"e":"Тарихи зерттеуге саяси айып тағу ғылыми тұжырымның дәлелін идеологиялық талаппен алмастыру қаупін көрсетеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Ермұхан Бекмаханов ісі"}]}]},{"number":33,"questions":[{"id":"hk-026","t":"1538–1580 жылдары Қазақ хандығын басқарған хан кім?","o":["Хақназар","Шығай","Есім","Тәуке"],"a":0,"e":"Хақназар хан ұзақ билік құрып, хандықтың әлсіреген саяси жағдайын қалпына келтіруге ұмтылды.","l":"A","topic":"Хақназар хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":125}},{"id":"ha-047","t":"Түргеш қағанаты өмір сүрген кезеңді көрсетіңіз.","o":["704–756 жылдар","552–603 жылдар","1128–1213 жылдар","942–1212 жылдар"],"a":0,"e":"Түргеш қағанаты VIII ғасырдың бірінші жартысында Жетісуда өмір сүрді.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"ha-091","t":"Әмір Темір мен Тоқтамыс 1391 және 1395 жылдары соғысты. Терек шайқасын дұрыс ажыратқан жауапты табыңыз.","o":["1391 жылы өтіп, Түргеш қағанатын жойды","1395 жылы өтіп, Тоқтамыстың жеңілісімен аяқталды","1395 жылы өтіп, Моғолстанның құрылуына әкелді","1391 жылы өтіп, Тоқтамыстың жеңісімен аяқталды"],"a":1,"e":"1391 жылы Құндызша, 1395 жылы Терек шайқасы болды; екі жорық та Тоқтамысқа ауыр соққы берді.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"hi-078","t":"1867–1868 жылғы бөліністе Ақмола мен Семей облыстары қай генерал-губернаторлыққа қарады?","o":["Кавказ","Батыс Сібір","Түркістан","Орынбор"],"a":1,"e":"Ақмола мен Семей облыстары Батыс Сібір генерал-губернаторлығының құрамында болды.","l":"B","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":150}},{"id":"hk-050","t":"«Жеті жарғыны» жасауға қатысқан үш биді атаңыз.","o":["Қасым, Хақназар, Тәуекел","Керей, Жәнібек, Бұрындық","Төле, Қазыбек, Әйтеке","Асан Қайғы, Бұқар, Үмбетей"],"a":2,"e":"Төле, Қазыбек және Әйтеке билер Тәуке хан дәуіріндегі құқықтық және саяси кеңестің көрнекті өкілдері болды.","l":"A","topic":"Тәуке ханның заңдары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":109}},{"id":"hk-103","t":"Оқиғалардың дұрыс хронологиялық тізбегін анықтаңыз.","o":["Аңырақай шайқасы → Қарақұм құрылтайы → Бұланты жеңісі","Қарақұм құрылтайы → Аңырақай шайқасы → Бұланты жеңісі","Қарақұм құрылтайы → Бұланты жеңісі → Аңырақай шайқасы","Бұланты жеңісі → Аңырақай шайқасы → Қарақұм құрылтайы"],"a":2,"e":"Қарақұм құрылтайы 1710 жылы өтті; Бұлантыдағы жеңіс 1720-жылдардың екінші жартысына, Аңырақай одан кейінгі кезеңге жатады.","l":"C","topic":"Қазақ-жоңғар соғыстарының хронологиясы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hm-125","t":"Кеңестік Қазақстан туралы екі зерттеу қорытындысы берілген: А — «Кәсіпорындар мен жоғары оқу орындары көбейді»; Ә — «Ашаршылық пен қуғын-сүргін халыққа ауыр зардап әкелді». Екеуін қатар ескергенде қандай қорытынды дұрыс?","o":["Экономикалық-мәдени жаңғырту адам шығыны мен саяси қысыммен қатар жүрді, сондықтан нәтижені әр өлшеммен бағалау қажет","Екі қорытынды бір кезеңге қатысты бола алмайды, сондықтан біреуін міндетті түрде алып тастау керек","Өнеркәсіп дамығандықтан, ашаршылық туралы деректерді зерттеудің қажеті жоқ","Қуғын-сүргін болғандықтан, оқу орындарының ашылуы туралы барлық дерек жалған"],"a":0,"e":"Экономикалық және мәдени өзгерістер саяси-әлеуметтік қасіреттерді жоққа шығармайды. Кезеңді бағалау жетістіктер мен адам тағдырына келген зардаптарды бірге қарастыруды талап етеді.","l":"C","topic":"Тарихи талдау","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-024","t":"XIX ғасырдың ортасында Кіші жүзде отаршылдыққа қарсы қозғалысты басқарған Көтібарұлы кім?","o":["Бекет","Ағыбай","Бекболат","Есет"],"a":3,"e":"Есет Көтібарұлы Кіші жүздегі ұлт-азаттық қозғалыс басшыларының бірі болды.","l":"A","topic":"Жанқожа және Есет көтерілістері","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":156}},{"id":"hm-039","t":"Семей ядролық полигонындағы алғашқы сынақ қай жылы жасалды?","o":["1961 жылы","1936 жылы","1989 жылы","1949 жылы"],"a":3,"e":"Полигондағы алғашқы ядролық жарылыс 1949 жылы болды.","l":"A","topic":"Ядролық полигон","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"ha-074","t":"Әбілқайыр хандығы деректерде тағы қалай аталды?","o":["Қимақ қағанаты","Көшпелі өзбектер мемлекеті","Қарақытай мемлекеті","Батыс Түрік қағанаты"],"a":1,"e":"Шығыс Дешті Қыпшақтағы Әбілқайыр билеген бірлестік Көшпелі өзбектер мемлекеті деген атаумен белгілі.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}}],"contexts":[{"id":"hce-33","title":"Ясауи мұрасы және кейінгі кесене","text":"Қожа Ахмет Ясауи сопылық дәстүрдің көрнекті өкілі болды. Оның есімі «Диуани хикмет» мұрасымен байланысты. Түркі тіліндегі діни-өнегелік өлеңдер рухани түсініктерді кең ортаға жеткізді. Ясы қаласы кейін Түркістан атауымен белгілі болды. XIV ғасырдың соңында Әмір Темірдің бұйрығымен үлкен кесене салынды. Ойшылдың өмірі мен белгілі кесененің салынған уақытын ажырату қажет. Бір тұлғаның мұрасы кейінгі ғасырларда жаңа сәулеттік мағына ала алады. Жазба мұра, діни дәстүр және сәулет тарихи жадтың әртүрлі қырын көрсетеді. Кейінгі құрылыстың мерзімі тұлғаның туған жылын өздігінен анықтамайды.","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":87},"questions":[{"id":"hce-33-1","t":"«Ясауи мұрасы және кейінгі кесене» контексі: Ясауиге қатысты мұра қайсы?","o":["Жами ат-тауарих","Құтты білік","Диуани хикмет","Тарих-и Рашиди"],"a":2,"e":"Мәтіндегі деректер «Диуани хикмет» деген жауапты негіздейді. Ясы кейін Түркістан атауымен белгілі болды.","l":"A","topic":"Ясауи мұрасы және кейінгі кесене"},{"id":"hce-33-2","t":"«Ясауи мұрасы және кейінгі кесене» контексі: Кесене құрылысын бұйырған кім?","o":["Әмір Темір","Қасым хан","Мөде","Сұлу қаған"],"a":0,"e":"Мәтіндегі деректер «Әмір Темір» деген жауапты негіздейді. Ясы кейін Түркістан атауымен белгілі болды.","l":"A","topic":"Ясауи мұрасы және кейінгі кесене"},{"id":"hce-33-3","t":"«Ясауи мұрасы және кейінгі кесене» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Кесененің салынған жылы ойшылдың туған жылын анықтайды","Хикметтер тек әскери есептен тұрған","Ойшыл мен үлкен кесене міндетті түрде бір дәуірде пайда болған","Ясы кейін Түркістан атауымен белгілі болды"],"a":3,"e":"Мәтіндегі деректер «Ясы кейін Түркістан атауымен белгілі болды» деген жауапты негіздейді. Ясы кейін Түркістан атауымен белгілі болды.","l":"B","topic":"Ясауи мұрасы және кейінгі кесене"},{"id":"hce-33-4","t":"«Ясауи мұрасы және кейінгі кесене» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір ескерткіштің мерзімі қаланың барлық тарихын анықтайды","Кейінгі сәулет мұрасы бұрынғы тұлғамен байланыса алмайды","Түркі тіліндегі өлеңдер рухани түсінік таратпаған","Тұлғаның өмірі мен кейінгі ескерткіш уақытын ажырату керек"],"a":3,"e":"Мәтіндегі деректер «Тұлғаның өмірі мен кейінгі ескерткіш уақытын ажырату керек» деген жауапты негіздейді. Ясы кейін Түркістан атауымен белгілі болды.","l":"B","topic":"Ясауи мұрасы және кейінгі кесене"},{"id":"hce-33-5","t":"«Ясауи мұрасы және кейінгі кесене» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Қожа Ахмет Ясауи сопылық дәстүрдің көрнекті өкілі болды.","Тұлғаның өмірі мен кейінгі ескерткіш уақытын ажырату керек","Ясы кейін Түркістан атауымен белгілі болды","Ойшыл мен үлкен кесене міндетті түрде бір дәуірде пайда болған"],"a":3,"e":"Мәтіндегі деректер «Ойшыл мен үлкен кесене міндетті түрде бір дәуірде пайда болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Тұлғаның өмірі мен кейінгі ескерткіш уақытын ажырату керек.","l":"C","topic":"Ясауи мұрасы және кейінгі кесене"}]},{"id":"hcl-33","title":"Тың және тыңайған жерлерді игеру","text":"Астық өндіруді тез ұлғайту мақсатымен кең көлемді жер жырту науқаны басталды. Бұл саясат қысқа мерзімде егістік көлемін арттырғанымен, табиғат пен халық құрамына да ықпал етті.\n\nТың және тыңайған жерлерді игеру науқаны 1954 жылы басталды. Егістік негізінен Солтүстік Қазақстанның далалық облыстарында кеңейтілді. Кең алқапты жырту мен жел әсерінен топырақ эрозиясы күшейді. Тың игеру Қазақстанға басқа республикалардан көптеген адамның келуіне әкелді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7},"questions":[{"id":"hcl-33-1","t":"«Тың және тыңайған жерлерді игеру» контексі: Тың игеру қай жылы басталды?","o":["1921 жылы","1937 жылы","1954 жылы","1986 жылы"],"a":2,"e":"Тың және тыңайған жерлерді игеру науқаны 1954 жылы басталды.","l":"A","topic":"Тың және тыңайған жерлерді игеру"},{"id":"hcl-33-2","t":"«Тың және тыңайған жерлерді игеру» контексі: Науқан негізінен Қазақстанның қай бөлігінде жүрді?","o":["Тек Маңғыстауда","Тек Алтайдың биік шыңдарында","Тек Балқаш көлінде","Солтүстік өңірлерінде"],"a":3,"e":"Егістік негізінен Солтүстік Қазақстанның далалық облыстарында кеңейтілді.","l":"A","topic":"Тың және тыңайған жерлерді игеру"},{"id":"hcl-33-3","t":"«Тың және тыңайған жерлерді игеру» контексі: Екі деректі сәйкестендіріңіз. 1) Тың игеру қай жылы басталды. 2) Тың игерудің экологиялық зардаптарының бірі қандай.","o":["1 — 1954 жылы; 2 — Топырақ эрозиясы","1 — 1921 жылы; 2 — Топырақ эрозиясы","1 — 1954 жылы; 2 — Мұхит деңгейінің бірден төмендеуі","1 — 1937 жылы; 2 — Жанартаулардың атқылауы"],"a":0,"e":"Тың және тыңайған жерлерді игеру науқаны 1954 жылы басталды. Кең алқапты жырту мен жел әсерінен топырақ эрозиясы күшейді.","l":"B","topic":"Тың және тыңайған жерлерді игеру"},{"id":"hcl-33-4","t":"«Тың және тыңайған жерлерді игеру» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Науқан негізінен Қазақстанның қай бөлігінде жүрді? 2) Науқан халық құрамына қалай әсер етті?","o":["1 — Солтүстік өңірлерінде; 2 — Сырттан жаппай көші-қонды күшейтті","1 — Тек Балқаш көлінде; 2 — Қалаларды түгел босатты","1 — Тек Маңғыстауда; 2 — Сырттан жаппай көші-қонды күшейтті","1 — Солтүстік өңірлерінде; 2 — Көші-қонды толық тоқтатты"],"a":0,"e":"Егістік негізінен Солтүстік Қазақстанның далалық облыстарында кеңейтілді. Тың игеру Қазақстанға басқа республикалардан көптеген адамның келуіне әкелді.","l":"B","topic":"Тың және тыңайған жерлерді игеру"},{"id":"hcl-33-5","t":"«Тың және тыңайған жерлерді игеру» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Астық көлемінің өсуін бағалағанда экологиялық және демографиялық салдарларды да бірге ескеру қажет.","Көші-қонның күшеюі тың игерудің тек демографиялық жоба болып, шаруашылық мақсаты болмағанын дәлелдейді.","Астық көлемінің артуы топырақ жағдайының ұзақ мерзімді өзгерісін бағалауды қажетсіз етеді.","Егістіктің кеңеюі табиғи ортаның ерекшеліктері өндіріс нәтижесіне әсер етпейтінін көрсетеді."],"a":0,"e":"Астық көлемінің өсуін бағалағанда экологиялық және демографиялық салдарларды да бірге ескеру қажет. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Тың және тыңайған жерлерді игеру"}]}]},{"number":34,"questions":[{"id":"hk-078","t":"1594 жылғы қазақ елшілігі мен 1595 жылғы орыс елшілігі нені дәлелдейді?","o":["Шекаралық мәселелердің түгел шешілгенін","Әскери одақтың барлық шарты орындалғанын","Екі мемлекеттің бір ханға бағынғанын","Екі мемлекет арасында өзара дипломатиялық байланыс болғанын"],"a":3,"e":"Бірінен кейін бірі жіберілген елшіліктер өзара келіссөз бен ресми байланыстардың дамуын көрсетеді.","l":"B","topic":"Тәуекел ханның дипломатиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":105}},{"id":"hi-091","t":"1916 жылғы көтерілістің ірі орталықтары дұрыс көрсетілген қатарды табыңыз.","o":["Қырым және Кавказ","Балтық және Еділ сағасы","Торғай және Жетісу","Алтай және Сахалин"],"a":2,"e":"Торғай мен Жетісу 1916 жылғы ұлт-азаттық қозғалыстың ең ірі орталықтары болды.","l":"A","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":250}},{"id":"hm-072","t":"«Бесеудің хаты» мен Т.Рысқұловтың Сталинге хатына ортақ мәселе қандай?","o":["Тың игерудегі ғарыш техникасы","Ауылдағы аштық пен күштеу саясатының зардаптары","1995 жылғы Конституция жобасы","Жаңа астананың сәулет жоспары"],"a":1,"e":"Екі құжат та ұжымдастыру жылдарындағы апатты жағдайға назар аудартты.","l":"A","topic":"Ашаршылық","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-124","t":"Оқиғаларды реттеңіз: 1) Қазревкомның құрылуы; 2) Ақпан революциясы; 3) Қазақ АКСР-інің құрылуы.","o":["3 → 1 → 2","2 → 3 → 1","2 → 1 → 3","1 → 2 → 3"],"a":2,"e":"Ақпан революциясы 1917 жылы болды. Қазревком 1919 жылы, Қазақ АКСР-і 1920 жылы құрылды.","l":"C","topic":"Қазревком және Қазақ АКСР","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":228}},{"id":"hi-021","t":"1824 жылы құрылған алғашқы сыртқы округтердің бірін көрсетіңіз.","o":["Верный","Көкшетау","Ақмола","Перовск"],"a":1,"e":"Көкшетау сыртқы округі 1824 жылы құрылды. Ол 1822 жылғы жарғыны іске асыру аясында ұйымдастырылды.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":162}},{"id":"ha-105","t":"Мемлекет, орталық және негізгі өзенді дұрыс біріктірген қатарды табыңыз.","o":["Оғыз — Янгикент — Сырдария","Оғыз — Суяб — Ертіс","Қимақ — Янгикент — Жайық","Қимақ — Алмалық — Сырдария"],"a":0,"e":"Оғыз мемлекетінің орталығы Янгикент Сырдарияның төменгі ағысында орналасқан; қимақтар Ертіс бойын мекендеген.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":22}},{"id":"hm-047","t":"1959 жылы жұмысшылар толқуы болған қаланы атаңыз.","o":["Тараз","Ақтау","Теміртау","Семей"],"a":2,"e":"1959 жылғы Теміртау оқиғалары өндіріс құрылысы кезіндегі әлеуметтік қиындықтармен байланысты болды.","l":"A","topic":"Кеңестік қоғам","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":11}},{"id":"hm-092","t":"Теңгенің енгізілуі экономикалық егемендікке қалай ықпал етті?","o":["Тек әкімшілік облыстарды құрды","Барлық мемлекеттік рәмізді ауыстырды","Дербес ақша-несие саясатын жүргізуге мүмкіндік берді","Қазақстанды ақша қолданудан бас тартқызды"],"a":2,"e":"Ұлттық валюта өз ақша айналымы мен қаржы саясатын ұйымдастыруға жағдай жасады.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"ha-034","t":"Қаңлы тайпаларының негізгі қоныстанған аймағы қайсы?","o":["Сырдарияның орта ағысы","Ертістің жоғарғы ағысы","Есілдің сол жағалауы","Еділдің төменгі ағысы"],"a":0,"e":"Қаңлылардың негізгі саяси және шаруашылық орталықтары Сырдарияның орта ағысымен байланысты.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hk-090","t":"Абылай сыртқы саясатында ескерген екі ірі көршіні көрсетіңіз.","o":["Бұхар хандығы мен Хиуа хандығы","Ресей мен Цин империясы","Ноғай Ордасы мен Моғолстан","Қырым хандығы мен Осман империясы"],"a":1,"e":"XVIII ғасырдағы қазақ даласына Ресей мен Цин империясының ықпалы күшейді; Абылай екеуімен де дипломатиялық қатынас ұстады.","l":"A","topic":"Абылай ханның саясаты","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}}],"contexts":[{"id":"hce-34","title":"Моңғол империясы: ұлыс және әулет","text":"1206 жылы Темүжін Шыңғыс хан атанып, моңғол тайпаларының біріккен билеушісі болды. Кейін кең аумақты империя қалыптасты. Жаулап алынған жерлер әулет мүшелеріне ұлыстар ретінде бөлінді. Қазақстан аумағының бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді. Ұлыс әулеттік билік пен аумақты басқаруды байланыстырды. Ортағасырлық иелікті қазіргі мемлекеттік шекарамен толық теңестіруге болмайды. Кейін ұлыстардың қатынасы өзгеріп, дербес құрылымдар пайда болды. Бастапқы ортақ империя олардың кейінгі тарихының түгел бірдей болғанын білдірмейді. Билік орталығы мен саяси мүдде уақыт өте өзгерді. Хронология осы айырмашылықты түсінуге көмектеседі.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8},"questions":[{"id":"hce-34-1","t":"«Моңғол империясы: ұлыс және әулет» контексі: 1206 жылы Темүжін қандай атақ алды?","o":["Күнби","Шаньюй","Шыңғыс хан","Жабғу"],"a":2,"e":"Мәтіндегі деректер «Шыңғыс хан» деген жауапты негіздейді. Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді.","l":"A","topic":"Моңғол империясы: ұлыс және әулет"},{"id":"hce-34-2","t":"«Моңғол империясы: ұлыс және әулет» контексі: Әулеттік аумақтық иелік қалай аталды?","o":["Ұлыс","Шахристан","Рабад","Медресе"],"a":0,"e":"Мәтіндегі деректер «Ұлыс» деген жауапты негіздейді. Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді.","l":"A","topic":"Моңғол империясы: ұлыс және әулет"},{"id":"hce-34-3","t":"«Моңғол империясы: ұлыс және әулет» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Ұлыс тек қаладағы базардың атауы болған","Ұлыс шекарасы қазіргі мемлекет шекарасымен толық бірдей болған","Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді","Ұлыстардың кейінгі тарихы түгел бірдей жүрген"],"a":2,"e":"Мәтіндегі деректер «Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді» деген жауапты негіздейді. Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді.","l":"B","topic":"Моңғол империясы: ұлыс және әулет"},{"id":"hce-34-4","t":"«Моңғол империясы: ұлыс және әулет» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Жаңа саяси орталықтар бұрынғы ұлыстардан қалыптаса алмайды","Бір империя құрамында болу кейінгі барлық мүддені бірдей етеді","Әулет мүшесінің есімі нақты қазіргі шекараны анықтайды","Ұлыстық жүйе әулеттік құқық пен аумақтық басқаруды ұштастырды"],"a":3,"e":"Мәтіндегі деректер «Ұлыстық жүйе әулеттік құқық пен аумақтық басқаруды ұштастырды» деген жауапты негіздейді. Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді.","l":"B","topic":"Моңғол империясы: ұлыс және әулет"},{"id":"hce-34-5","t":"«Моңғол империясы: ұлыс және әулет» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Ұлыс шекарасы қазіргі мемлекет шекарасымен толық бірдей болған","1206 жылы Темүжін Шыңғыс хан атанып, моңғол тайпаларының біріккен билеушісі болды.","Қазақстан бөліктері Жошы, Шағатай және Үгедей ұлыстарына кірді","Ұлыстық жүйе әулеттік құқық пен аумақтық басқаруды ұштастырды"],"a":0,"e":"Мәтіндегі деректер «Ұлыс шекарасы қазіргі мемлекет шекарасымен толық бірдей болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Ұлыстық жүйе әулеттік құқық пен аумақтық басқаруды ұштастырды.","l":"C","topic":"Моңғол империясы: ұлыс және әулет"}]},{"id":"hcl-34","title":"Жылымық кезеңі","text":"Сталин қайтыс болғаннан кейін қоғамдық өмірде белгілі өзгерістер байқалды. Саяси қысымды жұмсарту әрекеттері жүргізілгенімен, бірпартиялық жүйе мен идеологиялық шектеулер сақталды.\n\n1956 жылғы КОКП XX съезінде Сталиннің жеке басына табынуы сыналды. Сталиннен кейінгі қоғамдық өмірдің салыстырмалы жұмсаруы «жылымық» деп аталды. Бұл кезеңде саяси қуғын-сүргін құрбандарының бір бөлігін ақтау жүргізілді. Қоғамдық жұмсаруға қарамастан бірпартиялық билік пен идеологиялық бақылау сақталды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9},"questions":[{"id":"hcl-34-1","t":"«Жылымық кезеңі» контексі: Сталиннің жеке басына табыну қай съезде сыналды?","o":["КОКП XX съезінде","РКП X съезінде","Екінші жалпықазақ съезінде","Бірінші құрылтайда"],"a":0,"e":"1956 жылғы КОКП XX съезінде Сталиннің жеке басына табынуы сыналды.","l":"A","topic":"Жылымық кезеңі"},{"id":"hcl-34-2","t":"«Жылымық кезеңі» контексі: 1950–1960 жылдардағы салыстырмалы жұмсару кезеңі қалай аталды?","o":["Тоқырау","Қайта құру","Жылымық","Әскери коммунизм"],"a":2,"e":"Сталиннен кейінгі қоғамдық өмірдің салыстырмалы жұмсаруы «жылымық» деп аталды.","l":"A","topic":"Жылымық кезеңі"},{"id":"hcl-34-3","t":"«Жылымық кезеңі» контексі: Екі деректі сәйкестендіріңіз. 1) Сталиннің жеке басына табыну қай съезде сыналды. 2) Жылымық кезінде қандай үдеріс жүрді.","o":["1 — Екінші жалпықазақ съезінде; 2 — Крепостнойлықты енгізу","1 — КОКП XX съезінде; 2 — Хандық билікті қалпына келтіру","1 — КОКП XX съезінде; 2 — Қуғындалғандардың бір бөлігін ақтау","1 — РКП X съезінде; 2 — Қуғындалғандардың бір бөлігін ақтау"],"a":2,"e":"1956 жылғы КОКП XX съезінде Сталиннің жеке басына табынуы сыналды. Бұл кезеңде саяси қуғын-сүргін құрбандарының бір бөлігін ақтау жүргізілді.","l":"B","topic":"Жылымық кезеңі"},{"id":"hcl-34-4","t":"«Жылымық кезеңі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) 1950–1960 жылдардағы салыстырмалы жұмсару кезеңі қалай аталды? 2) Кезеңнің шектеуін қай тұжырым көрсетеді?","o":["1 — Жылымық; 2 — Барлық саяси шектеу жойылды","1 — Әскери коммунизм; 2 — КСРО бірден ыдырады","1 — Жылымық; 2 — Бірпартиялық жүйе сақталды","1 — Тоқырау; 2 — Бірпартиялық жүйе сақталды"],"a":2,"e":"Сталиннен кейінгі қоғамдық өмірдің салыстырмалы жұмсаруы «жылымық» деп аталды. Қоғамдық жұмсаруға қарамастан бірпартиялық билік пен идеологиялық бақылау сақталды.","l":"B","topic":"Жылымық кезеңі"},{"id":"hcl-34-5","t":"«Жылымық кезеңі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Саяси бақылаудың сақталуы қоғамдағы жұмсарудың ешбір нақты белгісі болмағанын дәлелдейді.","Жылымық саяси қысымды ішінара жұмсартты, бірақ кеңестік жүйенің негізгі құрылымын толық өзгертпеді.","Жеке басқа табынуды сынау кеңестік басқарудың негізгі құрылымдары түгел ауысқанын көрсетеді.","Қуғындалғандарды ақтау бірпартиялық биліктің сол кезеңде толық жойылғанын білдіреді."],"a":1,"e":"Жылымық саяси қысымды ішінара жұмсартты, бірақ кеңестік жүйенің негізгі құрылымын толық өзгертпеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Жылымық кезеңі"}]}]},{"number":35,"questions":[{"id":"hk-048","t":"XVII ғасырдың соңы мен XVIII ғасырдың басындағы Қазақ хандығының белгілі билеушісі кім?","o":["Керей хан","Қасым хан","Тәуке хан","Мамаш хан"],"a":2,"e":"Тәуке хан осы кезеңде ел бірлігін күшейтуге және құқықтық тәртіпті реттеуге күш салды.","l":"A","topic":"Тәуке хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"ha-003","t":"Мезолиттің тас дәуірі ішіндегі орны қандай?","o":["Неолит пен энеолиттің арасы","Энеолит пен қола дәуірінің арасы","Палеолит пен неолиттің арасы","Қола мен темір дәуірлерінің арасы"],"a":2,"e":"Мезолит орта тас дәуірі деп аталады, ол палеолиттен кейін және неолиттен бұрын өтті.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":78}},{"id":"ha-067","t":"Ақ Орданың орталығы болған қала қайсы?","o":["Янгикент","Алмалық","Суяб","Сығанақ"],"a":3,"e":"Сығанақ Ақ Орданың Сырдария бойындағы саяси және экономикалық орталығы болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hm-005","t":"Қазақстан қай жылы одақтас республика мәртебесін алды?","o":["1925 жылы","1946 жылы","1936 жылы","1920 жылы"],"a":2,"e":"1936 жылғы КСРО Конституциясы бойынша Қазақ АКСР-і Қазақ КСР-і болып қайта құрылды.","l":"A","topic":"Қазақ КСР","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hi-097","t":"1917 жылдың соңында Түркістан автономиясы қай қалада жарияланды?","o":["Қоқанда","Омбыда","Қарқаралыда","Оралда"],"a":0,"e":"Түркістан автономиясы 1917 жылғы қарашада Қоқан қаласында жарияланды.","l":"A","topic":"Түркістан автономиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":221}},{"id":"hi-076","t":"1867–1868 жылғы әкімшілік жүйенің жоғарыдан төменге қарай дұрыс ретін көрсетіңіз.","o":["Генерал-губернаторлық → облыс → уезд → болыс → ауыл","Уезд → облыс → болыс → генерал-губернаторлық → ауыл","Генерал-губернаторлық → уезд → облыс → ауыл → болыс","Облыс → генерал-губернаторлық → болыс → уезд → ауыл"],"a":0,"e":"Реформа аумақты бір-біріне бағынатын бес негізгі әкімшілік сатыға бөлді.","l":"B","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":180}},{"id":"ha-099","t":"Ботайдан жылқы сүйектері, ал Тасмоладан мұртты обалар табылған. Оларды дәуірлермен сәйкестендіріңіз.","o":["Ботай — қола дәуірі; Тасмола — энеолит","Ботай — энеолит; Тасмола — ерте темір дәуірі","Ботай — неолит; Тасмола — қола дәуірі","Ботай — ерте темір дәуірі; Тасмола — орта ғасыр"],"a":1,"e":"Ботай мәдениеті мыс-тас дәуіріне, Тасмола мәдениеті ерте темір дәуіріне жатады.","l":"B","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-118","t":"«Жылымық» пен тоқырау туралы төрт пікірдің дұрыстарын табыңыз: I — ХХ съезде жеке басқа табыну сыналды; II — тоқырауда әкімшілік басқару қайшылықтары күшейді; III — «жылымықта» бірпартиялық жүйе жойылды; IV — тоқырау кезеңі ЖЭС-тен бұрын болды.","o":["I және II","II және IV","III және IV","I және III"],"a":0,"e":"1956 жылғы ХХ съезд сталиндік жеке басқа табынуды сынады, бірақ партия үстемдігі сақталды. Тоқырау 1965–1985 жылдарға, ЖЭС 1920 жылдарға жатады.","l":"C","topic":"Кеңестік қоғам","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hk-109","t":"Дәуірлер мен билеушілер дұрыс сәйкестендірілген қатарды таңдаңыз.","o":["XV ғасыр — Абылай; XVI ғасыр — Хақназар; XVIII ғасыр — Керей","XV ғасыр — Керей; XVI ғасыр — Хақназар; XVIII ғасыр — Абылай","XV ғасыр — Хақназар; XVI ғасыр — Керей; XVIII ғасыр — Абылай","XV ғасыр — Керей; XVI ғасыр — Абылай; XVIII ғасыр — Хақназар"],"a":1,"e":"Керей алғашқы хандық кезеңге, Хақназар XVI ғасырға, Абылай XVIII ғасырға жатады.","l":"C","topic":"Қазақ хандары және ғасырлар","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"hk-030","t":"Хақназар хан қай жылы қаза тапты?","o":["1511 жылы","1643 жылы","1580 жылы","1771 жылы"],"a":2,"e":"Хақназардың қазасы 1580 жылға жатады және Баба сұлтанның қастандығымен байланыстырылады.","l":"A","topic":"Хақназар хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}}],"contexts":[{"id":"hce-35","title":"Отырар қорғанысының саяси ортасы","text":"1219 жылы моңғол әскерлері Отырарды қоршады. Қала Хорезм мемлекетінің маңызды орталықтарының бірі еді. Қорғанысты Қайыр хан басқарды. Оқиға сауда керуеніне қатысты дағдарыс және Шыңғыс ханның Хорезмге жорығы аясында қарастырылады. Бекініс қарсылық көрсетуге мүмкіндік берді. Сыртқы қоршау мен ішкі жағдай қорғаныс тағдырына әсер етті. Сауда жолындағы қала әскери нысанға да айнала алады. Бір қаланың тарихын тұтас өңірмен байланыстыра талдау қажет. Оқиғаның себебі, барысы және салдары өзара байланысты болғанымен, бір ұғым емес. Қаланың құлауын тек бір ғана тұрмыстық себеппен түсіндіру жеткіліксіз.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":8},"questions":[{"id":"hce-35-1","t":"«Отырар қорғанысының саяси ортасы» контексі: Отырар қоршауы қай жылы басталды?","o":["1465","1243","1206","1219"],"a":3,"e":"Мәтіндегі деректер «1219» деген жауапты негіздейді. Отырар сол кезеңде Хорезм құрамындағы қала болды.","l":"A","topic":"Отырар қорғанысының саяси ортасы"},{"id":"hce-35-2","t":"«Отырар қорғанысының саяси ортасы» контексі: Қорғанысты басқарған кім?","o":["Сұлу қаған","Едіге","Қайыр хан","Тәуекел"],"a":2,"e":"Мәтіндегі деректер «Қайыр хан» деген жауапты негіздейді. Отырар сол кезеңде Хорезм құрамындағы қала болды.","l":"A","topic":"Отырар қорғанысының саяси ортасы"},{"id":"hce-35-3","t":"«Отырар қорғанысының саяси ортасы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Отырар сол кезеңде Хорезм құрамындағы қала болды","Қорғаныс тағдырын тек дуалдың болуы толық анықтады","Керуен дағдарысы кеңірек жорықпен байланыспаған","Отырар Моңғол империясының алғашқы астанасы болған"],"a":0,"e":"Мәтіндегі деректер «Отырар сол кезеңде Хорезм құрамындағы қала болды» деген жауапты негіздейді. Отырар сол кезеңде Хорезм құрамындағы қала болды.","l":"B","topic":"Отырар қорғанысының саяси ортасы"},{"id":"hce-35-4","t":"«Отырар қорғанысының саяси ортасы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір оқиғаның себебі мен салдары әрдайым бірдей ұғым","Сауда маңызы мен әскери маңыз бір қалада ұштаса алады","Ішкі жағдай қоршаудағы қалаға әсер етпейді","Қала саудаға қатысса әскери нысан бола алмайды"],"a":1,"e":"Мәтіндегі деректер «Сауда маңызы мен әскери маңыз бір қалада ұштаса алады» деген жауапты негіздейді. Отырар сол кезеңде Хорезм құрамындағы қала болды.","l":"B","topic":"Отырар қорғанысының саяси ортасы"},{"id":"hce-35-5","t":"«Отырар қорғанысының саяси ортасы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Қорғаныс тағдырын тек дуалдың болуы толық анықтады","Отырар сол кезеңде Хорезм құрамындағы қала болды","Сауда маңызы мен әскери маңыз бір қалада ұштаса алады","1219 жылы моңғол әскерлері Отырарды қоршады."],"a":0,"e":"Мәтіндегі деректер «Қорғаныс тағдырын тек дуалдың болуы толық анықтады» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сауда маңызы мен әскери маңыз бір қалада ұштаса алады.","l":"C","topic":"Отырар қорғанысының саяси ортасы"}]},{"id":"hcl-35","title":"1979 жылғы Целиноград оқиғасы","text":"Кеңестік әкімшілік кейбір шешімдерді жергілікті қоғамның пікірін жеткілікті ескермей қабылдады. Қазақстанның аумақтық тұтастығына қатысты бастама қоғамдық наразылық туғызды.\n\n1979 жылғы маусымда Целиноградта қоғамдық наразылық өтті. Наразылық Қазақстан аумағында неміс автономиясын құру жобасына қарсы бағытталды. Қоғам автономия құру жобасын республиканың аумақтық тұтастығына қатысты мәселе ретінде қабылдады. Қарсылықтан кейін неміс автономиясын құру жобасы жүзеге асырылмады. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9},"questions":[{"id":"hcl-35-1","t":"«1979 жылғы Целиноград оқиғасы» контексі: 1979 жылғы наразылық қай қалада өтті?","o":["Қызылордада","Целиноградта","Түркістанда","Алматыда"],"a":1,"e":"1979 жылғы маусымда Целиноградта қоғамдық наразылық өтті.","l":"A","topic":"1979 жылғы Целиноград оқиғасы"},{"id":"hcl-35-2","t":"«1979 жылғы Целиноград оқиғасы» контексі: Наразылық қандай жобаға қарсы бағытталды?","o":["БҰҰ-ға мүше болуға","Теңгені енгізуге","Тың игеруді алғаш бастауға","Неміс автономиясын құруға"],"a":3,"e":"Наразылық Қазақстан аумағында неміс автономиясын құру жобасына қарсы бағытталды.","l":"A","topic":"1979 жылғы Целиноград оқиғасы"},{"id":"hcl-35-3","t":"«1979 жылғы Целиноград оқиғасы» контексі: Екі деректі сәйкестендіріңіз. 1) 1979 жылғы наразылық қай қалада өтті. 2) Оқиға Қазақстанның қай мәселесімен байланысты болды.","o":["1 — Целиноградта; 2 — Аумақтық тұтастықпен","1 — Алматыда; 2 — Аумақтық тұтастықпен","1 — Целиноградта; 2 — Теңіз шекарасын кеңейтумен","1 — Қызылордада; 2 — Ғарышкер даярлаумен"],"a":0,"e":"1979 жылғы маусымда Целиноградта қоғамдық наразылық өтті. Қоғам автономия құру жобасын республиканың аумақтық тұтастығына қатысты мәселе ретінде қабылдады.","l":"B","topic":"1979 жылғы Целиноград оқиғасы"},{"id":"hcl-35-4","t":"«1979 жылғы Целиноград оқиғасы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Наразылық қандай жобаға қарсы бағытталды? 2) Наразылықтан кейін жобаға не болды?","o":["1 — БҰҰ-ға мүше болуға; 2 — Қазақстаннан тыс мұхитқа көшірілді","1 — Неміс автономиясын құруға; 2 — Жүзеге асырылмады","1 — Тың игеруді алғаш бастауға; 2 — Жүзеге асырылмады","1 — Неміс автономиясын құруға; 2 — Дереу толық іске асты"],"a":1,"e":"Наразылық Қазақстан аумағында неміс автономиясын құру жобасына қарсы бағытталды. Қарсылықтан кейін неміс автономиясын құру жобасы жүзеге асырылмады.","l":"B","topic":"1979 жылғы Целиноград оқиғасы"},{"id":"hcl-35-5","t":"«1979 жылғы Целиноград оқиғасы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Автономияға қатысты дау этносаралық қатынастан бөлек болып, тек қалалық басқару қызметтерін бөлуге арналды.","Қоғамдық наразылық орталықтың аумақтық шешіміне жергілікті халықтың пікірін ескертуге ықпал етті.","Жергілікті қарсылықтың болуы автономия құру жобасының халық тарапынан қолдау тапқанын көрсетті.","Жобаның жүзеге аспауы қоғам пікірінің аумақтық шешімдерге әсер ете алмайтынын дәлелдейді."],"a":1,"e":"Қоғамдық наразылық орталықтың аумақтық шешіміне жергілікті халықтың пікірін ескертуге ықпал етті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1979 жылғы Целиноград оқиғасы"}]}]},{"number":36,"questions":[{"id":"ha-113","t":"Атлах шайқасы туралы қай екі тұжырым дұрыс? I. 751 жылы өтті. II. Тан Қытайының аймақтағы ықпалы әлсіреді. III. Моғолстан осы шайқаста құрылды. IV. Қарлұқтар арабтарға қарсы шешуші жеңіске жетті.","o":["I және IV","I және II","III және IV","II және III"],"a":1,"e":"751 жылғы Атлах шайқасында қарлұқтар арабтар жағына шығып, Тан әскерінің жеңілуіне ықпал етті; Моғолстан 1348 жылы құрылды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-090","t":"1990 жылғы егемендік декларациясы мен 1991 жылғы тәуелсіздік заңының арақатынасын анықтаңыз.","o":["Декларация ұлттық валютаны енгізді, заң тың игеруді бастады","Екеуі де Қазақ хандығын құрды","Декларация егемендік қағидаларын жариялады, заң тәуелсіздікті бекітті","Екі құжат та тек ауыл салығын реттеді"],"a":2,"e":"1990 жылғы құжат егемендікке қадам болса, 1991 жылғы заң мемлекеттің тәуелсіздігін бекітті.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hm-018","t":"Түрксіб теміржолы тұрақты пайдалануға қай жылы берілді?","o":["1921 жылы","1931 жылы","1946 жылы","1906 жылы"],"a":1,"e":"Құрылыс бөліктері 1930 жылы түйісіп, жол 1931 жылы тұрақты пайдалануға берілді.","l":"A","topic":"Индустрияландыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":235}},{"id":"hi-046","t":"Шоқан Уәлиханов зерттеген қырғыз халқының эпосын атаңыз.","o":["Қобыланды батыр","Алпамыс батыр","Манас","Қыз Жібек"],"a":2,"e":"Шоқан қырғыздың «Манас» эпосын зерттеп, оның үзінділерін жазып алды.","l":"A","topic":"XIX ғасырдағы ағартушылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":189}},{"id":"hm-055","t":"«Невада–Семей» қозғалысының негізгі талабы қандай болды?","o":["Тың жерлерді көбірек жырту","Карточкалық жүйені енгізу","Ұжымдастыруды жеделдету","Ядролық сынақтарды тоқтату"],"a":3,"e":"Бұл қоғамдық қозғалыс ядролық сынақтарға қарсы күресті.","l":"A","topic":"Қайта құру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":285}},{"id":"hk-067","t":"Есен-бұғаның Керей мен Жәнібекті қабылдауынан Моғолстан үшін күткен пайдасы қандай еді?","o":["Батыс шекарасында одақтас күш қалыптастыру","Керей мен Жәнібекті Шайбани әулетіне қарсы хан ету","Өзінің батыстағы барлық иелігінен біржола бас тарту","Жошы әулетінің Моғолстан тағына құқығын мойындау"],"a":0,"e":"Қазақ сұлтандарына қолдау көрсету Есен-бұғаға ішкі қарсыластары мен сыртқы қауіпке қарсы тірек іздеуге мүмкіндік берді.","l":"B","topic":"Есен-бұғаның саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":87}},{"id":"ha-069","t":"Моғолстанның алғашқы ханы кім?","o":["Тоғылық Темір","Есенбұға","Абд ар-Рашид","Ілияс Қожа"],"a":0,"e":"Тоғылық Темір 1348 жылы Моғолстанның алғашқы ханы болып көтерілді.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"hi-115","t":"Автор мен еңбекті дұрыс сәйкестендіріңіз.","o":["А. Байтұрсынұлы — «Қарасөздер»; Ы. Алтынсарин — «Маса»","А. Байтұрсынұлы — «Манас»; Ы. Алтынсарин — «Диуани лұғат ат-түрк»","А. Байтұрсынұлы — «Маса»; Ы. Алтынсарин — «Қазақ хрестоматиясы»","А. Байтұрсынұлы — «Евгений Онегин»; Ы. Алтынсарин — «Тарих-и Рашиди»"],"a":2,"e":"«Маса» Ахмет Байтұрсынұлына, «Қазақ хрестоматиясы» Ыбырай Алтынсаринге тиесілі. Екі еңбек те ағартушылық мазмұнға ие.","l":"C","topic":"XX ғасыр басындағы тұлғалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":261}},{"id":"hi-055","t":"Дулат Бабатайұлы, Шортанбай Қанайұлы, Мұрат Мөңкеұлы қай әдеби бағыт өкілдері саналады?","o":["Алаштың саяси публицистикасы","Зар заман","Көне түркі жазба дәстүрі","Кеңестік өндірістік поэзия"],"a":1,"e":"Бұл ақындар отарлық өзгерістер мен дәстүрлі өмірдің дағдарысын жырлаған «Зар заман» бағытына жатады.","l":"A","topic":"XIX ғасырдағы әдебиет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"hk-041","t":"Есіммен қатар хандық билікке таласқан Ташкент билеушісі кім?","o":["Тұрсын хан","Ұрыс хан","Есен-бұға хан","Берке хан"],"a":0,"e":"Тұрсын ханның дербес билікке ұмтылысы Есім ханмен қақтығысқа әкелді.","l":"A","topic":"Есім хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":103}}],"contexts":[{"id":"hce-36","title":"Алтын Орданың аумақтық және шаруашылық тірегі","text":"Алтын Орда Жошы ұлысы негізінде қалыптасты. Мемлекеттің құрылуы мен нығаюы Батый ханның қызметімен байланысты. Еділ бойындағы Сарай қалалары саяси және сауда орталықтары болды. Құрамына әртүрлі халықтар мен шаруашылық өңірлер кірді. Далалық мал шаруашылығы мен қалалық сауда бірін-бірі толықтырды. Салық, елшілік және әкімшілік байланыс кең аумақты біріктірді. Жошы әулетінің билігі саяси заңдылық үшін маңызды болды. Алтын Орданы тек көшпелі қоныстар жиынтығы деп сипаттау жеткіліксіз. Оның тарихы кейінгі Еуразия мемлекеттеріне ықпал етті. Бір орталықты білу бүкіл көпқырлы құрылымды толық түсіндірмейді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":142},"questions":[{"id":"hce-36-1","t":"«Алтын Орданың аумақтық және шаруашылық тірегі» контексі: Алтын Орда қай ұлыс негізінде қалыптасты?","o":["Жошы","Төле","Үгедей","Шағатай"],"a":0,"e":"Мәтіндегі деректер «Жошы» деген жауапты негіздейді. Сарай қалалары Еділ бойындағы орталықтар болды.","l":"A","topic":"Алтын Орданың аумақтық және шаруашылық тірегі"},{"id":"hce-36-2","t":"«Алтын Орданың аумақтық және шаруашылық тірегі» контексі: Алтын Орданың құрылуымен байланысты хан кім?","o":["Мұса","Бумын","Хақназар","Батый"],"a":3,"e":"Мәтіндегі деректер «Батый» деген жауапты негіздейді. Сарай қалалары Еділ бойындағы орталықтар болды.","l":"A","topic":"Алтын Орданың аумақтық және шаруашылық тірегі"},{"id":"hce-36-3","t":"«Алтын Орданың аумақтық және шаруашылық тірегі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Алтын Ордада қалалық өмір мүлде болмаған","Сарай қалалары Еділ бойындағы орталықтар болды","Әулеттік билік саяси заңдылыққа қатыссыз болған","Алтын Орда тек бір шағын қаламен шектелген"],"a":1,"e":"Мәтіндегі деректер «Сарай қалалары Еділ бойындағы орталықтар болды» деген жауапты негіздейді. Сарай қалалары Еділ бойындағы орталықтар болды.","l":"B","topic":"Алтын Орданың аумақтық және шаруашылық тірегі"},{"id":"hce-36-4","t":"«Алтын Орданың аумақтық және шаруашылық тірегі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір билеуші әулет барлық халықтың мәдениеті бірдей екенін дәлелдейді","Салық пен әкімшілік кең аумақты басқаруға әсер етпейді","Дала және қала байланысы мемлекеттің экономикалық тірегін толықтырды","Мал шаруашылығы мен қалалық сауда қатар өмір сүре алмайды"],"a":2,"e":"Мәтіндегі деректер «Дала және қала байланысы мемлекеттің экономикалық тірегін толықтырды» деген жауапты негіздейді. Сарай қалалары Еділ бойындағы орталықтар болды.","l":"B","topic":"Алтын Орданың аумақтық және шаруашылық тірегі"},{"id":"hce-36-5","t":"«Алтын Орданың аумақтық және шаруашылық тірегі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Дала және қала байланысы мемлекеттің экономикалық тірегін толықтырды","Алтын Ордада қалалық өмір мүлде болмаған","Сарай қалалары Еділ бойындағы орталықтар болды","Алтын Орда Жошы ұлысы негізінде қалыптасты."],"a":1,"e":"Мәтіндегі деректер «Алтын Ордада қалалық өмір мүлде болмаған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Дала және қала байланысы мемлекеттің экономикалық тірегін толықтырды.","l":"C","topic":"Алтын Орданың аумақтық және шаруашылық тірегі"}]},{"id":"hcl-36","title":"1986 жылғы Желтоқсан","text":"Қайта құру басталғанымен, орталықтың кадр саясатына наразылық сақталды. Алматыдағы жастардың алаңға шығуы ұлттық қадір-қасиет пен әділдік мәселесін ашық көтерді.\n\nЖелтоқсан оқиғасы 1986 жылы Алматыда болды. Дінмұхамед Қонаев қызметінен алынып, оның орнына Геннадий Колбин тағайындалды. Наразылыққа негізінен жастар мен студенттер қатысты. Орталықтың республика басшысын жергілікті пікірді ескермей ауыстыруы тікелей түрткі болды. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14},"questions":[{"id":"hcl-36-1","t":"«1986 жылғы Желтоқсан» контексі: Желтоқсан оқиғасы қай жылы болды?","o":["1991 жылы","1986 жылы","1979 жылы","1954 жылы"],"a":1,"e":"Желтоқсан оқиғасы 1986 жылы Алматыда болды.","l":"A","topic":"1986 жылғы Желтоқсан"},{"id":"hcl-36-2","t":"«1986 жылғы Желтоқсан» контексі: Қонаевтың орнына кім тағайындалды?","o":["Леонид Брежнев","Михаил Сперанский","Геннадий Колбин","Никита Хрущев"],"a":2,"e":"Дінмұхамед Қонаев қызметінен алынып, оның орнына Геннадий Колбин тағайындалды.","l":"A","topic":"1986 жылғы Желтоқсан"},{"id":"hcl-36-3","t":"«1986 жылғы Желтоқсан» контексі: Екі деректі сәйкестендіріңіз. 1) Желтоқсан оқиғасы қай жылы болды. 2) Наразылықтың негізгі қатысушылары кімдер болды.","o":["1 — 1986 жылы; 2 — Жастар мен студенттер","1 — 1986 жылы; 2 — Тек шетел теңізшілері","1 — 1991 жылы; 2 — Тек хан ұрпақтары","1 — 1979 жылы; 2 — Жастар мен студенттер"],"a":0,"e":"Желтоқсан оқиғасы 1986 жылы Алматыда болды. Наразылыққа негізінен жастар мен студенттер қатысты.","l":"B","topic":"1986 жылғы Желтоқсан"},{"id":"hcl-36-4","t":"«1986 жылғы Желтоқсан» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Қонаевтың орнына кім тағайындалды? 2) Оқиғаның тікелей түрткісі қандай болды?","o":["1 — Геннадий Колбин; 2 — Орталықтың кадрлық шешімі","1 — Геннадий Колбин; 2 — Теңгенің енгізілуі","1 — Леонид Брежнев; 2 — БҰҰ-ға қабылдау","1 — Никита Хрущев; 2 — Орталықтың кадрлық шешімі"],"a":0,"e":"Дінмұхамед Қонаев қызметінен алынып, оның орнына Геннадий Колбин тағайындалды. Орталықтың республика басшысын жергілікті пікірді ескермей ауыстыруы тікелей түрткі болды.","l":"B","topic":"1986 жылғы Желтоқсан"},{"id":"hcl-36-5","t":"«1986 жылғы Желтоқсан» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Алматыдағы оқиға республика басшысын тағайындауда жергілікті пікірдің толық ескерілгенін дәлелдейді.","Желтоқсан орталықтанған басқару мен ұлттық мүддені ескеру талабы арасындағы қайшылықты көрсетті.","Кадрлық ауысымға наразылық жастардың қоғамдық мәселеге емес, тек жеке қызмет алуға ұмтылғанын көрсетеді.","Қайта құру басталуы орталық пен республика арасындағы қайшылықтардың Желтоқсанға дейін толық шешілгенін білдіреді."],"a":1,"e":"Желтоқсан орталықтанған басқару мен ұлттық мүддені ескеру талабы арасындағы қайшылықты көрсетті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1986 жылғы Желтоқсан"}]}]},{"number":37,"questions":[{"id":"hi-088","t":"«Қазақ» газеті қай қалада жарық көрді?","o":["Ақмешітте","Қашғарда","Орынборда","Верныйда"],"a":2,"e":"«Қазақ» газеті Орынборда шығып, жалпыұлттық мәселелерді талқылады.","l":"B","topic":"XX ғасыр басындағы баспасөз","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":239}},{"id":"ha-086","t":"Қала маңындағы қыстақтан астық сақтайтын орындар мен орақтар табылды. Қыстақ пен қала арасындағы негізгі байланыс қандай болды?","o":["Мал жайылымдарын тең бөлу","Қағандарды сайлау рәсімін өткізу","Егіншілік өнімдерімен қамтамасыз ету","Әскери заңдар жинағын құрастыру"],"a":2,"e":"Егіншілік құралдары мен астық қоймалары қыстақтың қаланы азық-түлікпен қамтуға қатысқанын көрсетеді.","l":"B","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":21}},{"id":"hk-022","t":"Қосын жасақтау және аламан міндетін реттеу қай заң саласына кірді?","o":["Жұртшылық заңына","Әскери заңға","Елшілік заңына","Мүлік заңына"],"a":1,"e":"Әскер жинау мен әскери міндетті атқару әскери заңдардың мазмұнын құрады.","l":"A","topic":"Қасым ханның заңдары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":129}},{"id":"hm-053","t":"1986 жылғы Желтоқсан наразылығына тікелей түрткі болған шешім қандай?","o":["Тың игерудің басталуы","Д.Қонаевтың орнына Г.Колбиннің тағайындалуы","Ұлттық валютаның енгізілуі","Қазақстанның БҰҰ-ға қабылдануы"],"a":1,"e":"Қазақстанды басқарған Д.Қонаевты ауыстырып, Г.Колбинді тағайындау жастар наразылығын туғызды.","l":"A","topic":"Қайта құру","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"hk-045","t":"1643 жылы қазақ қолы жеңіске жеткен шайқас қалай аталады?","o":["Атлах шайқасы","Қатуан шайқасы","Орбұлақ шайқасы","Аңырақай шайқасы"],"a":2,"e":"Орбұлақ шайқасы 1643 жылы Жәңгір ханның басшылығымен жоңғарларға қарсы өтті.","l":"A","topic":"Орбұлақ шайқасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":142}},{"id":"hm-103","t":"Ауыл шаруашылығындағы өзгерістерді хронологиялық реттеңіз: 1 — «Бесеудің хаты»; 2 — ЖЭС-ке көшу; 3 — бай шаруашылықтарын тәркілеу; 4 — Т.Рысқұловтың Сталинге 1933 жылғы хаты.","o":["3–2–1–4","2–1–3–4","2–3–4–1","2–3–1–4"],"a":3,"e":"ЖЭС 1921 жылы басталды, тәркілеу 1928 жылы жүргізілді. «Бесеудің хаты» 1932 жылы, Рысқұловтың аталған хаты 1933 жылы жазылды.","l":"C","topic":"Хронология","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":252}},{"id":"hk-122","t":"1710 жылы өкілдердің ортақ жауға қарсы жасақ құруды талқылауы қай қорытындыны негіздейді?","o":["Әскери ынтымақ жалпы қазақтық мәселе ретінде қаралды","Жүздердің сыртқы саяси мүдделері мүлдем қиылыспады","Ортақ жасақ құру жергілікті мүдделерден тыс қаралмады","Құрылтай тек хан мұрагерлігінің тәртібін талқылады"],"a":0,"e":"Қарақұм құрылтайы ортақ қорғанысты талқылау арқылы жүздер мен тайпалар арасындағы саяси ынтымақтың қажеттігін көрсетті.","l":"C","topic":"Құрылтайдың маңызын талдау","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":187}},{"id":"hi-029","t":"1867–1868 жылғы реформалардан кейін қазақ жерінің негізгі бөлігі қандай үш генерал-губернаторлыққа бөлінді?","o":["Ақмола, Торғай, Сырдария","Қазан, Мәскеу, Кавказ","Орынбор, Батыс Сібір, Түркістан","Орал, Семей, Жетісу"],"a":2,"e":"Қазақ жері Орынбор, Батыс Сібір және Түркістан генерал-губернаторлықтарына бөлінді. Олардың құрамына облыстар кірді.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":150}},{"id":"ha-008","t":"Ботай мәдениеті қай дәуірге жатады?","o":["Орта ғасыр","Ерте темір дәуірі","Энеолит","Кейінгі палеолит"],"a":2,"e":"Ботай — Қазақстанның энеолит дәуіріне жататын археологиялық мәдениеті.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"ha-036","t":"Ғұн тайпаларын бір мемлекетке біріктірген әйгілі билеушіні атаңыз.","o":["Естеми","Бумын","Сұлу","Мөде"],"a":3,"e":"Мөде тұсында ғұндардың қуатты мемлекеттік бірлестігі қалыптасты.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}}],"contexts":[{"id":"hce-37","title":"Алтын Ордадағы дін: Берке және Өзбек","text":"Алтын Ордада ислам ықпалы біртіндеп артты. Берке ханның исламды қабылдауы маңызды оқиға болды. Өзбек хан тұсында 1312 жылы ислам мемлекеттік дін ретінде орнықты. Мешіт, білім және мұсылман елдерімен байланыс осы үдерістің қырлары еді. Билеушінің жеке сенімі мен мемлекеттік мәртебені шатастырмау қажет. Қоғамның бүкіл мәдениеті бір мезетте өзгерген жоқ. Түрлі дәстүрлер өзара ықпалдасты. Сызба: Беркенің дін қабылдауы → Өзбек кезіндегі мемлекеттік мәртебе → діни институттардың нығаюы. Хронология саяси және рухани өзгерісті дұрыс түсінуге көмектеседі. Ресми шешім ұзақ мәдени үдерістің бір маңызды кезеңі ғана болды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":143},"questions":[{"id":"hce-37-1","t":"«Алтын Ордадағы дін: Берке және Өзбек» контексі: Исламды мемлекеттік дін ретінде орнықтырған хан кім?","o":["Қасым","Тоқтамыс","Өзбек","Батый"],"a":2,"e":"Мәтіндегі деректер «Өзбек» деген жауапты негіздейді. Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды.","l":"A","topic":"Алтын Ордадағы дін: Берке және Өзбек"},{"id":"hce-37-2","t":"«Алтын Ордадағы дін: Берке және Өзбек» контексі: Мемлекеттік мәртебемен байланысты жыл қайсы?","o":["1465","1395","1206","1312"],"a":3,"e":"Мәтіндегі деректер «1312» деген жауапты негіздейді. Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды.","l":"A","topic":"Алтын Ордадағы дін: Берке және Өзбек"},{"id":"hce-37-3","t":"«Алтын Ордадағы дін: Берке және Өзбек» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды","Мешіттер тек әскери мұнара қызметін атқарған","Берке мен Өзбек бір билеушінің екі аты болған","1312 жылы барлық мәдени дәстүр бірден жойылды"],"a":0,"e":"Мәтіндегі деректер «Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды» деген жауапты негіздейді. Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды.","l":"B","topic":"Алтын Ордадағы дін: Берке және Өзбек"},{"id":"hce-37-4","t":"«Алтын Ордадағы дін: Берке және Өзбек» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Ресми шешім қоғамдағы барлық сенімді бір сәтте өзгертеді","Хронологияны ажыратудың тарихи талдауға қажеті жоқ","Діни институттар сыртқы байланысқа әсер етпейді","Жеке дін қабылдау мен мемлекеттік мәртебе екі бөлек оқиға"],"a":3,"e":"Мәтіндегі деректер «Жеке дін қабылдау мен мемлекеттік мәртебе екі бөлек оқиға» деген жауапты негіздейді. Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды.","l":"B","topic":"Алтын Ордадағы дін: Берке және Өзбек"},{"id":"hce-37-5","t":"«Алтын Ордадағы дін: Берке және Өзбек» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Жеке дін қабылдау мен мемлекеттік мәртебе екі бөлек оқиға","Берке мен Өзбек бір билеушінің екі аты болған","Алтын Ордада ислам ықпалы біртіндеп артты.","Берке ханның дін қабылдауы Өзбек ханның саясатына дейін болды"],"a":1,"e":"Мәтіндегі деректер «Берке мен Өзбек бір билеушінің екі аты болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Жеке дін қабылдау мен мемлекеттік мәртебе екі бөлек оқиға.","l":"C","topic":"Алтын Ордадағы дін: Берке және Өзбек"}]},{"id":"hcl-37","title":"Қайта құру және жариялылық","text":"1980 жылдардың екінші жартысында кеңестік жүйені жаңарту әрекеттері басталды. Қоғамда бұрын ашық талқыланбайтын тарихи және әлеуметтік мәселелер көтеріле түсті.\n\nМихаил Горбачев билікке келген 1985 жылдан бастап қайта құру бағыты жарияланды. Жариялылық қоғамдағы мәселелерді ашық талқылау мүмкіндігін кеңейтті. 1989 жылы Қазақ КСР-нің тілдер туралы заңы қабылданды. Экологиялық мәселелер мен ұлттық мүдделерді көтерген қоғамдық қозғалыстар белсенді болды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4},"questions":[{"id":"hcl-37-1","t":"«Қайта құру және жариялылық» контексі: Қайта құру саясаты қай жылы басталды?","o":["1954 жылы","1921 жылы","1936 жылы","1985 жылы"],"a":3,"e":"Михаил Горбачев билікке келген 1985 жылдан бастап қайта құру бағыты жарияланды.","l":"A","topic":"Қайта құру және жариялылық"},{"id":"hcl-37-2","t":"«Қайта құру және жариялылық» контексі: Қоғамдық мәселелерді ашық талқылау ұстанымы қалай аталды?","o":["Салғырт","Отырықшыландыру","Округтік басқару","Жариялылық"],"a":3,"e":"Жариялылық қоғамдағы мәселелерді ашық талқылау мүмкіндігін кеңейтті.","l":"A","topic":"Қайта құру және жариялылық"},{"id":"hcl-37-3","t":"«Қайта құру және жариялылық» контексі: Екі деректі сәйкестендіріңіз. 1) Қайта құру саясаты қай жылы басталды. 2) 1989 жылы Қазақ КСР-де қандай заң қабылданды.","o":["1 — 1921 жылы; 2 — Тілдер туралы заң","1 — 1936 жылы; 2 — Сібір қырғыздары туралы жарғы","1 — 1985 жылы; 2 — Тілдер туралы заң","1 — 1985 жылы; 2 — Жеті жарғы"],"a":2,"e":"Михаил Горбачев билікке келген 1985 жылдан бастап қайта құру бағыты жарияланды. 1989 жылы Қазақ КСР-нің тілдер туралы заңы қабылданды.","l":"B","topic":"Қайта құру және жариялылық"},{"id":"hcl-37-4","t":"«Қайта құру және жариялылық» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Қоғамдық мәселелерді ашық талқылау ұстанымы қалай аталды? 2) Қайта құру кезінде қандай қоғамдық белсенділік артты?","o":["1 — Салғырт; 2 — Экологиялық және ұлттық қозғалыстар","1 — Жариялылық; 2 — Экологиялық және ұлттық қозғалыстар","1 — Жариялылық; 2 — Тек хандық тақ таласы","1 — Отырықшыландыру; 2 — Тек құл саудасы"],"a":1,"e":"Жариялылық қоғамдағы мәселелерді ашық талқылау мүмкіндігін кеңейтті. Экологиялық мәселелер мен ұлттық мүдделерді көтерген қоғамдық қозғалыстар белсенді болды.","l":"B","topic":"Қайта құру және жариялылық"},{"id":"hcl-37-5","t":"«Қайта құру және жариялылық» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Тілдер туралы заңның қабылдануы ұлттық мәселелердің қоғамдық пікірталастан толық алынғанын білдірді.","Жүйені жаңарту туралы ұрандар кеңестік мәселелерді талқылауды шектеу арқылы іске асырылды.","Жариялылық кеңестік жүйенің мәселелерін ашып, қоғамдық қозғалыстардың күшеюіне жағдай жасады.","Жариялылықтың кеңеюі қоғамдық қозғалыстарға қажеттілік қалмағанын көрсетті."],"a":2,"e":"Жариялылық кеңестік жүйенің мәселелерін ашып, қоғамдық қозғалыстардың күшеюіне жағдай жасады. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қайта құру және жариялылық"}]}]},{"number":38,"questions":[{"id":"hm-068","t":"Индустрияландыру кезіндегі Қазақстан экономикасының шикізаттық бағытын қай белгі көрсетеді?","o":["Тек тұрмыстық қызметтің өсуі","Ауыл шаруашылығының жойылуы","Кен өндірудің өңдеуші салалардан басым дамуы","Барлық кеніштің жабылуы"],"a":2,"e":"Шикізаттық бағыт пайдалы қазбаларды өндіруге басымдық беріліп, өңдеу салаларының баяу дамуынан байқалды.","l":"A","topic":"Индустрияландыру","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":2}},{"id":"hi-114","t":"Қоғамдық басылымдарды дұрыс ажырататын қатарды табыңыз.","o":["«Айқап» — оқулық; «Қазақ» — күй","«Айқап» — газет; «Қазақ» — роман","«Айқап» — журнал; «Қазақ» — газет","«Айқап» — заң жинағы; «Қазақ» — ғылыми экспедиция"],"a":2,"e":"«Айқап» журнал түрінде, ал «Қазақ» газет түрінде жарық көрді. Екеуі де ұлттық қоғамдық ойға ықпал етті.","l":"C","topic":"XX ғасыр басындағы баспасөз","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":255}},{"id":"hi-041","t":"XIX ғасырдың соңында Қытайдан қоныс аударған ұйғырлар мен дүнгендер Қазақстанның қай өңіріне негізінен орналасты?","o":["Торғайға","Солтүстік Аралға","Жетісуға","Маңғыстауға"],"a":2,"e":"Ұйғырлар мен дүнгендердің негізгі қоныстанған өңірі Жетісу болды.","l":"A","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":158}},{"id":"hm-096","t":"1993 және 1995 жылғы Конституцияларға ортақ белгі қандай?","o":["Тәуелсіз Қазақстанның конституциялық негізін қалыптастыруы","Ресей империясының отарлық реформасы болуы","Тек ядролық сынақ күнтізбесін бекітуі","Қазақ АКСР-ін алғаш құруы"],"a":0,"e":"Екі Конституция да тәуелсіздік кезеңіндегі мемлекеттік құрылысты құқықтық реттеуге арналды.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":284}},{"id":"hk-010","t":"Қазақ қоғамында ата-тек пен ұрпақтар тарихын жеткізген дәстүр қалай аталды?","o":["Қалан","Жасақ","Шежіре","Құрылтай"],"a":2,"e":"Шежіре ру мен әулеттің таралуын және өткен оқиғаларды ұрпақтан ұрпаққа жеткізді.","l":"A","topic":"Дәстүрлі мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-016","t":"Қазақстандағы индустрияландыру кезінде салынған Түркістан–Сібір теміржолының қысқаша атауы қандай?","o":["Транссіб","БАМ","Түрксіб","Орынбор–Ташкент"],"a":2,"e":"Түрксіб Түркістан мен Сібір арасындағы экономикалық байланысты күшейтті.","l":"A","topic":"Индустрияландыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":235}},{"id":"hi-010","t":"Бөкей Ордасындағы 1836–1838 жылғы көтерілістің негізгі басшыларының бірін атаңыз.","o":["Досан Тәжіұлы","Жанқожа Нұрмұхамедұлы","Кенесары Қасымұлы","Исатай Тайманұлы"],"a":3,"e":"Исатай Тайманұлы көтерілістің әскери басшысы болды. Онымен бірге Махамбет Өтемісұлы күресті.","l":"A","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":159}},{"id":"ha-103","t":"Қағанаттарды құрылу уақытымен сәйкестендіріңіз: 1) Түрік; 2) Батыс Түрік; 3) Түргеш. А) 704; Ә) 552; Б) 603.","o":["1–А, 2–Б, 3–Ә","1–Ә, 2–Б, 3–А","1–Ә, 2–А, 3–Б","1–Б, 2–Ә, 3–А"],"a":1,"e":"Түрік қағанаты 552, Батыс Түрік 603, Түргеш 704 жылы құрылды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"hk-072","t":"Екі қауымның жайылым шекарасы туралы дауы Қасым хан заңдарының қай саласына жақын?","o":["Елшілік қатынастарға","Әскери міндеттерге","Мүлік құқығына","Қылмыстық жауапкершілікке"],"a":2,"e":"Жайылым мен жерді иеленуге қатысты дау меншік қатынастарына жатады.","l":"B","topic":"Дәстүрлі құқық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}},{"id":"ha-025","t":"Есік қорғанын зерттеген археологты көрсетіңіз.","o":["Михаил Сперанский","Әбілғазы Баһадүр","Василий Татищев","Кемел Ақышев"],"a":3,"e":"Кемел Ақышев бастаған археологиялық зерттеу Есік қорғанындағы сақ мұрасын ғылыми айналымға енгізді.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":83}}],"contexts":[{"id":"hce-38","title":"Тоқтамыс пен Әмір Темір: шайқастар тізбегі","text":"XIV ғасырдың соңында Әмір Темір мен Тоқтамыс арасында соғыс жүрді. 1391 жылы Құндызшада, 1395 жылы Терек бойында ірі шайқастар болды. Хронологиялық қатар: Құндызша → Терек. Соғыстар Алтын Орданың саяси және шаруашылық жағдайына ауыр әсер етті. Қалалар мен сауда байланыстары зардап шекті. Мемлекеттің әлсіреуіне ішкі билік тартыстары да қосылды. Бір шайқас барлық ыдырау үдерісін толық түсіндірмейді. Сыртқы соққы ішкі тұрақсыздықпен ұштасқанда салдар күшейді. Оқиғалардың уақытын салыстыру соғыстың бірнеше кезеңнен тұрғанын көрсетеді. Саяси және экономикалық салдарды бірге қарастыру тарихи бағаны толықтырады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":143},"questions":[{"id":"hce-38-1","t":"«Тоқтамыс пен Әмір Темір: шайқастар тізбегі» контексі: Тоқтамыстың қарсыласы кім болды?","o":["Бумын","Әмір Темір","Есім","Мөде"],"a":1,"e":"Мәтіндегі деректер «Әмір Темір» деген жауапты негіздейді. Құндызша шайқасы Терек шайқасынан бұрын өтті.","l":"A","topic":"Тоқтамыс пен Әмір Темір: шайқастар тізбегі"},{"id":"hce-38-2","t":"«Тоқтамыс пен Әмір Темір: шайқастар тізбегі» контексі: 1395 жылғы шайқас қай өзен бойында өтті?","o":["Шу","Терек","Іле","Талас"],"a":1,"e":"Мәтіндегі деректер «Терек» деген жауапты негіздейді. Құндызша шайқасы Терек шайқасынан бұрын өтті.","l":"A","topic":"Тоқтамыс пен Әмір Темір: шайқастар тізбегі"},{"id":"hce-38-3","t":"«Тоқтамыс пен Әмір Темір: шайқастар тізбегі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Соғыстың қала мен саудаға еш әсері болмады","Терек шайқасы Құндызшадан бұрын болды","Құндызша шайқасы Терек шайқасынан бұрын өтті","Бір шайқас Алтын Орданың барлық ыдырауын толық түсіндіреді"],"a":2,"e":"Мәтіндегі деректер «Құндызша шайқасы Терек шайқасынан бұрын өтті» деген жауапты негіздейді. Құндызша шайқасы Терек шайқасынан бұрын өтті.","l":"B","topic":"Тоқтамыс пен Әмір Темір: шайқастар тізбегі"},{"id":"hce-38-4","t":"«Тоқтамыс пен Әмір Темір: шайқастар тізбегі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Әскери жеңіліс экономикалық зардап әкеле алмайды","Сыртқы соғыс пен ішкі тартыстар әлсіреуге бірге ықпал етті","Саяси тұрақсыздық шаруашылық жағдайға қатыссыз","Құндызша мен Терек бір оқиғаның екі атауы"],"a":1,"e":"Мәтіндегі деректер «Сыртқы соғыс пен ішкі тартыстар әлсіреуге бірге ықпал етті» деген жауапты негіздейді. Құндызша шайқасы Терек шайқасынан бұрын өтті.","l":"B","topic":"Тоқтамыс пен Әмір Темір: шайқастар тізбегі"},{"id":"hce-38-5","t":"«Тоқтамыс пен Әмір Темір: шайқастар тізбегі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Құндызша шайқасы Терек шайқасынан бұрын өтті","XIV ғасырдың соңында Әмір Темір мен Тоқтамыс арасында соғыс жүрді.","Сыртқы соғыс пен ішкі тартыстар әлсіреуге бірге ықпал етті","Терек шайқасы Құндызшадан бұрын болды"],"a":3,"e":"Мәтіндегі деректер «Терек шайқасы Құндызшадан бұрын болды» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сыртқы соғыс пен ішкі тартыстар әлсіреуге бірге ықпал етті.","l":"C","topic":"Тоқтамыс пен Әмір Темір: шайқастар тізбегі"}]},{"id":"hcl-38","title":"Семей полигонының жабылуы","text":"Қазақстандағы ядролық сынақтар адам денсаулығы мен табиғатқа ауыр зиян келтірді. Қоғамдық қарсылық пен саяси шешімдер ядролық қауіпсіздік мәселесін халықаралық деңгейге шығарды.\n\nСемей ядролық полигонында алғашқы сынақ 1949 жылы өткізілді. Семей ядролық полигоны 1991 жылғы 29 тамызда жабылды. 1989 жылы құрылған Невада–Семей қозғалысы ядролық сынақтарға қарсы күресті. Невада–Семей қозғалысының бастамашысы ақын Олжас Сүлейменов болды. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6},"questions":[{"id":"hcl-38-1","t":"«Семей полигонының жабылуы» контексі: Семей полигонындағы алғашқы ядролық сынақ қай жылы өтті?","o":["1920 жылы","1991 жылы","1916 жылы","1949 жылы"],"a":3,"e":"Семей ядролық полигонында алғашқы сынақ 1949 жылы өткізілді.","l":"A","topic":"Семей полигонының жабылуы"},{"id":"hcl-38-2","t":"«Семей полигонының жабылуы» контексі: Семей полигоны қай жылы жабылды?","o":["1991 жылы","1954 жылы","1979 жылы","2003 жылы"],"a":0,"e":"Семей ядролық полигоны 1991 жылғы 29 тамызда жабылды.","l":"A","topic":"Семей полигонының жабылуы"},{"id":"hcl-38-3","t":"«Семей полигонының жабылуы» контексі: Екі деректі сәйкестендіріңіз. 1) Семей полигонындағы алғашқы ядролық сынақ қай жылы өтті. 2) Ядролық сынақтарға қарсы қозғалыс қалай аталды.","o":["1 — 1916 жылы; 2 — Невада–Семей","1 — 1949 жылы; 2 — Алашорда","1 — 1920 жылы; 2 — Қосшы","1 — 1949 жылы; 2 — Невада–Семей"],"a":3,"e":"Семей ядролық полигонында алғашқы сынақ 1949 жылы өткізілді. 1989 жылы құрылған Невада–Семей қозғалысы ядролық сынақтарға қарсы күресті.","l":"B","topic":"Семей полигонының жабылуы"},{"id":"hcl-38-4","t":"«Семей полигонының жабылуы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Семей полигоны қай жылы жабылды? 2) Қозғалыс жетекшісі кім болды?","o":["1 — 1991 жылы; 2 — Олжас Сүлейменов","1 — 1954 жылы; 2 — Олжас Сүлейменов","1 — 1991 жылы; 2 — Санжар Асфендияров","1 — 1979 жылы; 2 — Ыбырай Алтынсарин"],"a":0,"e":"Семей ядролық полигоны 1991 жылғы 29 тамызда жабылды. Невада–Семей қозғалысының бастамашысы ақын Олжас Сүлейменов болды.","l":"B","topic":"Семей полигонының жабылуы"},{"id":"hcl-38-5","t":"«Семей полигонының жабылуы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Ядролық қауіпсіздік бағыты экологиялық және денсаулық мәселелерін саяси шешімдерден бөлек қарастыруды талап етті.","Полигонды жабу азаматтық белсенділікке қатысы жоқ, тек сынақтардың табиғи түрде аяқталуы болды.","Қоғамдық қозғалыстың пайда болуы полигонның зардаптары жабылғаннан кейін ғана белгілі болғанын көрсетеді.","Экологиялық зардаптар туралы қоғамдық үн мен полигонды жабу шешімі ядролық қауіпсіздік бағытын күшейтті."],"a":3,"e":"Экологиялық зардаптар туралы қоғамдық үн мен полигонды жабу шешімі ядролық қауіпсіздік бағытын күшейтті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Семей полигонының жабылуы"}]}]},{"number":39,"questions":[{"id":"hm-123","t":"1990–1995 жылдардағы оқиғаларды реттеп, мемлекеттік дамудағы қызметімен байланыстырыңыз. Қай қатар дұрыс?","o":["Тәуелсіздік заңы — 1990; декларация — 1991; Конституция — 1992; теңге — 1995","Декларация — ақша жүйесі; тәуелсіздік заңы — БҰҰ мүшелігі; теңге — жаңа рәміздер; Конституция — тың игеру","Теңге — 1990; декларация — 1991; тәуелсіздік заңы — 1993; Конституция — 1995","Декларация — егемендік қағидалары; тәуелсіздік заңы — дербес мемлекет; теңге — ақша жүйесі; 1995 жылғы Конституция — құқықтық құрылыс"],"a":3,"e":"1990 жылғы декларациядан кейін 1991 жылғы тәуелсіздік заңы қабылданды. Теңге 1993 жылы енгізілді, 1995 жылы Конституция референдумда қабылданды.","l":"C","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hi-080","t":"Даладағы жәрмеңкелердің экономикалық маңызын көрсетіңіз.","o":["Барлық тұрақты сауда орталықтарын жойды","Мал айырбасын заңмен тыйды","Ақша қолдануды толық тоқтатты","Мал шаруашылығын кеңірек тауар-ақша айналымына тартты"],"a":3,"e":"Жәрмеңкелер дала тұрғындары мен көпестерді тоғыстырып, тауар-ақша қатынастарын кеңейтті.","l":"B","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":161}},{"id":"hi-013","t":"1838 жылы Исатай Тайманұлы қаза тапқан шайқас қай жерде болды?","o":["Бұланты бойында","Аягөз бойында","Шу бойында","Ақбұлақ бойында"],"a":3,"e":"Исатай Тайманұлы 1838 жылғы Ақбұлақ шайқасында қаза тапты.","l":"A","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":184}},{"id":"ha-039","t":"Түрік қағанатының құрылған жылын көрсетіңіз.","o":["603 жыл","704 жыл","552 жыл","942 жыл"],"a":2,"e":"Бумын бастаған түріктер 552 жылы жужандар билігін жойып, қағанат құрды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"ha-095","t":"Қарахан мемлекетінде исламның мемлекеттік дін ретінде орнығуы қандай мәдени өзгеріске тікелей жағдай жасады?","o":["Жазба мәдениетті толық тоқтатуға","Барлық қала халқын көшпелі өмірге ауыстыруға","Қыш бұйымдар жасауды тыйым салуға","Мешіттер мен медреселер құрылысының дамуына"],"a":3,"e":"Ислам институттарының нығаюы мешіттер мен діни білім беретін медреселердің дамуына ықпал етті.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"hk-088","t":"Аңырақай мен Бұланты шайқастарын біріктіретін ортақ белгі қандай?","o":["Екеуі де жоңғарларға қарсы күреске жатады","Екеуі де Бұхар хандығына қарсы жорықтарға жатады","Екеуі де Моғолстанмен шекаралық күреске жатады","Екеуі де Ресей бекіністеріне шабуылдар болды"],"a":0,"e":"Бұланты мен Аңырақай XVIII ғасырдың алғашқы жартысындағы қазақ-жоңғар соғыстарының маңызды оқиғалары болды.","l":"A","topic":"Қазақ-жоңғар соғыстары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hk-123","t":"Жиембеттің Есім дәуірімен, Бұқардың Абылай дәуірімен байланысы қандай тұжырымға негіз болады?","o":["Екі жырау бір мезгілде бір ханның кеңесшісі болды","Жыраулар әр кезеңде саяси өмірге үн қосып отырды","Жыраулар мұрасы саяси мәселелерден толық оқшау болды","Жыраулық дәстүр бір ғана ханның сарайында қалыптасты"],"a":1,"e":"Екі түрлі ғасырдағы жыраулардың билік пен ел тағдыры туралы толғаулары жыраулық дәстүрдің қоғамдық рөлін көрсетеді.","l":"C","topic":"Жыраулар және саясат","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":157}},{"id":"hk-004","t":"Қазақ хандығының құрылуын 1465–1466 жылдармен байланыстырған тарихшы кім?","o":["Ахмет Йүгнеки","Әбу Насыр әл-Фараби","Махмұд Қашғари","Мұхаммед Хайдар Дулати"],"a":3,"e":"Мұхаммед Хайдар Дулати «Тарих-и Рашиди» еңбегінде Қазақ хандығының алғашқы кезеңі туралы мәлімет қалдырды.","l":"A","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":101}},{"id":"ha-043","t":"Батыс Түрік қағанатының құрылған жылын атаңыз.","o":["603 жыл","552 жыл","704 жыл","756 жыл"],"a":0,"e":"603 жылы Түрік қағанаты Батыс және Шығыс қағанаттарға бөлінді.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":51}},{"id":"hm-002","t":"1920 жылы құрылған Қазақ АКСР-інің алғашқы астанасы қай қала болды?","o":["Семей","Ақмешіт","Орынбор","Алматы"],"a":2,"e":"Автономияның алғашқы астанасы Орынбор болды; кейін астана Ақмешітке көшірілді.","l":"A","topic":"Қазақ АКСР","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}}],"contexts":[{"id":"hce-39","title":"Ақ Орда және саяси сабақтастық","text":"Ақ Орда Шығыс Дешті Қыпшақта маңызды саяси рөл атқарды. Сығанақ оның белгілі орталығы болды. Ұрыс хан тұсында мемлекет күшейді. Сырдария қалалары сауда мен егіншілік аймақтарына ықпал ету үшін маңызды еді. Ақ Ордадағы тайпалар кейінгі қазақ мемлекеттілігінің қалыптасуына қатысты. Бірақ сабақтастық барлық институт өзгеріссіз сақталды дегенді білдірмейді. Аумақ, халық және әулеттік байланыспен бірге жаңа саяси жағдай да қалыптасты. Қала мен даланы бірге қарастыру мемлекеттің тіректерін түсіндіреді. Бір орталықтың болуы оның аумағын қазіргі шекарамен дәл теңестіруге жеткіліксіз. Тарихи жалғастық өзгерістермен қатар өмір сүре алады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":148},"questions":[{"id":"hce-39-1","t":"«Ақ Орда және саяси сабақтастық» контексі: Ақ Орданың белгілі орталығы қайсы?","o":["Сығанақ","Жаңакент","Сарай-Бату","Суяб"],"a":0,"e":"Мәтіндегі деректер «Сығанақ» деген жауапты негіздейді. Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды.","l":"A","topic":"Ақ Орда және саяси сабақтастық"},{"id":"hce-39-2","t":"«Ақ Орда және саяси сабақтастық» контексі: Ақ Орданы күшейткен билеуші кім?","o":["Кир","Үшлік","Сұлу","Ұрыс хан"],"a":3,"e":"Мәтіндегі деректер «Ұрыс хан» деген жауапты негіздейді. Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды.","l":"A","topic":"Ақ Орда және саяси сабақтастық"},{"id":"hce-39-3","t":"«Ақ Орда және саяси сабақтастық» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Ақ Ордада қала мүддесі мүлде болмаған","Кейінгі хандық Ақ Орданың өзгермейтін дәл көшірмесі болған","Сабақтастық барлық институттың толық бірдейлігін білдіреді","Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды"],"a":3,"e":"Мәтіндегі деректер «Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды» деген жауапты негіздейді. Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды.","l":"B","topic":"Ақ Орда және саяси сабақтастық"},{"id":"hce-39-4","t":"«Ақ Орда және саяси сабақтастық» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Тарихи байланыс сақталса да саяси институттар өзгеруі мүмкін","Ортақ аумақ барлық билеушіні бір тұлға етеді","Қала мен дала саясаты бір-біріне әсер етпейді","Бір орталықтың атауы қазіргі шекараны толық анықтайды"],"a":0,"e":"Мәтіндегі деректер «Тарихи байланыс сақталса да саяси институттар өзгеруі мүмкін» деген жауапты негіздейді. Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды.","l":"B","topic":"Ақ Орда және саяси сабақтастық"},{"id":"hce-39-5","t":"«Ақ Орда және саяси сабақтастық» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Кейінгі хандық Ақ Орданың өзгермейтін дәл көшірмесі болған","Тарихи байланыс сақталса да саяси институттар өзгеруі мүмкін","Ақ Орда Шығыс Дешті Қыпшақпен байланысты болды","Ақ Орда Шығыс Дешті Қыпшақта маңызды саяси рөл атқарды."],"a":0,"e":"Мәтіндегі деректер «Кейінгі хандық Ақ Орданың өзгермейтін дәл көшірмесі болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Тарихи байланыс сақталса да саяси институттар өзгеруі мүмкін.","l":"C","topic":"Ақ Орда және саяси сабақтастық"}]},{"id":"hcl-39","title":"Егемендік декларациясы","text":"КСРО дағдарысы республикалардың құқықтары мен дербестігі туралы пікірталастарды күшейтті. Егемендік туралы декларация кейінгі тәуелсіздікке апаратын саяси-құқықтық қадамдардың бірі болды.\n\nҚазақ КСР-інің мемлекеттік егемендігі туралы декларация 1990 жылғы 25 қазанда қабылданды. Құжат республиканың егемендігін, аумақтық тұтастығы мен дербес құқықтарын жариялады. Егемендік декларациясы 1991 жылғы тәуелсіздік туралы заңнан бұрын қабылданды. Декларация мемлекеттілікті дамытуға бағытталған саяси-құқықтық құжат болды. Құқықтық сызба: 1990 жылғы егемендік декларациясы → 1991 жылғы тәуелсіздік туралы заң.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-39-1","t":"«Егемендік декларациясы» контексі: Қазақ КСР-інің егемендік декларациясы қай жылы қабылданды?","o":["1990 жылы","1993 жылы","1995 жылы","1986 жылы"],"a":0,"e":"Қазақ КСР-інің мемлекеттік егемендігі туралы декларация 1990 жылғы 25 қазанда қабылданды.","l":"A","topic":"Егемендік декларациясы"},{"id":"hcl-39-2","t":"«Егемендік декларациясы» контексі: Декларацияда қандай қағида маңызды болды?","o":["Барлық заңның жойылуы","Көшпелі империя құру","Республиканың мемлекеттік егемендігі","Хандық алым-салықтың қайтарылуы"],"a":2,"e":"Құжат республиканың егемендігін, аумақтық тұтастығы мен дербес құқықтарын жариялады.","l":"A","topic":"Егемендік декларациясы"},{"id":"hcl-39-3","t":"«Егемендік декларациясы» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақ КСР-інің егемендік декларациясы қай жылы қабылданды. 2) Егемендік декларациясы тәуелсіздік заңынан қашан қабылданды.","o":["1 — 1986 жылы; 2 — Бұрын","1 — 1990 жылы; 2 — Кейін","1 — 1990 жылы; 2 — Бұрын","1 — 1993 жылы; 2 — Сол күні"],"a":2,"e":"Қазақ КСР-інің мемлекеттік егемендігі туралы декларация 1990 жылғы 25 қазанда қабылданды. Егемендік декларациясы 1991 жылғы тәуелсіздік туралы заңнан бұрын қабылданды.","l":"B","topic":"Егемендік декларациясы"},{"id":"hcl-39-4","t":"«Егемендік декларациясы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Декларацияда қандай қағида маңызды болды? 2) Декларацияның сипаты қандай?","o":["1 — Көшпелі империя құру; 2 — Тек сауда шоты","1 — Республиканың мемлекеттік егемендігі; 2 — Тек көркем поэма","1 — Республиканың мемлекеттік егемендігі; 2 — Саяси-құқықтық құжат","1 — Хандық алым-салықтың қайтарылуы; 2 — Саяси-құқықтық құжат"],"a":2,"e":"Құжат республиканың егемендігін, аумақтық тұтастығы мен дербес құқықтарын жариялады. Декларация мемлекеттілікті дамытуға бағытталған саяси-құқықтық құжат болды.","l":"B","topic":"Егемендік декларациясы"},{"id":"hcl-39-5","t":"«Егемендік декларациясы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Тәуелсіздік туралы заң декларациядан бұрын қабылданып, кейін егемендік қағидаларымен толықтырылды.","Егемендік декларациясы мен тәуелсіздік туралы заңның атаулары әртүрлі болғанымен, олардың құқықтық қызметі толық бірдей болды.","Егемендік декларациясы мен тәуелсіздік туралы заң бір үдерістің әртүрлі құқықтық сатылары болды.","Декларация қабылданған сәтте тәуелсіз мемлекеттің барлық институттары мен халықаралық байланыстары толық қалыптасып бітті."],"a":2,"e":"Егемендік декларациясы мен тәуелсіздік туралы заң бір үдерістің әртүрлі құқықтық сатылары болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Егемендік декларациясы"}]}]},{"number":40,"questions":[{"id":"hk-094","t":"Жайылымды бір орында жыл бойы шамадан тыс пайдалану қаупін азайтқан дәстүрлі тәсіл қайсы?","o":["Қысқы қонысты жазғы өрістен мүлде ажыратпау","Маусымға қарай қоныс ауыстыру","Барлық табынды бір мезгілде бір аңғарға жинау","Жайылымды мал санына қарамастан бір орында пайдалану"],"a":1,"e":"Маусымдық көшу өсімдік жамылғысын сақтауға және әр кезеңдегі табиғи мүмкіндікті пайдалануға жағдай жасады.","l":"B","topic":"Маусымдық шаруашылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":117}},{"id":"hi-125","t":"Алашорда үкіметі мен Қазревкомды бір мекеме деп атау неге қате?","o":["Екеуі де XV ғасырдағы хан кеңестері болғандықтан","Олар әртүрлі саяси негізде және әр кезеңде құрылған басқару органдары","Олар тек мәдени журналдардың атауы болғандықтан","Екеуі де Ресей императорларының жеке атақтары болғандықтан"],"a":1,"e":"Алашорда 1917 жылы ұлттық автономия үкіметі ретінде құрылды. Қазревком 1919 жылы кеңестік уақытша басқару органы ретінде пайда болды.","l":"C","topic":"Азамат соғысы және мемлекеттілік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":228}},{"id":"ha-035","t":"Ғұндардың жоғарғы билеушісінің лауазымы қандай?","o":["Гурхан","Күнби","Шаньюй","Жабғу"],"a":2,"e":"Ғұн мемлекетінің жоғарғы билеушісі шаньюй, қазақша баламасында тәңірқұт деп аталды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-063","t":"Алаш партиясы мен Алашорда үкіметінің жетекшісі кім болды?","o":["Тұрар Рысқұлов","Сәкен Сейфуллин","Әлихан Бөкейхан","Амангелді Иманов"],"a":2,"e":"Әлихан Бөкейхан Алаш қозғалысының саяси жетекшісі болды. Екінші жалпықазақ съезі оны Алашорда төрағасы етіп сайлады.","l":"A","topic":"Алаш қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":240}},{"id":"hi-030","t":"1867–1868 жылғы ережелер бойынша облысты кім басқарды?","o":["Болыс басқарушысы","Аға сұлтан","Әскери губернатор","Ауыл старшыны"],"a":2,"e":"Облыс билігі әскери губернатордың қолына берілді. Бұл әскери-әкімшілік басқаруды күшейтті.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":150}},{"id":"hm-063","t":"Қазақстанның Мемлекеттік туы мен елтаңбасы қашан бекітілді?","o":["1993 жылғы 15 қарашада","1992 жылғы 4 маусымда","1997 жылғы 10 желтоқсанда","1990 жылғы 25 қазанда"],"a":1,"e":"Тәуелсіз елдің туы мен елтаңбасы 1992 жылғы 4 маусымда қабылданды.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"hm-008","t":"ЖЭС жағдайында шаруалар салықтан артылған өнімін қалай пайдалана алды?","o":["Нарықта сата алды","Егіншілікпен айналыса алмады","Тек тегін өткізуге міндеттелді","Сақтауға мүлде тыйым салынды"],"a":0,"e":"ЖЭС саудаға шектеулі еркіндік беріп, шаруашылықты қалпына келтіруге бағытталды.","l":"A","topic":"ЖЭС","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":272}},{"id":"hm-097","t":"Семей полигонының жабылуын бағалауда қандай саланы негізгі деп алу орынды?","o":["Ортағасырлық қала құрылысын","Патшалық қоныстандыру заңдарын","Жоңғар шапқыншылығының әскери тактикасын","Экологиялық қауіпсіздік пен бейбіт сыртқы саясатты"],"a":3,"e":"Полигонның жабылуы халық денсаулығы мен қоршаған ортаны қорғауға және ядролық қауіпсіздікке қатысты болды.","l":"B","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-077","t":"Хақназардың II Абдаллах пен Баба сұлтан тартысын пайдалануы қандай тәсілге жатады?","o":["Әулеттік биліктен бас тартып, кеңесті ғана қалдыру","Қарсыластар арасындағы қайшылықты дипломатиялық пайдалану","Қарсылас билеушілермен барлық байланысты тоқтату","Оңтүстіктегі қалалардан ерікті түрде бас тарту"],"a":1,"e":"Хақназар көрші билеушілердің өзара күресін Қазақ хандығының саяси мүддесіне пайдалануға ұмтылды.","l":"A","topic":"Хақназар ханның дипломатиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":114}},{"id":"ha-102","t":"Тұжырымдарды бағалаңыз: I. Ғұндардың жоғарғы билеушісі шаньюй аталды. II. Түрік қағанатын Сұлу құрды. III. Түрік қағанаты 552 жылы құрылды. Қайсысы дұрыс?","o":["I және III","II және III","Тек II","I және II"],"a":0,"e":"Ғұндарда шаньюй атауы қолданылды, Түрік қағанатын 552 жылы Бумын құрды; Сұлу — түргеш қағаны.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}}],"contexts":[{"id":"hce-40","title":"Моғолстан және Есенбұғаның шешімі","text":"Моғолстан XIV ғасырдың ортасында қалыптасты. Негізін қалаған хан ретінде Тоғылық Темір белгілі. Мемлекет аумағына Жетісу мен Шығыс Түркістан бөліктері кірді. Кейін Есенбұға Керей мен Жәнібек бастаған топты батыс Жетісуда қабылдады. Бұл шешім саяси мүдделермен байланысты болды. Қоныс аударушыларға орын беру жаңа хандықтың қалыптасуына жағдай жасады. Бірақ Қазақ хандығын Моғолстанның өзгермейтін жалғасы деп қарауға болмайды. Екі мемлекеттің өз билеушілері мен мүдделері болды. Көршілес биліктердің ынтымақтастығы жаңа саяси құрылымға алғышарт жасай алады. Байланыс пен дербестікті бір-біріне қарсы қою дұрыс емес.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":150},"questions":[{"id":"hce-40-1","t":"«Моғолстан және Есенбұғаның шешімі» контексі: Моғолстанның негізін қалаған кім?","o":["Батый","Тәуке","Әбілқайыр","Тоғылық Темір"],"a":3,"e":"Мәтіндегі деректер «Тоғылық Темір» деген жауапты негіздейді. Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды.","l":"A","topic":"Моғолстан және Есенбұғаның шешімі"},{"id":"hce-40-2","t":"«Моғолстан және Есенбұғаның шешімі» контексі: Керей мен Жәнібекті қабылдаған хан кім?","o":["Өзбек","Есенбұға","Сұлу","Қасым"],"a":1,"e":"Мәтіндегі деректер «Есенбұға» деген жауапты негіздейді. Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды.","l":"A","topic":"Моғолстан және Есенбұғаның шешімі"},{"id":"hce-40-3","t":"«Моғолстан және Есенбұғаның шешімі» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Моғолстан тек Еділ бойында орналасқан","Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды","Қазақ хандығы Моғолстанның өзгермейтін екінші атауы болған","Есенбұға мен Тоғылық Темір бір адамның екі аты"],"a":1,"e":"Мәтіндегі деректер «Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды» деген жауапты негіздейді. Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды.","l":"B","topic":"Моғолстан және Есенбұғаның шешімі"},{"id":"hce-40-4","t":"«Моғолстан және Есенбұғаның шешімі» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Байланыс пен дербестік қатар болуы мүмкін емес","Екі мемлекет байланысса олардың билігі міндетті түрде бірдей болады","Орын беру барлық бұрынғы мүдденің жойылуын білдіреді","Саяси ынтымақтастық дербес хандықтың қалыптасуына жағдай жасады"],"a":3,"e":"Мәтіндегі деректер «Саяси ынтымақтастық дербес хандықтың қалыптасуына жағдай жасады» деген жауапты негіздейді. Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды.","l":"B","topic":"Моғолстан және Есенбұғаның шешімі"},{"id":"hce-40-5","t":"«Моғолстан және Есенбұғаның шешімі» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Қазақ хандығы Моғолстанның өзгермейтін екінші атауы болған","Саяси ынтымақтастық дербес хандықтың қалыптасуына жағдай жасады","Моғолстан Жетісу және Шығыс Түркістанмен байланысты болды","Моғолстан XIV ғасырдың ортасында қалыптасты."],"a":0,"e":"Мәтіндегі деректер «Қазақ хандығы Моғолстанның өзгермейтін екінші атауы болған» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Саяси ынтымақтастық дербес хандықтың қалыптасуына жағдай жасады.","l":"C","topic":"Моғолстан және Есенбұғаның шешімі"}]},{"id":"hcl-40","title":"Қазақстанның тәуелсіздігі","text":"1991 жылы кеңестік саяси жүйе терең дағдарысқа ұшырап, одақтас республикалар тәуелсіздік жариялады. Қазақстан жаңа мемлекеттің құқықтық негіздері мен халықаралық қатынастарын қалыптастыра бастады.\n\n1991 жылғы 16 желтоқсанда мемлекеттік тәуелсіздік туралы конституциялық заң қабылданды. Қазақстанның тәуелсіздігін алғаш таныған мемлекет Түркия болды. Тәуелсіздік елге дербес ішкі және сыртқы саясат жүргізуге құқық берді. Егемен билік, аумақ және өз құқықтық жүйесі тәуелсіз мемлекеттің негізгі белгілеріне жатады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15},"questions":[{"id":"hcl-40-1","t":"«Қазақстанның тәуелсіздігі» контексі: Қазақстанның тәуелсіздігі туралы заң қашан қабылданды?","o":["1991 жылғы 16 желтоқсанда","1995 жылғы 30 тамызда","1990 жылғы 25 қазанда","1993 жылғы 15 қарашада"],"a":0,"e":"1991 жылғы 16 желтоқсанда мемлекеттік тәуелсіздік туралы конституциялық заң қабылданды.","l":"A","topic":"Қазақстанның тәуелсіздігі"},{"id":"hcl-40-2","t":"«Қазақстанның тәуелсіздігі» контексі: Қазақстан тәуелсіздігін алғаш таныған мемлекет қайсы?","o":["Бразилия","Түркия","Жапония","Канада"],"a":1,"e":"Қазақстанның тәуелсіздігін алғаш таныған мемлекет Түркия болды.","l":"A","topic":"Қазақстанның тәуелсіздігі"},{"id":"hcl-40-3","t":"«Қазақстанның тәуелсіздігі» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстанның тәуелсіздігі туралы заң қашан қабылданды. 2) Тәуелсіздік Қазақстанға қандай мүмкіндік берді.","o":["1 — 1990 жылғы 25 қазанда; 2 — Дербес сыртқы саясат жүргізу","1 — 1993 жылғы 15 қарашада; 2 — Өз аумағынан бас тарту","1 — 1991 жылғы 16 желтоқсанда; 2 — Одақтық орталыққа толық бағыну","1 — 1991 жылғы 16 желтоқсанда; 2 — Дербес сыртқы саясат жүргізу"],"a":3,"e":"1991 жылғы 16 желтоқсанда мемлекеттік тәуелсіздік туралы конституциялық заң қабылданды. Тәуелсіздік елге дербес ішкі және сыртқы саясат жүргізуге құқық берді.","l":"B","topic":"Қазақстанның тәуелсіздігі"},{"id":"hcl-40-4","t":"«Қазақстанның тәуелсіздігі» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Қазақстан тәуелсіздігін алғаш таныған мемлекет қайсы? 2) Тәуелсіз мемлекеттің басты белгілерінің бірі қандай?","o":["1 — Түркия; 2 — Егемен билік пен аумақ","1 — Түркия; 2 — Шетел ханын сайлау","1 — Жапония; 2 — Егемен билік пен аумақ","1 — Канада; 2 — Ортақ империялық салғырт"],"a":0,"e":"Қазақстанның тәуелсіздігін алғаш таныған мемлекет Түркия болды. Егемен билік, аумақ және өз құқықтық жүйесі тәуелсіз мемлекеттің негізгі белгілеріне жатады.","l":"B","topic":"Қазақстанның тәуелсіздігі"},{"id":"hcl-40-5","t":"«Қазақстанның тәуелсіздігі» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Тәуелсіздік туралы заң ішкі егемендікті дербес халықаралық қатынастар жүргізу құқығымен ұштастырды.","Тәуелсіздікті алғаш шетелдің тануы егемен биліктің өз аумағындағы құқықтық негізін қажетсіз етті.","Дербес сыртқы саясат ішкі егемендіктен бөлек қалыптасқандықтан, тәуелсіздік туралы заңмен байланыспады.","Заң қабылдануы халықаралық мойындауға қажетті барлық дипломатиялық қатынастардың бір мезетте аяқталғанын білдірді."],"a":0,"e":"Тәуелсіздік туралы заң ішкі егемендікті дербес халықаралық қатынастар жүргізу құқығымен ұштастырды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қазақстанның тәуелсіздігі"}]}]},{"number":41,"questions":[{"id":"hm-021","t":"1937–1938 жылдары Қазақстан қоғамын қамтыған саяси қасірет қандай?","o":["Жаппай саяси қуғын-сүргін","ЖЭС-тің басталуы","Ұлттық валютаның енгізілуі","Тың игеру"],"a":0,"e":"1937–1938 жылдар сталиндік жаппай қуғын-сүргіннің шарықтаған кезеңі болды.","l":"A","topic":"Қуғын-сүргін","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":227}},{"id":"hi-019","t":"Кенесары қозғалысына қатысқан белгілі батырды табыңыз.","o":["Бөгенбай","Қабанбай","Ағыбай","Қарасай"],"a":2,"e":"Ағыбай батыр Кенесарының серіктерінің бірі болды. Қалған тұлғалар басқа тарихи кезеңдерде өмір сүрген.","l":"A","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":176}},{"id":"hm-112","t":"Қоғамдық-саяси оқиғаларды реттеңіз: 1 — Желтоқсан; 2 — Целиноград наразылығы; 3 — мемлекеттік егемендік декларациясы; 4 — тілдер туралы заң; 5 — тәуелсіздік туралы заң.","o":["1–2–4–3–5","2–1–4–3–5","2–4–1–5–3","2–1–3–4–5"],"a":1,"e":"Целиноград — 1979, Желтоқсан — 1986, тілдер туралы заң — 1989, декларация — 1990, тәуелсіздік туралы заң — 1991 жыл.","l":"C","topic":"Хронология","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"hk-075","t":"Ноғай ұлыстарының Қазақ хандығына қосылуының тікелей нәтижесін көрсетіңіз.","o":["Хандықтың халқы мен әскери әлеуеті артты","Барлық қазақ тайпасы ноғай билеушісіне бағынды","Хандықтың батыстағы барлық жайылымы бос қалды","Хандықтың саяси орталығы міндетті түрде Алмалыққа көшті"],"a":0,"e":"Халық пен жайылымдық аумақтың ұлғаюы Хақназар тұсындағы хандықтың күшін арттырды.","l":"A","topic":"Хақназар хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":138}},{"id":"ha-022","t":"Кирдің сақтарға жорығы қай уақытқа жатады?","o":["Б.з.б. 530 жыл","Б.з.б. 209 жыл","Б.з. 552 жыл","Б.з. 751 жыл"],"a":0,"e":"Парсы патшасы Кирдің массагеттерге қарсы жорығы б.з.б. 530 жылмен байланыстырылады.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}},{"id":"ha-084","t":"Археологтар қала қабырғасынан тыс жерде шеберханалар мен сауда орындарын тапты. Бұл қаланың қай бөлігі болуы ықтимал?","o":["Рабад","Цитадель","Орталық бекініс","Хан сарайы"],"a":0,"e":"Рабад қаланың сыртқы қолөнер және сауда аймағы болды.","l":"B","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":54}},{"id":"hk-110","t":"Абылай өміріне қатысты оқиғалардың дұрыс тізбегін көрсетіңіз.","o":["Хан сайлану → тұтқыннан босау → жоңғар тұтқынына түсу","Тұтқыннан босау → хан сайлану → жоңғар тұтқынына түсу","Жоңғар тұтқынына түсу → тұтқыннан босау → хан сайлану","Жоңғар тұтқынына түсу → хан сайлану → тұтқыннан босау"],"a":2,"e":"Абылай 1741 жылы тұтқынға түсті, 1743 жылы босады, 1771 жылы хан сайланды.","l":"C","topic":"Абылай хан хронологиясы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-087","t":"1905 жылғы Қарқаралы петициясының мәні қандай болды?","o":["Кеңес Одағын тарату","Отарлық қысымға қарсы саяси талаптарды билікке жеткізу","Қазақ хандығын Жетісуда алғаш құру","Күштеп ұжымдастыруды бастау"],"a":1,"e":"Петиция жер, дін, білім және саяси құқық мәселелерін көтерді. Бұл ұлттық саяси белсенділіктің өсуін көрсетті.","l":"B","topic":"XX ғасыр басындағы қоғамдық ой","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":154}},{"id":"ha-049","t":"Атлах шайқасы қай жылы болды?","o":["603 жыл","552 жыл","751 жыл","960 жыл"],"a":2,"e":"751 жылы Талас маңында араб және Қытай әскерлері арасында Атлах шайқасы болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15}},{"id":"hk-082","t":"Орбұлақ оқиғасын қазақ-жоңғар соғыстарына жатқызуға негіз болатын белгі қайсы?","o":["Қазақ қолының Шайбани әулетімен соғысуы","Қазақ қолының Қоқан әскерімен соғысуы","Қазақ қолының Бұхар әскеріне қарсы соғысуы","Жәңгір қолының жоңғар әскеріне қарсы соғысуы"],"a":3,"e":"1643 жылғы Орбұлақ шайқасында Қазақ хандығы Жоңғар хандығының әскерімен соғысты.","l":"A","topic":"Орбұлақ шайқасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":142}}],"contexts":[{"id":"hce-41","title":"Әбілқайыр хандығындағы дағдарыс","text":"XV ғасырда Шығыс Дешті Қыпшақта Әбілқайыр хандығы билік жүргізді. Ол көшпелі өзбектер мемлекеті деп те аталады. Әбілқайыр 1428 жылы хан болды. 1457 жылы ойраттардан жеңілу оның беделін әлсіретті. Ішкі тартыстар да тұрақтылыққа әсер етті. Керей мен Жәнібектің Моғолстанға көшуі осы ортада қарастырылады. Көшуді тек бір шайқастың автоматты нәтижесі деу жеткіліксіз. Наразылық, тайпалық мүдде және дербестікке ұмтылыс ұштасқан. Ішкі дағдарыс жаңа бірлестікке алғышарт болды. Сыртқы жеңіліс билікке қатынасты өзгертуі мүмкін, бірақ барлық шешімді жалғыз өзі анықтамайды. Саяси үдерістің бірнеше себебін қатар талдау қажет.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":150},"questions":[{"id":"hce-41-1","t":"«Әбілқайыр хандығындағы дағдарыс» контексі: Әбілқайыр хан болған жыл қайсы?","o":["1206","1312","1465","1428"],"a":3,"e":"Мәтіндегі деректер «1428» деген жауапты негіздейді. Хандық көшпелі өзбектер мемлекеті деп те аталды.","l":"A","topic":"Әбілқайыр хандығындағы дағдарыс"},{"id":"hce-41-2","t":"«Әбілқайыр хандығындағы дағдарыс» контексі: 1457 жылғы қарсылас кімдер болды?","o":["Манчжурлар","Арабтар","Ойраттар","Римдіктер"],"a":2,"e":"Мәтіндегі деректер «Ойраттар» деген жауапты негіздейді. Хандық көшпелі өзбектер мемлекеті деп те аталды.","l":"A","topic":"Әбілқайыр хандығындағы дағдарыс"},{"id":"hce-41-3","t":"«Әбілқайыр хандығындағы дағдарыс» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Әбілқайыр 1457 жылы алғаш хан болған","Хандықта ішкі тартыс мүлде болмаған","Көшуге тек бір шайқас әсер еткен","Хандық көшпелі өзбектер мемлекеті деп те аталды"],"a":3,"e":"Мәтіндегі деректер «Хандық көшпелі өзбектер мемлекеті деп те аталды» деген жауапты негіздейді. Хандық көшпелі өзбектер мемлекеті деп те аталды.","l":"B","topic":"Әбілқайыр хандығындағы дағдарыс"},{"id":"hce-41-4","t":"«Әбілқайыр хандығындағы дағдарыс» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Тайпалық мүдделердің еш рөлі болмаған","Сыртқы жеңіліс билеуші беделіне ықпал етпейді","Сыртқы жеңіліс пен ішкі наразылықты байланыстыра талдау қажет","Бір соғыс барлық саяси шешімді автоматты туғызады"],"a":2,"e":"Мәтіндегі деректер «Сыртқы жеңіліс пен ішкі наразылықты байланыстыра талдау қажет» деген жауапты негіздейді. Хандық көшпелі өзбектер мемлекеті деп те аталды.","l":"B","topic":"Әбілқайыр хандығындағы дағдарыс"},{"id":"hce-41-5","t":"«Әбілқайыр хандығындағы дағдарыс» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["XV ғасырда Шығыс Дешті Қыпшақта Әбілқайыр хандығы билік жүргізді.","Көшуге тек бір шайқас әсер еткен","Сыртқы жеңіліс пен ішкі наразылықты байланыстыра талдау қажет","Хандық көшпелі өзбектер мемлекеті деп те аталды"],"a":1,"e":"Мәтіндегі деректер «Көшуге тек бір шайқас әсер еткен» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сыртқы жеңіліс пен ішкі наразылықты байланыстыра талдау қажет.","l":"C","topic":"Әбілқайыр хандығындағы дағдарыс"}]},{"id":"hcl-41","title":"Мемлекеттік рәміздер","text":"Тәуелсіздіктен кейін жаңа мемлекеттің бірегейлігін білдіретін рәміздер қабылданды. Ту мен Елтаңба тарихи мұра мен ортақ болашақ туралы идеяларды бейнеледі.\n\nҚазақстанның Мемлекеттік Туы мен Елтаңбасы 1992 жылғы 4 маусымда қабылданды. Мемлекеттік Тудың авторы — суретші Шәкен Ниязбеков. Елтаңбаның ортасындағы шаңырақ ортақ үй мен бірлікті бейнелейді. Рәміздер мемлекеттің егемендігін, бірегейлігін және азаматтардың ортақ құндылықтарын білдіреді. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14},"questions":[{"id":"hcl-41-1","t":"«Мемлекеттік рәміздер» контексі: Қазақстанның Туы мен Елтаңбасы қай күні қабылданды?","o":["1995 жылғы 30 тамызда","1991 жылғы 16 желтоқсанда","1993 жылғы 15 қарашада","1992 жылғы 4 маусымда"],"a":3,"e":"Қазақстанның Мемлекеттік Туы мен Елтаңбасы 1992 жылғы 4 маусымда қабылданды.","l":"A","topic":"Мемлекеттік рәміздер"},{"id":"hcl-41-2","t":"«Мемлекеттік рәміздер» контексі: Мемлекеттік Тудың авторы кім?","o":["Ахмет Байтұрсынұлы","Қаныш Сәтбаев","Шәкен Ниязбеков","Мұхтар Әуезов"],"a":2,"e":"Мемлекеттік Тудың авторы — суретші Шәкен Ниязбеков.","l":"A","topic":"Мемлекеттік рәміздер"},{"id":"hcl-41-3","t":"«Мемлекеттік рәміздер» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстанның Туы мен Елтаңбасы қай күні қабылданды. 2) Елтаңбаның орталық бейнесі қандай.","o":["1 — 1991 жылғы 16 желтоқсанда; 2 — Шаңырақ","1 — 1992 жылғы 4 маусымда; 2 — Теңіз кемесі","1 — 1992 жылғы 4 маусымда; 2 — Шаңырақ","1 — 1993 жылғы 15 қарашада; 2 — Бу машинасы"],"a":2,"e":"Қазақстанның Мемлекеттік Туы мен Елтаңбасы 1992 жылғы 4 маусымда қабылданды. Елтаңбаның ортасындағы шаңырақ ортақ үй мен бірлікті бейнелейді.","l":"B","topic":"Мемлекеттік рәміздер"},{"id":"hcl-41-4","t":"«Мемлекеттік рәміздер» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Мемлекеттік Тудың авторы кім? 2) Мемлекеттік рәміздердің ортақ қызметі қандай?","o":["1 — Ахмет Байтұрсынұлы; 2 — Тек шекара күзету","1 — Шәкен Ниязбеков; 2 — Мемлекеттік бірегейлікті білдіру","1 — Қаныш Сәтбаев; 2 — Мемлекеттік бірегейлікті білдіру","1 — Шәкен Ниязбеков; 2 — Тек салық мөлшерін есептеу"],"a":1,"e":"Мемлекеттік Тудың авторы — суретші Шәкен Ниязбеков. Рәміздер мемлекеттің егемендігін, бірегейлігін және азаматтардың ортақ құндылықтарын білдіреді.","l":"B","topic":"Мемлекеттік рәміздер"},{"id":"hcl-41-5","t":"«Мемлекеттік рәміздер» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Ту мен Елтаңба қабылдануы егемендіктің құқықтық негіздерінің орнына тек көркем белгілер жеткілікті екенін көрсетті.","Рәміздер жаңа мемлекеттің егемендігін тарихи-мәдени мағынасы бар бейнелер арқылы танытты.","Рәміздердің ұлттық мәдени белгілерге сүйенуі олардың мемлекеттің ортақ азаматтық бірегейлігін білдіруіне кедергі болды.","Елтаңбадағы шаңырақ ортақ бірліктен гөрі әр өңірдің өз алдына саяси бөлінуін білдірді."],"a":1,"e":"Рәміздер жаңа мемлекеттің егемендігін тарихи-мәдени мағынасы бар бейнелер арқылы танытты. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Мемлекеттік рәміздер"}]}]},{"number":42,"questions":[{"id":"hk-003","t":"Есен-бұға екі қазақ сұлтанына Моғолстанның қай бөлігінен жер берді?","o":["Ферғана аңғарының ортасынан","Еділдің төменгі ағысынан","Батыс бөлігінен","Шығыс Түркістанның қиыр шығысынан"],"a":2,"e":"Керей мен Жәнібектің алғашқы қоныстары Моғолстанның батысындағы Шу мен Талас өңірінде болды.","l":"A","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":100}},{"id":"hi-061","t":"1916 жылғы Торғай көтерілісінің сардарбегі кім болды?","o":["Ұзақ Саурықұлы","Амангелді Иманов","Досан Тәжіұлы","Бекболат Әшекеев"],"a":1,"e":"Торғай көтерілісінде Амангелді Иманов әскери қолбасшы, сардарбек ретінде танылды.","l":"A","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":43}},{"id":"hi-105","t":"Жерді Ресей мемлекетінің меншігі деп жариялау мен қоныстандыру саясатының байланысын түсіндіретін жауапты таңдаңыз.","o":["Бұл қағида барлық қоныс аударушыларды елден шығарды","Мемлекеттік меншік қазақтардың жерін қайта бөлуге мәңгі тыйым салды","Мемлекеттік меншік қағидасы жерді империялық әкімшілік арқылы қайта бөлуге жағдай жасады","Жер мемлекеттік меншікке өткен соң отарлық әкімшілік жойылды"],"a":2,"e":"Жердің империялық мемлекеттік меншік деп танылуы әкімшілікке оны қоныстандыруға пайдалануға мүмкіндік берді. Сондықтан құқықтық өзгеріс жер қысымын күшейтті.","l":"C","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":154}},{"id":"hm-094","t":"Нарықтық экономикаға көшуге тән өзгерісті көрсетіңіз.","o":["Азық-түлік салғыртының міндетті енгізілуі","Барлық бағаның тек жоспармен біржола бекітілуі","Жеке кәсіптің толық жойылуы","Меншіктің әртүрлі нысандары мен бәсекенің дамуы"],"a":3,"e":"Нарықтық қатынастар меншік түрлерінің көптігіне және өндірушілер бәсекесіне сүйенеді.","l":"B","topic":"Тәуелсіздік","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-093","t":"1917 жылғы Ақпан революциясынан кейін Ресейде қандай билік құрылымы пайда болды?","o":["Түрік қағаны және жабғу","КСРО президенті және Жоғарғы Кеңес","Хан кеңесі және ұлыс бектері","Уақытша үкімет және жұмысшы-солдат кеңестері"],"a":3,"e":"Патша билігі құлағаннан кейін Уақытша үкімет пен кеңестер қатар өмір сүрді. Бұл жағдай қос өкімет деп аталды.","l":"A","topic":"1917 жылғы революциялар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":220}},{"id":"ha-041","t":"Батыс бағыттағы түрік жорықтарын басқарған тұлғаны көрсетіңіз.","o":["Сұлу","Тоныкөк","Естеми","Күлтегін"],"a":2,"e":"Естеми түріктердің батысқа қарай кеңеюін басқарып, қағанаттың халықаралық ықпалын күшейтті.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"hk-083","t":"Тәуке тұсында билер ықпалының өсуі қандай саламен тікелей байланысты болды?","o":["Хан тағын әулеттік мұраға беру құқығының жойылуы","Әскерді тек дінбасылардың басқаруы","Дауларды шешу және ортақ саяси кеңеске қатысу","Сыртқы сауданың толық билерге өткізілуі"],"a":2,"e":"Билер құқықтық дауларды шешіп, билер кеңесі арқылы ел ішіндегі келісімге ықпал етті.","l":"B","topic":"Билердің рөлі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":128}},{"id":"ha-124","t":"Қала астық пен қолөнер бұйымын, ал көшпелілер ет пен жүн жеткізген. Осы айырбастың ұзақ мерзімді ықпалын таңдаңыз.","o":["Шаруашылықтардың мамандануы өзара экономикалық тәуелділікті нығайтты","Өнім түрлерінің әртүрлілігі айырбасты мүлде тоқтатты","Қалалар тек мал өнімін өндіруге көшіп, егіншілікті жойды","Айырбас барлық көшпелі қауымды бірден қалаға көшірді"],"a":0,"e":"Әр тараптың басқа өнім ұсынуы тұрақты айырбасқа қажеттілік туғызып, қала мен дала байланысын күшейтті.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hm-071","t":"1931–1933 жылдардағы ашаршылықтың демографиялық салдарын көрсетіңіз.","o":["Барлық халықтың қалаға ерікті туризмге баруы","Халықтың қырылуы мен жаппай босқыншылық","Сыртқы көші-қонның мүлде болмауы","Табиғи өсімнің тұрақты күрт артуы"],"a":1,"e":"Ашаршылық халық шығынына және Қазақстаннан тыс жерлерге босып кетуге әкелді.","l":"A","topic":"Ашаршылық","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hm-009","t":"«Кіші Қазан» бағытын Қазақстанда жүргізген басшы кім?","o":["Жұмабай Шаяхметов","Геннадий Колбин","Филипп Голощекин","Дінмұхамед Қонаев"],"a":2,"e":"Ф.Голощекин қазақ ауылында «Кіші Қазан» саясатын жүргізді.","l":"A","topic":"Ұжымдастыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":238}}],"contexts":[{"id":"hce-42","title":"Ноғай Ордасы: саяси өзгеріс және ортақ мұра","text":"Ноғай Ордасы Еділ мен Жайық арасындағы кеңістікпен байланысты. Оның тарихында Едіге мен маңғыт ақсүйектері маңызды орын алды. Сарайшық белгілі орталық болды. Орда тайпалары көрші хандықтармен байланысқан. Кейін олардың бір бөлігі Қазақ хандығына қосылды. Бұл саяси және этникалық үдерістердің байланысын көрсетеді. Бағыныштылықтың өзгеруі мәдениеттің бірден толық жоғалуы емес. Ноғай және қазақ тарихындағы ортақ жырлар тарихи жақындықты түсіндіреді. Бірақ ортақ мұра екі құрылымның барлық кезеңде бірдей болғанын білдірмейді. Саяси дербестік пен мәдени байланыс қатар өмір сүре алады. Тарихи бағада осы айырмашылықты сақтау маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":149},"questions":[{"id":"hce-42-1","t":"«Ноғай Ордасы: саяси өзгеріс және ортақ мұра» контексі: Ноғай Ордасының негізгі кеңістігі қайсы?","o":["Еділ мен Жайық аралығы","Ніл мен Тигр аралығы","Шу мен Іле аралығы","Сена мен Темза аралығы"],"a":0,"e":"Мәтіндегі деректер «Еділ мен Жайық аралығы» деген жауапты негіздейді. Сарайшық Ноғай Ордасының белгілі орталығы болды.","l":"A","topic":"Ноғай Ордасы: саяси өзгеріс және ортақ мұра"},{"id":"hce-42-2","t":"«Ноғай Ордасы: саяси өзгеріс және ортақ мұра» контексі: Орда тарихындағы маңызды тұлға кім?","o":["Бумын","Едіге","Мұса","Томирис"],"a":1,"e":"Мәтіндегі деректер «Едіге» деген жауапты негіздейді. Сарайшық Ноғай Ордасының белгілі орталығы болды.","l":"A","topic":"Ноғай Ордасы: саяси өзгеріс және ортақ мұра"},{"id":"hce-42-3","t":"«Ноғай Ордасы: саяси өзгеріс және ортақ мұра» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Саяси бағыныштылық өзгерсе мәдениет бірден түгел жойылады","Ноғай Ордасы тек Шығыс Түркістанда орналасқан","Сарайшық Ноғай Ордасының белгілі орталығы болды","Ортақ жыр екі мемлекеттің барлық тарихы бірдей болғанын дәлелдейді"],"a":2,"e":"Мәтіндегі деректер «Сарайшық Ноғай Ордасының белгілі орталығы болды» деген жауапты негіздейді. Сарайшық Ноғай Ордасының белгілі орталығы болды.","l":"B","topic":"Ноғай Ордасы: саяси өзгеріс және ортақ мұра"},{"id":"hce-42-4","t":"«Ноғай Ордасы: саяси өзгеріс және ортақ мұра» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Ортақ мұра жақындықты көрсетеді, бірақ саяси құрылымдарды толық теңестірмейді","Саяси дербестік мәдени байланысқа кедергі","Бір жыр мемлекеттік шекараны толық анықтайды","Тайпалар ешқашан басқа хандыққа қосыла алмайды"],"a":0,"e":"Мәтіндегі деректер «Ортақ мұра жақындықты көрсетеді, бірақ саяси құрылымдарды толық теңестірмейді» деген жауапты негіздейді. Сарайшық Ноғай Ордасының белгілі орталығы болды.","l":"B","topic":"Ноғай Ордасы: саяси өзгеріс және ортақ мұра"},{"id":"hce-42-5","t":"«Ноғай Ордасы: саяси өзгеріс және ортақ мұра» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Ортақ мұра жақындықты көрсетеді, бірақ саяси құрылымдарды толық теңестірмейді","Ноғай Ордасы Еділ мен Жайық арасындағы кеңістікпен байланысты.","Сарайшық Ноғай Ордасының белгілі орталығы болды","Ортақ жыр екі мемлекеттің барлық тарихы бірдей болғанын дәлелдейді"],"a":3,"e":"Мәтіндегі деректер «Ортақ жыр екі мемлекеттің барлық тарихы бірдей болғанын дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Ортақ мұра жақындықты көрсетеді, бірақ саяси құрылымдарды толық теңестірмейді.","l":"C","topic":"Ноғай Ордасы: саяси өзгеріс және ортақ мұра"}]},{"id":"hcl-42","title":"Ұлттық валюта — теңге","text":"Нарыққа көшу кезінде Қазақстанға дербес ақша-несие саясатын жүргізу қажет болды. Ұлттық валюта енгізу мемлекеттік егемендіктің экономикалық тетіктерін қалыптастырды.\n\nҚазақстанның ұлттық валютасы теңге 1993 жылғы 15 қарашада айналымға енгізілді. Теңге тәуелсіз Қазақстанның ұлттық ақша бірлігі болды. Ұлттық валюта дербес ақша-несие саясатын жүргізудің маңызды тетігіне айналды. Теңгені енгізу экономикалық егемендікті нығайту және нарыққа көшу үдерісімен байланысты болды. Сабақтастық сызбасы: 1991 жылғы саяси тәуелсіздік → 1993 жылғы ұлттық валютаның енгізілуі.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-42-1","t":"«Ұлттық валюта — теңге» контексі: Теңге айналымға қай жылы енгізілді?","o":["1995 жылы","1991 жылы","1997 жылы","1993 жылы"],"a":3,"e":"Қазақстанның ұлттық валютасы теңге 1993 жылғы 15 қарашада айналымға енгізілді.","l":"A","topic":"Ұлттық валюта — теңге"},{"id":"hcl-42-2","t":"«Ұлттық валюта — теңге» контексі: Теңге қандай мемлекеттің ұлттық валютасы?","o":["Өзбекстанның","Қырғызстанның","Түркияның","Қазақстанның"],"a":3,"e":"Теңге тәуелсіз Қазақстанның ұлттық ақша бірлігі болды.","l":"A","topic":"Ұлттық валюта — теңге"},{"id":"hcl-42-3","t":"«Ұлттық валюта — теңге» контексі: Екі деректі сәйкестендіріңіз. 1) Теңге айналымға қай жылы енгізілді. 2) Ұлттық валютаны енгізу қандай саясатқа мүмкіндік берді.","o":["1 — 1993 жылы; 2 — Дербес ақша-несие саясатына","1 — 1993 жылы; 2 — Хандық мұрагерлікке","1 — 1995 жылы; 2 — Округтік сот жүйесіне","1 — 1991 жылы; 2 — Дербес ақша-несие саясатына"],"a":0,"e":"Қазақстанның ұлттық валютасы теңге 1993 жылғы 15 қарашада айналымға енгізілді. Ұлттық валюта дербес ақша-несие саясатын жүргізудің маңызды тетігіне айналды.","l":"B","topic":"Ұлттық валюта — теңге"},{"id":"hcl-42-4","t":"«Ұлттық валюта — теңге» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Теңге қандай мемлекеттің ұлттық валютасы? 2) Теңгені енгізу қай үдеріспен байланысты?","o":["1 — Қазақстанның; 2 — Полигонда сынақты көбейтумен","1 — Қырғызстанның; 2 — Экономикалық егемендікті нығайтумен","1 — Қазақстанның; 2 — Экономикалық егемендікті нығайтумен","1 — Өзбекстанның; 2 — Хандықтарды қайта құрумен"],"a":2,"e":"Теңге тәуелсіз Қазақстанның ұлттық ақша бірлігі болды. Теңгені енгізу экономикалық егемендікті нығайту және нарыққа көшу үдерісімен байланысты болды.","l":"B","topic":"Ұлттық валюта — теңге"},{"id":"hcl-42-5","t":"«Ұлттық валюта — теңге» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Теңге енгізілуі экономикалық егемендік саяси тәуелсіздіктен бұрын толық қалыптасқанын дәлелдейді.","Ұлттық валюта мемлекеттің экономикалық саясатына емес, тек банкноттардың сыртқы безендірілуіне қатысты өзгеріс болды.","Саяси тәуелсіздікпен бірге ұлттық ақша жүйесін қалыптастыру экономикалық дербестікті қамтамасыз етуге бағытталды.","Саяси тәуелсіздік алынғаннан кейін ақша-несие саясатына дербес тетік құру қажеттігі қалмады."],"a":2,"e":"Саяси тәуелсіздікпен бірге ұлттық ақша жүйесін қалыптастыру экономикалық дербестікті қамтамасыз етуге бағытталды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Ұлттық валюта — теңге"}]}]},{"number":43,"questions":[{"id":"hk-009","t":"Қазақ халқының этникалық негізі қалай қалыптасты?","o":["Бір ғана сырттан келген тайпадан","Тек бір діни қауымнан","Тек қала қолөнершілерінің бірігуінен","Қазақстан аумағындағы тайпалардың тарихи бірігуі арқылы"],"a":3,"e":"Қазақ халқының қалыптасуы Қазақстан аумағында ұзақ уақыт өмір сүрген тайпалардың тарихи сабақтастығына сүйенді.","l":"A","topic":"Қазақ халқының қалыптасуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":11}},{"id":"hm-033","t":"Соғыс кезінде Қазақстанға көшірілген кәсіпорындарды орналастыру үдерісі қалай аталады?","o":["Жекешелендіру","Эвакуация","Репатриация","Демаркация"],"a":1,"e":"Эвакуация өндіріс орындарын соғыс қаупі бар өңірлерден тылға көшіруді білдіреді.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"ha-010","t":"Ботай мәдениетін зерттеу қай жануардың ерте қолға үйретілуімен тығыз байланысты?","o":["Бұғы","Есек","Жылқы","Түйе"],"a":2,"e":"Ботай қонысынан табылған көптеген жылқы сүйектері жылқыны ерте пайдалану мен қолға үйрету мәселесін зерттеуге негіз болды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-101","t":"1920–1946 жылдардағы мәдени өзгерістерді сәйкестендіріңіз: А — кәсіби театрдың ашылуы; Ә — Қазақ педагогикалық институтының ашылуы; Б — Қазақ КСР Ғылым академиясының құрылуы. 1 — 1928; 2 — 1946; 3 — 1926.","o":["А–1, Ә–3, Б–2","А–3, Ә–2, Б–1","А–3, Ә–1, Б–2","А–2, Ә–1, Б–3"],"a":2,"e":"Кәсіби театр 1926 жылы, педагогикалық институт 1928 жылы, Ғылым академиясы 1946 жылы ашылды. Үш мекеме мәдениет, жоғары білім және ғылымның дамуын білдіреді.","l":"C","topic":"Мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-070","t":"Махамбеттің тарихи рөлін толық сипаттайтын жауапты таңдаңыз.","o":["Көтеріліс басшысы әрі күрес идеясын жырлаған ақын","Генерал-губернатор әрі әскери губернатор","Империялық реформалардың жобалаушысы","Шетелдік саяхатшы әрі археолог"],"a":0,"e":"Махамбет көтеріліске тікелей қатысты және оның еркіндік идеясын поэзиясында жеткізді.","l":"B","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":167}},{"id":"hk-044","t":"Әскери ерлігі үшін «Салқам» атанған қазақ ханы кім?","o":["Жәңгір","Қасым","Тәуекел","Бұрындық"],"a":0,"e":"Жәңгір хан жоңғарларға қарсы күрестегі ерлігімен танылып, «Салқам Жәңгір» аталды.","l":"A","topic":"Жәңгір хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"ha-089","t":"1203 жылы керейіттердің Шыңғыс ханнан жеңілуі қандай үдерістің бір бөлігі болды?","o":["Қарахан мемлекетінің ислам қабылдауы","Алтын Орданың тәуелсіз ұлыстарға ыдырауы","Моңғолиядағы тайпаларды бір билікке біріктіру","Қазақ хандығының Сыр бойына жорығы"],"a":2,"e":"Керейіттердің жеңілуі Шыңғыс ханның Моңғолиядағы қарсылас тайпалық бірлестіктерді бағындыру үдерісіне жатады.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-031","t":"1867–1868 жылғы реформалар бойынша облыстан кейінгі әкімшілік бірлік қандай болды?","o":["Округ","Уезд","Ұлыс","Қағанат"],"a":1,"e":"Әкімшілік жүйе генерал-губернаторлық–облыс–уезд–болыс–ауыл түрінде құрылды.","l":"A","topic":"1867–1868 жылдардағы реформалар","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"ha-056","t":"Қарахан мемлекетінде ислам мемлекеттік дін ретінде қабылданған жыл қайсы?","o":["751 жыл","960 жыл","1206 жыл","1312 жыл"],"a":1,"e":"960 жылы Мұса хан тұсында ислам Қарахан мемлекетінің мемлекеттік діні ретінде қабылданды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"hk-113","t":"Жаңадан құрылған хандықтың міндеттері берілген. Қай жұп сол кезеңге толық сәйкес келеді?","o":["Жүздерді округке бөлу және хандық билікті жою","Сұлтандар билігін тоқтату және тек билерге бағыну","Қазақ тайпаларын біріктіру және Сыр қалаларына орнығу","Сыр қалаларынан шегіну және Жетісудан толық көшу"],"a":2,"e":"Тайпаларды біріктіру мен Сыр қалалары үшін күрес XV–XVI ғасырлардағы хандықтың негізгі міндеттері болды.","l":"C","topic":"Алғашқы Қазақ хандығы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":140}}],"contexts":[{"id":"hce-43","title":"Қазақ халқы мен хандықтың қалыптасуы","text":"Қазақ халқының қалыптасуы ұзақ тарихи үдеріс болды. Тайпалардың байланысы, тілдік жақындық және ортақ шаруашылық кеңістігі оған ықпал етті. Саяси бірлестіктер ауысқанда барлық халықтық байланыс үзілген жоқ. XV ғасырда Қазақ хандығының құрылуы саяси ұйысуға жағдай жасады. Халықтың қалыптасуы мен мемлекеттің құрылуы өзара байланысты, бірақ бір ұғым емес. Тіл, мәдениет, аумақ және тарихи жад біртіндеп ортақтасты. Этникалық үдерісті бір күндік оқиғамен шектеуге болмайды. Бір ханның шешімі барлық алғышартты толық түсіндірмейді. Мемлекеттілік қалыптасқан ортада бұрынғы байланыстар мен жаңа саяси мүдделер ұштасқан. Өзгеріс пен сабақтастықты қатар қарастыру қажет.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":150},"questions":[{"id":"hce-43-1","t":"«Қазақ халқы мен хандықтың қалыптасуы» контексі: Мәтіндегі ұзақ үдеріс қайсы?","o":["Тек әскердің таратылуы","Халықтың қалыптасуы","Тек қаланың салынуы","Тек салықтың енгізілуі"],"a":1,"e":"Мәтіндегі деректер «Халықтың қалыптасуы» деген жауапты негіздейді. Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті.","l":"A","topic":"Қазақ халқы мен хандықтың қалыптасуы"},{"id":"hce-43-2","t":"«Қазақ халқы мен хандықтың қалыптасуы» контексі: Қазақ хандығы қай ғасырда құрылды?","o":["XVIII ғасыр","XV ғасыр","VI ғасыр","XI ғасыр"],"a":1,"e":"Мәтіндегі деректер «XV ғасыр» деген жауапты негіздейді. Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті.","l":"A","topic":"Қазақ халқы мен хандықтың қалыптасуы"},{"id":"hce-43-3","t":"«Қазақ халқы мен хандықтың қалыптасуы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті","Саяси билік ауысса барлық халықтық байланыс үзіледі","Мемлекет пен халықтың қалыптасуы толық бір ұғым","Халық бір күнде тек бір ханның шешімімен қалыптасты"],"a":0,"e":"Мәтіндегі деректер «Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті» деген жауапты негіздейді. Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті.","l":"B","topic":"Қазақ халқы мен хандықтың қалыптасуы"},{"id":"hce-43-4","t":"«Қазақ халқы мен хандықтың қалыптасуы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Тіл мен шаруашылық этникалық үдеріске ықпал етпейді","Этникалық үдеріс пен мемлекет құрылуын байланыстырып, ажыратып талдау керек","Хандықтың құрылуы бұрынғы мәдени байланыстарды толық жойды","Бір оқиға барлық ұзақ алғышартты толық түсіндіреді"],"a":1,"e":"Мәтіндегі деректер «Этникалық үдеріс пен мемлекет құрылуын байланыстырып, ажыратып талдау керек» деген жауапты негіздейді. Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті.","l":"B","topic":"Қазақ халқы мен хандықтың қалыптасуы"},{"id":"hce-43-5","t":"«Қазақ халқы мен хандықтың қалыптасуы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Этникалық үдеріс пен мемлекет құрылуын байланыстырып, ажыратып талдау керек","Қазақ халқының қалыптасуы ұзақ тарихи үдеріс болды.","Тілдік жақындық пен ортақ аумақ қалыптасуға ықпал етті","Халық бір күнде тек бір ханның шешімімен қалыптасты"],"a":3,"e":"Мәтіндегі деректер «Халық бір күнде тек бір ханның шешімімен қалыптасты» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Этникалық үдеріс пен мемлекет құрылуын байланыстырып, ажыратып талдау керек.","l":"C","topic":"Қазақ халқы мен хандықтың қалыптасуы"}]},{"id":"hcl-43","title":"1995 жылғы Конституция","text":"Тәуелсіз мемлекеттің саяси жүйесі құқықтық негіздерді нақтылауды қажет етті. Конституция мемлекеттік биліктің ұйымдасуын және азаматтардың негізгі құқықтарын бекітті.\n\nҚазақстан Республикасының Конституциясы 1995 жылғы 30 тамызда қабылданды. 1995 жылғы Конституция республикалық референдум арқылы қабылданды. Конституция мемлекеттің негізгі заңы және өзге заңдардың құқықтық негізі болып саналады. Конституция мемлекеттік биліктің құрылымын және адам мен азаматтың негізгі құқықтарын бекітеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-43-1","t":"«1995 жылғы Конституция» контексі: Қазіргі Конституцияның негізі болған құжат қай жылы қабылданды?","o":["1936 жылы","1920 жылы","1986 жылы","1995 жылы"],"a":3,"e":"Қазақстан Республикасының Конституциясы 1995 жылғы 30 тамызда қабылданды.","l":"A","topic":"1995 жылғы Конституция"},{"id":"hcl-43-2","t":"«1995 жылғы Конституция» контексі: Конституция қандай жолмен қабылданды?","o":["Шетел сотының шешімімен","Республикалық референдумда","Жәрмеңке жиналысында","Хан кеңесінде"],"a":1,"e":"1995 жылғы Конституция республикалық референдум арқылы қабылданды.","l":"A","topic":"1995 жылғы Конституция"},{"id":"hcl-43-3","t":"«1995 жылғы Конституция» контексі: Екі деректі сәйкестендіріңіз. 1) Қазіргі Конституцияның негізі болған құжат қай жылы қабылданды. 2) Конституцияның құқықтық орны қандай.","o":["1 — 1936 жылы; 2 — Тек сауда шарты","1 — 1995 жылы; 2 — Жеке ұйымның ережесі","1 — 1920 жылы; 2 — Мемлекеттің негізгі заңы","1 — 1995 жылы; 2 — Мемлекеттің негізгі заңы"],"a":3,"e":"Қазақстан Республикасының Конституциясы 1995 жылғы 30 тамызда қабылданды. Конституция мемлекеттің негізгі заңы және өзге заңдардың құқықтық негізі болып саналады.","l":"B","topic":"1995 жылғы Конституция"},{"id":"hcl-43-4","t":"«1995 жылғы Конституция» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Конституция қандай жолмен қабылданды? 2) Конституция реттейтін негізгі мәселе қайсы?","o":["1 — Шетел сотының шешімімен; 2 — Тек ауа райы","1 — Хан кеңесінде; 2 — Билік құрылымы мен азаматтардың құқықтары","1 — Республикалық референдумда; 2 — Билік құрылымы мен азаматтардың құқықтары","1 — Республикалық референдумда; 2 — Тек астық бағасы"],"a":2,"e":"1995 жылғы Конституция республикалық референдум арқылы қабылданды. Конституция мемлекеттік биліктің құрылымын және адам мен азаматтың негізгі құқықтарын бекітеді.","l":"B","topic":"1995 жылғы Конституция"},{"id":"hcl-43-5","t":"«1995 жылғы Конституция» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Конституцияның негізгі заң болуы өзге заңдардың оған сәйкестігін қарастыру қажеттігін жойды.","Референдум арқылы қабылдануы негізгі заңның тек дауыс бергендердің жеке қатынастарына қолданылатынын білдіреді.","Билік құрылымын бекіту азамат құқықтарының сол құқықтық жүйеден бөлек реттелуін талап етті.","Конституция билікті ұйымдастыру мен азамат құқықтарын бір құқықтық жүйеде байланыстырады."],"a":3,"e":"Конституция билікті ұйымдастыру мен азамат құқықтарын бір құқықтық жүйеде байланыстырады. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"1995 жылғы Конституция"}]}]},{"number":44,"questions":[{"id":"hm-027","t":"Бауыржан Момышұлының жауынгерлік жолы қай шайқаспен тығыз байланысты?","o":["Орбұлақ шайқасымен","Атлах шайқасымен","Аңырақай шайқасымен","Мәскеу үшін шайқаспен"],"a":3,"e":"Б.Момышұлы Панфилов дивизиясы құрамында Мәскеу түбіндегі шайқастарға қатысты.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":213}},{"id":"hm-098","t":"Ғылым академиясын құрудың ғылыми зерттеулерге әсері қандай болды?","o":["Жоғары білімді толығымен жойды","Барлық ғылыми жұмысты жеке үйірмелерге ғана қалдырды","Қазақстанда ғылыммен айналысуға тыйым салды","Зерттеулерді тұрақты ғылыми мекемелер арқылы ұйымдастыруға жағдай жасады"],"a":3,"e":"Академия зерттеу институттарын біріктіріп, ғылыми бағыттарды үйлестіруге мүмкіндік берді.","l":"B","topic":"Ғылым","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":214}},{"id":"hk-076","t":"Хақназардың II Абдаллахпен шарт жасасуын қандай мақсатпен байланыстыру орынды?","o":["Ноғай Ордасының ішкі билігін толық басқарумен","Мәскеуге қарсы тұрақты әскери одақ құрумен","Моғолстан тағына мұрагер ұсынумен","Оңтүстік шекарада қауіпсіздік пен одақтас іздеумен"],"a":3,"e":"Бұхар билеушісімен келісім оңтүстіктегі күрделі бәсекелестікте хандықтың мүддесін қорғауға бағытталды.","l":"B","topic":"Хақназар ханның дипломатиясы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":108}},{"id":"hk-019","t":"Қасым ханмен байланысты құқықтық ереже қалай аталады?","o":["«Есім ханның ескі жолы»","«Жеті жарғы»","«Сібір қырғыздары туралы жарғы»","«Қасым ханның қасқа жолы»"],"a":3,"e":"«Қасым ханның қасқа жолы» дәстүрлі әдет-ғұрып құқығын жүйелеумен байланысты.","l":"A","topic":"Қасым ханның заңдары","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"ha-029","t":"Бесшатыр сақ қорымы орналасқан тарихи аймақты атаңыз.","o":["Маңғыстау","Батыс Сібір","Торғай","Жетісу"],"a":3,"e":"Бесшатыр қорымы Іле аңғарындағы Жетісу сақтарының ірі ескерткіштерінің бірі.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":117}},{"id":"hi-099","t":"1919 жылы қазақ өлкесін басқару үшін құрылған уақытша орган қалай аталды?","o":["Алашорда","Мемлекеттік Дума","Уақытша үкімет","Қазревком"],"a":3,"e":"Қазақ революциялық комитеті — Қазревком — 1919 жылы құрылды. Ол кеңестік автономияны ұйымдастыруға қатысты.","l":"A","topic":"Қазревком және Қазақ АКСР","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":228}},{"id":"ha-104","t":"Түрік қағанаты 552 жылы құрылды, Атлах шайқасы 751 жылы өтті. Осы екі оқиғаның арасына қай оқиға орналасады?","o":["603 жылы Түрік қағанатының Батыс және Шығыс болып бөлінуі","1206 жылы Моңғол империясының жариялануы","960 жылы Қарахан мемлекетінде исламның мемлекеттік дін болуы","1348 жылы Моғолстанның құрылуы"],"a":0,"e":"603 жыл 552 жылдан кейін әрі 751 жылдан бұрын; қалған оқиғалар Атлах шайқасынан кейін болды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":51}},{"id":"hm-057","t":"Мемлекеттік егемендік туралы декларация қашан қабылданды?","o":["1990 жылғы 25 қазанда","1995 жылғы 30 тамызда","1993 жылғы 15 қарашада","1991 жылғы 16 желтоқсанда"],"a":0,"e":"Қазақ КСР-інің мемлекеттік егемендігі туралы декларация 1990 жылғы 25 қазанда қабылданды.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hi-109","t":"Жәрмеңкелердің өсуі мен өзен көлігінің дамуын біріктіретін экономикалық үрдіс қандай?","o":["Сауданың барлық түріне тыйым салынуы","Қала мен даланың байланысының біржола үзілуі","Натуралды шаруашылықтың толық оқшаулануы","Қазақстанның өңіраралық нарықтық байланыстарының кеңеюі"],"a":3,"e":"Жәрмеңке сауда орындарын, ал өзен көлігі тасымал жолдарын дамытты. Екеуі бірге өңіраралық айырбастың өсуіне ықпал етті.","l":"C","topic":"XIX ғасырдағы экономика","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":161}},{"id":"hi-003","t":"Кіші жүзде хандық билік қай жылы жойылды?","o":["1867 жылы","1822 жылы","1837 жылы","1824 жылы"],"a":3,"e":"Кіші жүзде 1824 жылғы реформа нәтижесінде хандық билік жойылды.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":171}}],"contexts":[{"id":"hce-44","title":"Керей мен Жәнібек: көшу және саяси орталық","text":"Керей мен Жәнібек бастаған топ Әбілқайыр билеген Дешті Қыпшақтан Моғолстанға көшті. Есенбұға оларға Шу мен Қозыбасы өңірінен орын берді. Оқиға туралы Мұхаммед Хайдар Дулатидың «Тарих-и Рашиди» еңбегінде мәлімет бар. Кейін жаңа орталыққа өзге топтар қосылды. Көшу хандықтың құрылуына алғышарт болды. Бұл тек мекен ауыстыру емес, дербестік пен жаңа одақ қалыптастыру мәселесі еді. Дулати оқиғадан кейінгі дәуірде жазғандықтан, хабарды басқа мәліметпен салыстыру қажет. Саяси орталықтың өсуі бір сәтте аяқталған жоқ. Қоныс, билік және халықтың бірігуін бірге қарастыру оның тарихи мәнін түсіндіреді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":150},"questions":[{"id":"hce-44-1","t":"«Керей мен Жәнібек: көшу және саяси орталық» контексі: Көшуді бастаған сұлтандар кімдер?","o":["Батый мен Берке","Керей мен Жәнібек","Бумын мен Сұлу","Қасым мен Тәуке"],"a":1,"e":"Мәтіндегі деректер «Керей мен Жәнібек» деген жауапты негіздейді. Көшу туралы Тарих-и Рашиди мәлімет береді.","l":"A","topic":"Керей мен Жәнібек: көшу және саяси орталық"},{"id":"hce-44-2","t":"«Керей мен Жәнібек: көшу және саяси орталық» контексі: Орын берілген өңір қайсы?","o":["Шу мен Қозыбасы","Ніл мен Синай","Еділ мен Қырым","Днепр мен Дон"],"a":0,"e":"Мәтіндегі деректер «Шу мен Қозыбасы» деген жауапты негіздейді. Көшу туралы Тарих-и Рашиди мәлімет береді.","l":"A","topic":"Керей мен Жәнібек: көшу және саяси орталық"},{"id":"hce-44-3","t":"«Керей мен Жәнібек: көшу және саяси орталық» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Көшуден кейін ешбір жаңа топ қосылмаған","Дулати оқиғаның тікелей қатысушысы болған","Көшу туралы Тарих-и Рашиди мәлімет береді","Көшу тек бір маусымдық мал айдау болды"],"a":2,"e":"Мәтіндегі деректер «Көшу туралы Тарих-и Рашиди мәлімет береді» деген жауапты негіздейді. Көшу туралы Тарих-и Рашиди мәлімет береді.","l":"B","topic":"Керей мен Жәнібек: көшу және саяси орталық"},{"id":"hce-44-4","t":"«Керей мен Жәнібек: көшу және саяси орталық» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Көшу жаңа саяси орталық пен дербес хандыққа жағдай жасады","Деректі салыстыру оның маңызын толық жоққа шығарады","Мекен ауыстыру саяси мүддемен еш байланыспайды","Хандықтың өсуі тек бір күнде аяқталған"],"a":0,"e":"Мәтіндегі деректер «Көшу жаңа саяси орталық пен дербес хандыққа жағдай жасады» деген жауапты негіздейді. Көшу туралы Тарих-и Рашиди мәлімет береді.","l":"B","topic":"Керей мен Жәнібек: көшу және саяси орталық"},{"id":"hce-44-5","t":"«Керей мен Жәнібек: көшу және саяси орталық» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Көшу жаңа саяси орталық пен дербес хандыққа жағдай жасады","Көшу тек бір маусымдық мал айдау болды","Көшу туралы Тарих-и Рашиди мәлімет береді","Керей мен Жәнібек бастаған топ Әбілқайыр билеген Дешті Қыпшақтан Моғолстанға көшті."],"a":1,"e":"Мәтіндегі деректер «Көшу тек бір маусымдық мал айдау болды» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Көшу жаңа саяси орталық пен дербес хандыққа жағдай жасады.","l":"C","topic":"Керей мен Жәнібек: көшу және саяси орталық"}]},{"id":"hcl-44","title":"Астананы көшіру","text":"Тәуелсіздік жылдары елдің саяси және кеңістіктік дамуына әсер еткен шешімдердің бірі қабылданды. Жаңа астана мемлекеттік басқару орталығы әрі елді танытатын символға айналды.\n\n1997 жылы ел астанасы Алматыдан Ақмолаға көшірілді. 1998 жылы Ақмола қаласының атауы Астана болып өзгертілді. Алматы астана көшірілгенге дейін республиканың саяси орталығы болды. Астананы көшіру мемлекеттік басқару орталығын елдің солтүстік-орталық бөлігіне ауыстырды. Уақыт сызбасы: Алматы → 1997 жылғы Ақмола → 1998 жылғы Астана атауы.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1},"questions":[{"id":"hcl-44-1","t":"«Астананы көшіру» контексі: Қазақстанның астанасы 1997 жылы қай қалаға көшірілді?","o":["Ақмолаға","Орынборға","Түркістанға","Қызылордаға"],"a":0,"e":"1997 жылы ел астанасы Алматыдан Ақмолаға көшірілді.","l":"A","topic":"Астананы көшіру"},{"id":"hcl-44-2","t":"«Астананы көшіру» контексі: Ақмола қаласы Астана атауын қай жылы алды?","o":["1998 жылы","1993 жылы","1991 жылы","2003 жылы"],"a":0,"e":"1998 жылы Ақмола қаласының атауы Астана болып өзгертілді.","l":"A","topic":"Астананы көшіру"},{"id":"hcl-44-3","t":"«Астананы көшіру» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстанның астанасы 1997 жылы қай қалаға көшірілді. 2) Астана көшіруге дейін астана болған қала қайсы.","o":["1 — Ақмолаға; 2 — Орал","1 — Орынборға; 2 — Тараз","1 — Қызылордаға; 2 — Алматы","1 — Ақмолаға; 2 — Алматы"],"a":3,"e":"1997 жылы ел астанасы Алматыдан Ақмолаға көшірілді. Алматы астана көшірілгенге дейін республиканың саяси орталығы болды.","l":"B","topic":"Астананы көшіру"},{"id":"hcl-44-4","t":"«Астананы көшіру» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Ақмола қаласы Астана атауын қай жылы алды? 2) Астананы көшірудің негізгі сипаты қандай?","o":["1 — 1998 жылы; 2 — Тек валюта атауын ауыстыру","1 — 1998 жылы; 2 — Мемлекеттік басқару орталығын өзгерту","1 — 1993 жылы; 2 — Тек шекараны жою","1 — 1991 жылы; 2 — Мемлекеттік басқару орталығын өзгерту"],"a":1,"e":"1998 жылы Ақмола қаласының атауы Астана болып өзгертілді. Астананы көшіру мемлекеттік басқару орталығын елдің солтүстік-орталық бөлігіне ауыстырды.","l":"B","topic":"Астананы көшіру"},{"id":"hcl-44-5","t":"«Астананы көшіру» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Астананы көшіру мен атауын өзгерту бір кезеңдегі оқиғалар болғандықтан, олардың мерзімін ажыратудың тарихи мәні жоқ.","Ақмола атауы Астана болып өзгерген соң ғана елдің басқару орталығын көшіру жүзеге асты.","Қала атауының өзгеруі астананы көшіруден бұрын өтіп, Алматының саяси орталық рөлін сол жылы аяқтады.","Астананы көшіру мен қала атауын өзгерту өзара байланысты, бірақ әр жылдары болған екі бөлек оқиға."],"a":3,"e":"Астананы көшіру мен қала атауын өзгерту өзара байланысты, бірақ әр жылдары болған екі бөлек оқиға. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Астананы көшіру"}]}]},{"number":45,"questions":[{"id":"hk-111","t":"Абылайдың Ресеймен де, Қытаймен де қатынас ұстауы туралы дерек қай қорытындыны ең жақсы негіздейді?","o":["Көршілердің барлығымен байланысты үзді","Екі империяның барлық аумағын басқарды","Дипломатиядан бас тартып, тек соғыс жүргізді","Бір ғана сыртқы күшке толық тәуелді болмауға ұмтылды"],"a":3,"e":"Көп бағыттағы қатынас Абылайдың көршілер арасындағы тепе-теңдікті хандық мүддесіне пайдаланғанын көрсетеді.","l":"C","topic":"Абылайдың сыртқы саясаты","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hk-073","t":"Хан жорыққа қатысатын жасақтардың міндетін реттеуі керек. Ол қандай құқықтық нормаларға сүйенеді?","o":["Тек елшілерді қабылдау нормаларына","Тек неке және отбасы нормаларына","Әскери міндеттерді белгілейтін нормаларға","Тек жерді мұраға қалдыру нормаларына"],"a":2,"e":"Қосын жинау, әскери тәртіп пен жауынгердің міндеттері әскери заңдармен реттелді.","l":"A","topic":"Дәстүрлі құқық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":129}},{"id":"hk-008","t":"Керей мен Жәнібек қай әулеттен тараған билеушілерге жатады?","o":["Темір әулетіне","Самани әулетіне","Жошы әулетіне","Сефеви әулетіне"],"a":2,"e":"Керей мен Жәнібек Шыңғыс ханның үлкен ұлы Жошыдан тараған әулет өкілдері болды.","l":"A","topic":"Қазақ хандығының әулеті","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-031","t":"Сталинград шайқасы қай жылдары өтті?","o":["1931–1933 жылдары","1942–1943 жылдары","1918–1920 жылдары","1954–1956 жылдары"],"a":1,"e":"Сталинград шайқасы 1942 жылдың жазынан 1943 жылдың ақпанына дейін созылды.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}},{"id":"ha-046","t":"Түргеш қағанатының негізін қалаған кім?","o":["Үшлік","Сұлу","Бумын","Мұқан"],"a":0,"e":"Үшлік қаған 704 жылы Түргеш қағанатының негізін қалады.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"ha-016","t":"Қола дәуірінің ескерткіштерін Орталық Қазақстанда жүйелі зерттеген ғалымды атаңыз.","o":["Шоқан Уәлиханов","Мұхаммед Хайдар Дулати","Әлкей Марғұлан","Махмұд Қашғари"],"a":2,"e":"Әлкей Марғұлан Орталық Қазақстан археологиялық экспедициясын басқарып, қола дәуірі мұрасын зерттеді.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hi-069","t":"Исатай–Махамбет көтерілісінің әлеуметтік себебін анықтаңыз.","o":["Жібек жолының жабылуы","Ұжымшарларға біріктіру","Жер тапшылығы мен алым-салықтың ауырлауы","Жоңғар шабуылының басталуы"],"a":2,"e":"Бөкей Ордасында жердің ықпалды топтардың қолына шоғырлануы және алымдар халық наразылығын күшейтті.","l":"B","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":43}},{"id":"ha-081","t":"Жібек жолынан жібекпен бірге діни мәтіндер мен көркем бұйымдар табылды. Бұл дерек жолдың қандай қызметін дәлелдейді?","o":["Тек әскери жорықтар үшін пайдаланылғанын","Саудамен қатар мәдени алмасу арнасы болғанын","Дін мен өнердің таралуына қатыспағанын","Тек бір мемлекеттің ішкі жолы болғанын"],"a":1,"e":"Тауарлармен бірге рухани және көркем мұраның таралуы Жібек жолының мәдени қызметін көрсетеді.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-121","t":"Қай салыстыру мәдени және ғылыми мекемелердің қалыптасу ретін де, қызметін де дұрыс көрсетеді?","o":["1926 — театр, геологиялық барлау; 1928 — Ғылым академиясы, сахна өнері; 1946 — педагогикалық институт, мұғалім даярлау","1926 — педагогикалық институт, мұғалім даярлау; 1928 — театр, сахна өнері; 1946 — Ғылым академиясы, зерттеулерді ұйымдастыру","1926 — театр, сахна өнері; 1928 — педагогикалық институт, мұғалім даярлау; 1946 — Ғылым академиясы, зерттеулерді ұйымдастыру","1926 — Ғылым академиясы, мұғалім даярлау; 1928 — педагогикалық институт, геологиялық барлау; 1946 — театр, сахна өнері"],"a":2,"e":"Кәсіби театр 1926 жылы, педагогикалық институт 1928 жылы, академия 1946 жылы ашылды. Олардың басты қызметтері тиісінше өнер, жоғары білім және ғылыми зерттеу болды.","l":"C","topic":"Мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-042","t":"XIX ғасырда көмір кенін игерумен танылған Қазақстан өңірін белгілеңіз.","o":["Қызылорда","Маңғыстау","Түркістан","Қарағанды"],"a":3,"e":"Қарағанды көмір кендері XIX ғасырда игеріле бастады. Бұл өлкенің өнеркәсіптік дамуына негіз болды.","l":"A","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":144}}],"contexts":[{"id":"hce-45","title":"Тарих-и Рашиди: құндылық және шектеу","text":"Мұхаммед Хайдар Дулати «Тарих-и Рашиди» еңбегін XVI ғасырда парсы тілінде жазды. Онда Моғолстан, қазақ хандары және Орталық Азия қатынастары баяндалады. Керей мен Жәнібектің көшуі, Қасым ханның беделі туралы мәлімет бар. Еңбек хандықтың алғашқы тарихына маңызды. Алайда әр санды қосымша дерексіз абсолют дәл көрсеткіш деп қабылдау дұрыс емес. Автордың уақыты, пайдаланған хабарлары және мақсаты ескеріледі. Еңбектің тілі, жазылған мерзімі және оқиға уақыты бөлек ұғымдар. Құнды дерек толық әрі қатесіз болмауы мүмкін. Сыни талдау деректің құнын жоймай, оны дұрыс пайдалануға көмектеседі.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":149},"questions":[{"id":"hce-45-1","t":"«Тарих-и Рашиди: құндылық және шектеу» контексі: Еңбектің авторы кім?","o":["Қадырғали Жалайыри","Мұхаммед Хайдар Дулати","Махмұд Қашқари","Жүсіп Баласағұни"],"a":1,"e":"Мәтіндегі деректер «Мұхаммед Хайдар Дулати» деген жауапты негіздейді. Тарих-и Рашиди XVI ғасырда жазылды.","l":"A","topic":"Тарих-и Рашиди: құндылық және шектеу"},{"id":"hce-45-2","t":"«Тарих-и Рашиди: құндылық және шектеу» контексі: Еңбек қай тілде жазылды?","o":["Қытай","Орыс","Латын","Парсы"],"a":3,"e":"Мәтіндегі деректер «Парсы» деген жауапты негіздейді. Тарих-и Рашиди XVI ғасырда жазылды.","l":"A","topic":"Тарих-и Рашиди: құндылық және шектеу"},{"id":"hce-45-3","t":"«Тарих-и Рашиди: құндылық және шектеу» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Парсы тілі оқиғаның тек Иранда болғанын дәлелдейді","Құнды деректің барлық санын тексерусіз дәл қабылдау қажет","Тарих-и Рашиди XVI ғасырда жазылды","Еңбек тек XVIII ғасырды сипаттайды"],"a":2,"e":"Мәтіндегі деректер «Тарих-и Рашиди XVI ғасырда жазылды» деген жауапты негіздейді. Тарих-и Рашиди XVI ғасырда жазылды.","l":"B","topic":"Тарих-и Рашиди: құндылық және шектеу"},{"id":"hce-45-4","t":"«Тарих-и Рашиди: құндылық және шектеу» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Бір мәлімет күмәнді болса бүкіл еңбек қажетсіз болады","Автор мақсаты тарихи талдауға қатыспайды","Автор ортасы мен өзге деректерді ескеру тарихи хабарды нақтылайды","Жазылған жыл мен сипатталған оқиға жылы міндетті түрде бірдей"],"a":2,"e":"Мәтіндегі деректер «Автор ортасы мен өзге деректерді ескеру тарихи хабарды нақтылайды» деген жауапты негіздейді. Тарих-и Рашиди XVI ғасырда жазылды.","l":"B","topic":"Тарих-и Рашиди: құндылық және шектеу"},{"id":"hce-45-5","t":"«Тарих-и Рашиди: құндылық және шектеу» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Тарих-и Рашиди XVI ғасырда жазылды","Құнды деректің барлық санын тексерусіз дәл қабылдау қажет","Автор ортасы мен өзге деректерді ескеру тарихи хабарды нақтылайды","Мұхаммед Хайдар Дулати «Тарих-и Рашиди» еңбегін XVI ғасырда парсы тілінде жазды."],"a":1,"e":"Мәтіндегі деректер «Құнды деректің барлық санын тексерусіз дәл қабылдау қажет» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Автор ортасы мен өзге деректерді ескеру тарихи хабарды нақтылайды.","l":"C","topic":"Тарих-и Рашиди: құндылық және шектеу"}]},{"id":"hcl-45","title":"БҰҰ және Қазақстан","text":"Тәуелсіз мемлекет халықаралық құқықтың толыққанды қатысушысы болуға ұмтылды. Халықаралық ұйымдарға қосылу елдің дипломатиялық байланыстарын кеңейтті.\n\nҚазақстан Біріккен Ұлттар Ұйымына 1992 жылғы 2 наурызда қабылданды. БҰҰ мемлекеттер арасындағы ынтымақтастық пен бейбітшілікті қолдайтын жаһандық ұйым. БҰҰ-ға кіру Қазақстанның тәуелсіз мемлекет ретіндегі халықаралық мойындалуын нығайтты. 1991 жылғы тәуелсіздік дербес сыртқы саясат пен халықаралық шарттар жасауға негіз берді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-45-1","t":"«БҰҰ және Қазақстан» контексі: Қазақстан БҰҰ-ға қай жылы мүше болды?","o":["1995 жылы","1986 жылы","1992 жылы","2010 жылы"],"a":2,"e":"Қазақстан Біріккен Ұлттар Ұйымына 1992 жылғы 2 наурызда қабылданды.","l":"A","topic":"БҰҰ және Қазақстан"},{"id":"hcl-45-2","t":"«БҰҰ және Қазақстан» контексі: БҰҰ қандай ұйым?","o":["Ортағасырлық хандық","Жаһандық халықаралық ұйым","Бір елдің саяси партиясы","Жергілікті жәрмеңке кеңесі"],"a":1,"e":"БҰҰ мемлекеттер арасындағы ынтымақтастық пен бейбітшілікті қолдайтын жаһандық ұйым.","l":"A","topic":"БҰҰ және Қазақстан"},{"id":"hcl-45-3","t":"«БҰҰ және Қазақстан» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстан БҰҰ-ға қай жылы мүше болды. 2) БҰҰ-ға мүшелік қандай мәртебені бекітті.","o":["1 — 1992 жылы; 2 — Тәуелсіз мемлекеттің халықаралық мойындалуын","1 — 1995 жылы; 2 — Хандық вассалдықты","1 — 1992 жылы; 2 — Отарлық облыс мәртебесін","1 — 1986 жылы; 2 — Тәуелсіз мемлекеттің халықаралық мойындалуын"],"a":0,"e":"Қазақстан Біріккен Ұлттар Ұйымына 1992 жылғы 2 наурызда қабылданды. БҰҰ-ға кіру Қазақстанның тәуелсіз мемлекет ретіндегі халықаралық мойындалуын нығайтты.","l":"B","topic":"БҰҰ және Қазақстан"},{"id":"hcl-45-4","t":"«БҰҰ және Қазақстан» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) БҰҰ қандай ұйым? 2) Елдің дербес сыртқы саясаты қай оқиғадан кейін мүмкін болды?","o":["1 — Жаһандық халықаралық ұйым; 2 — Тәуелсіздік алғаннан кейін","1 — Жаһандық халықаралық ұйым; 2 — 1822 жылғы жарғыдан кейін","1 — Жергілікті жәрмеңке кеңесі; 2 — Тәуелсіздік алғаннан кейін","1 — Бір елдің саяси партиясы; 2 — 1937 жылғы қуғын-сүргіннен кейін"],"a":0,"e":"БҰҰ мемлекеттер арасындағы ынтымақтастық пен бейбітшілікті қолдайтын жаһандық ұйым. 1991 жылғы тәуелсіздік дербес сыртқы саясат пен халықаралық шарттар жасауға негіз берді.","l":"B","topic":"БҰҰ және Қазақстан"},{"id":"hcl-45-5","t":"«БҰҰ және Қазақстан» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Қазақстанның халықаралық мойындалуы тәуелсіздік жариялауға дейін толық аяқталып, ұйымға кірумен байланыспады.","Тәуелсіздік алу мен БҰҰ-ға кіру ішкі егемендік пен халықаралық субъектіліктің қалыптасуын көрсетеді.","БҰҰ-ға кіру Қазақстанның дербес сыртқы саясат жүргізу құқығын ұйымға түгел тапсыруын білдірді.","Халықаралық ұйымға мүшелік ұлттық тәуелсіздік туралы заңның орнына қабылданған жалғыз құқықтық негіз болды."],"a":1,"e":"Тәуелсіздік алу мен БҰҰ-ға кіру ішкі егемендік пен халықаралық субъектіліктің қалыптасуын көрсетеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"БҰҰ және Қазақстан"}]}]},{"number":46,"questions":[{"id":"hm-048","t":"Сталиннің жеке басына табынуды сынаған партия съезі қайсы?","o":["КОКП-ның ХХ съезі","КОКП-ның І съезі","Қазақ кеңестерінің V съезі","РКП(б)-ның Х съезі"],"a":0,"e":"1956 жылғы ХХ съезде Сталиннің жеке басына табыну мәселесі көтерілді.","l":"A","topic":"Жылымық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":264}},{"id":"hm-078","t":"1947 жылғы карточкалық жүйенің жойылуы қай кезеңге жатады?","o":["ЖЭС-тің алғашқы жылдарына","Тың игерудің соңғы кезеңіне","Соғыстан кейінгі қалпына келтіру кезеңіне","Тәуелсіздік реформаларына"],"a":2,"e":"Карточкалық жүйе соғыс аяқталғаннан кейінгі қалпына келтіру жағдайында жойылды.","l":"B","topic":"Соғыстан кейінгі Қазақстан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"hk-071","t":"Қасым хан билігінің нәтижесін сипаттайтын тұжырымды таңдаңыз.","o":["Хандықта Шайбани әулетінің тікелей билігі орнады","Барлық сұлтанның дербес хандыққа бөлінуі аяқталды","Хандықтың аумағы кеңейіп, саяси беделі өсті","Қазақ хандығының Сыр өңірінен толық ығысуы жүзеге асты"],"a":2,"e":"Қасым дәуірі хандықтың күшеюімен және сыртқы дүниеге танылуымен сипатталады.","l":"B","topic":"Қасым хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":135}},{"id":"hk-014","t":"Қазақ хандығында хан тағына үміткерлер негізінен қай топтан шықты?","o":["Қолөнершілерден","Сұлтандардан","Құлдардан","Жалдамалы жұмысшылардан"],"a":1,"e":"Сұлтандар Шыңғыс хан әулетіне жатты және хандық билікке үміткер болуға әулеттік құқығы болды.","l":"A","topic":"Қазақ хандығының басқарылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":125}},{"id":"ha-073","t":"Ноғай Ордасының саяси орталығы болған қала қайсы?","o":["Суяб","Сарайшық","Талғар","Алмалық"],"a":1,"e":"Жайық бойындағы Сарайшық Ноғай Ордасының маңызды саяси орталығы болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"ha-108","t":"Екі тұрақтың бірінде тек аңшылық құралдары, екіншісінде дәнүккіш, орақ және қыш ыдыс табылды. Екінші тұрақтың шаруашылығын сипаттайтын негізді қорытындыны таңдаңыз.","o":["Аңшылықпен бірге өнім өндірудің нышандары болған","Астық түгелдей алыс мемлекеттерден әкелінген","Халық тек аң аулап, өсімдік өнімін пайдаланбаған","Барлық тұрғын маманданған темір ұстасы болған"],"a":0,"e":"Дән өңдеу және егін ору құралдары өндіруші шаруашылық белгілерін көрсетеді; олар сырттан әкелу немесе теміршілік туралы тұжырымға негіз болмайды.","l":"C","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-015","t":"«Бесеудің хаты» қай мәселені көтерді?","o":["Астананы Ақмолаға көшіруді","ЕҚЫҰ-ға төрағалық етуді","Ауылдағы ауыр жағдай мен ұжымдастыру зардаптарын","Тың игерудің алғашқы жоспарын"],"a":2,"e":"1932 жылғы хатта ұжымдастыру кезіндегі апат пен басшылықтың қателіктері сыналды.","l":"A","topic":"Ашаршылық","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-012","t":"1837 жылы Исатай жасағы патша әскерімен шайқасқан жерді көрсетіңіз.","o":["Орбұлақ","Тастөбе","Аңырақай","Атлах"],"a":1,"e":"Тастөбе шайқасы 1837 жылы өтті. Көтерілісшілер қаруы басым жазалаушы әскерге қарсы соғысты.","l":"A","topic":"Бөкей Ордасындағы көтеріліс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":184}},{"id":"hi-123","t":"Оқиғаларды реттеңіз: 1) 1916 жылғы көтеріліс; 2) 1905 жылғы Қарқаралы петициясы; 3) Алашорда үкіметінің құрылуы.","o":["2 → 3 → 1","3 → 1 → 2","2 → 1 → 3","1 → 2 → 3"],"a":2,"e":"Қарқаралы петициясы 1905 жылы жазылды. Көтеріліс 1916 жылы, Алашорда үкіметінің құрылуы 1917 жылы болды.","l":"C","topic":"XX ғасыр басындағы хронология","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":154}},{"id":"hi-094","t":"Алаш қозғалысының саяси бағдарламасына сәйкес келетін мақсат қандай?","o":["Қазақ жерін бөлшектеуді тереңдету","Отарлық құқықсыздықты сақтау","Қазақ тіліндегі білімді жою","Ұлттық автономия және құқықтық-демократиялық жаңару"],"a":3,"e":"Алаш қайраткерлері ұлттық автономияны, құқық теңдігін және білім беруді дамытуды жақтады.","l":"A","topic":"Алаш қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":218}}],"contexts":[{"id":"hce-46","title":"Қасым ханның билік тіректері","text":"XVI ғасырдың басында Қасым хан тұсында Қазақ хандығының ықпалы артты. Аумақ кеңейіп, көршілермен байланыс күшейді. Қасым есімі «Қасым ханның қасқа жолы» құқықтық дәстүрімен байланысты. Нормалар қоғамдық қатынасты реттеп, билік беделін нығайтуға қызмет етті. Сырдария қалалары үшін күресте саяси және шаруашылық мүдде ұштасқан. Күшейуді тек жорықпен түсіндіру жеткіліксіз. Ішкі басқару мен дипломатия да маңызды болды. Деректер ханның беделін жоғары бағалайды. Мұндай баға нақты әрекет пен тарихи орта аясында қарастырылады. Құқықтық тәртіп, сыртқы қатынас және әскери мүмкіндік бірін-бірі толықтырған.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7},"questions":[{"id":"hce-46-1","t":"«Қасым ханның билік тіректері» контексі: Мәтіндегі хан кім?","o":["Қасым","Жәңгір","Абылай","Тәуке"],"a":0,"e":"Мәтіндегі деректер «Қасым» деген жауапты негіздейді. Қасым билігі XVI ғасырдың басымен байланысты.","l":"A","topic":"Қасым ханның билік тіректері"},{"id":"hce-46-2","t":"«Қасым ханның билік тіректері» контексі: Онымен байланысты құқықтық атау қайсы?","o":["Жеті жарғы","Ескі жол","Уақытша ереже","Қасқа жол"],"a":3,"e":"Мәтіндегі деректер «Қасқа жол» деген жауапты негіздейді. Қасым билігі XVI ғасырдың басымен байланысты.","l":"A","topic":"Қасым ханның билік тіректері"},{"id":"hce-46-3","t":"«Қасым ханның билік тіректері» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Қасым билігі XVI ғасырдың басымен байланысты","Сырдария қалаларының шаруашылық маңызы болмаған","Құқықтық норманың билік беделіне қатысы болмаған","Хандық тек бір жорықтың арқасында барлық жағынан нығайды"],"a":0,"e":"Мәтіндегі деректер «Қасым билігі XVI ғасырдың басымен байланысты» деген жауапты негіздейді. Қасым билігі XVI ғасырдың басымен байланысты.","l":"B","topic":"Қасым ханның билік тіректері"},{"id":"hce-46-4","t":"«Қасым ханның билік тіректері» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Аумақтың кеңеюі ішкі басқаруды қажетсіз етеді","Бір деректің мадақтауы барлық жағдайды толық сипаттайды","Әскери күшпен бірге басқару және дипломатияны ескеру керек","Құқық пен сыртқы саясат бір-бірімен байланыспайды"],"a":2,"e":"Мәтіндегі деректер «Әскери күшпен бірге басқару және дипломатияны ескеру керек» деген жауапты негіздейді. Қасым билігі XVI ғасырдың басымен байланысты.","l":"B","topic":"Қасым ханның билік тіректері"},{"id":"hce-46-5","t":"«Қасым ханның билік тіректері» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Хандық тек бір жорықтың арқасында барлық жағынан нығайды","XVI ғасырдың басында Қасым хан тұсында Қазақ хандығының ықпалы артты.","Қасым билігі XVI ғасырдың басымен байланысты","Әскери күшпен бірге басқару және дипломатияны ескеру керек"],"a":0,"e":"Мәтіндегі деректер «Хандық тек бір жорықтың арқасында барлық жағынан нығайды» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Әскери күшпен бірге басқару және дипломатияны ескеру керек.","l":"C","topic":"Қасым ханның билік тіректері"}]},{"id":"hcl-46","title":"Қазақстан халқы Ассамблеясы","text":"Тәуелсіз елде әртүрлі этностар арасындағы келісімді сақтау маңызды міндет болды. Қоғамдық институттар ортақ азаматтық құндылықтар мен мәдени әртүрлілікті ұштастыруға бағытталды.\n\nҚазақстан халқы Ассамблеясы 1995 жылы құрылды. Ассамблеяның қызметі қоғамдық келісім мен этносаралық ынтымақты нығайтуға бағытталды. Қазақстан әртүрлі этнос өкілдері тұратын полиэтносты мемлекет болып табылады. Әртүрлі мәдени мұраны сақтау ортақ азаматтық бірлікпен ұштастырылды. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-46-1","t":"«Қазақстан халқы Ассамблеясы» контексі: Қазақстан халқы Ассамблеясы қай жылы құрылды?","o":["1917 жылы","1946 жылы","1995 жылы","1986 жылы"],"a":2,"e":"Қазақстан халқы Ассамблеясы 1995 жылы құрылды.","l":"A","topic":"Қазақстан халқы Ассамблеясы"},{"id":"hcl-46-2","t":"«Қазақстан халқы Ассамблеясы» контексі: Ассамблеяның негізгі бағыты қандай?","o":["Тек әскери техника шығару","Тек шетел валютасын сату","Тек салық жинау","Қоғамдық келісім мен этносаралық ынтымақ"],"a":3,"e":"Ассамблеяның қызметі қоғамдық келісім мен этносаралық ынтымақты нығайтуға бағытталды.","l":"A","topic":"Қазақстан халқы Ассамблеясы"},{"id":"hcl-46-3","t":"«Қазақстан халқы Ассамблеясы» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстан халқы Ассамблеясы қай жылы құрылды. 2) Қазақстанның этностық құрамын қай термин сипаттайды.","o":["1 — 1946 жылы; 2 — Тек көшпелі","1 — 1917 жылы; 2 — Полиэтносты","1 — 1995 жылы; 2 — Полиэтносты","1 — 1995 жылы; 2 — Бір ғана әулетті"],"a":2,"e":"Қазақстан халқы Ассамблеясы 1995 жылы құрылды. Қазақстан әртүрлі этнос өкілдері тұратын полиэтносты мемлекет болып табылады.","l":"B","topic":"Қазақстан халқы Ассамблеясы"},{"id":"hcl-46-4","t":"«Қазақстан халқы Ассамблеясы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Ассамблеяның негізгі бағыты қандай? 2) Мәдени әртүрлілікпен қатар қандай ортақ құндылық маңызды?","o":["1 — Тек салық жинау; 2 — Тілдік өшпенділік","1 — Қоғамдық келісім мен этносаралық ынтымақ; 2 — Міндетті рулық бөліну","1 — Қоғамдық келісім мен этносаралық ынтымақ; 2 — Азаматтық бірлік","1 — Тек әскери техника шығару; 2 — Азаматтық бірлік"],"a":2,"e":"Ассамблеяның қызметі қоғамдық келісім мен этносаралық ынтымақты нығайтуға бағытталды. Әртүрлі мәдени мұраны сақтау ортақ азаматтық бірлікпен ұштастырылды.","l":"B","topic":"Қазақстан халқы Ассамблеясы"},{"id":"hcl-46-5","t":"«Қазақстан халқы Ассамблеясы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Мәдени әртүрлілікті қолдау ортақ азаматтық құндылықтарды қалыптастырумен үйлесе алмайды.","Этностық әртүрлілікті сақтау мен ортақ азаматтық бірлікті нығайту өзара толықтыратын міндеттер ретінде қарастырылды.","Полиэтносты қоғамда бірлікті нығайту әр қауымның мәдени мұрасын ортақ азаматтық кеңістіктен бөлек ұстаумен ғана мүмкін.","Қоғамдық келісім институтының құрылуы этносаралық мәселелердің бұдан кейін талқылауды қажет етпейтінін дәлелдеді."],"a":1,"e":"Этностық әртүрлілікті сақтау мен ортақ азаматтық бірлікті нығайту өзара толықтыратын міндеттер ретінде қарастырылды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қазақстан халқы Ассамблеясы"}]}]},{"number":47,"questions":[{"id":"hi-054","t":"Абай шығармаларының алғашқы жинағы қай жылы жарық көрді?","o":["1917 жылы","1879 жылы","1891 жылы","1909 жылы"],"a":3,"e":"Абайдың алғашқы өлеңдер жинағы 1909 жылы Санкт-Петербургте басылды.","l":"A","topic":"XIX ғасырдағы әдебиет","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":146}},{"id":"hm-116","t":"1930 жылдардағы индустрияландыру мен саяси қуғын-сүргінді бірге зерттегенде қандай тұжырым негізді?","o":["Индустрияландырудың басталуы Қазақстанның сол кезде толық тәуелсіз болғанын дәлелдейді","Өндірістік құрылыс тоталитарлық бақылаумен қатар жүрді, сондықтан экономикалық өсім саяси еркіндікті білдірмейді","Өнеркәсіптің дамуы партиялық бақылау мен саяси қудалауды толығымен жойды","Қуғын-сүргін тек экономикалық күйреу жағдайында болады, өндіріс құрылысы болған жоқ"],"a":1,"e":"1930 жылдары жаңа кәсіпорындар мен көлік желілері салынды, бірақ жаппай қуғын-сүргін де жүрді. Осы екі құбылысты бірге қарастыру кезеңді біржақты түсіндіруден сақтайды.","l":"C","topic":"Қуғын-сүргін","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hk-106","t":"Екі пайымды бағалаңыз: I. «Жеті жарғы» Тәуке дәуірімен байланысты. II. Оны жасауға Төле, Қазыбек және Әйтеке билер қатысқан.","o":["Екі пайым да дұрыс","Тек I дұрыс","Екі пайым да қате","Тек II дұрыс"],"a":0,"e":"«Жеті жарғының» қалыптасуы Тәуке хан және үш бидің құқықтық қызметімен байланыстырылады.","l":"C","topic":"Тәуке хан және құқық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":109}},{"id":"hk-006","t":"Қазақ хандығының алғашқы ханы ретінде кім аталады?","o":["Тәуке","Тәуекел","Керей","Қасым"],"a":2,"e":"Қазақ хандығының негізін Керей мен Жәнібек қалады; алғашқы хандық билік Керейге берілді.","l":"A","topic":"Қазақ хандығының құрылуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hi-075","t":"Ақмешіттің алынуы Ресейдің қай бағыттағы ілгерілеуіне жол ашты?","o":["Қиыр Шығысқа","Сырдария бойы мен Оңтүстік Қазақстанға","Балтық жағалауына","Еділдің жоғарғы ағысына"],"a":1,"e":"Ақмешіт Сырдария бойындағы маңызды бекініс болды. Оның алынуы Ресейдің оңтүстіктегі әскери ықпалын арттырды.","l":"B","topic":"Оңтүстік Қазақстанның қосылуы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":170}},{"id":"ha-004","t":"Неолит дәуірінде кең таралған жаңа бұйымды атаңыз.","o":["Шойын соқа","Болат зеңбірек","Қыш ыдыс","Темір семсер"],"a":2,"e":"Неолитте саз балшықтан ыдыс жасап, оны күйдіру кең таралды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"ha-085","t":"Қазбада қала ішіндегі ең биік, жеке қорғаныс қабырғасы бар әкімшілік орын анықталды. Оның атауы қандай?","o":["Керуен жолы","Цитадель","Рабад","Қала маңындағы қыстақ"],"a":1,"e":"Цитадель билеуші ордасы мен әкімшілік ғимараттар орналасқан қорғалған бөлік еді.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":50}},{"id":"ha-044","t":"Батыс Түрік қағанатының негізгі орталығы болған қаланы көрсетіңіз.","o":["Суяб","Сарайшық","Сығанақ","Янгикент"],"a":0,"e":"Суяб Батыс Түрік қағанатының Жетісудағы маңызды саяси орталығы болды.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":6}},{"id":"hk-012","t":"Көшпелі малшылардың жайылымды маусым бойынша ауыстыруының негізгі себебі қандай?","o":["Барлық малды бір орталыққа шоғырландыру","Малға жыл бойы қолайлы өріс табу","Тек көрші хандықтарға елші жеткізу","Тұрақты қала гарнизондарын алмастыру"],"a":1,"e":"Маусымдық көшу табиғи жайылымды тиімді пайдалануға және малдың күйін сақтауға мүмкіндік берді.","l":"A","topic":"Дәстүрлі шаруашылық","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":117}},{"id":"hm-060","t":"Тәуелсіз Қазақстанның алғашқы Конституциясы қашан қабылданды?","o":["1936 жылғы 5 желтоқсанда","1993 жылғы 28 қаңтарда","1990 жылғы 25 қазанда","1920 жылғы 26 тамызда"],"a":1,"e":"Тәуелсіздік кезеңіндегі алғашқы Конституция 1993 жылғы 28 қаңтарда қабылданды.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":280}}],"contexts":[{"id":"hce-47","title":"Хақназар мен Тәуекел: саясат сабақтастығы","text":"Хақназар хан XVI ғасырда хандықты нығайтуға ұмтылды. Ноғай Ордасындағы тайпалардың бір бөлігі хандықпен жақындасты. Кейін Тәуекел Бұхарамен қатынас пен Мәуереннахр қалалары үшін күреске көңіл бөлді. 1598 жылғы жорық оңтүстіктегі ықпалды кеңейтуге бағытталды. Саяси қатар: Хақназардың нығайту әрекеті → кейінгі билеушілердің оңтүстіктегі саясаты. Хан ауысқанда барлық мақсат бірден жойылмайды. Кей бағытта сабақтастық сақталады. Сонымен бірге әр билеушінің жағдайы мен шешімі бөлек бағаланады. Сыртқы саясат одақ пен қарсыластықты қатар қолдануы мүмкін. Бір келісімді мәңгі өзгермейтін қатынас деп қабылдау дұрыс емес.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":149},"questions":[{"id":"hce-47-1","t":"«Хақназар мен Тәуекел: саясат сабақтастығы» контексі: 1598 жылғы жорықпен байланысты хан кім?","o":["Тәуекел","Қасым","Абылай","Тәуке"],"a":0,"e":"Мәтіндегі деректер «Тәуекел» деген жауапты негіздейді. Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты.","l":"A","topic":"Хақназар мен Тәуекел: саясат сабақтастығы"},{"id":"hce-47-2","t":"«Хақназар мен Тәуекел: саясат сабақтастығы» контексі: Хақназарға жақындасқан тайпалардың бір бөлігі қайдан шықты?","o":["Тан империясынан","Жоңғар хандығынан","Ноғай Ордасынан","Рим империясынан"],"a":2,"e":"Мәтіндегі деректер «Ноғай Ордасынан» деген жауапты негіздейді. Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты.","l":"A","topic":"Хақназар мен Тәуекел: саясат сабақтастығы"},{"id":"hce-47-3","t":"«Хақназар мен Тәуекел: саясат сабақтастығы» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Бір келісім көршімен мәңгі қайшылық болмайтынын дәлелдейді","Хан ауысқанда барлық сыртқы мақсат міндетті түрде жойылады","Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты","1598 жылғы жорық Хақназардан бұрынғы VI ғасырда өтті"],"a":2,"e":"Мәтіндегі деректер «Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты» деген жауапты негіздейді. Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты.","l":"B","topic":"Хақназар мен Тәуекел: саясат сабақтастығы"},{"id":"hce-47-4","t":"«Хақназар мен Тәуекел: саясат сабақтастығы» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Одақ пен қарсыластық бір мемлекеттің саясатында қатар кездеспейді","Ортақ бағыт екі билеушінің бір адам болғанын көрсетеді","Қала үшін күрес тек беделге қатысты, шаруашылыққа қатыссыз","Сабақтастықты сақтай отырып, әр билеушінің жағдайын жеке талдау қажет"],"a":3,"e":"Мәтіндегі деректер «Сабақтастықты сақтай отырып, әр билеушінің жағдайын жеке талдау қажет» деген жауапты негіздейді. Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты.","l":"B","topic":"Хақназар мен Тәуекел: саясат сабақтастығы"},{"id":"hce-47-5","t":"«Хақназар мен Тәуекел: саясат сабақтастығы» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Хақназар хан XVI ғасырда хандықты нығайтуға ұмтылды.","Хан ауысқанда барлық сыртқы мақсат міндетті түрде жойылады","Тәуекел саясаты Бұхара және оңтүстік қалалармен байланысты","Сабақтастықты сақтай отырып, әр билеушінің жағдайын жеке талдау қажет"],"a":1,"e":"Мәтіндегі деректер «Хан ауысқанда барлық сыртқы мақсат міндетті түрде жойылады» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Сабақтастықты сақтай отырып, әр билеушінің жағдайын жеке талдау қажет.","l":"C","topic":"Хақназар мен Тәуекел: саясат сабақтастығы"}]},{"id":"hcl-47","title":"Қазақстан және ЕҚЫҰ","text":"Қазақстан халықаралық ұйымдардағы белсенділігін арттыра отырып, қауіпсіздік диалогына қатыса бастады. Дипломатиялық бастамалар елдің сыртқы саяси беделін нығайтудың бір бағытына айналды.\n\nҚазақстан 2010 жылы Еуропадағы қауіпсіздік және ынтымақтастық ұйымына төрағалық етті. 2010 жылы ЕҚЫҰ саммиті Астанада өтті. ЕҚЫҰ мемлекеттер арасындағы қауіпсіздік пен ынтымақтастық мәселелерін талқылайды. Халықаралық ұйымға төрағалық Қазақстанның көпжақты дипломатиядағы белсенділігін көрсетті. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-47-1","t":"«Қазақстан және ЕҚЫҰ» контексі: Қазақстан ЕҚЫҰ-ға қай жылы төрағалық етті?","o":["2003 жылы","1991 жылы","2010 жылы","1995 жылы"],"a":2,"e":"Қазақстан 2010 жылы Еуропадағы қауіпсіздік және ынтымақтастық ұйымына төрағалық етті.","l":"A","topic":"Қазақстан және ЕҚЫҰ"},{"id":"hcl-47-2","t":"«Қазақстан және ЕҚЫҰ» контексі: 2010 жылғы ЕҚЫҰ саммиті қай қалада өтті?","o":["Орынборда","Астанада","Қоқанда","Семейде"],"a":1,"e":"2010 жылы ЕҚЫҰ саммиті Астанада өтті.","l":"A","topic":"Қазақстан және ЕҚЫҰ"},{"id":"hcl-47-3","t":"«Қазақстан және ЕҚЫҰ» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстан ЕҚЫҰ-ға қай жылы төрағалық етті. 2) ЕҚЫҰ қызметінің негізгі саласы қандай.","o":["1 — 2010 жылы; 2 — Қауіпсіздік және ынтымақтастық","1 — 1995 жылы; 2 — Тек астық сатып алу","1 — 2010 жылы; 2 — Тек теңге шығару","1 — 1991 жылы; 2 — Қауіпсіздік және ынтымақтастық"],"a":0,"e":"Қазақстан 2010 жылы Еуропадағы қауіпсіздік және ынтымақтастық ұйымына төрағалық етті. ЕҚЫҰ мемлекеттер арасындағы қауіпсіздік пен ынтымақтастық мәселелерін талқылайды.","l":"B","topic":"Қазақстан және ЕҚЫҰ"},{"id":"hcl-47-4","t":"«Қазақстан және ЕҚЫҰ» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) 2010 жылғы ЕҚЫҰ саммиті қай қалада өтті? 2) Қазақстанның төрағалығы қай саясатпен байланысты?","o":["1 — Астанада; 2 — Көпжақты дипломатиямен","1 — Астанада; 2 — Хандық мұрагерлікпен","1 — Қоқанда; 2 — Көпжақты дипломатиямен","1 — Орынборда; 2 — Әскери коммунизммен"],"a":0,"e":"2010 жылы ЕҚЫҰ саммиті Астанада өтті. Халықаралық ұйымға төрағалық Қазақстанның көпжақты дипломатиядағы белсенділігін көрсетті.","l":"B","topic":"Қазақстан және ЕҚЫҰ"},{"id":"hcl-47-5","t":"«Қазақстан және ЕҚЫҰ» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Саммит өткізу елдің көпжақты диалогтан екіжақты келіссөздерге ғана көшкенін көрсетті.","Төрағалық пен саммит өткізу халықаралық келіссөздер алаңы ретінде елдің дипломатиялық рөлін күшейтті.","Төрағалықтың бір жылға берілуі Қазақстанның қауіпсіздік мәселелерінде тек ішкі саясатпен шектелгенін дәлелдейді.","Халықаралық ұйымға төрағалық ету ұлттық сыртқы саясаттың дербестігінен толық бас тартуды білдіреді."],"a":1,"e":"Төрағалық пен саммит өткізу халықаралық келіссөздер алаңы ретінде елдің дипломатиялық рөлін күшейтті. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Қазақстан және ЕҚЫҰ"}]}]},{"number":48,"questions":[{"id":"hm-061","t":"Ұлттық валюта теңге айналымға қашан енгізілді?","o":["1991 жылғы 16 желтоқсанда","1992 жылғы 2 наурызда","1995 жылғы 1 наурызда","1993 жылғы 15 қарашада"],"a":3,"e":"Теңге 1993 жылғы 15 қарашада Қазақстанның ұлттық валютасы ретінде енгізілді.","l":"A","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":13}},{"id":"hk-063","t":"Абылайды хан көтерген 1771 жылғы жиын қай қалада өтті?","o":["Верныйда","Омбыда","Түркістанда","Орынборда"],"a":2,"e":"Түркістандағы хан сайлауы Абылайдың саяси беделін бекітті.","l":"A","topic":"Абылай хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":10}},{"id":"hi-118","t":"1916 жылғы қозғалыс жетекшілерін өңірлерімен дұрыс сәйкестендіріңіз.","o":["Амангелді Иманов — Торғай; Бекболат Әшекеев — Жетісу","Амангелді Иманов — Маңғыстау; Бекболат Әшекеев — Еділ","Амангелді Иманов — Бөкей Ордасы; Бекболат Әшекеев — Омбы","Амангелді Иманов — Жетісу; Бекболат Әшекеев — Торғай"],"a":0,"e":"Амангелді Торғай көтерілісінің сардарбегі болды. Бекболат Жетісудағы көтеріліс басшыларының бірі еді.","l":"C","topic":"1916 жылғы қозғалыс","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":238}},{"id":"hi-059","t":"Ахмет Байтұрсынұлы редактор болған ұлттық газет қалай аталды?","o":["Түркістан уалаятының газеті","Айқап","Қазақ","Дала уалаятының газеті"],"a":2,"e":"Ахмет Байтұрсынұлы «Қазақ» газетінің редакторы болды. Газет ұлттық қоғамдық ойдың маңызды мінберіне айналды.","l":"A","topic":"XX ғасыр басындағы баспасөз","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":12}},{"id":"ha-119","t":"Тайпалық бірлестіктерді кезеңдерімен сәйкестендіріңіз: 1) Сақтар; 2) Сарматтар; 3) Керейіттер. А) Ерте темір дәуірі; Ә) Орта ғасыр.","o":["1–Ә, 2–А, 3–А","1–А, 2–Ә, 3–А","1–Ә, 2–Ә, 3–А","1–А, 2–А, 3–Ә"],"a":3,"e":"Сақтар мен сарматтар ерте темір дәуіріне жатады; керейіттердің саяси бірлестігі орта ғасырларда өмір сүрді.","l":"C","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16}},{"id":"ha-001","t":"Қазақстандағы алғашқы адамдардың негізгі кәсіптерін көрсетіңіз.","o":["Аңшылық пен терімшілік","Металлургия мен қолөнер","Бау-бақша мен мал саудасы","Егіншілік пен сауда"],"a":0,"e":"Алғашқы адамдар дайын табиғи өнімді теріп, жабайы аңдарды аулап тіршілік етті.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":6}},{"id":"hm-087","t":"1979 жылғы Целиноград наразылығы мен 1986 жылғы Желтоқсанға ортақ белгі қандай?","o":["Екеуінің де орта ғасырда өтуі","Екеуінің де тың игеруді бастауы","Екеуінің де шетелдік басқыншылық болуы","Орталық шешімдеріне қоғамдық қарсылықтың байқалуы"],"a":3,"e":"Екі оқиға да жергілікті қоғам пікірінің орталық билік шешімдерімен қайшылыққа түсуін көрсетті.","l":"B","topic":"Кеңестік қоғам","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":9}},{"id":"hk-079","t":"Тәуекелдің Баба сұлтанды жеңуі оның саяси жағдайына қалай әсер етті?","o":["Оны II Абдаллахтың орнына Бұхар тағына отырғызды","Қолбасшылық беделін нығайтты","Оның Мәскеумен байланысты біржола үзуіне әкелді","Қазақ хандығын Моғолстанның құрамына қайтарды"],"a":1,"e":"Жеңіс Тәуекелдің әскери беделін көтерді, бірақ басқа мемлекеттің тағын автоматты түрде берген жоқ.","l":"B","topic":"Тәуекел ханның саясаты","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":101}},{"id":"hm-019","t":"Түрксіб құрылысына қолдау көрсеткен мемлекет қайраткерін атаңыз.","o":["Кенесары Қасымұлы","Тұрар Рысқұлов","Қасым хан","Шоқан Уәлиханов"],"a":1,"e":"Т.Рысқұлов Түрксіб құрылысын жүзеге асыруға атсалысқан мемлекет қайраткері болды.","l":"A","topic":"Индустрияландыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":236}},{"id":"hi-017","t":"1838 жылы Кенесары жасағы шабуыл жасаған бекіністі атаңыз.","o":["Ақмола","Петропавл","Қапал","Верный"],"a":0,"e":"Кенесары жасағы 1838 жылы Ақмола бекінісіне шабуыл жасады.","l":"A","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":170}}],"contexts":[{"id":"hce-48","title":"Есім хан: құқық және ішкі бірлік","text":"Есім хан XVI ғасырдың соңы мен XVII ғасырдың алғашқы бөлігінде билік жүргізді. Оның есімі «Есім ханның ескі жолы» дәстүрімен байланысты. Ішкі тартыстар мен оңтүстік қалалар мәселесі маңызды болды. Тұрсын ханмен қарсыластық билік бірлігіне әсер етті. Құқықтық тәртіп пен бедел тұрақтылықты қамтамасыз ету құралдары еді. Хандықты нығайту тек сыртқы жаумен күресу емес. Бір мемлекет ішіндегі билік орталықтарының бәсекесі оның күшіне ықпал етті. Атақтан бөлек нақты мүдде мен шешімді талдау қажет. Ішкі келісім сыртқы саясат жүргізу мүмкіндігіне де әсер етеді. Сондықтан тұрақтылықтың бірнеше тірегі қатар бағаланады.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":149},"questions":[{"id":"hce-48-1","t":"«Есім хан: құқық және ішкі бірлік» контексі: Есіммен байланысты құқықтық атау қайсы?","o":["Дала ережесі","Қасқа жол","Жеті жарғы","Ескі жол"],"a":3,"e":"Мәтіндегі деректер «Ескі жол» деген жауапты негіздейді. Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес.","l":"A","topic":"Есім хан: құқық және ішкі бірлік"},{"id":"hce-48-2","t":"«Есім хан: құқық және ішкі бірлік» контексі: Ішкі қарсыластықта аталған тұлға кім?","o":["Мұса","Кир","Батый","Тұрсын хан"],"a":3,"e":"Мәтіндегі деректер «Тұрсын хан» деген жауапты негіздейді. Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес.","l":"A","topic":"Есім хан: құқық және ішкі бірлік"},{"id":"hce-48-3","t":"«Есім хан: құқық және ішкі бірлік» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес","Ішкі билік тартысы мемлекеттің күшіне қатыссыз болды","Құқықтық тәртіп басқаруға еш ықпал етпеген","Тек сыртқы жау ғана хандық тұрақтылығына әсер етті"],"a":0,"e":"Мәтіндегі деректер «Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес» деген жауапты негіздейді. Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес.","l":"B","topic":"Есім хан: құқық және ішкі бірлік"},{"id":"hce-48-4","t":"«Есім хан: құқық және ішкі бірлік» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Тұрақтылық тек әскери санмен анықталады","Дауды реттеу мемлекеттің сыртқы мүмкіндігіне әсер етпейді","Бір атақ барлық билеуші мүддесін бірдей етеді","Ішкі билік қатынасы мен сыртқы қауіп қатар талдануы керек"],"a":3,"e":"Мәтіндегі деректер «Ішкі билік қатынасы мен сыртқы қауіп қатар талдануы керек» деген жауапты негіздейді. Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес.","l":"B","topic":"Есім хан: құқық және ішкі бірлік"},{"id":"hce-48-5","t":"«Есім хан: құқық және ішкі бірлік» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Тек сыртқы жау ғана хандық тұрақтылығына әсер етті","Есім билігі XVI ғасырдың соңы мен XVII ғасырдың басына сәйкес","Есім хан XVI ғасырдың соңы мен XVII ғасырдың алғашқы бөлігінде билік жүргізді.","Ішкі билік қатынасы мен сыртқы қауіп қатар талдануы керек"],"a":0,"e":"Мәтіндегі деректер «Тек сыртқы жау ғана хандық тұрақтылығына әсер етті» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Ішкі билік қатынасы мен сыртқы қауіп қатар талдануы керек.","l":"C","topic":"Есім хан: құқық және ішкі бірлік"}]},{"id":"hcl-48","title":"ЭКСПО–2017","text":"Халықаралық көрмелер мемлекеттердің технологиялық және мәдени жетістіктерін таныстыратын алаңға айналды. Қазақстанда өткен көрме энергия және тұрақты даму мәселелеріне назар аудартты.\n\nЭКСПО халықаралық мамандандырылған көрмесі Қазақстанда 2017 жылы өтті. ЭКСПО–2017 көрмесін Астана қаласы қабылдады. Көрменің «Болашақ энергиясы» тақырыбы энергия көздері мен тиімді технологияларға арналды. ЭКСПО — елдер жаңа идеялар мен жетістіктерін таныстыратын халықаралық көрме. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":16},"questions":[{"id":"hcl-48-1","t":"«ЭКСПО–2017» контексі: Қазақстанда ЭКСПО көрмесі қай жылы өтті?","o":["2010 жылы","2003 жылы","2017 жылы","1991 жылы"],"a":2,"e":"ЭКСПО халықаралық мамандандырылған көрмесі Қазақстанда 2017 жылы өтті.","l":"A","topic":"ЭКСПО–2017"},{"id":"hcl-48-2","t":"«ЭКСПО–2017» контексі: ЭКСПО–2017 қай қалада өтті?","o":["Астанада","Таразда","Семейде","Алматыда"],"a":0,"e":"ЭКСПО–2017 көрмесін Астана қаласы қабылдады.","l":"A","topic":"ЭКСПО–2017"},{"id":"hcl-48-3","t":"«ЭКСПО–2017» контексі: Екі деректі сәйкестендіріңіз. 1) Қазақстанда ЭКСПО көрмесі қай жылы өтті. 2) Көрменің тақырыбы қандай болды.","o":["1 — 1991 жылы; 2 — Болашақ энергиясы","1 — 2003 жылы; 2 — Жібек жолындағы соғыс","1 — 2017 жылы; 2 — Болашақ энергиясы","1 — 2017 жылы; 2 — Тек ежелгі металлургия"],"a":2,"e":"ЭКСПО халықаралық мамандандырылған көрмесі Қазақстанда 2017 жылы өтті. Көрменің «Болашақ энергиясы» тақырыбы энергия көздері мен тиімді технологияларға арналды.","l":"B","topic":"ЭКСПО–2017"},{"id":"hcl-48-4","t":"«ЭКСПО–2017» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) ЭКСПО–2017 қай қалада өтті? 2) ЭКСПО қандай сипаттағы шара?","o":["1 — Астанада; 2 — Халықаралық көрме","1 — Астанада; 2 — Әскери реформа","1 — Алматыда; 2 — Халықаралық көрме","1 — Таразда; 2 — Жер салығы"],"a":0,"e":"ЭКСПО–2017 көрмесін Астана қаласы қабылдады. ЭКСПО — елдер жаңа идеялар мен жетістіктерін таныстыратын халықаралық көрме.","l":"B","topic":"ЭКСПО–2017"},{"id":"hcl-48-5","t":"«ЭКСПО–2017» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Көрме елді танытуды энергияны тиімді пайдалану мен технологиялық жаңару тақырыптарымен байланыстырды.","Энергия тақырыбын таңдау көрменің мәдени және халықаралық таныстыру қызметін түгел жоққа шығарды.","Халықаралық көрме елді танытқанымен, оның тақырыбы технология мен тұрақты даму мәселелерінен бөлек болды.","Көрмені қабылдау жаңа технологияларды талқылауды қажетсіз етіп, дайын шешімдердің толық енгізілгенін білдірді."],"a":0,"e":"Көрме елді танытуды энергияны тиімді пайдалану мен технологиялық жаңару тақырыптарымен байланыстырды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"ЭКСПО–2017"}]}]},{"number":49,"questions":[{"id":"hm-124","t":"Мемлекеттік рәміздер, Конституция және БҰҰ мүшелігіне қатысты тұжырымдарды бағалаңыз: I — рәміздер мемлекеттің бірегейлігін танытады; II — Конституция мемлекеттік құрылысты құқықтық реттейді; III — БҰҰ мүшелігі ұлттық валютаның орнын алмастырады; IV — БҰҰ мүшелігі халықаралық қатынастарға қатысуды кеңейтеді.","o":["II, III және IV","I, III және IV","I, II және IV","I, II және III"],"a":2,"e":"Рәміздер, Конституция және халықаралық мүшелік мемлекеттіліктің әртүрлі қырларын нығайтады. БҰҰ мүшелігі ақша жүйесін алмастырмайды, ол халықаралық қатынастарға қатысты.","l":"C","topic":"Тәуелсіздік","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":14}},{"id":"ha-092","t":"Барақ ханның Сырдария қалалары үшін күресін түсіндіретін экономикалық себепті таңдаңыз.","o":["Қалалар арқылы сауда мен егіншілік ресурстарына ықпал ету","Қала тұрғындарын мал шаруашылығына толық көшіру","Еділ сағасындағы теңіз порттарын түгел иелену","Жетісудағы кеніштердің бәрін жабу"],"a":0,"e":"Сырдария қалалары сауда, қолөнер және егіншіліктің маңызды орталықтары болғандықтан, оларды иелену хан билігінің ресурстарын арттырды.","l":"B","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hm-073","t":"Қуғын-сүргіннің Қазақстан мәдениетіне әсерін қай тұжырым дұрыс сипаттайды?","o":["Ғылыми зерттеулерге ешқандай шектеу қойылмады","Барлық қаламгер саяси қысымнан толық қорғалды","Мәдениет партия бақылауынан түгел босады","Зиялы қауымның жойылуы мәдени дамуға ауыр соққы болды"],"a":3,"e":"Әдебиет пен ғылым өкілдерін қудалау ұлттық мәдениеттің сабақтастығына зиян келтірді.","l":"A","topic":"Қуғын-сүргін","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":212}},{"id":"hk-059","t":"Жоңғарларға қарсы күресте «Дарабоз» атанған батыр кім?","o":["Ағыбай","Қабанбай","Исатай","Бекболат"],"a":1,"e":"Қабанбай батыр қазақ-жоңғар соғыстарындағы қолбасшылық ерлігі үшін «Дарабоз» атанды.","l":"A","topic":"Қазақ батырлары","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":145}},{"id":"ha-033","t":"Үйсіндердің негізгі қоныстанған тарихи аймағын көрсетіңіз.","o":["Еділдің төменгі ағысы","Жетісу","Маңғыстау","Тобыл бойы"],"a":1,"e":"Үйсіндердің негізгі аумағы Жетісу, соның ішінде Іле аңғары болды.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":2}},{"id":"hk-017","t":"Қасым хан Қазақ хандығының негізін қалаған қай ханның ұлы болды?","o":["Жәңгірдің","Тәукенің","Жәнібектің","Керейдің"],"a":2,"e":"Қасым — Жәнібек ханның ұлы. Оның тұсында Қазақ хандығының саяси қуаты артты.","l":"A","topic":"Қасым хан","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":126}},{"id":"hk-112","t":"Хақназардың II Абдаллахпен шарты мен Абылайдың Ресей-Қытай арасындағы саясатына ортақ белгі қандай?","o":["Дәстүрлі шаруашылықтан толық бас тарту","Барлық көршіге бірдей соғыс жариялау","Сыртқы күштермен қатынасты мемлекеттің қауіпсіздігіне пайдалану","Бір ғана қаланың ішкі басқаруын өзгерту"],"a":2,"e":"Екі жағдайда да хан сыртқы байланыстарды Қазақ хандығының саяси жағдайын нығайту үшін қолданды.","l":"C","topic":"Қазақ хандарының дипломатиясын салыстыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":108}},{"id":"hi-081","t":"Пароход қатынасының дамуы Қазақстанның экономикасына қалай әсер етті?","o":["Сауда жолдарын түгел тоқтатты","Жүк тасымалы мен өңіраралық сауданы жеңілдетті","Қолөнер бұйымдарын пайдалануға тыйым салды","Жәрмеңкелерді бірден жойды"],"a":1,"e":"Өзен көлігі тауарды көбірек және алысырақ тасымалдауға мүмкіндік берді. Бұл сауданың дамуына ықпал етті.","l":"B","topic":"XIX ғасырдың экономикасы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":161}},{"id":"hi-022","t":"Қарқаралы сыртқы округі қай жылы құрылды?","o":["1867 жылы","1824 жылы","1854 жылы","1832 жылы"],"a":1,"e":"Қарқаралы сыртқы округі 1824 жылы құрылды. Бұл Орта жүзде округтік басқарудың орнығуын көрсетті.","l":"A","topic":"1822–1824 жылдардағы реформалар","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":189}},{"id":"ha-019","t":"Парсы жазбаларындағы «шошақ бөрікті сақтар» атауына қай топ сәйкес келеді?","o":["Тиграхауда","Аргиппей","Хаумаварга","Парадарайа"],"a":0,"e":"Тиграхауда атауы шошақ бөрік киген сақтарды білдіреді.","l":"A","topic":"Ежелгі кезең","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":4}}],"contexts":[{"id":"hce-49","title":"Орбұлақтағы әскери шешім","text":"1643 жылы Орбұлақта Жәңгір хан бастаған жасақ жоңғар әскеріне қарсы тұрды. Тар кеңістік пен қорғаныс тәсілі қарсыластың сандық басымдығын шектеуге көмектесті. Жалаңтөс баһадүрдің қолдауы шайқасқа ықпал етті. Жер бедері, ұйымдасу және көмек ұштасқан. Әскери табысты тек жауынгер санымен түсіндіру жеткіліксіз. Деректегі сандық хабарды қолданғанда оның негізін тексеру қажет. Тактикалық шешім мен саяси одақ бірін-бірі толықтырды. Шайқас қолайлы жерді пайдаланудың маңызын көрсетеді. Оқиғаның нәтижесі барлық кейінгі қауіптің біржола жойылғанын білдірмейді. Әскери оқиғаны ұзақ саяси күрес аясында бағалаған жөн.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15},"questions":[{"id":"hce-49-1","t":"«Орбұлақтағы әскери шешім» контексі: Орбұлақта қазақ қолын басқарған кім?","o":["Тәуекел","Керей","Қасым","Жәңгір"],"a":3,"e":"Мәтіндегі деректер «Жәңгір» деген жауапты негіздейді. Орбұлақ шайқасы 1643 жылы болды.","l":"A","topic":"Орбұлақтағы әскери шешім"},{"id":"hce-49-2","t":"«Орбұлақтағы әскери шешім» контексі: Жәңгірге қолдау көрсеткен қолбасшы кім?","o":["Едіге","Жалаңтөс баһадүр","Қайыр хан","Естеми"],"a":1,"e":"Мәтіндегі деректер «Жалаңтөс баһадүр» деген жауапты негіздейді. Орбұлақ шайқасы 1643 жылы болды.","l":"A","topic":"Орбұлақтағы әскери шешім"},{"id":"hce-49-3","t":"«Орбұлақтағы әскери шешім» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Шайқас нәтижесін тек әскер саны толық анықтады","Жалаңтөс көмегі тактиканы пайдалануды жоққа шығарады","Жер бедерінің қорғанысқа әсері болмаған","Орбұлақ шайқасы 1643 жылы болды"],"a":3,"e":"Мәтіндегі деректер «Орбұлақ шайқасы 1643 жылы болды» деген жауапты негіздейді. Орбұлақ шайқасы 1643 жылы болды.","l":"B","topic":"Орбұлақтағы әскери шешім"},{"id":"hce-49-4","t":"«Орбұлақтағы әскери шешім» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Одақтастың көмегі ішкі ұйымдасуды қажетсіз етеді","Бір жеңіс барлық кейінгі саяси қауіпті мәңгі жояды","Әр сандық хабарды дерексіз дәл қабылдау қажет","Тактика, жер бедері және одақтас көмегі бірге ықпал етті"],"a":3,"e":"Мәтіндегі деректер «Тактика, жер бедері және одақтас көмегі бірге ықпал етті» деген жауапты негіздейді. Орбұлақ шайқасы 1643 жылы болды.","l":"B","topic":"Орбұлақтағы әскери шешім"},{"id":"hce-49-5","t":"«Орбұлақтағы әскери шешім» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["1643 жылы Орбұлақта Жәңгір хан бастаған жасақ жоңғар әскеріне қарсы тұрды.","Тактика, жер бедері және одақтас көмегі бірге ықпал етті","Шайқас нәтижесін тек әскер саны толық анықтады","Орбұлақ шайқасы 1643 жылы болды"],"a":2,"e":"Мәтіндегі деректер «Шайқас нәтижесін тек әскер саны толық анықтады» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Тактика, жер бедері және одақтас көмегі бірге ықпал етті.","l":"C","topic":"Орбұлақтағы әскери шешім"}]},{"id":"hcl-49","title":"Дүниежүзі қазақтарының құрылтайы","text":"Тәуелсіздік шетелдегі қазақтармен мәдени және қоғамдық байланыстарды жаңартуға мүмкіндік берді. Ұлттық тұтастық мәселесі мемлекет шекарасымен ғана шектелмейтін ортақ мұра аясында қарастырылды.\n\nДүниежүзі қазақтарының алғашқы құрылтайы 1992 жылы өтті. 1992 жылғы алғашқы құрылтай Алматы қаласында ұйымдастырылды. Шетелдегі қандастардың тарихи отанына оралуы репатриация деп аталады. Құрылтай шетел қазақтары мен атажұрт арасындағы мәдени-қоғамдық байланысты нығайтуды көздеді. Тарихи талдау үшін деректерді жеке емес, өзара байланыста қарастыру маңызды.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15},"questions":[{"id":"hcl-49-1","t":"«Дүниежүзі қазақтарының құрылтайы» контексі: Дүниежүзі қазақтарының алғашқы құрылтайы қай жылы өтті?","o":["1992 жылы","1917 жылы","1954 жылы","1986 жылы"],"a":0,"e":"Дүниежүзі қазақтарының алғашқы құрылтайы 1992 жылы өтті.","l":"A","topic":"Дүниежүзі қазақтарының құрылтайы"},{"id":"hcl-49-2","t":"«Дүниежүзі қазақтарының құрылтайы» контексі: Алғашқы құрылтай қай қалада ұйымдастырылды?","o":["Орынборда","Алматыда","Қоқанда","Омбыда"],"a":1,"e":"1992 жылғы алғашқы құрылтай Алматы қаласында ұйымдастырылды.","l":"A","topic":"Дүниежүзі қазақтарының құрылтайы"},{"id":"hcl-49-3","t":"«Дүниежүзі қазақтарының құрылтайы» контексі: Екі деректі сәйкестендіріңіз. 1) Дүниежүзі қазақтарының алғашқы құрылтайы қай жылы өтті. 2) Атажұртқа қайта оралу үдерісі қалай аталады.","o":["1 — 1954 жылы; 2 — Демаркация","1 — 1992 жылы; 2 — Эвакуация","1 — 1917 жылы; 2 — Репатриация","1 — 1992 жылы; 2 — Репатриация"],"a":3,"e":"Дүниежүзі қазақтарының алғашқы құрылтайы 1992 жылы өтті. Шетелдегі қандастардың тарихи отанына оралуы репатриация деп аталады.","l":"B","topic":"Дүниежүзі қазақтарының құрылтайы"},{"id":"hcl-49-4","t":"«Дүниежүзі қазақтарының құрылтайы» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) Алғашқы құрылтай қай қалада ұйымдастырылды? 2) Құрылтайдың негізгі бағыты қандай?","o":["1 — Қоқанда; 2 — Ядролық сынақты көбейту","1 — Омбыда; 2 — Дүниежүзі қазақтарының байланысын нығайту","1 — Алматыда; 2 — Тек кен өндіру жоспарын бекіту","1 — Алматыда; 2 — Дүниежүзі қазақтарының байланысын нығайту"],"a":3,"e":"1992 жылғы алғашқы құрылтай Алматы қаласында ұйымдастырылды. Құрылтай шетел қазақтары мен атажұрт арасындағы мәдени-қоғамдық байланысты нығайтуды көздеді.","l":"B","topic":"Дүниежүзі қазақтарының құрылтайы"},{"id":"hcl-49-5","t":"«Дүниежүзі қазақтарының құрылтайы» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Репатриация мен құрылтай бір мақсатқа қатысты болғандықтан, бірін өткізу екіншісіне қажеттілікті толық жойды.","Атажұртпен байланыс тек мемлекет аумағында тұрғандарға қатысты болып, шетелдегі қауымдарды қамтымады.","Құрылтай мен репатриация тәуелсіздік жағдайында тарихи отанмен байланысты нығайтудың әртүрлі тетіктері болды.","Құрылтай өткізу мәдени байланыстарды тек қоныс аударғандармен шектеп, шетелде қалған қазақтармен қатынасты тоқтатуды көздеді."],"a":2,"e":"Құрылтай мен репатриация тәуелсіздік жағдайында тарихи отанмен байланысты нығайтудың әртүрлі тетіктері болды. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"Дүниежүзі қазақтарының құрылтайы"}]}]},{"number":50,"questions":[{"id":"ha-050","t":"Атлах шайқасында арабтар жағына шыққан тайпаларды көрсетіңіз.","o":["Наймандар","Жалайырлар","Керейіттер","Қарлұқтар"],"a":3,"e":"Қарлұқтардың арабтар жағына шығуы Атлах шайқасының нәтижесіне ықпал етті.","l":"A","topic":"Орта ғасыр кезеңі","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":1}},{"id":"hm-030","t":"Екі мәрте Кеңес Одағының Батыры атанған қазақстандықты көрсетіңіз.","o":["Ермұхан Бекмаханов","Ахмет Байтұрсынұлы","Санжар Асфендияров","Талғат Бигелдинов"],"a":3,"e":"Т.Бигелдинов әскери ұшқыш ретінде бұл атаққа екі рет ие болды.","l":"A","topic":"Ұлы Отан соғысы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hi-104","t":"Исатай–Махамбет пен Кенесары қозғалыстарын дұрыс салыстыратын тұжырымды табыңыз.","o":["Екі қозғалыс та жоңғарларға қарсы ұйымдастырылды","Екеуі де тек 1870 жылы өтті","Исатай Қоқан автономиясын жариялады, Кенесары газет шығарды","Екеуі де отарлық қысымға қарсы болды; Кенесары хандық билікті қалпына келтіруді көздеді"],"a":3,"e":"Екі қозғалыстың да отаршылдыққа қарсы сипаты болды. Кенесары қозғалысының айқын саяси мақсаты хандық мемлекеттілікті қалпына келтіру еді.","l":"C","topic":"Ұлт-азаттық қозғалыстарды салыстыру","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":182}},{"id":"hm-006","t":"Жаңа экономикалық саясатқа көшу туралы шешім қай жылы қабылданды?","o":["1928 жылы","1918 жылы","1921 жылы","1936 жылы"],"a":2,"e":"1921 жылғы партияның Х съезі жаңа экономикалық саясатқа көшуді бекітті.","l":"A","topic":"ЖЭС","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":7}},{"id":"hm-082","t":"Тың игеруді бағалағанда қандай екі құбылысты бірге ескеру қажет?","o":["Астық көлемінің өсуі мен экологиялық зардаптарын","Тек хандық билік пен жоңғар соғысын","Тек ғарыш ұшулары мен теңге бағамын","Тек теңіз тасымалы мен отарлық бекіністерді"],"a":0,"e":"Тың игеру астық өндірісін ұлғайтты, бірақ топырақ пен жайылымға теріс әсер етті.","l":"B","topic":"Тың игеру","source":{"file":"22_Қазақстан-тарихы_көшірме.pdf","page":3}},{"id":"hi-064","t":"Ахмет Байтұрсынұлының 1911 жылы жарық көрген өлеңдер жинағын атаңыз.","o":["Қалың мал","Қамар сұлу","Оян, қазақ!","Маса"],"a":3,"e":"«Маса» жинағының авторы — Ахмет Байтұрсынұлы. Онда халықты білімге және қоғамдық сергектікке шақыру идеясы бар.","l":"A","topic":"Алаш қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":261}},{"id":"hi-018","t":"Кенесары Қасымұлының соңғы жорығы қай аймақта аяқталды?","o":["Маңғыстауда","Қырғыз жерінде","Еділ бойында","Батыс Сібірде"],"a":1,"e":"Кенесарының соңғы шайқасы 1847 жылы қырғыз жерінде болды. Сол шайқаста ол қаза тапты.","l":"A","topic":"Кенесары қозғалысы","source":{"file":"ilide.info-1-pr_dcb320c8ad6b2f8e5512355eeebc48a6.pdf","page":171}},{"id":"hk-060","t":"XVIII ғасырдың 20-жылдары Кіші жүзді басқарған хан кім?","o":["Хақназар","Бұрындық","Қасым","Әбілқайыр"],"a":3,"e":"Әбілқайыр хан XVIII ғасырдың бірінші жартысында Кіші жүздің билеушісі болды.","l":"A","topic":"Әбілқайыр хан","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"hk-091","t":"1741–1743 жылдардағы Абылайға қатысты оқиға қай саладағы күрделі жағдайды көрсетеді?","o":["Қазақ-жоңғар әскери-саяси қатынастарын","Хандықта сұлтандар билігінің жойылуын","Қазақ-Бұхар елшілік қатынастарының басталуын","Қазақ-Мәскеу шекарасының ресми бөлінуін"],"a":0,"e":"Абылайдың жоңғар тұтқынына түсуі және босатылуы сол кезеңдегі соғыс пен дипломатиямен байланысты.","l":"B","topic":"Абылай ханның тұтқында болуы","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":3}},{"id":"ha-114","t":"Қарахан дәуірі қаласынан мешіт, медресе, шеберхана және теңгелер табылды. Қай қорытынды осы айғақтардың бәрін қамтиды?","o":["Діни білім, қолөнер және тауар-ақша қатынастары қатар дамыған","Теңгелер діни білімнің болмағанын дәлелдейді","Халық негізінен аңшылықпен ғана айналысқан","Қала тек діни орталық болып, саудаға қатыспаған"],"a":0,"e":"Мешіт пен медресе рухани-білім беру өмірін, шеберхана қолөнерді, теңгелер ақша айналымын көрсетеді.","l":"C","topic":"Ежелгі және ортағасырлық мәдениет","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":5}}],"contexts":[{"id":"hce-50","title":"Тәуке мен Абылай: бірлік және дербестік","text":"Тәуке хан есімі «Жеті жарғы» дәстүрімен байланысты. Төле, Қазыбек және Әйтеке билер қоғамдық дауларды реттеуде танылды. Кейін XVIII ғасырда Абылай сыртқы қауіп жағдайында елдің тұтастығын сақтауға ұмтылды. 1771 жылы ол Түркістанда хан көтерілді. Ресей және Қытаймен қатынаста елшілік пен тепе-теңдік тәсілдерін қолданды. Екі дәуірді біріктіретін мәселе ішкі келісім мен саяси дербестік болды. Бірақ әр ханның жағдайы және қолданған құралы бөлек еді. Құқықтық норма барлық даудың жойылғанын білдірмейді. Ресми сыртқы байланыс та ішкі биліктің түгел берілгенін автоматты дәлелдемейді. Нақты жағдайды талдау тарихи бағаны дәл етеді.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":153},"questions":[{"id":"hce-50-1","t":"«Тәуке мен Абылай: бірлік және дербестік» контексі: Жеті жарғы қай ханмен байланысты?","o":["Керей","Қасым","Батый","Тәуке"],"a":3,"e":"Мәтіндегі деректер «Тәуке» деген жауапты негіздейді. Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді.","l":"A","topic":"Тәуке мен Абылай: бірлік және дербестік"},{"id":"hce-50-2","t":"«Тәуке мен Абылай: бірлік және дербестік» контексі: Абылай 1771 жылы қай қалада хан көтерілді?","o":["Түркістан","Орынбор","Сарай-Бату","Суяб"],"a":0,"e":"Мәтіндегі деректер «Түркістан» деген жауапты негіздейді. Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді.","l":"A","topic":"Тәуке мен Абылай: бірлік және дербестік"},{"id":"hce-50-3","t":"«Тәуке мен Абылай: бірлік және дербестік» контексі: Мәтіндегі дерекке сәйкес келетін тұжырымды табыңыз.","o":["Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді","Заңдық дәстүр болса қоғамда қайшылық мүлде болмайды","Кез келген елшілік барлық ішкі биліктің толық берілгенін дәлелдейді","Тәуке мен Абылай бір билеушінің екі аты"],"a":0,"e":"Мәтіндегі деректер «Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді» деген жауапты негіздейді. Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді.","l":"B","topic":"Тәуке мен Абылай: бірлік және дербестік"},{"id":"hce-50-4","t":"«Тәуке мен Абылай: бірлік және дербестік» контексі: Деректерді байланыстырып, негізді қорытындыны анықтаңыз.","o":["Екі ханның ортақ мақсаты барлық құрал мен жағдайдың бірдей болғанын білдіреді","Дипломатия қолданылса әскери қауіп болмағаны анық","Ішкі келісім мен сыртқы дербестік мәселесін нақты дәуір жағдайында бағалау қажет","Ресми атаққа дейін тұлғада саяси ықпал болмайды"],"a":2,"e":"Мәтіндегі деректер «Ішкі келісім мен сыртқы дербестік мәселесін нақты дәуір жағдайында бағалау қажет» деген жауапты негіздейді. Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді.","l":"B","topic":"Тәуке мен Абылай: бірлік және дербестік"},{"id":"hce-50-5","t":"«Тәуке мен Абылай: бірлік және дербестік» контексі: Мәтінге сүйенгенде қай пайымның дәлелі жеткіліксіз?","o":["Кез келген елшілік барлық ішкі биліктің толық берілгенін дәлелдейді","Ішкі келісім мен сыртқы дербестік мәселесін нақты дәуір жағдайында бағалау қажет","Тәуке хан есімі «Жеті жарғы» дәстүрімен байланысты.","Абылай Ресеймен және Қытаймен дипломатиялық қатынас жүргізді"],"a":0,"e":"Мәтіндегі деректер «Кез келген елшілік барлық ішкі биліктің толық берілгенін дәлелдейді» деген пайымды дәлелдемейді. Мәтіннен шығатын негізгі тұжырым: Ішкі келісім мен сыртқы дербестік мәселесін нақты дәуір жағдайында бағалау қажет.","l":"C","topic":"Тәуке мен Абылай: бірлік және дербестік"}],"sources":[{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":153},{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":133}]},{"id":"hcl-50","title":"XX ғасырдағы тарихи әдебиет","text":"Тарихи өзгерістер әдеби шығармаларда адамдардың тағдыры арқылы бейнеленді. Жазушылар ұлттық тарихты зерттеу мен көркем баяндаудың әртүрлі тәсілдерін пайдаланды.\n\nӘбдіжәміл Нұрпейісов «Қан мен тер» трилогиясын жазды. Мұхтар Әуезовтің «Абай жолы» эпопеясы XIX ғасырдағы қазақ қоғамын көркем бейнелейді. Ілияс Есенберлиннің «Көшпенділер» трилогиясы қазақ мемлекеттілігінің тарихын көркем баяндады. Тарихи романда көркем қиял болатындықтан, оны тарихи құжаттармен салыстырып оқу қажет.","source":{"file":"ilide.info-pr_010d9b75dd1c4442273d3a465cadae5b.pdf","page":15},"questions":[{"id":"hcl-50-1","t":"«XX ғасырдағы тарихи әдебиет» контексі: «Қан мен тер» трилогиясының авторы кім?","o":["Мұхтар Әуезов","Ілияс Есенберлин","Әбдіжәміл Нұрпейісов","Абай Құнанбайұлы"],"a":2,"e":"Әбдіжәміл Нұрпейісов «Қан мен тер» трилогиясын жазды.","l":"A","topic":"XX ғасырдағы тарихи әдебиет"},{"id":"hcl-50-2","t":"«XX ғасырдағы тарихи әдебиет» контексі: «Абай жолы» эпопеясының авторы кім?","o":["Мұхтар Әуезов","Міржақып Дулатұлы","Сәкен Сейфуллин","Жамбыл Жабаев"],"a":0,"e":"Мұхтар Әуезовтің «Абай жолы» эпопеясы XIX ғасырдағы қазақ қоғамын көркем бейнелейді.","l":"A","topic":"XX ғасырдағы тарихи әдебиет"},{"id":"hcl-50-3","t":"«XX ғасырдағы тарихи әдебиет» контексі: Екі деректі сәйкестендіріңіз. 1) «Қан мен тер» трилогиясының авторы кім. 2) «Көшпенділер» трилогиясының авторы кім.","o":["1 — Мұхтар Әуезов; 2 — Ілияс Есенберлин","1 — Әбдіжәміл Нұрпейісов; 2 — Санжар Асфендияров","1 — Әбдіжәміл Нұрпейісов; 2 — Ілияс Есенберлин","1 — Ілияс Есенберлин; 2 — Қаныш Сәтбаев"],"a":2,"e":"Әбдіжәміл Нұрпейісов «Қан мен тер» трилогиясын жазды. Ілияс Есенберлиннің «Көшпенділер» трилогиясы қазақ мемлекеттілігінің тарихын көркем баяндады.","l":"B","topic":"XX ғасырдағы тарихи әдебиет"},{"id":"hcl-50-4","t":"«XX ғасырдағы тарихи әдебиет» контексі: Мәтінге сүйеніп екі мәселенің дұрыс шешімін табыңыз. 1) «Абай жолы» эпопеясының авторы кім? 2) Көркем тарихи шығармаға қатысты дұрыс ұстаным қандай?","o":["1 — Міржақып Дулатұлы; 2 — Оны салық есебі деп санау","1 — Мұхтар Әуезов; 2 — Оны өзге тарихи деректермен салыстыру","1 — Сәкен Сейфуллин; 2 — Оны өзге тарихи деректермен салыстыру","1 — Мұхтар Әуезов; 2 — Ондағы әр сөйлемді заң деп қабылдау"],"a":1,"e":"Мұхтар Әуезовтің «Абай жолы» эпопеясы XIX ғасырдағы қазақ қоғамын көркем бейнелейді. Тарихи романда көркем қиял болатындықтан, оны тарихи құжаттармен салыстырып оқу қажет.","l":"B","topic":"XX ғасырдағы тарихи әдебиет"},{"id":"hcl-50-5","t":"«XX ғасырдағы тарихи әдебиет» контексі: Барлық деректі біріктіргенде қандай тарихи қорытынды негізді?","o":["Көркем шығарманың тарихи жадқа әсері ондағы барлық оқиғаны қосымша тексерусіз ғылыми дерек деп қабылдауға негіз болады.","Көркем қиялдың болуы тарихи романдарды өткен қоғамды түсінуде пайдалануға толық кедергі келтіреді.","Әдебиет тарихи жадты байытады, ал ғылыми талдау көркем баяндау мен тексерілген деректі ажыратуды талап етеді.","Шығарма авторының белгілі болуы оның баяндауын тарихи құжаттармен салыстыру қажеттігін жояды."],"a":2,"e":"Әдебиет тарихи жадты байытады, ал ғылыми талдау көркем баяндау мен тексерілген деректі ажыратуды талап етеді. Бұл қорытынды мәтіндегі оқиғалар мен олардың нәтижелерін байланыстырады.","l":"C","topic":"XX ғасырдағы тарихи әдебиет"}]}]}];
